INSERT INTO public.document_files (
  id,document_id,file_type,storage_path,download_filename,mime_type,file_size,sha256,page_count,is_downloadable,download_block_reason
)
SELECT (x->>'id')::uuid,(x->>'document_id')::uuid,x->>'file_type',x->>'storage_path',x->>'download_filename',
       x->>'mime_type',(x->>'file_size')::bigint,x->>'sha256',(x->>'page_count')::integer,
       (x->>'is_downloadable')::boolean,x->>'download_block_reason'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT DO NOTHING;

COMMIT;

SELECT 'moj-all-verified-judgments-review-002-chunk-030' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"f31890e1-c074-5831-98b0-d2b8e38089f8","document_type":"judgment","category":"judicial","subcategory":"general","title":"قتل -قتل خطأ -حيازة ساح بدون ترخيص -استخدام ساح ناري -إقرار املدعى عليه -تنازل عن حق خاص -األخذ بالقرائن لتحديد القصد اجلنائي -إدانة بالقتل اخلطأ -عدم تقيد المحكمة بالوصف الوارد يف الئحة الدعوى -تعزير بالسجن وأخذ التعهد وإفهام بكفارة القتل اخلطأ ما أشار له القاضي يف تسبيب احلكم.","document_number":"34296822","case_number":"3246628","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/14","year":"1434","subject":"قتل -قتل خطأ -حيازة ساح بدون ترخيص -استخدام ساح ناري -إقرار املدعى عليه -تنازل عن حق خاص -األخذ بالقرائن لتحديد القصد اجلنائي -إدانة بالقتل اخلطأ -عدم تقيد المحكمة بالوصف الوارد يف الئحة الدعوى -تعزير بالسجن وأخذ التعهد وإفهام بكفارة القتل اخلطأ ما أشار له القاضي يف تسبيب احلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34296822 :‬تاريخه‪1434/8/14 :‬هـ‬\n                     ‫رقم الدعوى‪3246628:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34309760‬تاريخه‪1434/9/1 :‬هـ‬\n\n\n‫قتــل ‪ -‬قتــل خطــأ ‪ -‬حيــازة ســاح بــدون ترخيــص ‪ -‬اســتخدام ســاح‬\n‫نــاري ‪ -‬إقــرار املدعــى عليــه ‪ -‬تنــازل عــن حــق خــاص ‪ -‬األخــذ بالقرائــن‬\n‫لتحديــد القصــد اجلنائــي ‪ -‬إدانــة بالقتــل اخلطــأ ‪ -‬عــدم تقيد احملكمة‬\n‫بالوصــف الــوارد يف الئحــة الدعــوى ‪ -‬تعزيــر بالســجن وأخــذ التعهــد‬\n                                            ‫وإفهــام بكفــارة القتــل اخلطــأ‬\n\n\n\n\n                                      ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n‫توجيــه االتهــام مــن االدعــاء العــام نحــو املدعــى عليــه بقتــل املجنــي عليــه‬\n‫عمــدا عدوانــا وطلــب إثبــات صفــة القتــل ‪ ،‬تلقــت الدوريــات األمنيــة‬\n‫بالغــا عــن وجــود حالــة طــوارئ باملستشــفى فتوجهــت نحــوه فظهــر بــأن‬\n‫املجنــي عليــه تــويف إثــر تعرضــه إلطــاق نــار ‪ ،‬بضبــط إفــادة صاحــب‬\n‫املنــزل والــد املدعــى عليــه أفــاد بأنــه كان جالســا يف بيتــه فســمع صــوت‬\n‫إطــاق نــار مــن أحــد الغــرف فتوجــه نحــوه فوجــد ابنــه املدعــى عليــه‬\n‫ممســكا بســاح رشــاش ويصــرخ ويبكــي والدمــاء تســيل علــى صــدر‬\n‫املجنــي عليــه‪ ،‬بالتحقيــق مــع املدعــى عليــه أجــاب بأنــه قــام بإطــاق‬\n‫طلقــة يف الهــواء فلــم تخــرج رصاصــة فعشــق الســاح مــرة أخــرى وصوبــه‬\n\n                                                                                        ‫‪34‬‬\n\f     ‫نحــو املجنــي عليــه مازحــا يقصــد إخافتــه فانطلقــت رصاصــة نحــو‬\n     ‫صــدره‪ ،‬تنــازل ورثــة املجنــي عليــه عــن املدعــى عليــه‪ ،‬بعــرض الدعــوى‬\n     ‫عليــه أجــاب بــأن مــا جــاء يف دعــوى املدعــي العــام صحيــح حيــث قمــت‬\n     ‫بإطــاق طلقــة يف الهــواء فلــم تخــرج رصاصــة فعشــق الســاح مــرة أخــرى‬\n     ‫وصوبــه نحــو املجنــي عليــه مازحــا يقصــد إخافتــه فانطلقــت رصاصــة‬\n     ‫نحــو صــدره وكان ذلــك باخلطــأ ولــم أقصــد قتلــه‪ ،‬جــرى االطــاع علــى‬\n     ‫التقريــر الطبــي املتضمــن حــدوث الوفــاة نتيجــة الطلقــة الناريــة النافــذة‬\n     ‫بالصــدر‪ ،‬وإلقــرار املدعــى عليــه ودفعــه بحدوثــه خطــأ ‪ ،‬عليــه ولصغــر‬\n     ‫ســن املدعــى عليــه وإقــرار الورثــة بالتنــازل ولعــدم وجــود عــداوة ‪ ،‬وهــذه‬\n     ‫قرائــن تؤيــد دفــع املدعــى عليــه‪ ،‬لــذا فقــد قــررت احملكمــة ثبــوت‬\n     ‫قيــام املدعــى عليــه بإطــاق النــار مــن ســاح رشــاش نحــو املجنــي عليــه‬\n     ‫باخلطــأ أدى لوفاتــه وقــررت تعزيــره ألجلــه بســجنه شــهرا يحســب منهــا‬\n     ‫مــدة إيقافــه بســبب القضيــة مــع أخــذ التعهــد عليــه بعــدم العــودة ملثــل‬\n     ‫كمــت‪ ،‬أفهــم بــأن عليــه كفــارة قتــل اخلطــأ ‪،‬‬    ‫مــا بــدر منــه وبذلــك َح َ‬\n     ‫قــرر املدعــى عليــه القناعــة بينمــا اعتــرض املدعــي العــام بــدون الئحــة ‪،‬‬\n                                        ‫صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ..........‬القاضــي باحملكمــة اجلزائيــة‬\n     ‫بتبــوك بنــاء علــى املعاملــة الــواردة إلــى احملكمــة مــن هيئــة التحقيــق‬\n     ‫واإلدعــاء العــام بتبــوك بكتابهــم رقــم ‪ 9208‬وتاريــخ ‪1431/7/3‬ه ـ‬\n     ‫واحملالــة إلــي مــن فضيلــة الرئيــس برقــم ‪ 3246628‬وتاريــخ‬\n     ‫‪1432/2/18‬ه ـ والتــي ســبق أن أحيلــت لفضيــة القاضــي باحملكمــة‬\n\n‫‪35‬‬\n\f‫الشــيخ ‪..........‬برقــم ‪ 1576‬يف ‪1434/7/4‬ه ـ فصــدر فيهــا احلكــم مــن‬\n‫فضيلتــه برقــم ‪4/7/104‬ج وتاريــخ ‪1434/7/14‬ه ـ املنقــوض مــن‬\n‫محكمــة االســتئناف مبكــة املكرمــة مــن الدائــرة اجلزائيــة اخلامســة‬\n‫برقــم ‪/5/5‬ن‪/‬ج يف ‪1432/1/21‬ه ـ عليــه حضــر املدعــي العــام ‪..........‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪..........‬املكلــف لــدى‬\n‫احملكمــة مبوجــب كتــاب التعميد رقــم ‪..........‬يف ‪1433/9/5‬هـ وادعى‬\n‫علــى احلاضــر معــه ‪..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫ا يف حتريــر دعــواه بتاريــخ ‪1430/12/29‬ه ـ تلقــت‬                  ‫(‪ )..........‬قائ ـ ً‬\n‫الدوريــات األمنيــة بالغـ ًا عــن وجــود حالــة داخــل طــوارئ مستشــفى امللــك‬\n‫خالــد وعنــد حضــور الدوريــات وجــد ‪..........‬متوفــى داخــل املستشــفى‬\n‫لتعرضــه إلطــاق نــار وبضبــط إفــادة صاحــب املنــزل والــد احلــدث املدعى‬\n‫ـاء وحينمــا كان جالس ـ ًا يف‬   ‫عليــه أفــاد بأنــه يف الســاعة العاشــرة مسـ ً‬\n‫املجلــس وعندهــا ســمع طلقــة صــادرة مــن غرفــة النــوم التــي تخصــه‬\n‫وعندهــا حضــر فوجــد ابنــه ‪..........‬ممســك ًا بســاح رشــاش‬\n‫الكالشــنكوف وكان يصــرخ ويبكــي وممســك ًا بولــد شــقيقه‬\n‫‪..........‬ويقــول أبويــه ‪..........‬مــات مــات والدمــاء تســيل مــن صــدر ‪..........‬‬\n‫مــن اجلهــة اليمنــى لصــدره وأخــذ ‪..........‬وذهــب بــه إلــى املستشــفى كمــا‬\n‫أفــاد بــأن الســاح كان موجــود ًا بالغرفــة وباالنتقــال ملعاينــة موقــع‬\n‫اجلرميــة اتضــح أن املنــزل يقــع بحــي ‪..........‬خلــف قصــر أفــراح ‪..........‬وهــو‬\n‫عبــارة عــن عمــارة مســلحة مكونــة مــن دوريــن ومــكان اجلرميــة يقــع‬\n‫بالــدور األول ويتكــون مــن مدخــل ثــم ممــر ثــم بعــد املمــر مجلــس يف‬\n‫اجلهــة اليســرى طولــه خمســة يف أربعــة وغرفــة أربعــة يف أربعــة ثــم صالــة‬\n‫داخليــة مســاحتها أربعــة يف ســتة وغرفــة أخــرى صغيــرة والتــي وقــع فيهــا‬\n\n\n                                                                                           ‫‪36‬‬\n\f     ‫إطــاق النــار حســب إفــادة أهــل املنــزل ومســاحتها أربعــة يف أربعــة وجــد‬\n     ‫بداخلهــا طاولــة خشــبية وعليهــا مالبــس تبعــد عــن البــاب حوالــي متــر ًا‬\n     ‫تقريبـ ًا متحركــة مــن مكانهــا املالصــق للجــدار األيســر بحوالــي نصف‬\n     ‫متــر ويف اجلهــة اليمنــى مــن الغرفــة وجــدت مالبــس متنوعــة رجاليــة‬\n     ‫ونســائية كثيــرة موضوعــة علــى األرض بعضهــا فــوق بعــض بشــكل‬\n     ‫عشــوائي ووجــد الســاح نــوع رشــاش كالشــنكوف فــوق املالبــس‬\n     ‫مغطــى وال يظهــر منــه ســوى العقــب اخلشــبي اخللفــي و بالبحــث يف الغرفة‬\n     ‫وجــود العربــود رأس املقــذوف يف أعلــى املالبــس التــي علــى الطاولــة‬\n     ‫اخلشــبية ووجــد الظــرف الفــارغ يف الزاويــة اليمنــى املقابلــة للبــاب‬\n     ‫واحتمــال أن يكــون تغيــر مــن موقعــة أثنــاء البحــث ومــن خــال معاينــة‬\n     ‫املنــزل بشــكل كامــل والبحــث وجــد عرض ـ ًا ســاح آخــر عبــارة عــن‬\n     ‫مســدس ربــع صغيــر بداخــل جــراب الســاح ومخــزن أســود مــع تســع‬\n     ‫طلقــات حيــة ملفــوف الســاح يف قمــاش ملــون ويبــدوا أنــه لــم يســتخدم‬\n     ‫منــذ فتــره وكذلــك أثنــاء متشــيط املوقــع وجــدت بقــع دمويــة علــى فــراش‬\n     ‫األرض لونــه أزرق فــاحت وكذلــك بقــع دمويــة متفرقة يف الصالة الداخلية‬\n     ‫وثــاث نقــط دمويــة أمــام البــاب اخلارجــي وخــاف ذلــك لــم يظهــر أي‬\n     ‫أدلــة تفيــد التحقيــق وجــرى تصويــر املوقــع ورفــع جميــع اآلثــار وقــد صــدر‬\n     ‫التقريــر الطبــي رقــم بــدون وتاريــخ ‪1430/12/29‬ه ـ بحــق ‪..........‬‬\n     ‫واملتضمــن إصابتــه بطلــق نــاري ولديــه جــرح باحللمــة اليســرى بطــول‬\n     ‫(‪1.5‬ســم) وخــروج الطلقــة مــن ناحيــة اإلبــط األميــن بطــول حوالي (‪5‬ســم)‬\n     ‫مــع كســر ضلعــن يف الناحيــة اليمنــى مت اســتقبال املريــض املتوفــى‬\n     ‫بــدون عالمــات حيويــة كمــا ورد التقريــر رقــم ‪..........‬بشــأن فحــص‬\n     ‫عينــات رفعــت مــن يــد اجلانــي املدعــى عليــه حيــث أعطيت جميــع العينات‬\n\n\n‫‪37‬‬\n\f‫إيجابيــة ملخلفــات اإلطــاق علــى األيــدي كمــا ورد التقريــر الفنــي رقــم‬\n‫‪..........‬والعائــد للمتوفــى ‪..........‬واملتضمــن وجــود بقــع كثيفــة بلــون أحمر‬\n‫يشــتبه أن تكــون دم مــع وجــود متزقــات مــن ناحيــة مقدمــة القميــص‬\n‫بطــول (‪ )0.5‬ومتــزق مــن ناحيــة اإلبــط األميــن للقميــص بطــول (‪1.5‬ســم)‬\n‫كمــا ورد التقريــر الفنــي رقم‪..........‬واملتضمــن إيجابية العينات املوجودة‬\n‫مبالبــس املتوفــى ‪..........‬ألدمــي) كمــا ورد خطــاب مديــر مركز شــرطة‬\n‫احلمــراء ‪..........‬وتاريــخ ‪1431/2/9‬ه ـ واملتضمــن تقريــر مصــور ملوقــع‬\n‫اجلرميــة وجلثمــان املتوفــى واملتضمــن وجــود مدخــل للطلــق النــاري مــن‬\n‫الناحيــة اليســرى ومخــرج لــه مــن ناحيــة اإلبــط األميــن مــن اخللــف كمــا‬\n‫ورد خطــاب مديــر شــعبة التحريــات والبحــث اجلنائــي رقــم ‪ ..........‬وتاريــخ‬\n‫‪1431/1/2‬ه ـ واملتضمــن كــون العالقــة بــن اجلانــي وذوي املتوفــى‬\n‫(عالقــة عائليــة) كــون والــد ‪..........‬واملدعــو ‪..........‬هــو شــقيق املدعــو‬\n‫‪ ..........‬والــد املدعــى عليــه وبالبحــث والتحــري لــم يتضــح وجــود أي‬\n‫مشــاكل بينهــم كمــا صــدر التقريــر الطبــي الشــرعي النهائــي بالقضية‬\n‫رقــم ‪ ..........‬واملتضمــن أن الوفــاة تعــود لتوقــف القلــب والتنفــس نــاجت عــن‬\n‫علــة كامنــة تعــذر معرفتهــا نظــر ًا لعــدم تشــريح اجلثمــان ولكونــه بنــاء‬\n‫علــى الكشــف الظاهــري واألشــعة املجــراة وفحــص املالبــس ومعاينــة‬\n‫مــكان الوفــاة وســلبية عينــات الــدم والبــول فــا مانــع لدينــا مــن حــدوث‬\n‫الوفــاة نتيجــة الطلــق النــاري النافــذ بالصــدر ومــا يحدثــه عــادة مــن‬\n‫إصابــات بأحشــاء جــوف الصــدر وبالنســبة لزمــن الوفــاة نتيجــة الطلــق‬\n‫النــاري النافــذ بالصــدر ومــا يحدثــه عــادة مــن حوالــي ســاعة واحــدة مــن‬\n‫توقيــت املعاينــة األوليــة قــد تزيــد أو تنقــص تبع ـ ًا للتغيــرات احمليطــة‬\n‫باجلثمــان كمــا فــرزت أوراق مســتقلة حليــازة الســاح بــدون ترخيــص‬\n\n\n                                                                                       ‫‪38‬‬\n\f     ‫العائــد لوالــد اجلانــي واملســتخدم يف القضيــة والســاح اآلخــر املضبــوط‬\n     ‫وباســتجواب املدعــى عليــه احلــدث ‪..........‬أقــر بأنــه يف يــوم األربعــاء‬\n     ‫‪1431/12/29‬ه ـ أطلــق النــار مــن ســاح مــن نــوع رشــاش يعــود لوالــده‬\n     ‫علــى ‪..........‬طلقــة واحــدة باجتــاه الصــدر حيــث إنــه أطلــق طلقــة يف الهواء‬\n     ‫فلــم تخــرج مــن الســاح أي ذخيــرة فتوقــع أن الســاح ال يجــد بــه ذخيــرة‬\n     ‫وقــام بعــد ذلــك بتعشــيق الســاح مــرة أخــرى وتصويبــه باجتــاه ‪..........‬‬\n     ‫قاصــد ًا إخافتــه بذلــك وأنــه كان ميازحــه فأطلــق طلقــة واحــدة فأصابــت‬\n     ‫‪..........‬ممــا نتــج عنــه وفاتــه ومت تصديــق إقــراره شــرع ًا وملــا أشــير إليــه‬\n     ‫أقــرر توجيــه االتهــام للحــدث املذكــور بإطــاق النــار عمــد ًا مــن ســاح‬\n     ‫ا‬\n     ‫نــوع رشــاش طلقــة واحــدة أصابــت ‪ ..........‬بصــدره فــأرداه قتي ـ ً‬\n     ‫واســتخدامه للســاح العائــد لوالــده وذلــك لألدلــة والقرائــن التاليــة ‪.1‬‬\n     ‫إقــرار املدعــى عليــه املصــدق شــرع ًا واملنــوه عنــه يف الصفحــة رقــم (‪)4‬‬\n     ‫لفــة رقــم (‪.2 )29‬مــا جــاء مبحضــر متثيــل اجلرميــة املرفــق ‪.3‬مــا جــاء‬\n     ‫مبحضــر االنتقــال واملعاينــة املــدون علــى الصفحــة رقــم (‪ )4‬لفــة رقــم (‪)1‬‬\n     ‫‪.4‬مــا جــاء يف التقريــر املصــور ملســرح اجلرميــة وجثمــان املتوفــى لفــة رقــم‬\n     ‫(‪.5 )67‬مــا جــاء بالتقريــر الطبــي لفــة رقــم (‪. )41‬مــا جــاء يف التقريــر‬\n     ‫الفنــي رقــم (‪/60‬كيميــاء جنائيــة ‪1431/‬ه) لفــة رقــم (‪.7 )39‬التقريــر‬\n     ‫الطبــي الشــرعي النهائــي رقــم (‪1430/114‬ه) وحيــث إن مــا أقــدم عليــه‬\n     ‫املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إحالتــه‬\n     ‫لفضيلــة قاضــي األحــداث إلثبــات إدانتــه مبــا أســند إليــه وحتديــد صفــة‬\n     ‫القتــل والنظــر يف إنهــاء احلــق العــام يف ضــوء املــادة (‪ )174‬واملــادة رقــم‬\n     ‫(‪ )126‬و املــادة رقــم (‪ )152‬مــن نظــام اإلجــراءات اجلزائيــة (علم ـ ًا بــأن‬\n     ‫احلــق اخلــاص قــد انتهــى بالتنــازل وصــدق التنــازل شــرعاً) هــذه دعــواي‬\n\n\n‫‪39‬‬\n\f‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه وســؤاله عنهــا أجــاب‬\n‫بقولــه مــا ذكــره املدعــي العــام يف دعــواه صحيــح حيــث أننــي وجــدت‬\n‫ســاح لوالــدي يف الغرفــة وقــد قمــت بتعشــقيه وإطــاق النــار يف الهــواء‬\n‫مرتــن فلــم يخــرج مــن الســاح أي طلــق نــاري ثــم قمــت بتعشــيقه مــرة‬\n‫أخــرى وصوبتــه جتــاه ابــن عمــي ‪..........‬مــن بــاب املمازحــة وإخافتــه‬\n‫فخرجــت طلقــة فأصابــت ‪..........‬يف صــدره ممــا تســبب لــه بالوفــاة علمـ ًا‬\n‫أن مــا مت منــي كان عــن طريــق اخلطــأ فلــم أكــن أقصــد فعــل ذلــك‬\n‫هكــذا أجــاب وبالرجــوع إلــى أوراق املعاملــة وجــد باللفــة رقــم (‪)115‬‬\n‫صــك صــادر مــن احملكمــة العامــة بتبــوك برقــم ‪5/2‬يف ‪1430/2/24‬ه ـ‬\n‫املتضمــن تنــازل ورثــة القتيــل ‪..........‬وهمــا والــداه ‪ ..........‬و‪ ..........‬مبوجــب‬\n‫صــك حصــر ورثــة الصــادر مــن احملكمــة العامــة برقــم ‪..........‬يف‬\n‫‪1430/1/2‬ه ـ وذلــك أن قتــل املدعــى عليــه ألبنهمــا مــن ســاح رشــاش‬\n‫عــن طريــق اخلطــأ ركمــا جــرى الرجــوع إلــى التقريــر الطبــي الشــرعي‬\n‫النهائــي لفــة رقــم (‪ 86‬إلــى ‪ )92‬املتضمــن أن الوفــاة تعــود لتوقــف القلــب‬\n‫والتنفــس نــاجت عــن علــة كامنــة تعــذر معرفتهــا نظــر ًا لعــدم تشــريح‬\n‫اجلثمــان ولكــن بنــاء علــى الكشــف الظاهري واألشــعة املجــراة وفحص‬\n‫املالبــس ومعاينــة مــكان الوفــاة وســلبية العينــات الــدم والبــول فــا مانــع‬\n‫لدينــا مــن حــدوث الوفــاة نتيجــة الطلــق النــاري النافــذ بالصــدر ومــا‬\n‫يحدثــه عــادة مــن إصابــات بأحشــاء جــوف الصــدر والنســبة لزمــن الوفــاة‬\n‫فبنــاء علــى العالمــات الرميــة املشــاهدة علــى اجلثمــان حوالــي ســاعة‬\n‫واحــدة املعاينــة األوليــة قــد تزيــد أو تنقــص تبع ـ ًا للتغيــرات احمليطــة‬\n‫باجلثمــان كمــا جــرى الرجــوع إلــى لفــة رقــم (‪ )29‬صفحــة (‪ )4‬املتضمــن‬\n‫إقــرار املدعــى عليــه وفــق إجابتــه فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n\n\n                                                                                             ‫‪40‬‬\n\f     ‫واإلجابــة وملّــا أقــر املدعــى عليــه بإطالقــه للنــار علــى املجنــي عليــه‬\n     ‫والتســبب يف قتلــه وأن ذلــك عــن طريــق اخلطــأ وحيــث عــن اإلقــرار حجــة‬\n     ‫علــى صاحبــه مؤاخــذ بــه ونظــر ًا لكــون جميــع األدلــة والقرائــن احملتفــه‬\n     ‫باملعاملــة تؤيــد ذلــك مــن صغــر ســن املدعــى عليــه وإقــرار ورثــة املتوفــى‬\n     ‫ـدي إطــاق‬  ‫بذلــك وعــدم وجــود عــداوة لــذا وجلميــع مــا تقــدم فقــد ثبــت لـ َّ‬\n     ‫املدعــى عليــه النــار مــن ســاح نــوع رشــاش أصابــت املجنــي عليــه ‪..........‬‬\n     ‫فتســببت يف وفاتــه وأن القتــل املوصــوف مــن قبيــل اخلطــأ وقــررت تعزيــر‬\n     ‫املدعــى عليــه لقــاء مــا بــدر منــه بســجنه ملــدة شــهر يحتســب مــن ذلــك مــدة‬\n     ‫إيقافــه بســبب هــذه القضيــة مــع أخــذ التعهــد عليــه بعــدم العــودة ملثــل مــا‬\n     ‫بــدر منــه وبذلــك حكمــت كمــا أفهمتــه بــأن عليــه كفــارة القتــل اخلطــأ‬\n     ‫وهــي عتــق رقبــة فــإن لــم يجــد فصيــام شــهرين متتابعــن وبعــرض احلكــم‬\n     ‫علــى الطرفــن قــرر املدعــى عليــه قناعتــه بــه وأمــا املدعــي العــام فقــد‬\n     ‫قــرر اعتراضــه مكتفي ـ ًا مبــا جــاء يف أوراق املعاملــة عــن تقــدمي الئحــة‬\n     ‫اعتراضيــة وللبيــان حــرر ‪1434/8/14‬ه ـ وصلــى اهلل علــى نبينــا محمــد‬\n     ‫وعلــى آلــه وصحبــه أجمعــن‪ .‬احلمــد هلل وحــده وبعــد‪ :‬فقــد اطلعن ــا نحــن‬\n     ‫قـض ــاة الدائ ــرة اجلزائيــة الثانيــة يف محكمــة االســتئناف مبنطقــة تبــوك‬\n     ‫علــى املعاملــة الــواردة مــن احملكمــة اجلزائيــة بتبــوك برقــم وتاريــخ‬\n     ‫‪1434/8/21‬هـ‪،‬املرفــق بهــا القــرار الصــادر مــن فضيلــة ‪..........‬برقــم‬\n     ‫وتاريــخ ‪1434/8/14‬ه ـ ‪،‬واخلــاص بدعــوى املدعــي العــام ضــد ‪..........‬يف‬\n     ‫قضيــة إثبــات صفــة القتــل ‪ ،‬علــى النحــو املوضــح بالقــرار واملتضمــن‬\n     ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة‬\n     ‫ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق‬\n                                    ‫‪،‬وصلى اهلل على نبينا محمد آله وصحبه وسلم‪.‬‬\n\n\n‫‪41‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":34,"source_page_end":41,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d10d8cf188569f007c4333e9c4a524806506dbea8a5ca428fae139165e54c70c","normalized_text_hash":"2e46b15b860f03f7144a3b886c9a4ec4c400b8e1885f2a58bd4c6bc819879f53","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p34-34296822"},{"id":"73bc1b8d-70c3-5f7c-ab67-4457eb8ab744","document_type":"judgment","category":"judicial","subcategory":"general","title":"قيام أخته -املدعى عليها -بضرب أخيه مما تسبب بجرح يف رأسه من جهة الصدغ وبعد مضي ما يقارب الثاث ساعات فارق احلياة وبناء على التقرير الطبي بأن سبب الوفاة يعود لتوقف مفاجئ يف الدورة الدموية قاموا بدفنه دون إباغ اجلهات األمنية ،تنازل ورثة املجني عليه عن املدعى عليها عدا املبلغ ،بعرض الدعوى على «وكيل املدعى عليها» أجاب مبذكرة جوابية خالصتها إنكاره","document_number":"34223913","case_number":"3422571","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/27","year":"1434","subject":"قيام أخته -املدعى عليها -بضرب أخيه مما تسبب بجرح يف رأسه من جهة الصدغ وبعد مضي ما يقارب الثاث ساعات فارق احلياة وبناء على التقرير الطبي بأن سبب الوفاة يعود لتوقف مفاجئ يف الدورة الدموية قاموا بدفنه دون إباغ اجلهات األمنية ،تنازل ورثة املجني عليه عن املدعى عليها عدا املبلغ ،بعرض الدعوى على «وكيل املدعى عليها» أجاب مبذكرة جوابية خالصتها إنكاره","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34223913 :‬تاريخه‪1434/5/27 :‬هـ‬\n                     ‫رقم الدعوى‪3422571:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34270456‬تاريخه‪1434/7/17 :‬هـ‬\n\n\n‫قتــل ‪ ،‬قتــل خطــأ ‪ ،‬ضــرب باســتخدام ســطل حديــدي «أداة حديديــة» ‪،‬‬\n‫ضــرب أفضــى إلــى املــوت ‪ ،‬دعــوى عامــة وخاصــة ‪ ،‬تقريــر طبــي شــرعي ‪،‬‬\n                                                 ‫رد دعــوى املدعــى العــام‪.‬‬\n\n\n\n\n                                      ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن قبــل االدعــاء العــام علــى املدعــى عليهــا بقيامهــا‬\n‫بقتــل أخيهــا بضربهــا علــى رأســه بســطل حديــدي إثــر اعتــداء بالضــرب‬\n‫حصــل بينهمــا حصلــت بينهمــا ويطلــب إثبــات صفــة قتلهــا لــه «شــبه‬\n‫عمــد» لتطبيــق مقتضــى اإلرادة امللكيــة يف حقهــا بســجنها ســنتني‬\n‫ونصــف حيــث تقــدم أحــد املواطنــن ألحــد مراكــز الشــرطة ببــاغ عــن‬\n‫قيــام أختــه ‪ -‬املدعــى عليهــا ‪ -‬بضــرب أخيــه ممــا تســبب بجــرح يف رأســه‬\n‫مــن جهــة الصــدغ وبعــد مضــي مــا يقــارب الثــاث ســاعات فــارق احليــاة‬\n‫وبنــاء علــى التقريــر الطبــي بــأن ســبب الوفــاة يعــود لتوقــف مفاجــئ يف‬\n‫الــدورة الدمويــة قامــوا بدفنــه دون إبــاغ اجلهــات األمنيــة ‪ ،‬تنــازل ورثــة‬\n‫املجنــي عليــه عــن املدعــى عليهــا عــدا املبلــغ ‪ ،‬بعــرض الدعــوى علــى‬\n‫«وكيــل املدعــى عليهــا» أجــاب مبذكــرة جوابيــة خالصتهــا إنــكاره‬\n\n                                                                                        ‫‪42‬‬\n\f     ‫بــأن الضربــة التــي أصابتــه مــن موكلتــه أدت لوفاتــه‪ ،‬وإمنــا تــويف إثــر‬\n     ‫نوبــة ربــو حــادة أدت لتوقــف مفاجــئ يف الــدورة الدمويــة والتنفــس‪،‬‬\n     ‫وأن دعــوى املدعــي اخلــاص «املبلــغ» كيديــة إثــر خــاف مالــي بينهمــا ‪،‬‬\n     ‫جــرى االطــاع علــى التقريــر الطبــي املتضمــن بــأن ســبب الوفــاة توقــف‬\n     ‫مفاجــئ يف الــدورة الدمويــة والتنفســية ‪ ،‬جــرى االطــاع علــى اعتــراف‬\n     ‫املدعــى عليهــا املتضمــن إقرارهــا بالشــجار الــذي دار بينهــا وبــن املتوفــى‬\n     ‫تطــور لالشــتباك باأليــدي فقامــت علــى إثــر ضربــه وشــد شــعر رأســه‬\n     ‫بتنــاول ســطل حديــدي بجوارهــا ضربــت بــه رأســه ففرقــت بينهمــا‬\n     ‫أختــه‪ ،‬فشــاهدت قطــرات مــن دم تســيل مــن رأســه يف محــل االصابــة‬\n     ‫فاتصــل علــى الدوريــات األمنيــة فحلــوا اإلشــكال بينهمــا وقــررا التنــازل‬\n     ‫عــن بعضهمــا يف املوقــع فمكــث قليــا وغــادر املوقــع ومعــه أختــه وبعــد‬\n     ‫منتصــف الليــل اتصلــت أختهــا عليــه فأخبرتهــا بنقلــه للمستشــفى فاقــدا‬\n     ‫الوعــي ثــم أخبــرت بوفاتــه ‪ ،‬بعــرض اإلقــرار علــى وكيلها صــادق عليه‪،‬‬\n     ‫جــرى االطــاع علــى محضــر اســتجواب أخــت املتوفــى واملدعــى عليهــا‬\n     ‫واملتضمــن أن املتوفــى يعانــي مــن مــرض بصــدره وبعــد ضربــه مــن قبــل‬\n     ‫املدعــى عليهــا اتصــل املتوفــى بالشــرطة ولــم يــرض نقلــه للمستشــفى وأن‬\n     ‫الــدم الــذي خــرج منــه كان قليــا وقــد خــرج وهــو يقــود ســيارته ‪ ،‬جــرى‬\n     ‫االطــاع علــى إفــادة أخــوي املدعــى عليهــا أن املتوفــى كان يعانــي مــن‬\n     ‫ألــم يف صــدره ‪ ،‬جــرى االطــاع علــى إفــادة أحــد أقاربــه بــأن املتوفــى‬\n     ‫كان يعانــي مــن ألــم يف صــدره ويســتفرغ دمــا وكان يعانــي مــن األلــم يف‬\n     ‫صــدره مــن خمــس ســنوات تقريبـ ًا ‪ ،‬وعليــه وملــا تضمنــه التقريــر الطبــي‪،‬‬\n     ‫ومــا ورد يف محاضــر اســتجواب أشــقاء املدعــى عليهــا وأقــارب املتوفــى‬\n     ‫مــن أنــه كان يعانــي مــن مــرض يف صــدره وأن الــدم الــذي نــزف منــه‬\n\n\n‫‪43‬‬\n\f‫كان قليــا ‪ ،‬لــذا قــررت احملكمــة عــدم ثبــوت إدانــة املدعــى عليهــا‬\n‫بقتــل أخيهــا وصرفــت النظــر عــن طلــب املدعــي العــام ‪ ،‬بعرضــه علــى‬\n‫املدعــي العــام قــرر االعتــراض بالئحــة ‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                               ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬مســاعد رئيــس احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫وتاريــخ‬           ‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم‬\n‫‪1434/01/13‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ ‪1434/01/13‬ه ـ‬\n‫ففــي يــوم اإلثنــن املوافق‪1434/03/23‬ه ـ افتتحــت اجللســة الســاعة ‪45‬‬\n‫‪ 09 :‬وفيهــا حضر‪..........‬املكلــف بالترافــع لدينــا يف قضايــا احلــق العــام‬\n‫مبوجــب خطــاب رئيــس دائــرة اإلدعــاء العــام مبكــة املكرمــة رقــم‬\n‫‪..........‬يف ‪1434/1/24‬ه ـ وأدعــى علــى ‪ 38(..........‬عام ـاً) ســعودية‬\n‫ا يف دعــواه عليهــا أنــه بتاريخ‬‫اجلنســية بالســجل املدنــي رقــم (‪ )..........‬قائـ ً‬\n‫‪1433/4/5‬ه ـ تقــدم املواطــن‪.......... /‬ملركــز شــرطة ‪..........‬ببــاغ عــن‬\n‫قيــام أختــه املدعــى عليهــا بضــرب أخيــه ‪..........‬البالــغ مــن العمر‪42‬عــام‬\n‫ممــا تســبب يف إصابتــه بجــرح يف رأســه مــن جهــة الصــدغ األميــن وبعــد‬\n‫مضــي مــا يقــارب الثــاث ســاعات فــارق احليــاة وبنقلــه ملستشــفى امللــك‬\n‫فيصــل ومعاينتــه مــن قبــل الطبيــب املقيــم صــدر بحقــه التقريــر الطبــي‬\n‫‪..........‬بتاريــخ ‪1433/3/26‬ه ـ صــادر مــن مستشــفى امللــك فيصــل‬\n‫متضمن ـ ًا ان ســبب الوفــاه توقــف مفاجــئ بالقلــب والــدوره الدمويــه‬\n‫والتنفســيه‪ .‬وان إخوتــه قامــوا بدفنــه دون إبــاغ اجلهــات االمنيــه عــن‬\n\n                                                                                         ‫‪44‬‬\n\f     ‫االصابــه التــي بــه وقــد مت دفنــه ولــم يبلــغ هــو اال بعــد مضــي أكثــر مــن‬\n     ‫أســبوع علــى الواقعــة وبضبــط أقــوال اخــوة املجنــي عليــه ذكــرت‬\n     ‫املدعوة‪........../‬شــقيقة طــريف القضيــة بــان املجنــي عليــه حضــر للمنــزل‬\n     ‫العائــد لوالدتهمــا والــذي تقطنــه رفقــة أختهــا املدعــى عليهــا وأثنــاء‬\n     ‫وجــوده بداخــل غرفتهــا حضــرت املدعــى عليهــا وحــدث بينهــا وبــن‬\n     ‫أخيهــا نقــاش بســبب عــدم رغبتهــا يف حضــوره للمنــزل وتطــور النقــاش‬\n     ‫الشــتباك ومضاربــه وقامــت املدعــى عليهــا بالتقــاط ســطل حديــدي‬\n     ‫وضربــت بــه رأس أخيهــا ممــا تســبب لــه بجــرح نــزف علــى أثــره قليــا مــن‬\n     ‫الــدم وقــام هــو باالتصــال علــى الدوريــات االمنيــه التــي حضــرت للموقــع‬\n     ‫وتنــازل الطرفــان عــن بعضهمــا البعــض وبعدهــا جلــس لديهــا باملنــزل‬\n     ‫لفتــرة وغــادرت معــه ملنزلــه وكان يقــود الســيارة وبعــد وصولهــم أطعــم‬\n     ‫القطــط العائــدة لــه ومتــدد علــى فراشــه وأحــس ببعــض اآلالم وطلبــت منــه‬\n     ‫الذهــاب للمستشــفى فرفــض ذلــك وبعــد فتــره أحســت انــه غــاب عــن‬\n     ‫الوعــي وأبلغــت ذويهــا وابنهــا الذيــن نقلــوه للمستشــفى وقــد أفــادت بــأن‬\n     ‫املجنــي عليــه لــه تاريــخ مرضــي قــدمي وكان يســعل حتــى يخــرج الــدم مــن‬\n     ‫فمــه وبضبــط أقــوال بقيــة أخــوة املجنــي عليــه توافقــت أقوالهــم مــع‬\n     ‫أقــوال أخيهــم املدعــي حيــال تعــرض املجنــي عليــه ألصابــه تــويف بعدهــا‬\n     ‫بثــاث ســاعات كمــا أخبرتهــم أختهــم ‪..........‬بذلــك ممــا يؤكــد أن‬\n     ‫املتوفــى بــه إصابــه أدت لنزيــف مــن رأســه وقــد توافقــت أقوالهــم بــأن‬\n     ‫املجنــي عليــه لــه تاريــخ مرضــي قــدمي وكان يســعل حتــى يخــرج الــدم مــن‬\n     ‫فمــه ولديــه ربــو مزمــن وأنهــم قامــوا بدفنــه بنــاء لتقريــر الطبيــب املختص‬\n     ‫الــذي لــم يذكــران ســبب الوفــاة االصابــه وأنهــم ابلغــوا أخاهــم األكبــر‬\n     ‫وهــو املدعــي باملشــكلة التــي حدثــت وطالبهــم بعــدم دفــن اجلثمــان‬\n\n\n‫‪45‬‬\n\f‫لرغبتــه يف احلضــور واالســتفادة مــن كليــة أخيــه املتــويف إلصابتــه هــو‬\n‫بفشــل كلــوي وحاجتــه ملتبــرع بضبــط أقــوال املدعو‪20........../‬عامــا‬\n‫ســعودي اجلنســيه وهــو ابــن املــرأه ‪ - ..........‬شــقيقة املجنــي عليــه‪ -‬وهــو‬\n‫مــن قــام بإســعافه حيــث حضــر لــه يف تلــك الليلــه مبنزلــه وهــو يكــح‬\n‫بشــده ويســتفرغ الــدم وطلــب منــه أن يقــوم بشــراء عشــاء وعنــد ذهابــه‬\n‫اتصلــت عليــه والدتــه وطلبــت منــه احلضــور الن املجنــي عليــه خالــه اليــرد‬\n‫عليهــم وحضــر ونقلــه ملســتوصف ‪..........‬ب‪ ..........‬فابلغــوه بانــه فــارق‬\n‫احليــاه ومت نقلــه بواســطة الهــال االحمــر ملستشــفى امللــك فيصــل مبكــه‬\n‫وعاينــه الطبيــب واصــدر أذنــه بدفنــه بســماع شــهادة الشــاهد ‪..........‬ابــن‬\n‫اخــت املجنــي عليــه افــاد بانــه اثنــاء غســل املجنــي عليــه شــاهد الــدم ينــزل‬\n‫مــن راســه كمــا شــاهد اثــر نــزف الــدم اثنــاء تكفينــه بضبــط شــهادة‬\n‫املدعو‪........../‬شــقيق املجنــي عليــه أفــاد مبشــاهدته نــزف الــدم مــن أخيه‬\n‫اثنــاء غســله لــه قبــل دفنــه وبضبــط شــهادة الشــاهد ‪ ..........‬افــاد بانــه‬\n‫حضــر ب‪ ..........‬وقــت وصــول االســعاف وكانــت متوقفــة بجــوار‬\n‫ســيارة‪..........‬وقاموا بانــزال املجنــي عليــه واركابــه باالســعاف ولــم‬\n‫يشــاهد أثــار دم وبعــد ان اخــذوا اجلثمــان للمستشــفى شــاهد اثــار نــزف‬\n‫بســيط مــن راس املجنــي عليــه وباملغســله اتصــل املدعــي ‪..........‬علــى أخيه‬\n‫‪..........‬وطلــب عــدم دفــن اجلثمــان لالســتفاده مــن الكلــي العائــده‬\n‫للمتوفــى حيــث انــه يعانــي مــن فشــل كلــوي وبســواله هــل يعانــي املجنــي‬\n‫عليــه مــن امــراض افــاد بانــه يعانــي مــن كتمــه بالصــدر وقــد حضــر‬\n‫جميــع أوليــاء الــدم وهــم إخــوة املجنــي عليــه وقــرروا تنازلهــم شــرعا عــن‬\n‫أختهــم وعــدم رغبتهــم يف نبــش قبــر أخيهــم وصــدق التنازل شــرع ًا ماعدا‬\n‫املدعــي الــذي يطالــب بالتحقيــق وإظهــار النتائــج وبإحالــة املدعــى عليهــا‬\n\n\n                                                                                         ‫‪46‬‬\n\f     ‫للجنــة الطبيــة الشــرعية صــدر بحقهــا التقريــر الطبــي النفســي رقــم‬\n     ‫‪..........‬وتاريــخ ‪1433/12/20‬ه ـ املتضمــن أن املدعــى عليهــا مســؤولة‬\n     ‫جنائي ـ ًا عــن تصرفاتهــا وباســتجواب املدعــى عليهــا ‪ ........../‬اقــرت‬\n     ‫بضــرب أخيهــا ليلــة الواقعــة بســطل حديــدي إثــر قيامــه بضربهــا وأنهــا‬\n     ‫شــاهدت نزيف ـ ًا دموي ـ ًا طفيــف مــن موقــع االصابــه حيــث ضربتــه يف‬\n     ‫رأســه بســطل حديــدي لقــاء تهجمــه عليهــا بســبب مشــاكل ســابقه‬\n     ‫ـاء لبــاغ املجنــي عليــه ومت‬‫بينهمــا وقــد حضــرت الدوريــات االمنيــه بنـ ً‬\n     ‫الصلــح مبوقــع احلادثــة وقــرر الطرفــان التنــازل عــن بعضهمــا البعــض‬\n     ‫وبعــد مغــادرة املجنــي عليــه ملنــزل أختــه اجتــه لبيتــه وبعــد مــرور مــا يقارب‬\n     ‫الثــاث ســاعات عانــى مــن الــم مفاجــي وتــويف قبــل إســعافه وصدقــت‬\n     ‫اقرارهــا شــرع ًا بذلــك وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى‬\n     ‫عليهــا بالقتــل شــبه العمــد بضــرب اخيهــا ‪........../‬بســطل حديــدي أثــر‬\n     ‫قيامــه بالتضــارب معهــا ممــا تســبب يف إصابتــه ووفاتــه متاثــر ًا بجراحــه‬\n     ‫وذلــك لألدلــة والقرائــن التاليــة‪ -1:‬إقرارهــا املصــدق شــرع ًا مبــا اســند‬\n     ‫اليهــا املــدون بالصفحــة رقــم( ‪) 5‬مــن دفتــر التحقيــق املرفــق لفــه رقــم(‪65‬‬\n     ‫)‪ -2‬اقوال الشهود املدونه مبلف االستدالل ا ملرفق لفه(‪-3)28/14/2/1‬‬\n     ‫محضــر االنتقــال واملعاينــه املــدون مبلــف االســتدالل املرفــق لفــه(‪-4)19‬‬\n     ‫التقريــر الطبــي املرفــق لفــه(‪ -5)10‬تقريــر رقم‪/21-270‬فحــوص‬\n     ‫وراثيه‪1433/‬ه ـ املرفــق بــاوراق القضيــه‪ -6‬دعــوى املدعــي وتطابقهــا مــع‬\n     ‫أقــوال اطــراف القضيــه واملدونــه مبلــف االســتدالل لفــه(‪ )1‬وبالبحــث‬\n     ‫عــن ســوابقها لــم يعثــر لهــا علــى ســوابق وحيــث ان مــا قامــت بــه املدعــى‬\n     ‫عليهــا فعــل محــرم ومعاقــب عليــه شــرعا لــذا أطلــب اثبــات صفــة القتــل‬\n     ‫شــبه العمــد ضدهــا إســتنادا إلــى املــواد(‪ )174-129-126‬واحلكــم‬\n\n\n‫‪47‬‬\n\f‫عليها بتطبيق االراده امللكيه رقم ‪ 2104/4/8‬بتاريخ‪1363/10/26‬هـ‬\n‫ورقم‪2624‬بتاريخ‪1372/4/9‬ه ـ وفقــا ملــا ورد يف قــرار املجلــس االعلــى‬\n‫رقــم ‪ 3/106‬بتاريــخ ‪1408/4/23‬ه ـ املؤيــد باالمــر الســامي‬\n‫رقم‪1197/4‬بتاريخ‪1409/6/12‬ه ـ علمــا ان احلــق اخلــاص انتهى بالتنازل‬\n‫ماعــدا احــد اوليــاء الــدم مــازال مطالبــا بحقــه وبســؤال املدعــى عليــه‬\n‫وكالــة ‪ ..........‬بالســجل املدنــي رقــم (‪ )..........‬مبوجب الوكالة الصادرة‬\n‫مــن كتابــة العــدل الثانيــة مبكــة املكرمــة رقــم (‪ )..........‬يف‬\n‫‪1434/2/4‬ه ـ قــال أطلــب إمهالــي للــرد علــى الئحــة املدعي العــام فجرى‬\n‫رفــع اجللســة ويف يــوم الثالثــاء املوافق‪1434/04/23‬ه ـ افتتحــت اجللســة‬\n‫الســاعة (‪ )10‬وفيهــا حضــر الطرفــان وقــدم املدعــى عليــه وكالــة ‪..........‬‬\n‫علــى دعــوى املدعــي العــام وهــذا نصــه (إشــارة إلــى الدعــوى املقيــدة لــدى‬\n‫فضيلتكــم برقــم (‪ )34108241‬وتاريــخ ‪1434/1/13‬ه ـ املقامــة مــن‬\n‫اإلدعــاء العــام واملطالــب فيهــا بإثبــات صفــة القتــل شــبه العمــد بحــق‬\n‫موكلتي‪..........‬التهامهــا بقتــل أخيهــا ‪..........‬واســتنادا للمــادة‬\n‫(‪174‬إجــراءات جزائيــة) أوجــز ردي يف النقــاط اآلتيــه‪ :‬أوال‪ :‬إن الغــرض‬\n‫مــن دعــوى املدعــي باحلــق اخلــاص هــو النكايــة مبوكلتــي وإحلــاق األذى‬\n‫بهــا ومحاولــة احلصــول علــى كســب مالــي واالنتقــام منهــا لوجــود‬\n‫خالفــات ســابقة بينهمــا حيــث كان املدعــي باحلــق اخلــاص وكيــا‬\n‫ملوكلتــي يف تصفيــة حقوقهــا يف تركــة والدهــا وحلصــول ضــرر علــى‬\n‫موكلتــي مــن املدعــي قامــت بإلغــاء وكالتــه وكذلــك بقيــة أخواتهــا‬\n‫اقتــداء بهــا ممــا جعــل املدعــي يحمــل الضغينــة لهــا مرفــق صــور‬\n‫الــوكاالت والفســخ‪ -‬ب‪ -‬مــا ذكــره املدعــي باحلــق اخلــاص يف شــكواه‬\n‫مــن أنــه لــم يعــرف بإصابــة املتوفــى برأســه قبــل دفنــه يخالــف الواقــع‬\n\n\n                                                                                     ‫‪48‬‬\n\f     ‫حيــث أن أخــوة املتوفــى أبلغــوا املدعــي مبــا حــدث بــن موكلتــي واملتوفى‬\n     ‫قبــل دفنــه وطالبهــم بعــدم دفــن اجلثمــان لرغبتــه يف احلضــور واالســتفادة‬\n     ‫مــن كليــة أخيــه املتوفــى إلصابــة املدعــي بالفشــل الكلــوي وحاجتــه‬\n     ‫ملتبــرع ؛ ورفــض الورثــة ذلــك وهــذا هــو الســبب احلقيقــي لرفعــه الدعــوى‬\n     ‫بعــد الوفــاة بعشــرة أيــام انتقامــا مــن موكلتــي املعارضــة لــه علــى وجــه‬\n     ‫اخلصــوص ومــن بقيــة أخوتــه لعــدم تلبيــة طلبــه وابتــدأ مبوكلتــي التــي‬\n     ‫اتهمهــا بالقتــل وقــام كذلــك برفــع دعــاوى متعــددة علــى بقيــة أخوتــه‬\n     ‫يطالبهــم مبطالبــات ماليــة ممــا يــدل علــى كيديــة دعــواه وعــدم صحــة‬\n     ‫زعمــه ثاني ـ ًا ‪ :‬عــدم وجــود أدلــة لتوجيــه التهمــة ضــد موكلتــي وجــه‬\n     ‫املدعــي العــام إلــى موكلتــي تهمــة القتــل شــبه العمــد بضــرب أخيهــا‬\n     ‫بســطل حديــدي أثــر قيامهمــا بالتضــارب مع ـ ًا ممــا تســبب يف إصابتــه‬\n     ‫ا وال أســاس‬  ‫ووفاتــه متأثــر ًا بجراحــه وهــذا غيــر صحيــح جملــة وتفصيـ ً‬\n     ‫لــه مــن الصحــة واملدعــي العــام ليــس لديــه البينــة علــى مــا قــال و قــد نفــى‬\n     ‫التقريــر الطبــي وأقــوال الشــهود الــذي ذكــر أن ســبب هــو إصابــة الرأس‬\n     ‫؛ فالوفــاة لــم حتــدث نتيجــة تأثــره بإصابــة الــرأس كمــا زعــم املدعــي‬\n     ‫العــام ألن اإلصابــة كانــت ســطحية ولــم تســبب غيــر نــزف طفيــف و‬\n     ‫هــذا مــا أكــده الشــهود ‪ ،‬أمــا األلــم الــذي حلــق املتوفــى قبــل وفاتــه كان‬\n     ‫مــن مضاعفــات مرضــه املزمــن بالربــو والكتمــة الصدريــة و الســعال‬\n     ‫حتــى خــروج الــدم وهــذا مــا أكــده التقريــر الطبــي و أقــوال الشــهود‬\n     ‫علــى النحــو التالــي‪ :‬أ‪ -‬ليــس يف الدعــوى املقامــة ضــد موكلتــي بينــة‬\n     ‫تثبــت صحــة التهمــة الباطلــة وكل مــا ورد يف الئحــة االدعــاء العــام مــن‬\n     ‫بينــات وقرائــن جميعهــا تثبــت بــراءة موكلتــي مــن التهمــة املوجهــة لهــا ؛‬\n     ‫فموكلتــي لــم تقصــد ضــرب أخيهــا إمنــا قصــدت دفــع أذاه عنهــا عنــد‬\n\n\n‫‪49‬‬\n\f‫ضربــه لهــا وشــد شــعرها بشــدة وأثنــاء ذلــك المســت يدهــا الســطل‬\n‫املوجــود بالغرفــة فضربتــه بهــا لوقــف ضربــه املبــرح ؛ فلــم يوجــد قصــد‬\n‫وال آلــة قاتلــة ولــم يثبــت شــرعا تســبب الضربــة يف وفاتــه ؛ فالتقريــر‬\n‫الطبــي رقــم ‪..........‬تاريــخ ‪1433/3/26‬ه ـ هــو الفيصــل يف القضيــة حيث‬\n‫نــص علــى أن ســبب الوفــاة [ توقــف مفاجــئ بالــدورة الدمويــة واجلهــاز‬\n‫التنفســي والقلــب ] ممــا يثبــت قطعــا أن الوفــاة كانــت طبيعيــة ويدحــض‬\n‫زعــم املدعــي العــام بــأن الوفــاة كانــت نتيجــة تأثــره بجــراح إصابــة‬\n‫الــرأس ‪ ،‬كمــا أن هــذه اإلصابــة تركــت جرحــا ســطحيا وقــد ذكــر‬\n‫ذلــك جميــع الشــهود فلــم يحــدث نزيــف أو مضاعفــات أدت إلــى الوفــاة ؛‬\n‫فلــو كانــت هــذه اإلصابــة ســببا يف الوفــاة لظهــر ذلــك يف التقريــر الطبي‬\n‫الــذي ذكــر أن ســبب الوفــاة توقــف مفاجــئ بالــدورة الدمويــة وليــس‬\n‫نزيــف حســب زعــم املدعــى العــام كمــا أن النزيــف املزعــوم لــن يخفــى‬\n‫علــى الطيــب الــذي أعــد التقريــر وإدارة املستشــفى كانــت ســتحول‬\n‫ـاء علــى‬\n        ‫امللــف للشــرطة للتحقيــق يف ذلــك ب‪ -‬ذكــر املدعــى العــام بنـ ً‬\n‫شــهادة جميــع أخــوة املتوفــى مبــا فيهــم املدعــي أن املتوفــى لــه تاريــخ‬\n‫مرضــي قــدمي وكان يســعل حتــى يخــرج الــدم مــن فمــه ولديــه ربــو مزمــن‬\n‫وقــد ذكــرت الشــاهدة ‪..........‬أن املتوفــى بعــد مشــاجرته مــع موكلتــي‬\n‫واتصالــه بالشــرطة وانتهــاء الشــكوى بالصلــح ؛ جلــس معهــا باملنــزل‬\n‫وكان طبيعيــا ال يشــتكي مــن أيــة اآلالم ثــم غــادرت معــه ملنزلــه وكان‬\n‫يقــود ســيارته وبعــد وصولهــم أطعــم القطــط ‪ ،‬ثــم بعــد ذلــك متــدد علــى‬\n‫الفــراش عندهــا أحــس ببعــض اآلالم ورفــض الذهــاب للمستشــفى إلــى‬\n‫أن فقــد الوعــي ‪ ،‬كمــا ذكــر الشــاهد ‪..........‬الــذي قــام بإســعاف‬\n‫املتوفــى بــأن املتوفــى كان يكــح بشــدة ويســتفرغ الــدم عنــد حضــوره‬\n\n\n                                                                                  ‫‪50‬‬\n\f     ‫إليــه ممــا يــدل يقينــا أن األلــم الــذي شــعر بــه املتوفــى وفقــد بعــده الوعــي‬\n     ‫كان بســبب مرضــه املزمــن ومــن الواضــح تعــرض املتوفــى لنوبــة ربــو‬\n     ‫حــادة أدت إلــى انســداد الشــعب الهوائيــة ممــا تــاه توقف الــدورة الدموية‬\n     ‫واجلهــاز التنفســي والقلــب وحدثــت الوفــاة ‪ ،‬ومــن املعلــوم طبيـ ًا أن مريض‬\n     ‫الربــو معــرض لنوبــات الربــو احلــادة والشــديدة التــي ميكــن أن تــؤدي إلــى‬\n     ‫الوفــاة إذا لــم تتــدارك وتعالــج يف الوقــت املناســب‪ ،‬خاصــة عنــد أولئــك‬\n     ‫الذيــن ال يشــعرون بشــدة األعــراض أو الذيــن ال يقــدرون خطورتهــا وقــد‬\n     ‫ذكــرت الشــاهدة ‪..........‬عنــد ســؤال احملقــق لهــا ( بعــد أن قامت املدعوة‬\n     ‫‪..........‬بضــرب املدعــو ‪..........‬ملــاذا لــم ينقــل إلــى املستشــفى ؟ ) فأجابــت‬\n     ‫بقولهــا (لــم يــرض ولــم يفكــر يف الضربــة وإمنــا كان يعانــي مــن صــدره‬\n     ‫‪ ،‬ممــا يعنــي أن أقــوال الشــهود تطابقــت مــع التقريــر الطبــي يف أن وفاتــه‬\n     ‫كان بســبب مرضــه املزمــن وليــس بســبب إصابــة الــرأس كمــا ذكــر‬\n     ‫املدعــي العــام الــذي اســتند علــى أقــوال املدعــي باحلــق اخلــاص ؛ فبالتالــي‬\n     ‫تنتفــي العالقــة الســببية بــن ضربــة الســطل ووفــاة ‪..........‬ممــا يعنــي‬\n     ‫انتفــاء مســؤولية موكلتــي عــن وفــاة أخيهــا ثالث ـ ًا ‪ :‬قــرار االتهــام جانبــه‬\n     ‫الصــواب و يحتــاج إلــى إعــادة نظــر أ‪ -‬وجــه االدعــاء العــام التهمــة‬\n     ‫ـاء علــى أقــوال مرســلة عاريــة مــن الصحــة وتخالــف الواقــع‬     ‫ملوكلتــي بنـ ً‬\n     ‫والتقاريــر الطبيــة ‪ ،‬حيــث اســتند علــى أقــوال املدعــي باحلــق اخلــاص دون‬\n     ‫بينــة تثبــت صحــة دعــواه يقــول الرســول صلــى اهلل عليــه وســلم (لــو يعطــى‬\n     ‫النــاس بدعواهــم‪ ،‬الدعــى رجــال أمــوال قــوم ودماءهــم‪ ،‬ولكــن البينــة‬\n     ‫علــى املدعــي واليمــن علــى مــن أنكــر) واســتناده يف اتهــام موكلتــي‬\n     ‫إلــى مجــرد أقــوال املدعــي ُيعــد إخــال بالقواعــد الشــرعية التــي تقضــي‬\n     ‫بــأن األصــل يف اإلنســان البــراءة والبــراءة يقــن ال يــزول بالشــك وال يعــدل‬\n\n\n‫‪51‬‬\n\f‫عــن ذلــك إال بدليــل قاطــع وال يجــوز املطالبــة بإثبــات تهمــة القتــل شــبه‬\n‫العمــد ملجــرد الشــك دون التثبــت مــن التهمــة اســتناد ًا إلــى قــول الرســول‬\n‫‪ -‬صلــى اهلل عليــه وســلم ‪ ( -‬ادرؤا احلــدود بالشــبهات فــإن كان لــه‬\n‫مخــرج فخلــوا ســبيله فــإن اإلمــام ليخطــئ يف العفــو خيــر مــن أن يخطــئ‬\n‫يف العقوبــة ) ويقــول بــن تيميــة‪« :‬إمنــا العقوبــة علــى ذنــب ثابــت» [فتــاوى‬\n‫ابــن تيميــة (‪ ]107/28‬بــل إن جميــع األدلــة املذكــورة يف الئحــة اإلدعــاء‬\n‫العــام تثبــت بــراءة موكلتــي مــن التهمــة الباطلــة املنســوبة لهــا ب‪ -‬طالــب‬\n‫االدعــاء العــام بإثبــات صفــة القتــل شــبه العمــد بحــق موكلتــي وهــذا‬\n‫االتهــام يفتقــد ألركان اجلــرم املطالــب بإثباتــه حيــث أن القتــل شــبه‬\n‫العمــد هــو أن يقصــد الفعــل دون نيــة القتــل وحيــث أن ضربــة موكلتــي‬\n‫علــى رأس املتوفــى لــم تتســبب يف قتلــه وإمنــا كانــت وفاتــه طبيعيــة كمــا‬\n‫هــو مبــن يف التقريــر الطبــي فبالتالــي ال ينطبــق هــذا الوصــف عليهــا‬\n‫لعــدم ارتكابهــا اجلــرم املنســوب إليهــا وعــدم وجــود جرميــة يف األصــل‬\n‫لطبيعيــة الوفــاة ت‪ -‬ذكــر املدعــي العــام يف مذكرتــه ‪ -‬ص‪ 2‬ســطر‪، 6‬‬\n‫أنــه [ بضبــط أقــوال بقيــة أخــوة املجنــى عليــه توافقــت أقوالهــم مــع أقــوال‬\n‫أخيهــم املدعــي حيــال تعــرض املجنــى عليــه إلصابــة توفــى بعدهــا بثــاث‬\n‫ســاعات كمــا أخبرتهــم أختهــم ‪ ]..........‬و لعــدم وجــود بينــات علــى دعوى‬\n‫املدعــى العــام حــاول االســتناد علــى هــذا القــول حملاولــة إدانــة موكلتــي‬\n‫حيــث ذكــر [ ممــا يؤكــد أن املتوفــى بــه إصابــة أدت لنزيــف مــن رأســه‬\n‫] وهــذا اســتناد خاطــئ حيــث أن مــا ذكرتــه الشــاهدة ‪..........‬أنــه بعــد‬\n‫ا مــن الــدم وهــذا يــدل‬  ‫ضربــة الســطل حــدث جــرح نــزف علــى أثــره قليـ ً‬\n‫علــى أن اجلــرح ســطحي وليــس باجلــرح الــذي حــدث علــى أثــره نزيــف‬\n‫غزيــر أو نزيــف داخلــي باملــخ أدى إلــى املــوت ‪ ،‬والصحيــح أن املتوفــى‬\n\n\n                                                                                       ‫‪52‬‬\n\f     ‫حانــت منيتــه يف هــذه الســاعة وكانــت وفاتــه طبيعيــة وال ميكــن ربــط‬\n     ‫وفاتــه باألحــداث التــي حدثــت قبــل الوفــاة بســاعات ألن هــذه األحــداث‬\n     ‫لــم يثبــت أنهــا أحدثــت الوفــاة ث‪ -‬طالــب االدعــاء العــام بإثبــات صفــة‬\n     ‫القتــل شــبه العمــد بحــق موكلتــي وذلــك عــن التهمــة املنســوبة إليهــا‬\n     ‫وحيــث نــص القــرار الــوزاري رقــم ‪ 1900‬بتاريــخ ‪1428/7/9‬ه ـ علــى‬\n     ‫اجلرائــم املوجبــة لإليقــاف حلــن االنتهــاء منهــا شــرع ًا ومنهــا جرائــم القتــل‬\n     ‫العمــد وشــبه العمــد و إن إطــاق ســراح موكلتــي يــدل علــى أن االدعــاء‬\n     ‫العــام غيــر متأكــد مــن التهمــة التــي وجههــا ملوكلتــي وأن ليــس هنــاك‬\n     ‫مبــرر إليقافهــا ج‪ -‬ذكــر املدعــي العــام بيانــات خاطئــة يف مذكرتــه‬\n     ‫بغــرض محاولــة إدانــة موكلتــي منهــا ذكــره يف ‪-‬ص‪ -1‬أن موكلتــي‬\n     ‫موقوفــة علــى ذمــة القضيــة وهــذا غيــر صحيــح حيــث أن موكلتــي أفــرج‬\n     ‫عنهــا قبــل حتويــل الدعــوى للمحكمــة د‪ -‬قــال املدعــي العــام أن التقريــر‬\n     ‫الطبــي النفســي رقــم ‪..........‬تاريــخ ‪1433/12/20‬هـ ذكر أنها‪ .‬مســؤولة‬\n     ‫جنائيــة عــن تصرفاتهــا يف محاولــة منــه لالســتناد علــى هــذا التقريــر يف‬\n     ‫إدانــة موكلتــي ‪ ،‬وهــذا التقريــر ال يعطــي املدعــي العــام دليــل علــى أنهــا‬\n     ‫مســؤولة جنائيــا عــن وفــاة أخيهــا لعــدم وجــود إدانــة يف التقريــر الطبــي‬\n     ‫املذكــور حيــث ذكــر التقريــر أنهــا تعتبــر مســؤولة جنائيــا يف حــال‬\n     ‫إدانتهــا يف القضيــة ولــم يثبــت شــرعا ذلــك رابع ـ ًا ‪ :‬أجيــب علــى األدلــة‬\n     ‫والوقائــع التــي اســتند إليهــا املدعــي العــام بإيجــاز يف التالــي باإلضافــة‬\n     ‫إلــى مــا ذكــر أعــاه‪ -1 :‬إقرارهــا املصــدق شــرع ًا مبــا أســند إليهــا‬\n     ‫بالصفحــة رقــم ‪ 5‬مــن دفتــر التحقيــق املرفــق لفــه ‪ 65‬لــم تقــر موكلتــي‬\n     ‫بقتــل شــقيقتها كمــا ذكــر املدعــي العــام وإمنــا ذكــر أنهــا حاولــت صــد‬\n     ‫هجومــه بضربــة علــى رأســه وبالتالــي حــاول املدعــي العــام جتزئــة إقــرار‬\n\n\n‫‪53‬‬\n\f‫موكلتي حملاولة إدانتها بطريقة خاطئة مخالفا بذلك ‪،‬م‪106‬مرافعات‬\n‫شــرعية‪ -‬التــي تنــص علــى أنــه ال يتجــزأ اإلقــرار علــى صاحِ ِبــه‪ ،‬فــا‬\n‫ويتــرك الصا ِلــح ل ـ ُه‪ ،‬بــل يؤخــذ جملــة واحِ ــدة ‪،‬‬  ‫يؤخــذ مِ نــه الضــار ِبــه ُ‬\n‫فموكلتــي أقــرت بضربــه علــى رأســه ولــم تقــر بالقتــل وقــد ثبــت شــرعا‬\n‫مبوجــب التقريــر الطبــي و شــهادة الشــهود أن الوفــاة كانــت بســبب‬\n‫توقــف الــدورة الدمويــة واجلهــاز التنفســي والقلــب وليــس بســبب إصابــة‬\n‫الــرأس كمــا زعــم املدعــي العــام ‪ -2‬أقــوال الشــهود املدونــة مبلــف‬\n‫االســتدالل املرفــق لفــه (‪ )28/14/2/1‬لــم يذكــر الشــهود أن إصابــة‬\n‫الــرأس أدت إلــى الوفــاة إمنــا ذكــروا أنهــم شــاهدوا دم قليــا برأســه بــل‬\n‫إن الذيــن شــهدوا احلــادث ذكــروا أن املتوفــى كان يعانــي قبــل وفاتــه‬\n‫مــن صــدره و ليــس مــن إصابــة الــرأس كمــا هــو موضــح أعــاه ‪-3‬‬\n‫محضــر االنتقــال واملعاينــة املــدون مبلــف االســتدالل املرفــق لفــة (‪)19‬‬\n‫جميــع مــا ذكــر بهــذا احملضــر ال يوجــد فيــه مــا يــدل علــى تهمــة القتــل‬\n‫‪ -4‬التقريــر الطبــي املرفــق لفــة ‪ 10‬وهــذا التقريــر جــزم بــكل وضــوح أن‬\n‫الوفــاة كانــت بســبب توقــف مفاجــئ بالقلــب والــدورة الدمويــة واجلهــاز‬\n‫التنفســي ممــا يثبــت بــراءة موكلتــي مــن التهمــة الباطلــة املنســوبة إليهــا‬\n‫‪ -5‬تقريــر رقــم‪ ..........‬املرفــق بــأوراق القضيــة هــذا التقريــر ال يوجــد بــه‬\n‫مــا يــدل علــى إثبــات التهمــة ‪ -6‬دعــوى املدعــي وتطابقهــا مــع أقــوال‬\n‫أطــراف القضيــة واملدونــة مبلــف االســتدالل لفــة ‪ 1‬ال يصــح االســتناد‬\n‫علــى أقــوال املدعــي دون بينــات تثبــت صحــة دعــواه يقــول الرســول عليــه‬\n‫الصــاة والســام ‪ -‬البينــة علــى املدعــي ‪ ،‬فلــم يقــدم املدعــي أيــة بينــة‬\n‫ـاء علــى مــا ســبق تقدميــه أعــاه ألتمــس‬   ‫تثبــت صحــة دعــواه خامس ـاً‪ :‬بنـ ً‬\n‫مــن فضيلتكــم احلكــم بــرد دعــوى املدعــي العــام املبنيــة علــى دعــوى‬\n\n\n                                                                                            ‫‪54‬‬\n\f     ‫املدعــي باحلــق اخلــاص طبقــا للمــادة ‪ 4 -‬مرافعــات شــرعية ‪ -‬وألتمــس‬\n     ‫احلكــم ببــراءة موكلتــي مــن التهمــة الباطلــة املنســوبة إليهــا لعــدم ثبــوت‬\n     ‫دعــوى املدعــي العــام واخلــاص) وبعــرض ذلــك علــى املدعــي العــام قــال‬\n     ‫الصحيــح مــا ذكرتــه وقــد ضمنــت الئحــة دعــواي مــا لــدي مــن بينــات‬\n     ‫وقرائــن تثبــت صحــة مــا أدعيــت بــه وليــس لــدي ســواه فجــرى رفع اجللســة‬\n     ‫لدراســة املعاملــة ويف يــوم الســبت املوافــق‪ 1434/05/25‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة (‪ )8:15‬وفيهــا حضــر الطرفــان وقــد جــرى اإلطــاع علــى‬\n     ‫التقريــر الطبــي املرفــق باملعاملــة لفــة (‪ )10‬وتضمــن أن نتيجــة الكشــف‬\n     ‫الطبــي تــرى أن ســبب الوفــاة توقــف مفاجــئ بالقلــب والــدورة الدمويــة‬\n     ‫والتنفســية وصــدر التقريــر بتاريــخ ‪1433/3/26‬ه ـ كمــا جــرى اإلطالع‬\n     ‫علــى إقــرار املدعــى عليهــا املــدون علــى ملــف التحقيــق لفــة (‪ )66‬صحيفــة‬\n     ‫(‪ )5‬وهــذا نصــه (أقــر وأعتــرف أنا‪........../‬ســعودية اجلنســية مبوجــب‬\n     ‫ســجل مدنــي رقــم (‪ )..........‬وأنــا بكامــل قــواي العقليــة واجلســدية‬\n     ‫املعتبــرة شــرع ًا مــن غيــر ضغــط أو إكــراه بأنــه بتاريــخ ‪1433/3/26‬ه ـ‬\n     ‫بعــد صــاة العشــاء حضــرت لغرفــة أختــي ‪..........‬التــي تقطــن معــي يف‬\n     ‫نفــس املنــزل ووجــدت أخــي ‪..........‬لديهــا بالغرفــة وحيــث أن املذكــور‬\n     ‫بينــي وبينــه مشــاكل ســابقة حيــث أنــه يتلفــظ علـ َـي وال يقــوم علــى‬\n     ‫خدمتــي وحصــل بيننــا نقــاش حــاد تطــور الشــتباك باأليدي وقــام بضربي‬\n     ‫وشــدي مــن شــعري ويف حلظــة وقعــت يــدي علــى ســطل حديــدي قمــت‬\n     ‫بجذبــه وضربــت ‪..........‬بــه علــى رأســه وفرقــت بيننــا أختــي ‪..........‬‬\n     ‫وشــاهدت قطــرات مــن الــدم تخــرج مــن مــكان اإلصابــة التــي فأتصــل‬\n     ‫هــو علــى الدوريــات األمنيــة وحضــروا إلــى املوقــع وحــل االشــكال بيننــا‬\n     ‫ا ‪..........‬‬\n                ‫وقررنــا التنــازل عــن بعضنــا البعــض بنفــس املوقــع ومكــث قليـ ً‬\n\n\n‫‪55‬‬\n\f‫مــن ثــم غــادر املنــزل يقــود ســيارته وبرفقتــه أختــي ‪..........‬وبعــد منتصــف‬\n‫الليــل اتصلــت علـ َـي أختــي صبــاح وســألني عــن املشــكلة وقالــت أن‬\n‫‪..........‬مت نقلــه للمستشــفى فاقــد ًا للوعــي ولــم أقتنــع مبــا ذكــرت فقمــت‬\n‫بــدوري باالتصــال علــى أختــي ‪..........‬التــي قامــت بالدعاء علـ َـي وأخبرتني‬\n‫أن ‪..........‬أنتقــل إلــى رحمــة اهلل وقمــت بالذهــاب إلى املستشــفى للتأكد‬\n‫مــن الواقــع ولــم أمتكــن مــن شــاهدته وأبلغــت بأنــه يف ثالجــة املوتــى هــذا‬\n‫مــا لــدي وأذنــت ملــن يشــهد واهلل خيــر الشــاهدين) وبعرضــه علــى املدعــى‬\n‫عليــه وكالــة قــال نعــم صــدر هــذا اإلقــرار مــن موكلتــي كمــا جــرى‬\n‫االطــاع علــى اســتجواب شــقيقة املتــويف وهــي ‪..........‬املــدون علــى‬\n‫الصحيفــة (‪ )13‬مــن ملــف التحقيــق لفــة (‪ )1‬وتضمــن أن املتــويف كان‬\n‫يعانــي مــن صــدره وبعــد ضربــه مــن قبــل املدعــى عليهــا أتصــل علــى‬\n‫الشــرطة ولــم يرضــى أن ينقــل إلــى املستشــفى والــدم الــذي خــرج منــه‬\n‫كان قليــل جــد ًا وخــرج يقــود ســيارته كمــا جــرى االطــاع علــى‬\n‫اســتجواب ‪ ..........‬علــى الصحيفــة (‪ )13‬مــن ملــف التحقيــق لفــة (‪)14‬‬\n‫و‪..........‬علــى الصحيفــة (‪ )9‬مــن ذات امللــف وتضمــن أن املتــويف كان‬\n‫يعانــي مــن ألــم يف صــدره كمــا أفــاد ‪ ..........‬يف الصحيفــة (‪ )15‬أن‬\n‫املتــويف كان يعانــي مــن ألــم يف صــدره ويســتفرغ دم وكان يعانــي مــن‬\n‫األلــم يف صــدره مــن خمــس ســنوات تقريبـ ًا وكان يتحــدث معــه وأعطــاه‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n                                            ‫مبلغـ ًا مــن املــال لشــراء عشــاء وبنـ ً‬\n‫ومــا تضمنــه التقريــر الطبــي املذكــور أعــاه ومــا جــاء يف اســتجوابات‬\n‫أشــقاء وأقــارب املتــويف مــن أنــه كان يعانــي مــن مــرض يف صــدره وأن‬\n‫ا فلــم يثبــت لــدي قتــل املدعــى‬ ‫الــدم الــذي نــزف معــه املتــويف كان قليـ ً‬\n‫عليهــا ألخيهــا ‪..........‬وحكمــت بصــرف النظــر عــن طلــب املدعــي العــام‬\n\n\n                                                                                          ‫‪56‬‬\n\f     ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه وكالــة قناعتــه‬\n     ‫باحلكــم كمــا قــرر املدعــي العــام اإلعتــراض بالئحــة وبــاهلل التوفيــق ‪،‬‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n     ‫‪ 1434/05/25‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى مــا ال نبــي‬\n                                                   ‫بعده ‪ ،‬وبعد ‪:‬ـ فقد جرى منا نحن‬\n     ‫قضــاة الدائــرة اجلزائيــة الثانيــة يف محكمــة االســتئناف مبنطقــة مكــة‬\n                                                                    ‫املكرمــة اإلطــاع‬\n     ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة‬\n     ‫املكرمــة املســاعد الشــيخ ‪........../‬برقــم ‪ 34108241‬وتاريــخ‬\n                                                                       ‫‪1434 /7 /9‬ه ـ‬\n     ‫املرفــق بهــا القــرار الشــرعي رقــم ‪ 34223913‬وتاريــخ ‪1434/5/27‬ه ـ‬\n     ‫الصــادر مــن فضيلتــه املتضمــن دعــوى املدعــي العــام ضــد املــرأة‪........../‬‬\n     ‫املتهمــة يف قضيــة قتــل احملكــوم فيــه مبــادون باطنــه ‪ .‬وبدراســة‬\n     ‫القراروصـ ـ ــورة ضبطــه والئحتــه االعتراضيــة تقررباالكثريــة املوافقــة‬\n     ‫علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                      ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪57‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":42,"source_page_end":57,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"330249f822c347f0fb83dc421f4bb00850c17eac4e8f242158e752b24bc6872f","normalized_text_hash":"32dd5d515ff532024c86e00c0323a67974c824ec3e2f9b0094090ad92dfb02a3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p42-34223913"},{"id":"7e64f08d-ebe6-503d-ad6b-aa315c821fcc","document_type":"judgment","category":"judicial","subcategory":"general","title":"-1األمر السامي رقم 10711يف 1393/5/2ه وقرار مجلس القضاء األعلى بهيئته الدائمة برقم 3/51يف 1409/3/6ه املؤيد باألمر السامي رقم /1197/4م يف 1409/6/2ه املبلغ بالتعميم /8ت 95/يف 1409/7/25ه بشأن تطبيق اإلرادة امللكية على قاتل العمد وشبه العمد إذا تنازل أولياء الدم عن القصاص (التصنيف املوضوعي","document_number":"3460109","case_number":"3466575","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة صك بإثبات تنازل أولياء الدم عن القصاص","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/11","year":"1434","subject":"-1األمر السامي رقم 10711يف 1393/5/2ه وقرار مجلس القضاء األعلى بهيئته الدائمة برقم 3/51يف 1409/3/6ه املؤيد باألمر السامي رقم /1197/4م يف 1409/6/2ه املبلغ بالتعميم /8ت 95/يف 1409/7/25ه بشأن تطبيق اإلرادة امللكية على قاتل العمد وشبه العمد إذا تنازل أولياء الدم عن القصاص (التصنيف املوضوعي","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3460109 :‬تاريخه‪1434/3/11 :‬هـ‬\n                    ‫رقم الدعوى‪3466575:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34197846‬تاريخه‪1434/4/24 :‬هـ‬\n\n\n‫قتــل ‪ ،‬قتــل عمــد ‪ ،‬اســتخدام ســاح نــاري ‪ ،‬إقــرار املدعــى عليــه ‪ ،‬تنــازل‬\n‫عــن حــق خــاص ‪ ،‬تقريــر طبــي نفســي‪ ،‬تقريــر طبــي شــرعي ‪ ،‬تقريــر أدلــة‬\n                     ‫جنائيــة‪ ،‬ثبــوت إدانــة‪ ،‬عقوبــة عائــدة للجهــة املختصــة‪.‬‬\n\n\n\n\n‫‪ -1‬األمــر الســامي رقــم ‪ 10711‬يف ‪1393/5/2‬ه ـ وقــرار مجلــس القضــاء‬\n‫األعلــى بهيئتــه الدائمــة برقــم‪ 3/51‬يف ‪1409/3/6‬ه ـ املؤيــد باألمــر‬\n‫الســامي رقــم ‪/1197/4‬م يف ‪1409/6/2‬ه ـ املبلــغ بالتعميــم ‪/8‬ت‪ 95/‬يف‬\n‫‪1409/7/25‬ه ـ بشــأن تطبيــق اإلرادة امللكيــة علــى قاتــل العمــد وشــبه‬\n‫العمــد إذا تنــازل أوليــاء الــدم عــن القصــاص (التصنيــف املوضوعــي‬\n                                           ‫لتعاميــم وزارة العــدل ‪.)782/1‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن قبــل واالدعــاء العــام للمدعــى عليــه لقيامه بقتل‬\n‫شــقيقته عمــدا وعدوانــا وطلــب إثبات ما أســند إليــه وإفهامه بأن عقوبته‬\n‫لــدى اجلهــة املختصــة وفــق اإلرادة امللكيــة ‪ -‬حيــث تلقــت الشــرطة بالغــا‬\n‫مــن الهــال األحمــر بتعــرض إمرأة لطلقات ناريــة أدت لوفاتها ‪ -‬ضبطت‬\n‫إفــادة املجنــي عليهــا قبــل وفاتهــا وحاصلــه قيــام شــقيقها‪ -‬املدعــى عليــه‪-‬‬\n‫بإطــاق النــار عليهــا وهــي يف غرفتهــا بشــكل مفاجــئ وال تعلــم الدافــع‬\n\n                                                                                     ‫‪58‬‬\n\f     ‫غيــر أنــه يعانــي مــن مــرض نفســي وشــكوك وضــاالت ‪ ،‬أقــر املدعــى‬\n     ‫عليــه حتقيقــا بقتلــه شــقيقته ألنــه ســمع مــن أحــد أقاربــه بــأن لشــقيقته‬\n     ‫عالقــة مــع أحــد الرجــال ‪ ،‬أنكــر القريــب مــا نســبه إليــه املدعــى عليــه‬\n     ‫ومبواجهتــه باملدعــى عليــه تراجــع وقــرر بأنهــا كانــت مجــرد شــكوك‬\n     ‫لديــه ولــم يســمع منــه ذلــك ‪ ،‬صــدر مــن احملكمــة العامــة صــك بإثبــات‬\n     ‫تنــازل أوليــاء الــدم عــن القصــاص‪ ،‬صــدر تقريــر طبــي مــن مستشــفى‬\n     ‫الصحــة النفســية بأنــه جــرى تشــخيص حالتــه نوبــات صــرع كبــرى وأنــه‬\n     ‫يعانــي مــن اضطــراب يف التفكيــر وشــكوك وضــاالت غيــر مبــررة‬\n     ‫يف ســلوك شــقيقته كمــا صــدر تقريــر آخــر بأنــه ونظــرا ملــا يعانيــه‬\n     ‫مــن صــرع مصحــوب بأعــراض ذهنيــة مصحوبــة مبعتقــدات خاطئــة‬\n     ‫وســوء احلكــم علــى األمــور فــإن ذلــك يخفــف عنــه املســؤولية اجلنائيــة‬\n     ‫‪ ،‬بعــرض الدعــوى علــى املدعــى عليــه أقــر بقيامــه بقتــل شــقيقته ودفــع‬\n     ‫بأنــه مريــض نفســي ويعانــي مــن صــرع وقــد انتابــه حالــة نفســية شــديدة‬\n     ‫قــام علــى إثرهــا بالدخــول علــى أختــه يف غرفتهــا وإطــاق النــار عليهــا‬\n     ‫مــن مســدس وتوفيــت بعــد ذلــك ‪ ،‬جــرى االطــاع علــى شــهادة الوفــاة‬\n     ‫املتضمنــة ثبــوت وفــاة شــقيقته ‪ ،‬عليــه فقــد قــررت احملكمــة ثبــوت قيــام‬\n     ‫املدعــى عليــه بقتــل شــقيقته عمــدا وعدوانــا وإفهامــه بــأن عقوبتــه عائــدة‬\n     ‫للجهــة املختصــة ‪ ،‬قــرر املدعــى عليــه القناعــة بينمــا قــرر املدعــي العــام‬\n         ‫االعتــراض بــدون الئحــة ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪59‬‬\n\f‫اجلزائيــة‬\n   ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة‬\n‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة االحســاء برقــم وتاريــخ ‪ 1434/02/10‬ه ـ املقيدة‬\n‫باحملكمــة برقــم وتاريــخ ‪ 1434/02/10‬ه ـ ففــي يــوم األربعــاء‬\n‫املوافــق‪ 1434/03/04‬ه ـ افتتحــت اجللســة الســاعة ‪ 12 : 00‬وفيهــا‬\n‫حضــر املدعــي ‪..........‬وادعــى ضــد احلاضــر معــه ‪..........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪..........‬قائــا يف دعــواه إنــه بتاريــخ‬\n‫‪1433/2/15‬ه ـ تلقــت غرفــة عمليــات شــرطة محافظــة األحســاء بالغـ ًا‬\n‫مــن الهــال األحمــر الســعودي عــن قيامهــم بنقــل املــرأة تدعــى‪.......... /‬‬\n‫إلــى مستشــفى امللــك فهــد بالهفــوف علــى إثــر تعرضهــا لإلصابــة بعــدة‬\n‫طلقــات ناريــة أثنــاء وجودهــا مبنزلهــا وباالنتقــال واملعاينــة جلســم املجنــي‬\n‫عليهــا اتضــح وجــود عــدد تســع فتحــات بعضهــا دخــول وبعضهــا اآلخــر‬\n‫خــروج فيمــا أظهــرت األشــعة التــي اتخــذت علــى جســمها وجــود طلقتــن‬\n‫مســتقرتني بها أحدهما يف الظهر واألخرى بالركبة اليســرى ومبعاينة‬\n‫املنــزل محــل ارتــكاب اجلرميــة اتضــح انــه منــزل حديــث البنــاء يقــع يف‬\n‫حــي ‪..........‬ومبعاينــة مســرح احلــادث اتضــح أنهــا غرفــة مبســاحة (‪4,4‬م)‬\n‫حتتــوي علــى ســرير نــوم مفــرد ودوالب صغيــر وطاولــة كمبيوتــر وطاولة‬\n‫أخــرى عليهــا جهــاز تلفزيــون وقــد تبــن أن اجلــدار للجهــة الشــرقية‬\n‫صناعــي (جبــس بــورد) فيمــا شــوهد علــى ارتفــاع (‪120‬ســم) مــن اجلــدار‬\n‫عــدد أربــع فتحــات دخــول متقاربــة ملقاذيــف ناريــة جميعهــا نافــذة للجهــة‬\n‫األخــرى مــن اجلــدار والتــي مت تتبعهــا واتضــح اســتقرارها يف دوالب‬\n\n                                                                                      ‫‪60‬‬\n\f     ‫مالبــس مــن الغرفــة املجــاورة يف الوقــت الــذي شــوهد مقذوفــن ناريــن‬\n     ‫علــى أرضيــة الغرفــة محــل اإلصابــة وأيض ـ ًا بقعتــي دمــاء صغيــرة علــى‬\n     ‫الســجادة حيــث قــام ذوي املجنــي عليهــا بتســليم جهــة التحقيــق ســاح‬\n     ‫نــاري مــن نــوع مســدس ‪ ....‬ماركــة ‪ ....‬عيــار (‪ )22‬يحمــل الرقــم (‪)..........‬‬\n     ‫يتســع إلــى عــدد تســع طلقــات ناريــة وبفحصــه مبدئي ـ ًا اتضــح بــأن‬\n     ‫اســطوانة الســاح حتتــوي علــى عــدد تســعة ظــروف ناريــة فارغــة وتبــن‬\n     ‫أن الفاعــل املدعــى عليــه وهــو شــقيق املجنــي عليهــا وبتفتيــش غرفــة‬\n     ‫املدعــى عليــه عثــر علــى ســاح نــاري آخــر نــوع ‪ ....‬عيــار (‪ ).....‬يحمــل رقــم‬\n     ‫(‪ )..........‬مــع خزنــن بــدون طلقــات ناريــة (فــرزت لــه أوراق مســتقلة‬\n     ‫للســاح) وبضبــط إفــادة املجنــي عليهــا قبــل وفاتهــا أفــادت أنــه بعــد‬\n     ‫منتصــف ليــل يــوم الواقعــة كانــت جالســة مبفردهــا يف غرفتهــا مبنــزل‬\n     ‫والدهــا يف حــي ‪..........‬وقــد حضــر مــن خــارج املنــزل شــقيقها املدعــى‬\n     ‫عليــه الــذي دخــل عليهــا يف غرفتهــا وقــام دون ســابق نقــاش معهــا بإشــهار‬\n     ‫ســاح نــاري اجتاههــا ومــن ثــم مباشــرتها بإطــاق عــدة طلقــات ناريــة‬\n     ‫اجتاههــا ممــا أدى إلــى إصابتهــا يف العمــود الفقــرة والركبــة اليســرى‬\n     ‫والصــدر وقــد مت مناقشــتها عــن أســباب إقــدام شــقيقها بإطــاق النــار‬\n     ‫عليهــا وذكــرت بأنــه ال يوجــد أيــة ســوى أن شــقيقها يعانــي مــن مــرض‬\n     ‫نفســي واضطرابــات يف التفكيــر وشــكوك وضــاالت غيــر مبــررة‬\n     ‫ويتلقــى العــاج منــذ فتــرة طويلــة يف مستشــفى الصحــة النفســية‬\n     ‫باألحســاء والــذي توفيــت فيمــا بعــد نتيجــة اإلصابــة التــي حلقــت بهــا‬\n     ‫وباســتجواب املدعــى عليــه أقــر أنــه يف مســاء يــوم الواقعــة اجتــه برفــق‬\n     ‫خالــه‪.......... /‬واملدعــو‪.......... /‬إلــى محافظــة ‪ ...‬حلضــور عــزاء أحــد‬\n     ‫أقاربــه ويف طريــق عودتــه إلــى محافظــة األحســاء اســتمع إلــى نقــاش‬\n\n\n‫‪61‬‬\n\f‫كان يــدور بــن خالــه املذكــور ‪..........‬حيــث صــرح خالــه دخــول شــخص‬\n‫يدعــى ‪..........‬علــى شــقيقته ‪..........‬يف املنــزل وبعــد وصولهــم إلى محافظة‬\n‫األحســاء دخــل إلــى منزلــه ثــم وقــف علــى بــاب غرفــة شــقيقاته وقــام‬\n‫ينظــر اليهــن وقــد كــن نائمــات جميعهــن يف الوقــت الــذي اجتــه إلــى‬\n‫غرفتــه بالــدور العلــوي مــن املنــزل وأخــذ ســاحه النــاري مــن نوع مســدس‬\n‫‪ ....‬ماركــة ‪ .....‬عيــار (‪ )22‬يحمــل الرقــم (‪ )..........‬ومــن ثــم نــزل مباشــرة‬\n‫إلــى الغرفــة اخلاصــة بشــقيقته‪.......... /‬وقــام بالدخــول عليهــا ومباغتتهــا‬\n‫وذلــك بإطــاق عــدة أعيــرة ناريــة اجتاههــا ممــا أدى إلــى إصابتهــا بعــدة‬\n‫طلقــات نتــج عنــه ســقوطها علــى األرض وذلــك علــى خلفيــة مــا صــرح بــه‬\n‫خالــه يف الســيارة حيــث دخــول شــخص عليهــا وبضبــط إفــادة ‪ ....‬املدعــى‬\n‫عليــه‪.......... /‬مــا أورده املدعــى عليــه مــن حيــث تصريحــه لــه مبعلومــات‬\n‫مفادهــا دخــول شــخص يدعــى‪.......... /‬علــى املجنــي عليهــا والــذي نفــى‬\n‫تلــك املعلومــة وذكــر أنــه يف الليلــة التــي حدثــت فيهــا الواقعــة كان‬\n‫واملدعــى عليــه وقريبــه ‪..........‬قادمــن مــن محافظــة ‪ ...‬بعــد حضورهــم‬\n‫وفــاة أحــد أبنــاء جماعتهــم ويف طريــق عودتهــم لإلحســاء جــاءت ســيرة‬\n‫املتوفــى‪.......... /‬مــن بــاب الذكــرى فقــط ثــم فوجــئ عقــب وصولهــم‬\n‫لإلحســاء بإقــدام املدعــى عليــه علــى جرميتــه جتــاه املجني عليهــا وبضبط‬\n‫إفــادة املرافــق ‪.......... /‬لهــم يف الســيارة حــول مــا ورد مــن حديــث يف‬\n‫الســيارة أثنــاء ركوبــه معهــم املدعــى عليــه وحيــث نفــى ذلــك وكان يف‬\n‫الليلــة التــي حدثــت فيهــا الواقعــة هــو واجلانــي وخاله قادمــن من محافظة‬\n‫اخلــرج بعــد حضورهــم عــزاء أحــد أبنــاء جماعتهــم ويف طريقهم لإلحســاء‬\n‫جــاءت ســيرة املتوفى‪..........‬مــن بــاب الذكــرى فقــط ثــم فوجــئ عقــب‬\n‫وصولهــم لإلحســاء بإقــدام املدعــى عليــه علــى جرميتــه جتــاه املجنــي‬\n\n\n                                                                                       ‫‪62‬‬\n\f     ‫عليهــا فيمــا ذكــر أن املدعــى عليــه يعانــي مــن مــرض نفســي واضطــراب‬\n     ‫يف التفكيــر وشــكوك جتــاه شــقيقته وبضبــط والــدة املجنــي عليهــا‬\n     ‫وشــقيقاتها‪........../‬والذي أفــادوا جميعـ ًا بأنــه يف حوالــي الســاعة الثانيــة‬\n     ‫عشــر صباحـ ًا يف اليــوم االثنــن املوافــق ‪1433/2/15‬ه ـ حضــر املدعــو‪/‬‬\n     ‫‪..........‬الــذي كان يف زيــارة إلــى محافظــة ‪ ....‬برفــق خالهــم ألداء واجــب‬\n     ‫العــزاء وبعــد دخولــه املنــزل قــام بالســام عليهــم ثــم صعــد إلــى غرفــة‬\n     ‫نومــه وبعــد حلظــات نــزل وبيــده منشــفه ودخــل دورة امليــاه ثــم خــرج وصعــد‬\n     ‫مــرة أخــرى إلــى غرفتــه وعــاد متوجه ـ ًا إلــى غرفــة شــقيقته‪.......... /‬ثــم‬\n     ‫ســمعن صــوت إطــاق النــار وخــرج مباشــرة مــن الغرفــة وهــو يكبــر (اهلل‬\n     ‫أكبــر اهلل أكبــر) وبيــده مســدس وقــام بالنظــر إليهــم ورمــى الســاح‬\n     ‫يف مــوزع املنــزل ويف حلــال اجتهــن إلــى غرفــة املجنــي عليهــا وشــاهدا‬\n     ‫الدمــاء يف األرض وعلــى مالبســها يف الوقــت الــذي أكــدن عــدم وجــود‬\n     ‫أي خــاف بــن اجلانــي واملجنــي عليهــا وأن اجلانــي يعانــي مــن مــرض‬\n     ‫نفســي واضطرابــات يف التفكيــر والشــكوك يف اآلخريــن وبضبــط‬\n     ‫إفــادة زوج شــقيقته‪ )40(.......... /‬عام ـ ًا ســعودي اجلنســية ســجل مدنــي‬\n     ‫رقــم (‪ )..........‬متعلــم موظــف حكومــي يســكن محافظــة اإلحســاء‬\n     ‫والــذي ذكــر املدعــى عليــه أنــه قــام بإهدائــه الســاح املســتخدم يف‬\n     ‫اجلرميــة ومبناقشــته عــن مصــدر الســاح املســتخدم يف القضيــة أقــر بأنــه‬\n     ‫قــام بإعطائــه لشــقيق زوجتــه املدعــو‪.......... /‬منذ عشــر ســنوات كهدية‬\n     ‫وقــد وعــده بــأن يقــوم بتصريــح الســاح باســمه إال أنــه لــم يفعــل وبعــرض‬\n     ‫الســاح تعــرف عليــه ومبواجهــة املدعــى عليــه ‪..........‬وخالــه املدعــو‬\n     ‫‪ ..........‬وابــن عمــه ‪..........‬ملعرفــة صحــة مــا ادعــى بــه املدعــى عليــه مــن‬\n     ‫ســماعه قولهــم أن شــقيقته املجنــي عليهــا تربطهــا عالقــة مــع املدعــو‬\n\n‫‪63‬‬\n\f‫‪..........‬وقــد أكــدا عــدم صحــة مــاورد علــى لســانة ومبواجهتــه بهــم‬\n‫تراجــع عــن اقوالــه وأثــار أنــه لــم يســمع بذلــك منهــم وإمنــا بنــاء علــى‬\n‫شــكوك لديــه وفيمــا بعــد ورد خطــاب رئيــس احملكمــة العامــة‬\n‫باألحســاء رقــم (‪)33/1423663‬بتاريــخ ‪1433/09/19‬ه ـ واملتضمــن‬\n‫إثبــات تنــازل أوليــاء الــدم عــن القصــاص وصــدر بحــق املدعــى عليــه‬\n‫التقريــر الطبــي مــن مستشــفى الصحــة النفســية مبحافظــة األحســاء‬\n‫برقــم ‪ ..........‬وتاريــخ ‪1433/02/22‬ه ـ املتضمــن مراجعــة املدعــى عليــه‬\n‫للمستشــفى بتاريــخ ‪1429/09/15‬ه ـ ومت تشــخيص حالتــه نوبــات صــرع‬\n‫كبــرى ومت حتويلــة للمتابعــة بعيــادة األمــراض العصبيــة فيمــا أشــير‬\n‫بأنــه منــوم حالي ـ ًا طرفهــم منــذ تاريــخ ‪1433/03/15‬ه ـ وأتضــح بعــد‬\n‫الكشــف أنــه يعانــي مــن اضطــراب التفكيــر وشــكوك وضــاالت‬\n‫غيــر مبــرره يف ســلوك شــقيقته (املجنــي عليهــا) وانــه البــد مــن عرضــه‬\n‫علــى اللجنــة الطبيــة الشــرعية وصــدر التقريــر الطبــي رقــم ‪..........‬بتاريــخ‬\n‫‪1433/07/14‬ه ـ مــن مستشــفى الصحــة النفســية بالطائــف والــذي‬\n‫يتضمــن أن اللجنــة تــرى نظــر ًا ملــا يعانيــة املذكــور مــن مــرض الصــراع‬\n‫واملصحــوب بأعــراض ذهنيــة والتــي تشــمل املعتقــدات املرضيــة اخلاطئــة‬\n‫وســوء احلكــم علــى األمــور فــإن ذلــك يخفــف مــن مســؤليته اجلانبيــه عمــا‬\n‫قــام بــه كــم اثبــت التقريــر رقــم (‪/12‬طــب شــرعي‪1433/‬هـ) املتضمــن‬\n‫أنــه بفحــص مالبــس املجنــي عليهــا تبــن وجــود عــدة ثمانيــة ثقــوب يف‬\n‫القميــص دائريــة الشــكل علــى الكتــف األميــن مــن اجلهــة األماميــة‬\n‫واخللفيــة مــع وجــود ثقــب أســفل البــدن اخللفــي األيســر أيضـ ًا ثقــب دائــري‬\n‫الشــكل يف الشــلحة يقــع اســفل يســار البــدن اخللفــي وكمــا ورد خطــاب‬\n‫مستشــفى امللــك فهــد ب الهفــوف رقــم (‪ ..........‬يف ‪1433/02/21‬ه ـ‬\n\n\n                                                                                      ‫‪64‬‬\n\f     ‫املتضمــن بــأن املصابــة ‪..........‬واملنومــة لديهــم انتقلــت الــى رحمــة اهلل‬\n     ‫نتيجــة اإلصابــات التــي حلقــت بهــا وصــدر بحقهــا شــهادة الوفــاة (‪)..........‬‬\n     ‫مــن األحــوال املدنيــة ورد التقريــر الطبــي الصــادر مــن مستشــفى امللــك‬\n     ‫فهــد بالهفــوف رقــم(‪ )..........‬يف ‪1433/03/23‬ه ـ املتضمــن اآلتــي او ًال‬\n     ‫وجــد باجلثــة عــدد ثمــان طلقــات ناريــة غيــر نافــذة بالظهــر والركبــة‬\n     ‫اليســرى والســتة الباقيــة فتحــات دخــول وخــروج ملرامــي ناريــة مفــردة‬\n     ‫تعــذر حتديــد ماهيــة الفتحــات مــن حيــث الدخــول واخلــروج نتيجــة تغيــر‬\n     ‫معالــم الفتحــات بإجــراءات اإلســعاف واملعاجلــة ومــرور الوقــت وقــد‬\n     ‫احدثــت هــذه اإلصابــات أذيــات موضعيــة بالنســبة لألطــراف مــع كســر‬\n     ‫بالعمــود الفقــري الفقــرة الظهريــة الثامنــة وإصابــة بالرئــة اليمنــى‬\n     ‫بالنســبة لطلقــة الظهــر حيــث اســتقر جــزء منهــا بالرئــة اليمنــى وجــدار‬\n     ‫الصــدر األميــن وهــذه األصابــات مبجملهــا ناجمــة عــن األصابــة بطلــق‬\n     ‫نــاري مفــرد ويرجــع لتحديــد فتحــات الدخــول واخلــروج بدقــة الــى تقريــر‬\n     ‫األدلــة اجلنائيــة املتعلــق بفحــص املالبــس مــع وجــود خثــرات بالوريــد‬\n     ‫الفخــذي األيســر وأوردة الســاق اليســرى ثاني ـ ًا جــاءت نتيجــة فحــص‬\n     ‫مختبــر األنســجة مبستشــفى امللــك فهــد بالهفــوف تفيــد ( بعــدم وجــود‬\n     ‫ال مــن الغــدة النخاميــة واملــخ واملخيــخ وجــذع املــخ‬      ‫تغيــرات يف ك ً‬\n     ‫والكليتــن واملبيضــن والرحــم والشــرايني األكليلــة وامللتــف األميــن‬\n     ‫واأليســر مــع وجــود تضيــق بنســبة (‪ )%50‬بالنــازل األمامــي مــع وجــود‬\n     ‫تنخــر جلــدي مــع رد فعــل حيــوي يتوافــق مــع اصابــة حيويــة وعــدم وجــود‬\n     ‫عالمــة البــودرة يف الفتحــة رقــم (‪ )4-1-2-8-6-5-9‬مــع وجــود عالمــة‬\n     ‫البــودرة يف الفتحــة رقــم (‪ )3‬فقــط مــع وجــود خثــرات متعضيــة يف كل‬\n     ‫مــن الوريــد احلرقفــي األيســر األصلــي والوريــد الشــظوي العميــق والوريــد‬\n\n\n‫‪65‬‬\n\f‫الفخــذي األيســر ثالثـ ًا الوفــاة ســببها اإلصابــات الناريــة ومــا أحدثتــه مــن‬\n‫أذيــات ومضاعفــات ومــا رافــق احلالــة مــن هبــوط بالــدورة الدمويــة‬\n‫والتنفســية‪ 0‬التقاريــر املخبريــة ‪ -1‬وصدر التقريــر الرقم ‪..........‬املتضمن‬\n‫بالكشــف عــن التلوثــات الدمويــة ألحــد املقاذيــف النارية جــاءت نتيجتها‬\n‫(إيجابــي) مــع فصيلــة دم املجنــي عليهــا ‪ -2‬وصــدر التقريــر الرقــم ‪..........‬‬\n‫املتضمــن بالكشــف عــن التلوثــات الدمويــة للعينــات املرفوعــة مــن‬\n‫مســرح احلــادث جــاءت نتيجتهــا إيجابيــة للدمــاء اآلدميــة مــع فصيلــة دم‬\n‫املجنــي عليهــا ‪ -3‬وصــدر التقريــر الرقــم ‪..........‬املتضمــن بالكشــف عــن‬\n‫التلوثــات الدمويــة ملالبــس املجنــي عليهــا جــاءت نتيجــة بعضهــا إيجابيــة‬\n‫للدمــاء األدميــة مــع فصيلــة دم املجنــي عليهــا ‪ 0‬وقــد اســفر التحقيــق معــه‬\n‫عــن توجيــه األتهــام لــه باإلقــدام علــى قتــل شــقيقته عمــد ًا وعدوانـ ًا وذلــك‬\n‫بإطــاق اعيــرة ناريــة عليهــا مباشــرة مــن ســاح مســدس ‪ .....‬ماركة(‪)....‬‬\n‫عيار(‪).....‬ممــا أدى إلــى إصابتهــا بخمســة منهــا أدى الــى إصابتهــا ومــن‬\n‫ثــم نتــج عــن ذلــك وفاتهــا وذلــك لألدلــة والقرائــن التاليــة‪ -1‬إقــراره مبــا‬\n‫نــوه عنــه املــدون علــى الصفحــة رقــم (‪ )15-14‬مــن ملــف التحقيــق املرفــق‬\n‫لفــة(‪ -2 )22‬ماأثبتــه محضــر املعاينــة املتضمــن إصابــة املذكــوره بعــدد‬\n‫خمــس طلقــات ناريــة خلــف تســع فتحــات بعضهــا فتحــات دخــول وبعضها‬\n‫فتحــات خــروج مبواضــع مختلفــة مــن جســدها وفــق ماجــاء بالتقريــر‬\n‫األمنــي املرفــق لفــة(‪ -3 )8-6‬مــا أثبتــه محضــر معاينــة الغرفــة محــل‬\n‫اطــاق النــار املتضمــن مشــاهدة عــدد أربعــة فتحــات دخــول متقاربــة‬\n‫ملقاذيــف ناريــة يف اجلــدار الشــرقي املكــون مــن لوائــح جبســية جميعهــا‬\n‫نافــذه والتــي تتبعهــا واتضــح اســتقرارها يف دوالب بالغرفــة املجــاورة‬\n‫وكــذا العثــور علــى مقذوفــن ناريــن يف ارضيــة الغرفــة وأيضـ ًا بقعتــن‬\n\n\n                                                                                         ‫‪66‬‬\n\f     ‫دمــاء صغيــرة علــى الســجادة ممــا يؤكــد تعــرض املجنــي عليهــا لإلصابة‬\n     ‫أثنــاء تواجدهــا يف غرفتهــا ‪ -4‬مــاورد بأقــوال املجنــي عليهــا املتضمنــه‬\n     ‫قيــام شــقيقها ‪..........‬بإطــاق عــدة طلقــات ناريــة جتاههــا أثنــاء تواجدهــا‬\n     ‫يف غرفتهــا مبنزلهــم ‪ -5‬مبــا جــاء بأقــوال شــقيق والــدة املدعــى عليــه‬\n     ‫‪..........‬املتضمــن بأنــه وقريبــه ‪ ..........‬كانــا يتحدثــان عــن املدعــو ‪..........‬‬\n     ‫املتوفــى قبــل نحــو عشــر ســنوات مــن بــاب الذكــرى فقــط وأن املدعــى‬\n     ‫عليــه املذكــور أقــدم علــى جرميتــه جتــاه شــقيقته نتيجــة معاناتــه مــع‬\n     ‫مــرض نفســي املــدون علــى صفحــات ملــف التحقيــق املرفــق لفــة(‪)10-9‬‬\n     ‫‪ -6‬مــا أثبتــه محضــر ضبــط الســاح النــاري املســتخدم يف القتــل وهــو‬\n     ‫مــن نــوع مســدس ‪ .....‬ماركــة ‪ ....‬عيــار(‪ ).....‬يحمــل الرقــم (‪ )..........‬يف‬\n     ‫منــزل املدعــى عليــه الــذي اتضــح بالفحص املبدئي أن اســطوانة الســاح‬\n     ‫حتتــوي علــى عــدد تســعة ظــروف ناريــه فارغــة ‪ -7‬مــا أثبتــه التقاريــر‬\n     ‫احليويــة والفنيــة املرفــق علــى الصفحــة رقــم (‪ )200-195‬لفــة رقم (‪-130‬‬\n     ‫‪ )132‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق‬\n     ‫جنائيــة مســجلة وحيــث أن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليته‬\n     ‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند‬\n     ‫إليــه وإثبــات بصفــة القتــل وإفهامــه بــأن عقابــه وفق ـ ًا لــإرادة امللكيــة‬\n     ‫عائــد ًا للجهــة املختصــة علمـ ًا أنــه صــدر القــرار الشــرعي مــن احملكمــة‬\n     ‫العامــة مبحافظــة األحســاء رقــم (‪ )33/407434‬وتاريــخ ‪1433/9/11‬هـ‬\n     ‫املتضمــن تنــازل اوليــاء الــدم عــن حقهــم يف القصــاص هــذه دعــواي‬\n     ‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي‬\n     ‫العــام يف دعــواه مــن قيامــي بإطــاق النــار علــى شــقيقتي ‪..........‬وقتلهــا‬\n     ‫صحيــح وقــد حصــل يف هــذا األمــر لكونــي مريــض نفســي وأعانــي مــن‬\n\n\n‫‪67‬‬\n\f‫الصــرع وقــد جاءتنــي حالــة نفســيه شــديدة فقمــت بالدخــول علــى أختــي‬\n‫املذكــورة يف غرفتهــا وأطلقــت عليهــا النــار مــن املســدس ثــم حملــت إلــى‬\n‫املستشــفى وتوفيــت بعــد ذلــك هــذه إجابتــي بعــد ذلــك جــرى الرجــوع إلــى‬\n‫شــهادة الوفــاة لشــقيقة املدعــى عليــه علــى لفــة ‪ 46‬مــن املعاملــة وفيهــا‬\n‫أثبــات وفــاة شــقيقة ‪..........‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وإقــرار املدعــى عليــه بقيامــه بإطــاق النــار علــى شــقيقته ‪..........‬ووفاتهــا‬\n‫بعــد ذلــك وبنــاء علــى شــهادة الوفــاة املذكــورة أعــاه بنــاء علــى ذلــك‬\n‫كلــه فقــد ثبــت لــدي بــان املدعــى عليــه قــد قتــل شــقيقته املذكــورة‬\n‫عمــد ًا عدوان ـ ًا وأفهمتــه بــأن عقابــه علــى ذلــك وفــق اإلرادة امللكيــة‬\n‫عائــده للجهــة املختصــة وبعــرض ذلــك عليــه وعلــى املدعــي العــام قــرر‬\n‫املدعــى عليــه قناعتــه وقــرر املدعــي العام عــدم قناعته وطلب االســتئناف‬\n‫وقــرر بأنــه لــن يقــدم الئحــة اعتراضيــه وإمنــا يكتفــي بــأوراق املعاملــة‬\n‫والئحــة الدعــوى عــن االعتــراض واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                  ‫محمد وعلى آله وصحبه وسلم‪ .‬حرر يف ‪1434/03/04‬هـ‬\n‫فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة األولــى مبحكمــة‬\n‫االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف برقــم ‪3478500‬‬\n‫وتاريــخ ‪1434/6/10‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪34/1495982‬‬\n‫وتاريــخ ‪1434/6/20‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ ‪..........‬املســجل برقــم ‪ 3460109‬وتاريــخ‬\n‫‪1434/3/11‬ه ـ اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد‪........../‬يف قضيــة‬\n‫اثبــات صفــة القتــل وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬عليــه قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حرريف‪1434/6/24‬ه ـ‬\n                                                                                       ‫‪68‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":58,"source_page_end":68,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2f06c4ae0efbe8f88194a4ee2d3068c344d0d7de59f5014d2e348b08d846f668","normalized_text_hash":"7878d37d790efc165d61cfa9d3563855fa62192a051a652a09e41a872c46f870","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p58-3460109"},{"id":"ac2787d2-6ca2-5a5b-81a5-ad1b29ef73a2","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -قتل -طعن بسكني -طلب إثبات صفة القتل وتطبيق اإلرادة امللكية -تعاطي احلبوب احملظورة «الكبتاجون» -حيازة حشيش -إقرار املدعى عليه -ثبوت إدانة -ثبوت صفة القتل العمد والعقوبة عائدة للجهة املختصة -تقرير قصاص األثر - تعزير مبصادرة السيارة املستخدمة يف اجلرمية .","document_number":"34204971","case_number":"3494926","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/4","year":"1434","subject":"اعتداء -قتل -طعن بسكني -طلب إثبات صفة القتل وتطبيق اإلرادة امللكية -تعاطي احلبوب احملظورة «الكبتاجون» -حيازة حشيش -إقرار املدعى عليه -ثبوت إدانة -ثبوت صفة القتل العمد والعقوبة عائدة للجهة املختصة -تقرير قصاص األثر - تعزير مبصادرة السيارة املستخدمة يف اجلرمية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34204971 :‬تاريخه‪1434/5/4 :‬هـ‬\n                         ‫رقم الدعوى‪3494926:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34247869‬تاريخه‪1434/6/21 :‬هـ‬\n\n\n     ‫اعتــداء ‪ -‬قتــل ‪ -‬طعــن بســكني ‪ -‬طلــب إثبــات صفــة القتــل وتطبيــق‬\n     ‫اإلرادة امللكيــة ‪ -‬تعاطــي احلبــوب احملظــورة «الكبتاجــون» ‪ -‬حيــازة‬\n     ‫حشــيش ‪ -‬إقــرار املدعــى عليــه ‪ -‬ثبــوت إدانــة ‪ -‬ثبــوت صفــة القتــل‬\n     ‫العمــد والعقوبــة عائــدة للجهــة املختصــة ‪ -‬تقريــر قصــاص األثــر ‪-‬‬\n                     ‫تعزيــر مبصــادرة الســيارة املســتخدمة يف اجلرميــة ‪.‬‬\n\n\n\n\n     ‫‪ -1‬األمــر الســامي رقــم ‪ 10711‬يف ‪1393/5/2‬ه ـ وقــرار مجلــس القضــاء‬\n     ‫األعلــى بهيئتــه الدائمــة برقــم‪ 3/51‬يف ‪1409/3/6‬ه ـ املؤيــد باألمــر‬\n     ‫الســامي رقــم ‪/1197/4‬م يف ‪1409/6/2‬ه ـ املبلــغ بالتعميــم ‪/8‬ت‪ 95/‬يف‬\n     ‫‪1409/7/25‬ه ـ بشــأن تطبيــق اإلرادة امللكيــة علــى قاتــل العمــد وشــبه‬\n     ‫العمــد إذا تنــازل أوليــاء الــدم عــن القصــاص (التصنيــف املوضوعــي‬\n                                                ‫لتعاميــم وزارة العــدل ‪.)782/1‬‬\n\n\n\n\n     ‫جــرى توجيــه االتهــام مــن االدعــاء العــام علــى املدعــى عليــه بقيامــه بقتــل‬\n     ‫املجنــي عليــه عمــدا وعدوانــا وطلــب إثباتــه واحلكــم عليــه بتطبيــق‬\n     ‫اإلرادة امللكيــة ومصــادرة الســيارة حيــث قــام املدعــى عليــه بتســليم‬\n     ‫نفســه للجهــات األمنيــة معترفــا بأنــه قــام بقتــل املجنــي عليــه بطعنــه‬\n\n‫‪69‬‬\n\f‫بالســكني ‪ -‬أقــر املدعــى عليــه محاكمــة بــأن املجنــي عليــه صديقــه‬\n‫وأنــه اختلــف معــه فطعنــه بالســكني فرمــاه املجنــي عليــه بحجــر فقــام‬\n‫بعدهــا بطعنــه عــدة مــرات ولــم يكــن يتوقــع بأنهــا ســتقتله فلمــا رأى‬\n‫ينــزف دمــا ســاعده فأركبــه ســيارته وتوجــه بــه ألقــرب مركــز صحــي‬\n‫ثــم ســلم نفســه للشــرطة ‪ ،‬عليــه وإلقــرار املدعــى عليــه بقصــد اجلنايــة‬\n‫مبحــدد يف مقتــل علــى نحــو متكــرر يقتــل غالبــا ‪ ،‬لــذا فقــد ثبــت لــدى‬\n‫احملكمــة أن صفــة قتــل املدعــى عليــه للمجنــي عليــه عمــد وأف َه َمــت‬\n‫املدعــى عليــه بــأن عقوبتــه لقــاء احلــق العــام عائــد للجهــة املختصــة حســب‬\n‫اإلرادة امللكيــة‪ ،‬ومصــادرة الســيارة املســتعملة يف اجلرميــة والتصــرف‬\n‫حك َمــت ‪ ،‬قــرر املدعــى عليــه عــدم‬   ‫بهــا حســب التعليمــات وبذلــك َ‬\n‫القناعــة وطلــب االســتئناف بــدون الئحــة ‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                     ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 3494926‬وتاريــخ‬\n‫‪ 1434/02/26‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1434/02/26‬ه ـ‬\n‫ففــي يــوم الســبت املوافــق‪ 1434/05/04‬ه ـ افتتحت اجللســة الســاعة ‪45‬‬\n‫‪ 10 :‬وفيهــا حضــر ‪ /‬املدعــي العــام ‪..........‬مبوجــب خطــاب التكليــف‬\n‫مــن مرجعــه رقــم‪..........‬يف ‪1434/1/24‬ه ـ وادعــى علــى احلاضــر ‪/‬‬\n‫‪ ،..........‬البالــغ مــن العمــر (‪ )24‬عام ـ ًا ‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب‬\n‫الســجل املدنــي رقــم (‪ ، )..........‬موقــوف بســجون مكــة املكرمــة‬\n\n                                                                                      ‫‪70‬‬\n\f     ‫بتاريــخ ‪29‬ـ ــ‪1432/4/30‬هـ ـ ـ قــام املدعــى عليــه املذكــور بتســليم نفســه‬\n     ‫إلــى مركــز شــرطة ‪..........‬مخبــر ًا عــن قيامــه بالتضــارب مــع املجنــي‬\n     ‫عليه‪........../‬أثنــاء جلوســهما لوحدهمــا يف منطقــة ‪..........‬خلــف مركــز‬\n     ‫‪..........‬وقيامــه بضــرب املجنــي عليــه ثــم نقلــه إلــى املســتوصف‬\n     ‫‪..........‬ب‪..........‬وحضــر إلــى املركــز لتســليم نفســه ومبعاينــة الســيارة‬\n     ‫التــي يســتقلها املدعــى عليــه نــوع ‪ ........‬رقــم اللوحــة (‪ )..........‬اللــون ‪......‬‬\n     ‫‪ ،‬اتضــح وجــود آثــار دمــاء علــى البابــن اخللفيــن األميــن واأليســر وآثــار‬\n     ‫دمــاء علــى املقعــد اخللفــي وبتفتيــش الســيارة نــوع ‪ .........‬رقــم اللوحــة‬\n     ‫(‪ )..........‬اللــون ‪ ......‬عثــر علــى قطعــة بنيــة اللــون يشــتبه أن تكــون مــن‬\n     ‫احلشــيش املخــدر علــى املرتبــة اخللفيــة مــن اجلهــة اليمنــى مت تــزن(‪ 3‬جــم)‬\n     ‫ثالثــة جرامــات (مت احلكــم يف قضيــة املخــدرات مبوجــب القــرار‬\n     ‫الشــرعي رقــم (‪ )6/207‬وتاريــخ ‪1433/4/14‬هـ ـ املرفــق ومبعاينــة موقــع‬\n     ‫احلادثــة ‪ :‬اتضــح بأنــه يقــع يف منطقــة ‪..........‬بعــد أن قــام املدعــى عليــه‬\n     ‫باإلرشــاد إلــى موقــع احلادثــة باالجتــاه إلــى الطريــق املــؤدي إلــى مســجد‬\n     ‫‪..........‬وقبــل املســجد مت األلتفــاف إلــى اليســار والدخــول إلــى طريــق‬\n     ‫إســفلتي والوصــول إلــى مخطــط حديــث اإلنشــاء ويف اجلهــة اليمنــى‬\n     ‫الشــمالية الغربيــة مســجد ‪..........‬وقــام املدعــى عليــه باإلرشــاد إلــى‬\n     ‫منطقــة جبليــة ممهــدة خلــف االســتراحات وعثــر باملوقــع على أربــع مواقع‬\n     ‫بهــا بقــع دمويــة كبيــرة يف إنحــاء متفرقــة متسلســلة مــن أعلــى املنطقــة‬\n     ‫اجلبليــة إلــى األســفل بطــول ‪ 800‬متــر تقريبــا ومنهــا بقعــة دمويــة يف أعلــى‬\n     ‫املنطقــة اجلبليــة وعثــر علــى جــوال وشــماغ وطاقيتــن بيضــاء اللــون‬\n     ‫وشــريحة ومقبــض ســكني مكســور ونصــل ســكني مكســور يبعــد‬\n     ‫عــن املقبــض مبســافة حوالــي متريــن عليهــا آثــار دمــاء وفردتــي حــذاء‬\n\n\n‫‪71‬‬\n\f‫وآثــار إطــارات ســيارة كمــا وجــد آثــار إطــارات ســيارة واضحــة أثنــاء‬\n‫طلوعهــا ونزولهــا مــن أعلــى املنطقــة اجلبلية وقام قصــاص األثر مبقارنتها‬\n‫مــع الســيارة التــي حضــر بهــا املدعــى عليــه نــوع ‪ ........‬رقــم اللوحــة‪..........‬‬\n‫اللــون رصاصــي واتضــح بأنهــا نفــس اإلطــارات التــي شــاهد آثارهــا يف‬\n‫املوقــع ورد تقريــر األدلــة اجلنائيــة تقريــر فنــي رقــم (‪ )19‬مســرح حــادث‬\n‫لعــام ‪1432‬ه ـ ـ متضمن ـ ًا تعــرض املجنــي عليــه للطعــن باســتخدام أداة‬\n‫حــادة وإصابتــه بجــروح طعنيــة غائــرة أدت إلــى وفاتــه كمــا ورد تقريــر‬\n‫األدلــة اجلنائيــة فنــي انطبــاق رقــم (‪ )..........‬لعــام ‪1432‬ه ـ ـ انطبــاق أثــر‬\n‫جلــزء مــن بصمــة راحــة اليــد اليمنــى (مــا حتــت األصابــع) متــام االنطبــاق‬\n‫للجــزء املقابــل لــه مــن طبعــة بصمــة راحــة اليــد للمدعــى عليــه ومت رفــع‬\n‫األثــر مــن زجــاج البــاب مــن اخلــارج خلــف الســائق ‪ .‬وانطبــاق أثــر جلــزء مــن‬\n‫بصمــة راحــة اليــد اليمنــى (كلــوة خنصــر) متــام االنطبــاق للجــزء املقابــل‬\n‫لهــا مــن طبعــة راحــة اليــد اليســرى للمدعــى عليــه ومت رفــع األثــر مــن‬\n‫زجــاج البــاب مــن اخلــارج خلــف الســائق ‪ .‬وانطبــاق أثــر جلــزء مــن بصمــة‬\n‫راحــة اليــد اليســرى (كلــوة خنصــر) متــام االنطبــاق للجــزء املقابــل لهــا‬\n‫مــن طبعــة راحــة اليــد اليســرى للمدعــى عليــه ومت رفــع األثــر مــن البــاب‬\n‫خلــف الســائق ‪ .‬وانطبــاق أثــر جلــزء مــن بصمــة راحــة اليــد اليمنــى (كلــوة‬\n‫خنصــر) متــام االنطبــاق للجــزء املقابــل لهــا مــن طبعــة راحــة اليــد اليســرى‬\n‫للمدعــى عليــه ومت رفــع األثــر مــن علــى البــاب اخللفــي األيســر ‪ ،‬وباقــي‬\n‫اآلثــار ال تــزال مجهولــة كمــا ورد تقريــر األدلــة اجلنائيــة فنــي انطبــاق‬\n‫رقــم (‪ )..........‬لعــام ‪1432‬هـ ـ ـ انطبــاق أثــر جلــزء مــن بصمــة راحــة اليــد‬\n‫اليســرى متــام االنطبــاق للجــزء املقابــل لــه مــن طبعــة راحــة اليــد اليســرى‬\n‫للمجنــي عليــه‪........../‬ومت رفــع األثــر مــن علــى البــاب اخللفــي األيســر مــن‬\n\n\n                                                                                            ‫‪72‬‬\n\f     ‫الزجــاج مــن الداخــل ‪ .‬وانطبــاق أثــر جلــزء مــن بصمــة راحــة اليــد اليســرى‬\n     ‫(كلــوة خنصــر) متــام االنطبــاق للجــزء املقابــل لهــا مــن طبعــة راحــة اليــد‬\n     ‫اليســرى للمجنــي عليــه‪ /‬ومت رفــع األثــر مــن علــى البــاب اخللفــي األيســر‬\n     ‫مــن الزجــاج مــن الداخــل ‪ .‬انطبــاق أثــر جلــزء مــن بصمــة يــد اليمنــى للجــزء‬\n     ‫املقابــل لهــا مــن طبعــة بصمــة أصبــع إبهــام اليــد اليمنــى للمجنــي عليــه‪/‬‬\n     ‫‪..........‬ومت رفــع األثــر مــن الزجــاج خلــف املعــاون وباقــي اآلثــار ال تــزال‬\n     ‫مجهولــة تقريــر األدلــة اجلنائيــة فنــي رقم (‪..........‬متضمــن اآلتي ‪-1‬تطابق‬\n     ‫األمنــاط الوراثيــة للعينــة رقــم (‪01‬ـ ـ ـ ‪ 07‬ـ ــ‪ 09‬ـ ــ‪ 11‬ـ ــ‪ 19‬ـ ــ‪ 21‬ـ ــ‪23‬ـ ــ‪25‬ـ ـ ــ‪)28‬‬\n     ‫الــوارد تفصيلهــا باجلــدول وأنهــا أمنــاط وراثيــة ذكريــة واحــدة مجهولــة‬\n     ‫املصــدر ‪ ،‬كمــا أتضــح اختــاف األمنــاط الوراثيــة لعينــة الــدم القياســية‬\n     ‫(‪ )29‬للمدعــى عليــه عــن األمنــاط الوراثيــة املذكــورة أعــاه ‪-2‬األمنــاط‬\n     ‫الوراثيــة لعينــة الــدم القياســية (‪ )29‬للمدعــى عليــه تقــع ضمــن األمنــاط‬\n     ‫الوراثيــة املختلفــة رقــم (‪20‬ـ ـ ــ‪ )24‬ممــا يــدل علــى أنــه مصــدر هــذا‬\n     ‫االختــاط يف تلــك العينتــن كمــا ورد تقريــر الطــب شــرعي رقــم‬\n     ‫(‪ )..........‬املتضمــن تطابــق جميــع القطــوع التــي علــى مالبــس املجنــي‬\n     ‫عليــه مــع اإلصابــات التــي باجلثــة ‪ ،‬واإلصابــة املوجــودة بيســار العنــق‬\n     ‫واإلبــط األيســر إصابــة طعنيــة نافــذة واإلصابــة التــي يســار مقــدم الصدر‬\n     ‫ومقــدم الكتــف األيســر إصابــة طعنيــة غيــر نافــذة وجميــع هــذه‬\n     ‫اإلصابــات حدثــت مــن اإلصابــة بجســم صلــب حــاد وســن مدبــب مثــل‬\n     ‫الســكني ‪ ،‬والســحجات الهاللية الشــكل على مقدم الســاعد األيســر‬\n     ‫والعضــد األميــن وخلفيــة الكتــف األميــن وأعلــى ميــن مقــدم الصــدر‬\n     ‫حدثــت مــن جســم صلــب مدبــب مثــل رأس الســكني واجلــرح القطعــي‬\n     ‫الــذي يف مقــدم الســاعد األيســر نــاجت عــن أداة حــادة كالســكني أيضـ ًا‬\n\n\n‫‪73‬‬\n\f‫‪ ،‬واجلــرح القطعــي علــى اجلانــب األنســي لليــد اليمنــى الــذي دفاعــي نــاجت‬\n‫عــن جســم صلــب حــاد كالســكني ‪ ،‬وجميــع اإلصابــات املذكــورة‬\n‫أعــاه حيويــة ‪ ،‬ولــم يشــاهد بعمــوم اجلثــة أي إصابــات أخــرى ‪ ،‬كمــا لــم‬\n‫يظهــر مــن خــال الفحــص باألشــعة العاديــة واحلــس اليــدوي وجــود‬\n‫كســور كمــا أظهــرت أشــعة الصــدر وجــود جتمــع هوائــي يف اجلهــة‬\n‫اليســرى بالتجويــف الصــدري ‪ ،‬وبينــت الصفــة التشــريحية إصابــة‬\n‫األوعيــة الدمويــة يســار العنــق بجــوار اجلانــب األنســي لزاويــة الفــك‬\n‫الســفلي األيســر واألنســجة الرخويــة املجــاورة حتــى يســار قاعــدة اللســان‬\n‫مقابــل الطعنــة التــي يســار العنــق وكذلــك اســترواح صــدري يف اجلهــة‬\n‫اليســرى مــن جتويــف الصــدر نــاجت عــن اجلــرح الطعنــي النافــذ الــذي يف‬\n‫منطقــة اإلبــط األيســر حيــث نفــذ إلــى التجويــف الصــدري بــن الضلــع‬\n‫اخلامــس والســادس يف الناحيــة الوحشــية اخللفيــة وهــذه اجلــروح اجتاههــا‬\n‫مــن اجلهــة العليــا اليســرى جلســد املجنــي عليــه إلــى اجلهــة الســفلية اليمنــى‬\n‫‪ ،‬كمــا ثبــت ســلبية العينــات املأخــوذة مــن اجلثــة للمواد املخدرة والســامة‬\n‫واملســكرة وســبب الوفــاة النزيــف احلــاد النــاجت عــن إصابــة أوعيــة دمويــة‬\n‫أعلــى يســار الرقبــة نتيجــة إصابــة طعنيــة غائــرة بآلــة حــادة كالســكني‬\n‫واالســترواح الصــدري يف اجلهــة اليســرى مــن الصــدر نــاجت عــن طعنــة‬\n‫غائــرة يف منطقــة اإلبــط األيســر ســاهم يف ســرعة تدهــور حالــة املجنــي‬\n‫عليــه وحصلــت الوفــاة يف حوالــي الســاعة الثانيــة عشــر والنصــف بعــد‬\n‫منتصــف ليلــة االثنــن املوافــق ‪1432/4/30‬هـ ـ ـ ورد‪ /‬خطــاب مديــر‬\n‫شــعبة التحريــات والبحــث اجلنائــي رقــم (‪ )..........‬وتاريــخ ‪1432/5/9‬هـ ـ ـ‬\n‫متضمــن أنــه مــن خــال البحــث والتحــري اتضــح بــأن املدعــى عليــه‬\n‫واملجنــي عليــه أصدقــاء ويتــرددون علــى بعضهمــا البعــض وهمــا مــن‬\n\n\n                                                                                         ‫‪74‬‬\n\f     ‫مســتعملي املســكرات واملخــدرات حســب مــا يشــاع عنهمــا يف احلــي‬\n     ‫الــذي يســكنون فيــه مبنطقــة ‪..........‬وأن ســبب قيــام املدعــى عليــه بطعن‬\n     ‫املجنــي عليــه الختالفهمــا علــى حســاب املخــدرات حيــث اختلفــوا علــى‬\n     ‫مبالــغ ماليــة وكان املدعــى عليــه يطالــب املجنــي عليــه بهــا ونشــب‬\n     ‫خــاف بينهمــا ونتــج عنــه طعــن املدعــى عليــه للمجنــي عليــه ممــا أدى‬\n     ‫إلــى وفاتــه بوضــع التقاريــر وورد تقريــر األدلــة اجلنائيــة رقــم ‪)..........‬‬\n     ‫متضمــن تطابــق األمنــاط لعينــة األظافــر القياســية رقــم (‪ )..........‬للمجنــي‬\n     ‫عليــه‪ /‬مــع األمنــاط الوراثيــة للعينــة رقــم (‪ )..........‬مــع األمنــاط الوراثيــة‬\n     ‫للعينــات مــن رقــم (‪ )..........‬إلــى رقــم (‪ )..........‬ورقــم (‪ )..........‬ومــن رقــم‬\n     ‫(‪ )..........‬إلــى رقــم (‪ )..........‬ورقــم (‪ )..........‬ورقــم (‪ )..........‬ومــن رقــم‬\n     ‫(‪ )..........‬إلــى رقــم (‪ )..........‬الصــادر بحقهــا التقريــر رقم‪..........‬ممــا يثبت‬\n     ‫بــأن املجنــي عليــه ‪.......... /‬هــو مصــدر تلــك العينــات ‪ ،‬وأن األمنــاط‬\n     ‫الوراثيــة لعينــة األظافــر القياســية للمجنــي عليه‪........../‬رقــم (‪)..........‬‬\n     ‫تقــع ضمــن األمنــاط الوراثيــة املختلطــة للعينة رقــم (‪ )..........‬ورقم (‪)..........‬‬\n     ‫الصــادر بحقهــا التقريــر رقم‪..........‬بســماع أقــوال‪.......... /‬ذكــر بأنــه يف‬\n     ‫ا وأثنــاء مــروره بجــوار‬   ‫يــوم احلادثــة ويف الســاعة الثانيــة عشــر والربــع ليـ ً‬\n     ‫مســتوصف ‪..........‬شــاهد ســيارة نــوع جمــس اللــون رصاصــي واملدعــى‬\n     ‫عليــه ينــزل منهــا وثيابــه مليئــة بالــدم وذهــب وأحضــر عربيــة ومســعفني‬\n     ‫ولــم يشــاهده بعدهــا ويف املقعــد اخللفــي املجنــي عليــه ‪.......... /‬وهــو‬\n     ‫مصــاب يف رقبتــه مــن اجلهــة اليســرى ويف إبطــه األيســر وقام هو بإســعاف‬\n     ‫املجنــي عليــه وقــال لــه املجنــي عليــه (يــا ‪..........‬أســعفنى أنــا مبــوت) وأثناء‬\n     ‫محاولــة إســعافه باملســتوصف نطــق بالشــهادة وتــويف بســماع أقــوال‪/‬‬\n     ‫‪..........‬ذكــر بأنــه يف يــوم احلادثــة حضــر املدعــى عليــه مــا بــن الســاعة‬\n\n\n‫‪75‬‬\n\f‫ا إلــى منزلهــم وبقيادتــه‬    ‫احلاديــة عشــر والنصــف إلــى الثانيــة عشــر لي ـ ً‬\n‫ســيارة نــوع ‪ ....‬وتقابــل معــه وشــقيقه املجنــي عليــه فقــال املدعــى عليــه‬\n‫للمجنــي عليــه هيــا معــي ســوف نذهــب مشــوار وطلــب هــو مــن املدعــى‬\n‫عليــه الذهــاب معهمــا فــرد عليــه املدعــى عليــه بقولــه بنروح مشــوار قريب‬\n‫ونعــود ثــم دخــل هــو إلــى املنــزل ثم علم بعد ذلك بوفاة شــقيقة باســتجواب‬\n‫املدعــى عليــه أقــر بقتــل املجنــي عليــه‪.......... /‬وذلــك بضربــة بالســكني‬\n‫وذكــر بأنــه يف يــوم احلادثــة وبعــد صــاة العشــاء اتصــل علــى املجنــي‬\n‫عليــه وطلــب منــه إيجــاد شــخص لشــراء احلبــوب احملظــورة وتواعــد معــه‬\n‫ا توجــه إلــى منــزل‬  ‫عنــد منزلــه يف ‪..........‬ويف حوالــي الســاعة العاشــرة ليـ ً‬\n‫املجنــي عليــه وتقابــل مــع شــقيقه‪........../‬وحضر املجنــي عليــه بعــد ذلــك‬\n‫ا ثــم انطلــق هــو مــع املجنــي عليــه وبقيادتــه ســيارة نــوع ‪.....‬‬\n                                                                      ‫وحتدثــوا قليـ ً‬\n‫اللــون‪ ......‬وذهبــا إلــى أحــد معــارف املجنــي عليــه يف ‪..........‬الــذي قــام‬\n‫بإرشــادهم إلــى مــكان شــخص آخــر لشــراء املخــدرات وأعطــى املجنــي‬\n‫عليــه مبلــغ (‪ )90‬تســعني ريــال وأضــاف عليهــا املجنــي عليــه مبلــغ (‪)100‬‬\n‫مائــة ريــال وقــام بإعطائهــا للشــخص الــذي يعرفــه والــذي قــام بــدورة‬\n‫بشــراء حبــوب مــن الكبتاجــون وقطعــة مــن احلشــيش املخــدر وإعطائهــا‬\n‫للمجنــي عليــه وأنــزل الشــخص الــذي معهــم يف ‪..........‬واجتــه هــو واملجني‬\n‫عليــه إلــى بقالــه وقامــا بشــراء العصيــر واجتــه بعــد ذلــك إلــى مخطــط‬\n‫جبلــي علــى طريــق ‪..........‬وصعــد بالســيارة إلــى أعلــى املخطــط ثــم نــزل‬\n‫مــن الســيارة وأخــرج الســكني مــن جيبــه وتضــارب مــع املجنــي عليــه‬\n‫وقــام بضربــه بالســكني ثــم نــزل املجنــي عليــه إلــى أســفل املخطــط وحلــق‬\n‫بــه وتضــارب معــه مــرة أخــرى وعندمــا شــاهد الــدم علــى مالبــس املجنــي‬\n‫عليــه صعــد إلــى الســيارة واســتمر املجنــي عليــه يف النــزول وحلــق باملجنــي‬\n\n\n                                                                                         ‫‪76‬‬\n\f     ‫عليــه بالســيارة وفتــح قفــل األبــواب وركــب املجنــي عليــه يف املرتبــة‬\n     ‫اخللفيــة ثــم تنــاول هــو ثــاث حبــات مــن احلبــوب احملظــورة والتــي قــام‬\n     ‫بشــرائها وكانــت علــى درج الســيارة األوســط وتوجــه بعــد ذلــك إلــى‬\n     ‫املســتوصف ‪..........‬ب‪..........‬وتوقــف عنــد املســتوصف وقــام بإدخــال‬\n     ‫املجنــي عليــه إلســعافه وتوجــه بعــد ذلــك إلــى مركــز شــرطة ‪..........‬‬\n     ‫وقــام بتســليم نفســه وأضــاف بأنــه قــام بشــراء الســكني املســتخدمة مــن‬\n     ‫نــوع (‪ )........‬مــن محطــة ‪..........‬قبــل احلادثــة مــن أجــل التضــارب بهــا مــع‬\n     ‫املجنــي عليــه ‪ ،‬وصــدق إقــراره بذلــك شــرع ًا وقــد انتهــى التحقيــق إلــى‬\n     ‫توجيــه االتهــام للمدعــى عليــه بقتــل‪.......... /‬بطعنــه بســكني عمــد ًا‬\n     ‫وعدوان ـ ًا ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة ‪-1‬إقــراره املصــدق شــرع ًا‬\n     ‫املنــوه عنــه املــدون علــى صفحــة رقــم (‪ )2/1‬مبلــف التحقيــق رقــم (‪)3‬‬\n     ‫املرفــق لفــه رقــم (‪-2 )22‬مــا جــاء يف التقريــر الطبــي الشــرعي النهائــي‬\n     ‫املنــوه عنــه واملرفــق لفــه رقــم (‪ )92‬إلــى (‪-3)102‬تقاريــر األدلــة اجلنائيــة‬\n     ‫رقم ‪ )..........‬ورقم (‪ )..........‬ورقم (‪ )..........‬ورقم (‪ )..........‬ورقم (‪)..........‬‬\n     ‫واملرفقــة لفــة رقــم (‪33‬ـ ــ‪37‬ـ ــ‪ 41‬ـ ـ ـ ومــن ‪ 67‬إلــى ‪-4)77‬محضــر قصــاص‬\n     ‫األثــر املنــوه عنــه واملــدون علــى صفحــة رقــم (‪ )11‬مبلــف إجــراءات‬\n     ‫االســتدالل املرفــق لفــه رقــم (‪-5 )2‬محضــر االنتقــال واملعاينــة والتفتيــش‬\n     ‫املنــوه عنهــا واملــدون مبلــف إجــراءات االســتدالل املرفــق لفــه رقــم‬\n     ‫(‪ 1‬ـ ـ‪ 2‬ـ ــ‪ )30‬وحيــث إن مــا قــام بــه املدعــى عليــه فعــل محــرم ومعاقــب‬\n     ‫عليــه شــرع ًا لــذا أطلــب إثبــات صفــه القتــل وتطبيــق اإلرادة امللكيــة‬\n     ‫واحلكــم مبصــادرة الســيارة املســتخدمة يف اجلرميــة نــوع ‪ .....‬رقــم اللوحــة‬\n     ‫(‪( )..........‬احلــق اخلــاص مــا زال قائم ـاً) هــذه دعــواي وبســؤال املدعــى‬\n     ‫عليــه اجــاب بقولــه مــا ذكــره املدعــي العــام صحيــح حيــث اختلفــت مــع‬\n\n\n‫‪77‬‬\n\f‫املجنــي عليــه وكان صديقــا لــي ثــم طلبــت منــه مرافقتــي إلــى املخطــط‬\n‫اجلبلــي املذكــور واختلفنــا وتخاصمنــا وطعنتــه بالســكني ثــم ضربنــي‬\n‫بحجــر ثــم طعنتــه عــدة مــرات وإحداهــا يف جانــب رقبتــه وكنــت أقصــد‬\n‫إصابتــه لكننــي لــم أتوقــع أن اإلصابــات ســتقتله وعندمــا رأيــت أنــه‬\n‫ينــزف ســاعدته حتــى ركــب الســيارة وتوجهــت بــه ألقــرب مركــز‬\n‫صحــي ثــم ســلمت نفســي للشــرطة هــذه إجابتــي فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وإلــى إقــرار املدعــى عليــه بدعــوى املدعــي العــام‬\n‫وحيــث إنــه أصــاب املجنــي عليــه مبحــدد يقتــل غالبــا وأصابــه يف مقتــل‬\n‫وكــرر الطعــن وهــو قاصــد اإلصابــة لــذا فقــد ثبــت لــدي أن صفــة قتــل‬\n‫املدعــى عليــه للمجنــي عليــه هــي القتــل العمــد وأفهمــت املدعــى عليــه‬\n‫بــأن جــزاءه لقــاء احلــق العــام عائــد للجهــة املختصــة حســب اإلرادة‬\n‫امللكيــة مبثــل هــذا الشــأن وحكمــت مبصــادرة الســيارة املســتخدمة يف‬\n‫اجلرميــة والتصــرف بهــا حســب األنظمــة والتعليمــات اخلاصــة بهــذا الشــأن‬\n‫وبعــرض احلكــم علــى املدعــى عليــه لــم يقنــع وطلــب االســتئناف بــدون‬\n‫الئحــة فأجيــب لطلبــه ولــم يعــارض املدعــي العــام حيــث حكــم لــه بــكل‬\n‫طلباتــه وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وآله وصحبه‬\n‫‪ .‬حــرر يف ‪1434/5/4‬هــ‪ .‬ثــم عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫وبرفقهــا القــرار رقــم ‪ 34247869‬وتاريــخ ‪1434/06/21‬ه ـ املتضمــن‬\n‫املوافقــة والتصديــق علــى احلكــم قاضــي اســتئناف ‪..........‬قاضــي‬\n‫اســتئناف‪..........‬قاضي اســتئناف ‪..........‬لــذا جــرى إحلاقــه وإثباتــه وبــاهلل‬\n                                                ‫التوفيق حرر يف ‪1434/07/10‬هـ‬\n\n\n\n\n                                                                                      ‫‪78‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":69,"source_page_end":78,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b2791ce7cff4a1828c2e544b63a0f12409f6b502c643dde469eb3847e40a855e","normalized_text_hash":"87f1295d4c3d07ef3ca1107c6fcf0c8751c76cdd30b537e82ee07059959c4c51","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p69-34204971"},{"id":"233af501-96c6-5312-b50e-058bd6b059f5","document_type":"judgment","category":"judicial","subcategory":"general","title":"قتل -القتل العمد وشبه العمد اخلطأ -قتل خطأ -حدث -إقرار املدعى عليه -تنازل عن احلق اخلاص -مشروعية االستئناس بالقرائن يف حتديد القصد اجلنائي -رد دعوى اإلدانة بالقتل اخلطأ -عدم صحة تنازل الولي عن حقوق القاصرين حتت واليته ما أشار له القاضي يف تسبيب احلكم.","document_number":"3312366","case_number":"32507275","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة كما هو موضح يف أوراق املعاملة","circuit":"الدائرة اجلزائية الثانية رقم 33150802وتاريخ 1433/3/23ه","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/1/8","year":"1434","subject":"قتل -القتل العمد وشبه العمد اخلطأ -قتل خطأ -حدث -إقرار املدعى عليه -تنازل عن احلق اخلاص -مشروعية االستئناس بالقرائن يف حتديد القصد اجلنائي -رد دعوى اإلدانة بالقتل اخلطأ -عدم صحة تنازل الولي عن حقوق القاصرين حتت واليته ما أشار له القاضي يف تسبيب احلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 3312366 :‬تاريخه‪1433/1/8 :‬هـ رقم‬\n                               ‫الدعوى‪32507275:‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 3433818‬تاريخه‪1434/2/10 :‬هـ‬\n\n\n       ‫قتــل ‪ -‬القتــل العمــد وشــبه العمــد اخلطــأ ‪ -‬قتــل خطــأ ‪ -‬حــدث ‪ -‬إقــرار‬\n       ‫املدعــى عليــه ‪ -‬تنــازل عــن احلــق اخلــاص ‪ -‬مشــروعية االســتئناس‬\n       ‫بالقرائــن يف حتديــد القصــد اجلنائــي ‪ -‬رد دعــوى اإلدانــة بالقتــل‬\n       ‫اخلطــأ ‪ -‬عــدم صحــة تنــازل الولــي عــن حقــوق القاصريــن حتــت واليتــه‬\n\n\n\n\n                                              ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n       ‫جــرى توجيــه مــن قبــل االدعــاء العــام علــى املدعــى عليــه احلــدث بقيامــه‬\n       ‫بقتــل شــقيقه عمــدا وعدوانــا وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n       ‫بعقوبــة تعزيريــة حيــث تلقــت الشــرطة بالغــا عــن وجــود شــخص مطعــون‬\n       ‫وباالنتقــال للموقــع واســتجواب أســرته ظهــر بــأن املدعــى عليــه هــو مــن‬\n       ‫تســبب بقتلــه علــى إثــر شــجار أســري ‪ ،‬انتهــى احلــق اخلــاص بالتنــازل ‪،‬‬\n       ‫أقــر املدعــى عليــه بتســببه يف قتــل أخيــه ودفــع بأنــه لــم يكــن عمــدا بــل‬\n       ‫خطــأ حيــث ال توجــد عــداوة بينــه وبــن املجنــي عليــه حيــث تدخــل لفــك‬\n       ‫الشــجار بــن املجنــي عليــه وشــقيقه اآلخــر فلمــا تفرقــا عــاد املجنــي عليــه‬\n       ‫وبيــده ســكينا والمــه علــى فــض واقعــة الضــرب بينهما وطعنــه يف ذراعه‬\n       ‫األيســر ثــم رفــع يــده مــرة أخــرى ليطعنــه بهــا فمســك يــده ودفعــه للخلــف‬\n\n‫‪79‬‬\n\f‫فارتــدت الســكني عليــه نحــو قلبــه ثــم ســار قليــا وســقط علــى األرض‬\n‫‪ ،‬وألن الظاهــر انتفــاء قصــد اجلنايــة وقصــده الدفــاع عــن نفســه ‪ ،‬يؤيــده‬\n‫تصديــق ورثــة املجنــي عليــه ‪ ،‬لــذا وألن القصــد خفــي وإمنــا يســتدل لــه‬\n‫بالقرائــن ‪ ،‬وألن القرائــن املصاحبــة للجنايــة تؤيــد صحــة دفعــه لعــدم‬\n‫ثبــوت حملــه الســكني ابتــداء وعــدم وجــود عــداوة ســابقة عليــه ولتنــازل‬\n‫الورثــة عــن الديــة ‪ ،‬وملجمــوع مــا تقــدم فقــد قــررت احملكمــة صــرف‬\n‫النظــر عــن طلــب املدعــي العــام إثبــات صفــة قتــل املدعــى عليــه للمجنــي‬\n‫كمــت ‪،‬‬  ‫ـاء وبذلــك َح َ‬‫عليــه عمــدا وثبــوت إدانــة املدعــى عليــه بقتلــه خطـ ً‬\n‫أفهــم املدعــى عليــه بــأن عليــه كفــارة قتــل اخلطــأ ‪ ،‬قــرر املدعــى عليــه‬\n‫القناعــة واملدعــى العــام عدمهــا بــدون تقــدمي الئحــة ‪ ،‬عــادت القضيــة‬\n‫مــن محكمــة االســتئناف مبلحوظتــن األولــى بأنــه جــرى ضبــط تنــازل‬\n‫والــدة املقتــول أصالــة وواليــة وســكت عــن إثباتــه مــن عدمــه واملتعــن‬\n‫إثباتــه بحــق البالــغ دون القاصــر‪ ،‬واألخــرى بطلــب إعــادة النظــر يف‬\n‫حتديــد صفــة القتــل بالنظــر إلــى اآللــة (الســكني) مــع مــا صاحــب‬\n‫ذلــك مــن شــجار واعتــراف املدعــى عليــه بأنــه مســك بيــد املجنــي عليــه‬\n‫وبيــده الســكني فدفعــه فطعــن نفســه وأن أقــل األحــوال أن يكــون شــبه‬\n‫عمــد‪ ،‬أجابــت احملكمــة عــن امللحوظتــن بأنهــا لــم تقــم بضبــط التنــازل‬\n‫بصفــة مســتقلة يف ضبــط التنــازالت وإمنــا ذكــرت ذلــك ملــا تنازلــت يف‬\n‫احملكمــة العامــة كمــا هــو موضــح يف أوراق املعاملــة ‪ ،‬وعــن امللحوظــة‬\n‫الثانيــة بــأن املدعــى عليــه لــم يقصــد اجلنايــة وأن العمــد و شــبه العمــد‬\n‫يتفقــان يف القصــد ويختلفــان يف اآللــة ‪ ،‬والقتــل اخلطــأ ليــس فيــه قصــد‬\n‫اجلنايــة واملدعــى عليــه لــم يقصــد اجلنايــة حيــث ال عــداوة مســبقة وال هــو‬\n‫مــن جــاء بالســكني وطعــن لــذا لــم يظهــر لهــا مــا يوجــب الرجــوع عــن‬\n                       ‫احلكــم ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n                                                                                       ‫‪80‬‬\n\f     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪..........‬القاضــي باحملكمــة اجلزئيــة‬\n     ‫ـاء علــى املعاملــة احملالــة إلــي مــن فضيلــة الرئيــس‬\n                                                            ‫مبنطقــة تبــوك وبنـ ً‬\n     ‫املساعد برقم ‪ 321233181‬وتاريخ ‪ 1432 / 10 / 2‬ه ـ ويف متام الساعة‬\n     ‫العاشــرة مــن هــذا األربعــاء املوافــق ‪ 1433 / 1 /5‬هـ ـ افتتحــت اجللســة‬\n     ‫وفيهــا حضــر املدعــي العــام ‪.......... /‬ســعودي مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪..........‬واملعمــد مــن احملكمــة برقــم ‪..........‬يف ‪ 1431 / 7 / 15‬هـ ـ‬\n     ‫وحضــر حلضــوره املدعــى عليــه‪.......... /‬ســعودي اجلنســية مبوجب الســجل‬\n     ‫املدنــي رقــم ‪..........‬فأدعــى قائــا يف حتريــر دعــواه أنــه يف يــوم األحــد‬\n     ‫املوافــق ‪1432/6/26‬ه ـ ويف متــام الســاعة الرابعــة عصــر ًا ورد بــاغ مــن‬\n     ‫مستشــفى امللــك فهــد بتبــوك ملركــز شــرطة ‪..........‬عــن وجــود شــخص‬\n     ‫مطعــون وهــو بحالــة حرجــة وباالنتقــال واملعاينــة تبــن أنــه املجنــي عليــه‬\n     ‫‪..........‬وبســماع أقــوال شــقيق املجنــي عليــه‪ .......... /‬أفــاد أنــه وجــد أخــوه‬\n     ‫املجنــي عليــه مطعــون وممــدد خــارج املنــزل بالقــرب مــن زاويــة املنــزل ‪.‬‬\n     ‫وباالنتقــال واملعاينــة ملوقــع اجلرميــة تبــن أنــه ال يوجــد آثــار أو عالمــات‬\n     ‫ـاء علــى عــدم وجــود أي‬ ‫تــدل علــى أن الواقعــة حصلــت خــارج املنــزل وبنـ ً‬\n     ‫معلومــات فقــد مت معاينــة املنــزل مــن الداخــل وقــد تبــن وجــود آثــار دمــاء‬\n     ‫علــى بعــض اجلــدران واملوكيــت ومت رفعهــا ومبناقشــة أشــقاء املتوفــى‪/‬‬\n     ‫‪10(..........‬ســنوات ) أفــادوا بــأن هنــاك مشــكلة حدثــت بــن شــقيقهم‪/‬‬\n     ‫‪..........‬املجنــي عليــه و‪..........‬اجلانــي وأن بهــا آلــة حــادة ـ ســكني ـ وأن‬\n     ‫شــقيقهم‪.......... /‬اجلانــي تعــرض للطعــن بكتفــه األيســر وشــقيقهم‬\n     ‫‪..........‬املجنــي عليــه تعــرض لطعنــه بصــدره‪ ،‬وباالنتقــال إلــى مستشــفى‬\n\n‫‪81‬‬\n\f‫‪ ...........‬ملعاينــة جثمــان املتوفــى اتضــح أنــه بالعقــد الثالــث مــن العمــر‬\n‫بطــول حوالــي ‪170‬ســم حنطــي البشــرة لــون الشــعر أســود وطويــل يرتــدي‬\n‫ســروال أبيــض طويــل لــم يتــم العثــور علــى متزقــات وعليــه بقــع بلــون أحمــر‬\n‫يشــتبه أنهــا دم وكذلــك يرتــدي ســروال قصيــر بلــون أبيــض عليــه بقــع‬\n‫بلــون أحمــر يشــتبه أنهــا دم و فانيلــة نــص كــم مقصــوص أثناء اإلســعاف‬\n‫بــه متــزق بطــول ‪3‬ســم بأعلــى الصــدر مــن الناحيــة اليســرى وعليــه بقــع‬\n‫بلــون أحمــر يشــتبه أن تكــون دم واتضــح وجــود جــرح طعنــي أعلــى يســار‬\n‫الصــدر بطــول حوالــي ‪2.5‬ســم وكذلــك جــرح أيســر الصــدر مــكان‬\n‫تركيــب أنبــوب لتصريــف الســوائل ‪ ،‬ويف يــوم األحــد املوافــق‬\n‫‪1432/7/17‬ه ـ مت االنتقــال للموقــع الــذي حدثــت فيــه اجلرميــة مبنزلهــم‬\n‫الكائــن بحــي ‪..........‬وقــام املدعــى عليــه بتمثيــل اجلرميــة وكان متثيــل‬\n‫اجلرميــة مطابــق ملــا ذكــرة املدعــى عليــه ‪ ،‬وقــد مت عــرض احلــدث علــى‬\n‫فضيلــة قاضــي األحــداث وأمــر بإيقافــه حتــى محاكمتــه كمــا هــو‬\n‫مرفــق لفــه (‪ )59‬صفحــة (‪، )15‬وباســتجواب املدعــى عليــه‪.......... /‬أقــر‬\n‫بأنــه يف يــوم األحــد املوافــق ‪1432/6/26‬ه ـ ويف حوالــي الســاعة الثالثــة‬\n‫عصــر ًا حدثــت مشــاجرة بــن األخويــن ‪..........‬و‪..........‬وقــام بالتفريــق‬\n‫بينهمــا وذهــب ‪..........‬إلــى مجلــس الرجــال مــع أمــه وأخواتــه وذهــب‬\n‫املجنــي عليــه‪.......... /‬إلــى غرفتــه اخلاصــة ومكــث املدعــى عليــه ‪..........‬‬\n‫بصالــة املنــزل وال يوجــد عنــده أحــد وفجــأة خــرج املجنــي عليــه‪.......... /‬‬\n‫مــن غرفتــه اخلاصــة وبيــده اليمنــى ســكني ( نصــاب خضــرة ) لونهــا‬\n‫أبيــض وهــو يقــول لــه ( ملــاذا فككــت بينــي وبــن ‪ )..........‬فقــال لــه‬\n‫املدعــى عليــه ( ال نريــد مشــاكل ) فقــام املجنــي عليــه‪.......... /‬وطعــن‬\n‫املدعــى عليــه يف عضــده األيســر فأمســك املدعــى عليــه بيــد املجنــي‬\n\n\n                                                                                       ‫‪82‬‬\n\f     ‫عليــه‪.......... /‬ودفعــه علــى صــدره فدخلــت الســكني يف صــدر املجنــي‬\n     ‫عليــه‪.......... /‬فهــرب املدعــى عليــه نحــو مجلــس الرجــال وكان يلحــق بــه‬\n     ‫املجنــي عليــه ويقــول لــه ( فــدا كــذا الذيــب ) وســقط بعدها أمــام املطبخ‬\n     ‫باملمــر وقــام املدعــى عليــه بإخبــار أخيــه‪.......... /‬فقامــا بحمــل املجنــي‬\n     ‫عليــه ‪.......... /‬وإركابــه يف الســيارة مــن نــوع ‪ ..........‬لونهــا أســود مــع‬\n     ‫ذهبــي وذهــب بــه ‪ .......‬إلــى املستشــفى إلســعافه وعــاد املدعــى عليــه إلــى‬\n     ‫املنــزل وأخبــر والدتــه وشــقيقته‪.......... /‬مبــا حصــل واتصــل املدعــى عليــه‬\n     ‫علــى أخويــه‪.......... /‬و‪ ..........‬وأخبرهــم مبــا حصــل وأفــاد املدعــى عليــه‬\n     ‫بــأن الســكني املســتخدمة يف اجلرميــة قــام أخــوه الصغيــر املدعــو‪.......... /‬‬\n     ‫برميهــا يف حاويــة النفايــات اخلاصــة باملنــزل وصــادق علــى إقــراره شــرع ًا‬\n     ‫‪ ،‬وبضبــط إفــادة شــقيق املدعــى عليــه واملجنــي عليــه‪.......... /‬أفــاد أنــه يف‬\n     ‫يــوم االحــد املوافــق ‪1432/6/26‬ه ـ حوالــي الســاعة الثانيــة ظهــر ًا‬\n     ‫اســتيقظ شــقيقه ‪..........‬مــن نومــه ويطالــب بالفطــور وقــام بتنــاول وجبــة‬\n     ‫اإلفطــار وبعــد انتهائــه مــن اإلفطــار ذهــب إلــى غرفتــه وذهــب هــو إلــى‬\n     ‫املطعــم إلحضــار وجبــة الغــداء وعندمــا أحضــر الغــداء إلــى املنــزل طلبــوا‬\n     ‫مــن ‪..........‬أن يشــاركهم يف الغــداء هــو وأمــه وأختــه ‪..........‬و‪..........‬‬\n     ‫و‪ ..........‬و‪ ..........‬لكنــه رفــض وال يريــد الغــداء وبعــد انتهائهــم مــن‬\n     ‫الغــداء حضــر إلــى أمه‪..........‬وطلــب منهــا أن تعمــل لــه قهــوة تركيــة‬\n     ‫فقالــت لــه أمــه أنــا ال أشــتغل عنــدك خدامــة وأخــذ يتلفــظ علــى أمــه‬\n     ‫بألفــاظ غيــر الئقــة ويقــوم بلعنهــا فقــام إليــه فأمــره بــأن يذهــب إلــى‬\n     ‫غرفتــه لكونــه دائمـ ًا يعمــل مشــاكل يف البيــت فرفــض أن يذهــب إلــى‬\n     ‫غرفتــه وقــام ‪..........‬بضربــه علــى صــدره بيــده وقــام هــو بدفعه وتشــابكا‬\n     ‫فقــام أخيــه ‪..........‬بالتفريــق بينهمــا وفكهــم عــن بعــض فذهــب أخيــه‬\n\n\n‫‪83‬‬\n\f‫‪..........‬إلــى غرفتــه وذهــب هــو إلــى مجلــس الرجــال مــع والدتــه وأختــه‬\n‫‪..........‬وأخيــه ‪..........‬وأخيــه ‪..........‬وأخيــه ‪..........‬فبعدهــا قــال ألخيــه‬\n‫‪..........‬اذهــب وأكــوي ثوبــه يف الصالــة فبعدمــا ذهــب ‪..........‬وســمع‬\n‫صــوت شــجار بــن أخيــه ‪..........‬وأخيــه ‪..........‬فشــاهد عــن طريــق املنظرة‬\n‫أخيــه ‪..........‬ميــد يــده علــى ‪ ..........‬فبعدهــا هــرب ‪..........‬إلــى املجلــس‬\n‫فلحــق بــه أخيــه ‪..........‬فأمســك ب‪ ..........‬وشــاهد الــدم علــى صــدره فقال‬\n‫هيــا نذهــب إلســعافك باملستشــفى فســقط ‪..........‬علــى األرض عنــد بــاب‬\n‫املطبــخ وقــام بعدهــا هــو وأخيــه ‪..........‬بحملــه ونقلــه بالســيارة مــن نــوع‬\n‫‪ ........‬أســود وذهبــي بــه لوحــده إلــى مستشــفى ‪ ......‬ولــم يذهــب معــه أخيــه‬\n‫‪..........‬وحينمــا دخــل إلــى املستشــفى اخبرهــم بأنــه مطعــون فجلــس‬\n‫ينتظــر ويــرى مــاذا يحصــل فحضــر إليــه أخيــه ‪..........‬باملستشــفى بقســم‬\n‫الطــوارئ وبعدهــا تلقــى خبــر وفاتــه حينمــا عــاد إلــى البيــت ‪.‬وقــد مت‬\n‫حفــظ االتهــام بحــق املدعــو‪.......... /‬يف قضيــة املضاربــة بينــه وبــن املجني‬\n‫عليــه لعــدم كفايــة األدلــة وذلــك اســتناد ًا للمــادة رقــم (‪ )124‬مــن نظــام‬\n‫اإلجــراءات اجلزائيــة ‪ ،‬وبضبــط إفــادة املــرأة‪ .......... /‬والــدة اجلانــي‬\n‫واملجني عليه أفادت أنه يف يوم األحد املوافق ‪1432/6/26‬هـ اســتيقظ‬\n‫ابنهــا‪.......... /‬املجنــي عليــه الســاعة الثانيــة ظهــر ًا وكعادتــه يقــوم‬\n‫بالصيــاح عليهــم والصــراخ لكونــه مريــض حركي ـ ًا ولديــه اختــال يف‬\n‫املــخ يحصــل لــه أحيان ـ ًا بعــد حــادث مــروري حصــل لــه وطلــب طعــام‬\n‫اإلفطــار وبعــد انتهائــه مــن الفطــور رجــع إلــى غرفتــه وقرابــة الســاعة‬\n‫الثالثــة والنصــف قامــوا مبناداتــه مــن أجــل أن يتغــدى معهــم فرفــض أن‬\n‫يشــاركهم يف الغــداء وبعــد أن انهــوا الغــداء جــاء ابنهــا‪.......... /‬وهــم يف‬\n‫صالــة املنــزل وطلــب منهــا وهــو يســب ويشــتم أن تعمــل لــه فنجــان قهــوة‬\n\n\n                                                                                         ‫‪84‬‬\n\f     ‫تركــي فقالــت لــه أنــا مانــي خدامــة عنــدك فأخــذ يســبها ويلعنهــا‬\n     ‫ويشــتهما فقــام ابنهــا‪.......... /‬يدافــع عنهــا ويقــول ألخيــه‪.......... /‬ليــش‬\n     ‫تســب أمــي وتلعنهــا وحصلــت بينهــم مشــابكة باأليــدي فقــام ابنهــا‪/‬‬\n     ‫‪..........‬بالتفريــق بــن إخوانــه وإبعادهــم عــن بعــض فقامــت بعدهــا بأخــذ‬\n     ‫ابنهــا‪.......... /‬و‪ ..........‬و‪ ..........‬و‪ ..........‬و‪ ..........‬وذهبــت بهــم إلــى مجلــس‬\n     ‫الرجــال الكتفــاء شــر ابنهــا‪.......... /‬حيــث أنــه دائمـ ًا يســبب املشــاكل‬\n     ‫بــن إخوانــه وذكــرت بأنهــم أثنــاء جلوســهم باملجلــس أمــر ابنهــا ‪..........‬‬\n     ‫أخــوه ‪..........‬بــأن يكــوي لــه ثــوب املوجــود يف الصالــة فقــام ‪..........‬وذهــب‬\n     ‫إلــى الصالــة وفجــأة ســمعت صــوت ابنهــا ‪..........‬مرتفعـ ًا عاليـ ًا كعادتــه‬\n     ‫يســب ويشــتم إخوانــه ولــم تذهــب لهــم ألننهــم متعوديــن علــى ســبه‬\n     ‫وصياحــه وأفــادت بــأن أبنهــا ‪..........‬أخبرهــا بــأن أخويــه ‪..........‬و‪..........‬‬\n     ‫متطاعنــن بالســكني ويريــد أن يذهــب ب‪ ..........‬إلى املستشــفى فقامت‬\n     ‫لتنظــر مــاذا حصــل فشــاهدت ابنهــا ‪..........‬واقــف وفنيلتــه عليهــا دم‬\n     ‫بســيط ومتقطعــة ثــم أســعفوه إلــى املستشــفى وبعدهــا علمــت بوفاتــه‬\n     ‫باملستشــفى ‪.‬وقــد مت حفــظ االتهــام بحــق املجنــي عليــه يف قضيــة ســبه‬\n     ‫لوالدتــه النقضــاء الدعــوى اجلزائيــة بوفــاة املجنــي عليــه وذلــك اســتناد ًا‬\n     ‫للمــادة رقــم (‪ )22‬مــن نظــام اإلجــراءات اجلزائيــة‪ ،‬وبضبــط إفــادة الفتاة‪/‬‬\n     ‫‪..........‬أفــادت أنــه يف يــوم األحــد املوافــق ‪1432/6/26‬ه ـ عــادت مــن‬\n     ‫املدرســة إلــى البيــت قرابــة الســاعة الواحــدة والنصــف وكان يف املنــزل‬\n     ‫والدتهــا وإخوانهــا ‪..........‬و‪ ..........‬و‪ ..........‬و‪ ..........‬و‪ ..........‬فاســتيقظ‬\n     ‫أخيهــا ‪..........‬وخــرج مــن غرفتــه وهــو يطلــب طعــام اإلفطــار وأعــدت لــه‬\n     ‫اإلفطــار فــول وأفطــر يف الصالــة فذهبــت إلــى غرفتهــا لتســتريح مــن‬\n     ‫عنــاء الدراســة وفجــأة ســمعت صــوت أخيهــا ‪..........‬عالي ـ ًا يســب ويلعــن‬\n\n\n‫‪85‬‬\n\f‫فخرجــت مــن غرفتهــا يف يــوم األحــد املوافــق ‪1432/6/26‬ه ـ ويف متــام‬\n‫الســاعة الثالثــة عصــر ًا كنــا جالســن بالصالــة فخــرج أخيــه ‪..........‬مــن‬\n‫غرفتــه وطلــب مــن أمــه إصــاح قهــوة تركيــة فرفضــت أمــه فجلــس‬\n‫يســب عليهــا ويلعــن فقــام عليــه أخــي ‪..........‬يخاصمــه وحصلــت بينهــم‬\n‫مشــاجرة فقــام أخيــه ‪..........‬يفــك بينهــم فقامــت أمــه بأخذهــم إلــى‬\n‫مجلــس الرجــال إال أنــه جلــس يف الصالــة فرجــع إلــى أخيــه ‪..........‬وهــو‬\n‫يف الصالــة يريــد أن يكــوي ثوب ـ ًا فخــرج أخيــه ‪..........‬مــن غرفتــه ومعــه‬\n‫ســكني وقــال ل‪..........‬ملــاذا دزيتنــي ) فقــام ‪..........‬بطعــن ‪..........‬يف ذراعه‬\n‫فتشــاجرا فقــام ‪..........‬وكان يريــد أخــذ الســكني مــن يــد ‪..........‬فقــام‬\n‫‪..........‬بــرد الســكني إلــى صــدره فهــرب ‪..........‬إلــى املجلــس وحلــق بــه‬\n‫‪..........‬ويف الطريــق ســقط ‪..........‬باملمــر مقابــل املطبــخ وكان يشــاهد‬\n‫الــدم علــى صــدر ‪..........‬وهــذا مــا حصــل ‪ .‬وقــد صــدر بحــق املجنــي عليــه‬\n‫‪........../‬التقريــر الطبــي الشــرعي النهائــي رقم‪..........‬وتاريــخ‬\n‫‪1432/7/1‬ه ـ املتضمــن أن الوفــاة ناجتــة عــن اجلــرح الطعنــي باجلهــة‬\n‫اليســرى مــن الصــدر والــذي أدى إلــى متــزق بالرئــة اليســرى والشــريان‬\n‫الرئــوي ومــا نتــج عنــه مــن نــزف وصدمــه نزفيــه‪ .‬كمــا صــدر بحــق‬\n‫املدعــى عليــه ‪........../‬التقريــر الطبــي رقــم (‪ )..........‬وتاريــخ‬\n‫‪1432/6/28‬ه ـ املتضمــن وجــود جــرح قطعــي بالكتــف األيســر حوالــي‬\n‫‪1‬ســم ومــدة الشــفاء أســبوع واحــد وقــد أســفر التحقيــق عــن توجيــه‬\n‫االتهــام للحــدث‪.......... /‬بقتــل شــقيقه‪.......... /‬عمــد ًا وعدوان ـ ًا وذلــك‬\n‫بطعنــه بســكني يف صــدره أدت لوفاتــه وذلــك لألدلــة والقرائــن اآلتيــة ‪:‬‬\n                                                                                     ‫‪-‬‬\n          ‫‪ -1‬ما جاء باعترافه املصادق عليه شرع ًا املرفق لفه رقم (‪. )68‬‬\n\n\n                                                                                         ‫‪86‬‬\n\f     ‫‪ -2‬مــا جــاء مبحضــر االنتقــال واملعاينــة املــدون علــى الصفحــة رقــم‬\n                                                          ‫(‪ )10‬املرفــق برقــم (‪. )99‬‬\n     ‫‪ -3‬مــا جــاء بأقــوال والــدة املدعــى عليــه وأشــقائه ( ‪-.......... ..........‬‬\n     ‫‪ ).......... ،..........‬املدونــة علــى دفاتــر التحقيــق املرفقــة لفــة رقــم (‪)59‬‬\n                                                                              ‫ورقــم (‪)42‬‬\n             ‫‪ -4‬ما جاء بتقرير الطب الشرعي املرفق لفه رقم ( ‪) 78 , 70‬‬\n     ‫‪ -5‬مــا جــاء مبحضــر متثيــل اجلرميــة وأنــه مطابــق ملــا جــاء يف أقــوال‬\n                                            ‫املدعــى عليــه املرفــق لفــه رقــم (‪. )84‬‬\n                       ‫‪ -6‬ما جاء بتقرير األدلة اجلنائية املرفق لفه رقم (‪. )87‬‬\n                     ‫‪ -7‬ما جاء مبحضر معاينة اجلثة لفه رقم (‪ )43‬ص (‪)10‬‬\n          ‫‪ -8‬التقرير الطبي املرفق اخلاص باملدعى عليه املرفق لفه (‪. )15‬‬\n     ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه احلــدث املذكــور من قتــل النفس‬\n     ‫عمــد ًا بغيــر حــق فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب ‪ -1:‬إثبات‬\n     ‫مــا أســند إليــه ‪ -2،‬احلكــم عليــه بعقوبــة تأديبيــة لقــاء احلــق العــام يف‬\n     ‫ضــوء املــادة (‪ )174‬مــن نظــام اإلجــراءات اجلزائيــة‪ ( ،‬علم ـ ًا بــأن احلــق‬\n     ‫اخلــاص انتهــى بالتنــازل ) هــذه دعــواي وبعــرض دعــوي املدعــي العــام‬\n     ‫علــى املدعــي عليــه أجــاب بقولــه أن مــا ذكــره املدعــي العــام يف دعــواه‬\n     ‫مــن تســببي يف قتــل أخــي ‪..........‬صحيــح ولكــن لــم يكــن ذلــك عمــد ًا‬\n     ‫حيــث انــه ال توجــد بينــي وبــن املجنــي عليــه أي عــداوة وهــو شــقيقي وإمنــا‬\n     ‫كان ذلــك عــن طريــق اخلطــأ بســبب أن املجنــي عليــه توجــد بينــه وبــن‬\n     ‫أخــي ســوء تفاهــم وتدخلــت لفــك هــذا الشــجار بينهمــا وبعدهــا ذهــب‬\n     ‫أخــي املجنــي عليــه إلــى غرفتــه وذهــب أخــي ‪..........‬مــع أخوتــي ووالدتــي‬\n     ‫إلــى املجلــس فشــاهدت أخويهــا ‪..........‬و‪ ..........‬يتشــاجران وكان أخيهــا‬\n\n\n‫‪87‬‬\n\f‫‪..........‬يفــك بينهــا وبعــد انتهــاء املشــكلة قامــت أمهــا وأخذتهــم جميع ـ ًا‬\n‫إلــى مجلــس الرجــال وعــاد أخيهــا ‪..........‬إلــى غرفتــه وهــم يف املجلــس‬\n‫أمــر أخيهــا ‪..........‬أخيهــا ‪..........‬بــأن يكــوي لــه ثوب ـ ًا يف صالــة املنــزل‬\n‫فخــرج ‪..........‬مــن املجلــس وبعــد حلظــات جــاء أخيهــا ‪..........‬وذكــر أن‬\n‫أخويــه ‪..........‬و‪..........‬تطاعنــا بالســكني وشــاهدت ‪..........‬وكان يلبــس‬\n‫مالبــس داخليــة بيضــاء عليهــا دم وقــام ‪..........‬و‪ ..........‬بحمــل ‪..........‬‬\n‫بالســيارة وذهــب بــه ‪..........‬للمستشــفى وبضبــط إفــادة‪.......... /‬أفــاد بانــه‬\n‫شــاهد أخيــه ‪..........‬وأخيــه ‪..........‬يتشــاجران ففــك بينهــم أخيــه ‪..........‬‬\n‫وأخذتهــم أمهــم إلــى املجلــس وكان أخيــه ‪..........‬يســب ويشــتم وعــض‬\n‫أخيــه ‪..........‬أخيــه ‪..........‬يف أذنــه وهــذا مــا حصــل وبضبــط إفــادة‪/‬‬\n‫‪..........‬أفــاد بأنــه فطلــب منــي أخــي ‪..........‬أن أقــوم بكــوي ثوبــه فذهبــت‬\n‫إلــى الصالــة وبعدهــا ذهــب املجنــي عليــه ولــم انتبــه لــه وكانــت يف يــده‬\n‫ســكني فأجتــه إلـ ٌـي وقــال لــي ملــاذا فككــت املضاربــة بينــي وبــن أخــي‬\n‫‪..........‬فقلــت لــه يــا ‪..........‬مــا نبغــي مشــاكل بهــذه العبــارة فقــام بطعنــي‬\n‫يف ذراعــي األيســر ممــا أدى إلــى جرحــي ثــم رفــع يــده لكــي يطعنــي مــرة‬\n‫أخــرى فقمــت مبســك يــده ثــم دفعتــه إلــى اخللــف بقــوه فعــادت الســكني‬\n‫إلــى جهــة قلبــه وبعدهــا اخــذ ميشــي متجهــا للمجلــس وبعدهــا ســقط‬\n‫علــى األرض فقمــت بإخبــار أخــي ورأى املوقــف وبعدهــا قمــت بحملــه‬\n‫أنــا وأخــي ‪..........‬إلــى الســيارة والزال علــى قيــد احليــاة ثــم ذهــب بــه‬\n‫أخــي ‪..........‬إلــى املستشــفى هكــذا أجــاب كمــا جــرى ســؤاله املدعــى‬\n‫عليــه عــن بلوغــه وقــت اجلرميــة فأجــاب بقولــه كنــت بالغ ـ ًا وقــت اجلرميــة‬\n‫يف واحتالمــي هكــذا أجــاب وبســؤال‬            ‫وذلــك بظهــور عالمــات البلــوغ ٌ‬\n‫املدعــي العــام هــل لديــك بينــة علــى أن القتــل حصــل عمــدا فأجــاب ليــس‬\n\n\n                                                                                           ‫‪88‬‬\n\f     ‫لــدي بينــه ســوى مــا جــاء يف أوراق املعاملــة هكــذا أجــاب ويف أثنــاء‬\n     ‫اجللســة حضــرت والــدة املدعــى عليــه واملجنــي عليــه ‪.......... /‬ســعودية‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪..........‬وأخــوت املجنــي عليــه ‪/‬‬\n     ‫‪..........‬ســعودي مبوجــب الســجل املدنــي رقــم ‪..........‬و‪..........‬ســعودي‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪..........‬و‪ ..........‬ســعودي مبوجــب الســجل‬\n     ‫املدنــي رقــم ‪..........‬و‪ ..........‬ســعودية مبوجــب الســجل املدنــي رقــم ‪..........‬و‬\n     ‫‪..........‬ســعودية مبوجــب الســجل املدنــي رقــم ‪ ،..........‬وعليــه قــررت والدة‬\n     ‫املجنــي عليــه بــأن املجنــي عليــه لديــه أعاقــه يف يــده اليســرى وال يســتطيع‬\n     ‫إنزالهــا وكذلــك رجلــه اليســرى لديــه أصابــه بهــا وذلــك بســبب حــادث‬\n     ‫مــروري ممــا تســبب يف حصــول عــرج يف رجلــه وكمــا قــررت والــدة‬\n     ‫املجنــي عليــه وبحســب واليتهــا علــى القاصريــن ‪..........‬و‪ ..........‬وعــن‬\n     ‫نفســها بأنهــا متنازلــة يف احلــق اخلــاص كمــا قــرر بقولهــا إننــي أصــادق‬\n     ‫علــى صفــة القتــل وكيفيــه وقوعــه وأنــه كان خطــأ مــن املدعــى عليــه‬\n     ‫كمــا قــرروا إخــوة املدعــى عليــه واملجنــي عليــه بقولهــم أننــا متنازلــون‬\n     ‫عــن احلــق اخلــاص كمــا قــرروا املصادقــة علــى مــا ذكــره املدعــي عليــه‬\n     ‫مــن صفــة القتــل التــي ذكــر هكــذا أجابــوا ‪ ،‬فبنــاء علــى مــا تقــدم مــن‬\n     ‫الدعــوى واإلجابــة ولعــدم وجــود بينــه للمدعــي العــام علــى القتــل العمــد‬\n     ‫وملصادقــة ورثــة املجنــي عليــه يف صفــة القتــل وانــه كان على صفة اخلطأ‬\n     ‫ولكــون املدعــى عليــه ذكــر بأنــه قــام بدفــع املجنــي عليــه بعــد مــا طعنــه‬\n     ‫يف ذراعــه وكمــا ان املجنــي عليــه توجــد لديــه أعاقــه يف يــده اليســرى‬\n     ‫كمــا ذكــرت والدتــه ممــا يصعــب دفــع الســكني التــي ارتكــزت‬\n     ‫يف صــدره ومبــا انــه ال توجــد عــدواه بــن املدعــى عليــه واملجنــي عليــه‬\n     ‫ولكــون مــا قــرره الفقهــاء رحمهــم اهلل تعالــى مــن ان قتــل العمــد وشــبه‬\n\n\n‫‪89‬‬\n\f‫العمــد يتفقــان يف القصــد يف اجلنايــة إال إنهمــا يختلفــان يف اآللــة فالعمــد‬\n‫يف آلــة تقتــل غالبــا وشــبه العمــد مــاال تقتــل غالبــا واخلطــأ يســتثنى فيــه‬\n‫قصــد اجلنايــة فاملدعــى عليــه يظهــر منــه انــه لــم يقصــد اجلنايــة وإمنــا قصد‬\n‫دفــع املجنــي عليــه مــن إصابتــه مــرة أخــرى وممــا يؤكــد ذلــك مصادقــة‬\n‫ورثــة املجنــي عليــه ومبــا أن القصــد خفــي ال يظهــر وال يتجلــى إال بوجــود‬\n‫قرائــن تــدل عليــه فهنــا عــدم حملــه اآللــة ابتــداء وعــدم العــداوة املســبقة‬\n‫ومبــا أن ورثــة املجنــي عليــه قــد قــرروا تنازلهــم عــن حقهــم اخلــاص مــن‬\n‫الديــة وبنــاء علــى ذلــك كلــه فقــد صرفــت النظــر عــن إثبــات صفــة قتــل‬\n‫العمــد لعــدم الثبــوت كمــا ثبــت لــدي إدانــة املدعــى عليــه يف تســببه يف‬\n‫قتــل أخيــه وذلــك عــن طريــق اخلطــأ وبذلــك حكمــت وبعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــى عليــه القناعــة بــه وأمــا املدعــي العــام فقــرر‬\n‫اعتراضــه بــدون تقــدمي الئحــة اعتراضيــة ‪ ،‬كمــا انــه ســوف يتــم إفهامــه‬\n‫بالكفــارة بعــد اكتســاب احلكــم الصفــة القطعيــة وللبيــان حــرر يف‬\n‫‪1433 / 1/ 5‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه ‪،‬‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن املوافــق ‪1433/11/1‬ه ـ‬\n‫الســاعة العاشــرة جــرى فتــح ضبــط هــذه القضيــة وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف بخطابهــم رقــم وتاريــخ ‪1433/4/27‬ه ـ‬\n‫واملقيــدة باحملكمــة برقــم وتاريــخ ‪1433/5/3‬ه ـ ومشــفوعها قــرار‬\n‫الدائــرة اجلزائيــة الثانيــة رقــم ‪ 33150802‬وتاريــخ ‪1433/3/23‬ه ـ‬\n‫املتضمــن ( وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ‬\n‫باألكثريــة مــا يلــي‪ :‬أوال‪ :‬ضبــط فضيلتــه تنــازل والــدة املقتــول بصفتهــا‬\n‫وليــة علــى القاصريــن مــن الورثــة وســكت فضيلتــه عــن إثبــات ذلــك‬\n‫مــن عدمــه والواجــب أن يــرد هــذا التنــازل فيمــا يخــص القصــر ويفهــم‬\n\n\n                                                                                        ‫‪90‬‬\n\f     ‫الوليــة بأنــه ال يحــق لهــا التنــازل عــن حقــوق القاصريــن ‪ .‬ثانيــا ‪ :‬حكــم‬\n     ‫فضيلتــه بإدانــة املدعــى عليــه يف تســببه يف قتــل أخيــه عــن طريــق اخلطــأ‬\n     ‫وصــرف النظــر عــن طلــب املدعــي العــام إثبــات صفــة القتــل العمــد‬\n     ‫وهــذا يف غيــر محــل نظــر فالقتــل حصــل مــن املدعــى عليــه وال خــاف‬\n     ‫عليــه أمــا القصــد فتــدل عليــه آلــة القتــل وهــي الســكني التــي تقتــل‬\n     ‫غالبــا يضــاف إليهــا حصــول املشــاجرة بــن القاتــل واملقتــول و اعتــراف‬\n     ‫القاتــل أثنــاء احملاكمــة بــأن املقتــول بيــده الســكني وهــوى بهــا ليطعــن‬\n     ‫القاتــل فقــام مبســك يــد املقتــول وبهــا الســكني فدفعهــا بقــوة فانغــرزت‬\n     ‫الســكني يف صــدر أخيــه وقتلتــه فــإن لــم يكــن ذلــك قتــل عمــد فــا‬\n     ‫أقــل مــن أن يكــون شــبه عمــد فعلــى فضيلتــه إعــادة النظــر والتأمــل يف‬\n     ‫حكمــه ‪ .‬ثالثــا‪ :‬صــورة الضبــط لــم توقــع مــن قبــل املختــص والبــد مــن‬\n     ‫ذلــك فعلــى فضيلتــه إكمــال الــازم وإحلــاق مــا يجــد للضبــط وصــورة‬\n     ‫والقــرار وســجله وإعــادة املعاملــة كاملتبــع واهلل املوفــق وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬قاضــي اســتئناف ‪ ..........‬ختــم‬\n     ‫وتوقيــع‪ ،‬قاضــي اســتئناف د‪...........‬ختــم وتوقيــع ‪ ،‬رئيــس الدائــرة ‪..........‬‬\n     ‫ختــم وتوقيــع ‪ .‬فأقــول جوابــا علــى مالحظــة أصحــاب الفضيلــة أوال‪ :‬لــم‬\n     ‫أقــم بضبــط التنــازل بصفــة مســتقلة يف ضبــط التنــازالت وإمنــا ذكــرت‬\n     ‫ذلــك ملــا تنازلــت يف احملكمــة العامــة كمــا هــو موضــح يف أوراق املعاملة‬\n     ‫‪ ،‬أمــا امللحوظــة الثانيــة فلــم يظهــر لــي خــاف مــا توصلــت إليــه لكــون‬\n     ‫املدعــى عليــه لــم يقصــد اجلنايــة و كمــا ال يخفــى على أصحــاب الفضيلة‬\n     ‫أن العمــد و شــبه العمــد ينفعــان يف القصــد ويختلفــان يف اآللــة والقتــل‬\n     ‫اخلطــأ ليــس فيــه قصــد اجلنايــة وهنــا املدعــى عليــه لــم يقصــد اجلنايــة‬\n     ‫حيــث ال عــداوة مســبقة وال هــو مــن جــاء بالســكني وطعــن ‪ ،‬وأمــا‬\n\n\n‫‪91‬‬\n\f‫امللحوظــة الثالثــة فقــد جــرى إكمــال الــازم وعليــه فــا أزال مســتمرا‬\n‫علــى مــا حكمــت بــه وللبيــان حــرر يف متــام الســاعة العاشــرة و الربــع‬\n‫مــن يــوم االثنــن املوافــق ‪1433/11/1‬ه ـ وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم ‪ .‬احلمــد هلل وحــده وبعــد ‪ ....‬فقــد اطلعنــا نحــن‬\n‫قضــاة الدائــرة الثانيــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف‬\n‫مبنطقــة اجلــوف علــى املعاملــة الــواردة مــن احملكمــة اجلزائيــة بتبــوك‬\n‫برقــم وتاريــخ ‪1433/11/14‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة الشيخ‪........../‬املســجل برقــم يف‪1433/1/8‬ه ـ اخلــاص بدعــوى‬\n‫املدعــي العــام ضــد‪ .......... /‬يف قضيــة إثبــات صفــة القتــل وقــد تضمــن‬\n‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلــة‬\n‫القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا الســابق رقــم‬\n‫‪ 33150802‬وتاريــخ ‪1433/3/23‬ه ـ تقــرر باألكثريــة املصادقــة علــى‬\n‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                         ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪92‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":79,"source_page_end":92,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7c429200b291ed220ce9d10f553239c9391ddbfe65063d818af6e094d8626f41","normalized_text_hash":"f4ae4df3ad22317eba3821e122aee55b1028e6475fc3c83a67fc816de5da9346","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p79-3312366"},{"id":"80a10ed6-1951-5562-9e2c-a969cae89ff4","document_type":"judgment","category":"judicial","subcategory":"general","title":"قتل عمد -إثبات صفة القتل العمد ،حد املسكر ،قيادة حتت تأثير املسكر ،إقرار ،تنازل عن حق خاص ،تقرير أدلة جنائية ، إدانة بالقتل العمد وانطباق موجب تطبيق اإلرادة امللكية على قاتل العمد مبعرفة اجلهة املختصة.","document_number":"33460348","case_number":"33167151","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/21","year":"1434","subject":"قتل عمد -إثبات صفة القتل العمد ،حد املسكر ،قيادة حتت تأثير املسكر ،إقرار ،تنازل عن حق خاص ،تقرير أدلة جنائية ، إدانة بالقتل العمد وانطباق موجب تطبيق اإلرادة امللكية على قاتل العمد مبعرفة اجلهة املختصة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 33460348 :‬تاريخه‪1433/11/21 :‬هـ‬\n                           ‫رقم الدعوى‪33167151:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 33273852‬تاريخه‪1433/6/1 :‬هـ‬\n\n\n       ‫قتــل عمــد ‪ -‬إثبــات صفــة القتــل العمــد ‪ ،‬حــد املســكر ‪ ،‬قيــادة حتــت‬\n       ‫تأثيــر املســكر ‪ ،‬إقــرار ‪ ،‬تنــازل عــن حــق خــاص ‪ ،‬تقريــر أدلــة جنائيــة ‪،‬‬\n       ‫إدانــة بالقتــل العمــد وانطبــاق موجــب تطبيــق اإلرادة امللكيــة علــى قاتــل‬\n                                                 ‫العمــد مبعرفــة اجلهــة املختصــة‪.‬‬\n\n\n\n\n       ‫‪ -1‬األمــر الســامي رقــم ‪ 10711‬يف ‪1393/5/2‬ه ـ وقــرار مجلــس القضــاء‬\n       ‫األعلــى بهيئتــه الدائمــة برقــم‪ 3/51‬يف ‪1409/3/6‬ه ـ املؤيــد باألمــر‬\n       ‫الســامي رقــم ‪/1197/4‬م يف ‪1409/6/2‬ه ـ املبلــغ بالتعميــم ‪/8‬ت‪ 95/‬يف‬\n       ‫‪1409/7/25‬ه ـ بشــأن تطبيــق اإلرادة امللكيــة علــى قاتــل العمــد وشــبه‬\n       ‫العمــد إذا تنــازل أوليــاء الــدم عــن القصــاص (التصنيــف املوضوعــي‬\n                                                  ‫لتعاميــم وزارة العــدل ‪.)782/1‬‬\n\n\n\n       ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه األول بقتــل املجني‬\n       ‫عليــه عمــد ًا بإطــاق النــار عليــه مــن مسدســه احلكومــي‪ ،‬وشــرب األول‬\n       ‫والثانــي للمســكر الــذي أحضــره األول وحيازتهمــا لــه وقيــادة الثانــي‬\n       ‫للســيارة حتــت تأثيــر املســكر ‪ ،‬وطلــب إثبــات إدانتهمــا مبــا أســند‬\n       ‫إليهمــا وإثبــات صفــة القتــل العمــد وتطبيــق اإلرادة امللكيــة بحــق القاتــل‬\n\n‫‪93‬‬\n\f‫املدعــى عليــه األول واحلكــم عليهمــا بحد شــرب املســكر وقيــادة الثاني‬\n‫للســيارة حتــت تأثيــر املســكر وإفهامــه بــأن عقوبته يف ذلــك عائد للجهة‬\n‫املختصــة حيــث ورد بــاغ عــن وجــود شــخص متوفــى يف املستشــفى بطلق‬\n‫نــاري ‪ -‬بتفتيــش الســيارة الواقفــة أمــام بــاب الطــوارئ عثــر علــى ســاح‬\n‫نــاري وثالثــة أظــرف فارغــة وأربــع طلقــات حيــة داخــل جــراب املســدس‬\n‫وقــارورة مــاء بهــا مــادة (العــرق) املســكر ‪ -‬باستشــمام املدعــى عليهمــا‬\n‫ظهــر انبعــاث رائحــة املســكر مــن أفواههمــا ‪-‬صــدر تقريــر مــن األدلــة‬\n‫اجلنائيــة بــأن الطلقــات املســتخرجة مــن جســم املجنــي عليــه تعــود‬\n‫للمســدس املضبــوط بالســيارة ‪ -‬حضــر وكيــل ورثــة املقتــول وقــرر‬\n‫تنــازل موكليــه عــن املدعــى عليــه األول ‪ -‬أقــر املدعــى عليــه األول بأنــه‬\n‫ركــب مــع املدعــى عليــه الثانــي واملجنــي عليــه بســيارة وتعاطــوا جميعــا‬\n‫املســكر الــذي أحضــره لهــم وجتولــوا بالســيارة وكان معــه مسدســا‬\n‫حكوميــا فأطلــق طلقــة يف الهــواء مازحــا وكان يظــن املســدس خاليــا‬\n‫مــن الطلقــات فانطلقــت رصاصــة مــن مسدســه نحــو املجنــي عليــه ودفــع‬\n‫بأنــه لــم يتعمــد قتلــه ومتنــى لــو أن الطلقــة أصابتــه ولــم تصــب املجنــي عليه‬\n‫لكونــه عزيــزا عليــه وأنــه تائــب ‪ -‬جــرى ســؤال املدعــى عليــه عــن خدمته‬\n‫العســكرية فأجــاب بأنهــا ســبعة عشــر عامــا‪ ،‬كمــا جــرى ســؤاله هــل‬\n‫يوجــد يف املســدس تأمــن فأجــاب بأنــه ال يوجــد بــه تأمــن ‪ -‬أقــر املدعــى‬\n‫عليــه الثانــي بشــربه املســكر وقيامــه بقيــادة الســيارة حتــت تأثيــره وأنــه‬\n‫تائــب ‪ -‬جــرى االطــاع علــى التقريــر الفنــي اجلنائــي املتضمــن اإلشــارة‬\n‫ألثــر الطلقــات التــي كانــت موجــودة علــى جســم املدعــى عليــه ‪ -‬عليــه‬\n‫وإلقــرار املدعــى عليهمــا أنهمــا شــربا املســكر وإلقــرار املدعــى عليــه‬\n‫األول بأنــه أشــهر ســاحه علــى املدعــى عليــه الثانــي واملجنــي عليــه‬\n\n\n                                                                                         ‫‪94‬‬\n\f     ‫وأطلــق عليــه طلقــة واحــدة أدت لوفاتــه‪ ،‬وألن املدعــى عليــه األول رجــل‬\n     ‫أمــن وقــد ســلم لــه الســاح ويلزمــه احملافظــة عليــه وعــدم العبــث بــه أو‬\n     ‫املــزح‪ ،‬وألن املدعــى عليــه األول قــد تــدرب علــى الســاح الــذي حصــل‬\n     ‫بــه القتــل ويعلــم بأنــه ال أمــان فيــه كمــا يعلــم بــأن مــا فيــه مــن طلقــات‬\n     ‫حيــة تكــون ظاهــرة حلاملــة‪ ،‬عليــه والنتهــاء احلــق اخلــاص بتنــازل ورثــة‬\n     ‫كمــت باآلتــي ‪ :‬أوال‪ /‬جلــد كل‬          ‫املجنــي عليــه لذلــك كلــه فقــد َح َ‬\n     ‫واحــد مــن املدعــى عليهمــا حــد املســكر ثمانــن جلــدة دفعــة واحــدة‬\n     ‫علنــا ‪ .‬ثانيــا‪ /‬ثبــوت إدانــة املدعــى عليــه الثانــي بقيــادة الســيارة حتــت‬\n     ‫تأثيــر املســكر وأن عقابــه يف ذلــك للجهــة املختصــة ‪ .‬ثالثــا‪ /‬ثبــوت إدانــة‬\n     ‫املدعــى عليــه األول بقتــل املجنــي عليــه عمــدا لتعمــده إطــاق النــار وإن‬\n     ‫لــم يقصــد النتيجــة وبنــاء عليــه يســجن خمــس ســنني مــن تاريــخ توقيفــه‬\n     ‫‪ -‬قــرر املدعــى عليــه الثانــي القناعــة واملدعــي العــام عــدم االعتــراض أمــا‬\n     ‫املدعــى عليــه األول فعــدم القناعــة فأفهــم بالتعليمــات ‪ -‬عــادت القضيــة‬\n     ‫مــن محكمــة االســتئناف مبلحوظــة بــأن احلكــم علــى املدعــى عليــه‬\n     ‫األول بســجن خمــس ســنوات غيــر مــاق للدعــوى فاملدعــي العــام يطلــب‬\n     ‫تطبيــق اإلرادة امللكيــة وفقــا للتعليمــات ‪ -‬قــررت احملكمــة رجوعهــا‬\n     ‫عــن احلكــم بســجن املدعــى عليــه األول خمــس ســنوات وانطبــاق اإلرادة‬\n     ‫امللكيــة بحقــه وإنفــاذه عائــد للجهــة املختصــة ‪ -‬صــدق احلكــم مــن‬\n                                                                ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪95‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة باخلرج‪/‬املســاعد برقــم وتاريــخ ‪ 1433/03/07‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم وتاريــخ ‪1433/3/7‬ه ـ ففــي يــوم األحــد‬\n‫املوافــق ‪ 1433/04/25‬ه ـ افتتحــت اجللســة بشــأن دعــوى املدعــي‬\n‫العــام بدائــرة التحقيــق واالدعــاء العــام ضــد كال مــن ‪.......... :‬ســعودي‬\n‫مبوجــب الســجل املدنــي رقــم ‪..........‬و ‪..........‬ســعودي مبوجــب الســجل‬\n‫املدنــي رقــم ‪..........‬كمــا حضــر ‪..........‬ســعودي مبوجــب الســجل املدنــي‬\n‫رقــم ‪..........‬بالوكالــة عــن ‪..........‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة بشــرق الريــاض برقــم ‪..........‬يف ‪1433/4/18‬ه ـ واحملــررة‬\n‫وهــذا نصهــا ( بأنــه يف الســاعة اخلامســة صبــاح يــوم اجلمعــة املوافــق‬\n‫‪1432/5/25‬ه ـ تبلــغ مركــز شــرطة ‪..........‬مــن الشــرطة العســكرية‬\n‫يف املؤسســة العامــة للصناعــات احلربيــة عــن وجــود شــخص متوفــى‬\n‫بطلــق نــاري يف الكتــف األيســر واخترقــت الصــدر يف أســفل البطــن ‪.‬‬\n‫وباالنتقــال رفــق املختصــن إلــى املستشــفى وجــد املجنــي عليــه‪.......... /‬‬\n‫يف العقــد الثالــث مــن العمــر حنطــي البشــرة متوســط الطــول ويرتــدي‬\n‫ثــوب أبيــض بــدون شــماغ ومبعاينــة اجلثمــان وجــد بــه أثــر طلقــة واحــدة‬\n‫يف الكتــف األيســر واخترقــت الصــدر واســتقرت يف أســفل البطــن‪ .‬وقــد‬\n‫مت معاينــة الســيارة مــن نــوع صنــي لوحــة رقــم (‪ )..........‬أبيــض مســتأجرة‬\n‫باســم‪.......... /‬وكانــت واقفــة أمــام بوابــة الطــوارئ وبتفتيشــها عثــر‬\n‫علــى ســاح مســدس أبــو محالــة رقمــه (‪ )..........‬وعــدد ثالثــة أظــرف‬\n\n                                                                                     ‫‪96‬‬\n\f     ‫فارغــة وكذلــك عــدد أربــع طلقــات حيــة داخــل جــراب املســدس(فرزت‬\n     ‫أوراق مســتقلة ملعاجلــة ذلــك) وعثــر علــى قــارورة مــاء صغيــرة بهــا أكثــر‬\n     ‫مــن النصــف مــادة ســائلة (عــرق) كمــا شــوهد يف املقعــد األمامــي‬\n     ‫للراكــب علــى بقــع دم وقــد صــدر التقريــر الطبــي الشــرعي النهائــي‬\n     ‫مــن إدارة الطــب الشــرعي باملديريــة العامــة للشــؤون الصحيــة مبنطقــة‬\n     ‫الريــاض برقــم (‪ )..........‬لســنة ‪1432‬ه ـ املتضمــن أنــه بإجــراء الكشــف‬\n     ‫الطبــي الشــرعي والصفــة التشــريحية والفحــوص املعمليــة علــى جثمــان‬\n     ‫املتوفــى‪ 37 ،.......... /‬ســنة ‪ ،‬ســعودي اجلنســية ‪ ،‬تبــن وجــود جــرح نــاري‬\n     ‫حيــوي وحديــث بأعلــى وحشــية العضــد األيســر وقــد نفــذ إلــى يســار‬\n     ‫التجويــف الصــدري والبطــن ثــم اســتقر مقذوفــه بأعلــى إنســية وخلفيــة‬\n     ‫الفخــذ األميــن وقــد أحــدث يف مســاره تهتــك شــديد يف الرئــة واملعــدة‬\n     ‫واملســاريقا ونزيــف شــديد وكان اجتــاه إطالقــه مــن األعلــى واليســار‬\n     ‫إلــى األســفل واليمــن بزاويــة تقــدر ب ـ ‪ 45‬درجــة يف الوضــع الطبيعــي‬\n     ‫القائــم للجســم مــع العلــم بــأن لــكل مــن الطــرف العلــوي واجلــذع حريــة‬\n     ‫يف احلركــة وقــد مت التحفــظ علــى مقذوفــه املســتخرج بغــرض إرســاله‬\n     ‫للمختصــن باألدلــة اجلنائيــة لبيــان نوعــه ونــوع ســاحه وقــد أثبــت‬\n     ‫الكشــف والفحــوص النســجية وجــود عالمــات لقــرب اإلطــاق والتــي‬\n     ‫تشــير إلــى أن اإلطــاق قريــب إال أنــه يصعــب إحداثهــا مــن الشــخص‬\n     ‫نفســه وهــذه اإلصابــة لوحدهــا وبحــد ذاتهــا مميتــه مبــا ضاعفهــا ‪ .‬كمــا‬\n     ‫لــم يتبــن وجــود آثــار مقاومــة أو متاســك أو أي إصابــات أخــرى ‪ .‬كمــا‬\n     ‫ثبــت إيجابيــة كل مــن عينــات الــدم والبــول وســائل قــاع العــن للكحــول‬\n     ‫املســكر بنســبة متوســطة تشــير إلــى تعاطــي املذكــور للكحــول أثنــاء‬\n     ‫حياتــه ‪ ،‬إال أنــه ليــس لهــا دخــل يف إحــداث الوفــاة ‪ ،‬كمــا ثبــت ســلبية‬\n\n‫‪97‬‬\n\f‫العينــات البيولوجيــة واحلشــوية األخــرى للســموم واملخــدرات املوصوفــة‬\n‫يف صلــب التقريــر ‪ .‬وتعــزى الوفــاة إلــى توقــف القلــب والتنفــس الناجــم‬\n‫عــن الطلــق النــاري ومــا ضاعفــه مــن تهتــك ونزيــف وصدمــة‪ .‬ويعــود‬\n‫تاريــخ الوفــاة إلــى ‪1432/5/25‬هـ‪.‬وصــدر بحقــه شــهادة الوفــاة مــن إدارة‬\n‫األحــوال املدنيــة يف ‪..........‬برقــم ‪ ..........‬وتاريــخ ‪1432/6/8‬هــ‪ .‬وبفحــص‬\n‫الســائل الشــفاف الــذي بقــارورة املــاء املضبوطــة أثبــت التقريــر الصــادر‬\n‫مــن شــعبة املختبــرات اجلنائيــة بــإدارة األدلــة اجلنائيــة بشــرطة منطقــة‬\n‫الريــاض باألمــن العــام برقــم ‪..........‬إيجابيتــه للكحــول اإليثيلــي بنســبة‬\n‫(‪ )%74‬أربعــة وســبعون باملائــة ‪ .‬وباستشــمام املدعــى عليهمــا اتضــح وجود‬\n‫رائحــة تشــبه رائحــة املســكر تنبعــث مــن فيهما‪ .‬كما أنــه وبتحليل عينة‬\n‫مــن دم املدعــى عليــه األول أثبــت التقريــر الكيمائــي الشــرعي الصــادر‬\n‫مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية باملديريــة‬\n‫العامــة للشــؤون الصحيــة مبنطقــة الريــاض برقــم ‪..........‬إيجابيتهــا ملــادة‬\n‫الكحــول اإليثيلــي‪ .‬وبفحــص مالبــس املجنــي عليــه صــدر التقريــر مــن‬\n‫شــعبة الطــب الشــرعي بــإدارة املختبــرات اجلنائيــة بــاإلدارة العامــة لألدلــة‬\n‫اجلنائيــة باألمــن العــام برقــم ‪..........‬املتضمــن وجــود ثقــب فتحــة خــروج‬\n‫مقــذوف نــاري يف اجلهــة الداخليــة للكــم األيســر بالثــوب العائــد للمجنــي‬\n‫عليــه وتبــن وجــود ثقــب فتحــة دخــول باجلهــة اخلارجيــة للكــم األيســر‬\n‫يجــاور الثقــب املوصــوف ســابق ًا كمــا تبــن وجــود ثقــب فتحــة دخــول‬\n‫باجلهــة اخلارجيــة للكــم األيســر وثقــب فتحــة خــروج باجلهــة الداخليــة‬\n‫للفانيلــة العائــدة للمجنــي عليــه‪ .‬وبفحــص املســدس الــذي مــن نــوع (أبــو‬\n‫محالــة) حكومــي أمريكــي الصنــع عيــار ‪ 0.38‬بوصــة رقــم‪ ..........‬مــع‬\n‫اجلــراب وعــدد (‪ )3‬ظــروف فارغــة عيــار ‪ 0.38‬بوصــة وعــدد (‪ )4‬طلقــات‬\n\n\n                                                                                      ‫‪98‬‬\n\f     ‫حيــة عيــار ‪ 0.38‬بوصــة املضبوطــة ومقــذوف نــاري عيــار ‪ 0.38‬بوصــة‪-‬‬\n     ‫املســتخرج مــن جســم املجنــي عليــه‪ -‬أثبــت التقريــر الفنــي الصــادر مــن‬\n     ‫إدارة فحــص األســلحة واآلالت بــاإلدارة العامــة لألدلــة اجلنائيــة باألمــن‬\n     ‫العــام برقــم ‪..........‬املتضمــن أن الـ(‪)3‬ثالثــة الظــروف الفارغــة التــي مــن‬\n     ‫عيــار ‪ 0.38‬بوصــة مطلقــة مــن املســدس املشــار إليــه‪ .‬كمــا أثبــت أن‬\n     ‫املقــذوف النــاري الــذي مــن عيــار (‪ )0.38‬بوصــة‪ -‬املســتخرج مــن جســم‬\n     ‫املجنــي عليــه‪ُ -‬مطلــق مــن املســدس املشــار إليــه ‪ .‬وباســتجواب املدعــى‬\n     ‫عليــه األول أقــر أنــه يف صبــاح يــوم اجلمعــة املوافــق ‪1432/5/25‬ه ـ‬\n     ‫عنــد الســاعة الواحــدة والنصــف صباح ـ ًا كان قادم ـ ًا مــن الريــاض‬\n     ‫وبحوزتــه ســاحه حكومــي مســدس ربــع أبــو محالــة فأجــرى اتصــال‬\n     ‫علــى املدعــى عليــه الثانــي ليتقابــا عنــد محطــة ‪..........‬ب‪..........‬‬\n     ‫واجتــه إلــى املوقــع مباشــرة فوجــد املدعــى عليــه الثانــي واملجنــي عليــه‬\n     ‫علــى ســيارة املدعــى عليــه الثانــي نــوع صنــي أبيــض فركــب معهمــا‬\n     ‫يف املرتبــة اخللفيــة وقــد كان قــد أحضــر معــه مــن الريــاض مســكر‬\n     ‫عبــارة عــن قــارورة مــاء صغيــرة بهــا مــادة املســكر نــوع (عــرق) فشــربوا‬\n     ‫املســكر داخــل الســيارة أثنــاء ســيرهم علــى الطريــق وعنــد كبــري‬\n     ‫‪..........‬باجتــاه الغــرب أخــرج مسدســه احلكومــي وشــحنه بطلقــة ثــم‬\n     ‫قــام بإطــاق طلقــة واحــدة يف الهــواء ثــم قــام ميــازح املدعــى عليــه الثانــي‬\n     ‫واملجنــي عليــه داخــل الســيارة بســاحه املســدس املذكــور وتخويفهــم‬\n     ‫بــه ثــم ضغــط علــى الزنــاد فخرجــت الطلقــة وأصابــت املجنــي عليــه‬\n     ‫يف كتفــه األيســر فحــاول إســعافه بالضغــط علــى مــكان اإلصابــة‬\n     ‫والذهــاب بــه للمستشــفى إال أنــه فــارق احليــاة وصــدق علــى ذلــك شــرعاً‪.‬‬\n     ‫وباســتجواب املدعــى عليــه الثانــي أقــر بأنــه يف صبــاح يــوم اجلمعــة املوافــق‬\n\n\n‫‪99‬‬\n\f‫‪1432/5/25‬ه ـ عنــد الســاعة الواحــدة والنصــف صباح ـ ًا كان هــو‬\n‫وخالــه املجنــي عليــه علــى ســيارته نــوع صنــي بيضــاء وهــو يقودهــا عنــد‬\n‫محطــة ‪..........‬ب‪ ..........‬بانتظــار املدعــى عليــه األول والــذي كان قادمـ ًا‬\n‫مــن الريــاض فتقابلــوا عنــد احملطــة املذكــورة وركــب معهمــا املدعــى‬\n‫عليــه األول يف املرتبــة اخللفيــة وقــد أحضــر معــه حبــة شــراب مســكر‬\n‫نــوع (عــرق) صغيــرة فذهبــوا وتعاطــوا املســكر داخــل الســيارة أثنــاء‬\n‫ســيرهم وعنــد كوبــري ‪..........‬علــى الطريــق املــؤدي باجتــاه الغــرب قــام‬\n‫املدعــى عليــه األول بإخــراج مسدســه احلكومــي الــذي كان يحملــه معه‬\n‫وأطلــق طلقــة واحــدة يف الهــواء ثــم قــام بتخويفهــم باملســدس فانطلقــت‬\n‫طلقــه منــه فأصابــت املجنــي عليــه يف كتفــه األيســر ثــم اجتهــوا بــه‬\n‫للمستشــفى إلســعافه وصــدق علــى ذلــك شــرع ًا ‪ .‬وقــد انتهــى التحقيــق‬\n‫معهمــا إلــى توجيــه االتهــام لــأول بقتــل‪ .......... /‬عمــد ًا وذلــك بإطــاق‬\n‫النــار عليــه مــن مسدســه احلكومــي وشــرب األول والثانــي للمســكر‬\n‫الــذي أحضــره األول وحيازتهمــا لــه وقيــادة الثانــي للســيارة حتــت تأثيــر‬\n‫املســكر‪ .‬وفــق قــرار االتهــام رقم‪..........‬لعــام ‪1432‬ه ـ املؤيــد مــن جلنــة‬\n‫إدارة هيئــة التحقيــق واالدعــاء العــام بقرارهــا ‪..........‬لعــام ‪1432‬ه ـ وذلــك‬\n                                                         ‫لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ .1‬مــا جــاء بإقــرار املدعــى عليــه األول املصــادق عليــه شــرع ًا املنــوه عنــه‬\n‫املــدون علــى الصفحــة رقــم (‪ )3‬مــن ملــف التحقيــق رقــم (‪ )2‬املرفــق لفــه‬\n                                                                               ‫رقــم(‪.)2‬‬\n‫‪ .2‬مــا جــاء بإقــرار املدعــى عليــه الثانــي املصــادق عليــه شــرع ًا املنــوه عنــه‬\n‫املــدون علــى الصفحــة رقــم (‪ )4‬مــن ملــف التحقيــق رقــم (‪ )2‬املرفــق لفــه‬\n                                                                             ‫رقــم (‪.)2‬‬\n\n\n                                                                                           ‫‪100‬‬\n\f      ‫‪ .3‬مــا جــاء مبحضــر املعاينــة للســيارة املنــوه عنــه املــدون علــى الصفحــة‬\n                       ‫رقــم (‪ )8‬مــن ملــف التحقيــق رقــم (‪ )2‬املرفــق لفــه رقــم (‪.)2‬‬\n      ‫‪ .4‬مــا جــاء بالتقريــر الطبــي الشــرعي النهائــي رقــم (‪ 301‬ط ش) املنــوه‬\n                                                         ‫عنــه املرفــق لفــه رقــم (‪.)81-76‬‬\n      ‫‪ .5‬مــا جــاء مبحضــر االستشــمام املنــوه عنــه املــدون علــى الصفحــة رقــم‬\n                             ‫(‪ )6‬مــن ملــف التحقيــق رقــم (‪ )1‬املرفــق لفــه رقــم (‪.)1‬‬\n          ‫‪ .6‬ما جاء بالتقرير رقم ‪..........‬املنوه عنه املرفق لفه رقم (‪.)116-114‬‬\n         ‫‪ .7‬ما جاء بالتقرير الفني رقم ‪..........‬املنوه عنه املرفق لفه رقم (‪.)104‬‬\n      ‫‪ .8‬مــا جــاء بالتقريــر رقــم ‪..........‬املنــوه عنــه املنــوه عنــه املرفــق لفــه رقــم‬\n                                                                                           ‫(‪.)71‬‬\n                             ‫‪ .9‬ما جاء بالصور الفوتوغرافية املرفقة لفة رقم (‪.)64‬‬\n      ‫‪ .10‬مــا جــاء يف التقريــر الكيمائــي الشــرعي رقــم ‪..........‬املنــوه عنــه‬\n                                                                      ‫املرفــق لفــه رقــم (‪.)54‬‬\n                    ‫‪ .11‬ما جاء يف تقرير الشرطة العسكرية املرفق لفة رقم(‪. )4‬‬\n      ‫وبالبحــث عــن مــا إذا كان لهمــا ســوابق لــم يعثــر لهمــا علــى ســوابق‬\n                                                                              ‫مســجلة جنائي ـاً‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا وهمــا بكامــل أهليتهمــا‬\n      ‫املعتبــرة شــرعاً‪-‬فعل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتهمــا‬\n      ‫مبــا ُأ ْس ـن َِد إليهمــا وإثبــات صفــة القتــل العمــد وتطبيــق اإلرادة امللكيــة‬\n      ‫بحــق القاتل‪-‬املدعــى عليــه األول‪ -‬واحلكــم علــى املدعــى عليهمــا بحــد‬\n      ‫املســكر وإلثبات إدانة الثاني بقيادة الســيارة وهو حتت تأثير املســكر‬\n      ‫وإفهامــه أن أمــر معاقبتــه علــى ذلــك عائــد للجهــة املختصــة وفق ـ ًا للبنــد‬\n      ‫(ثانيــا) مــن املرســوم امللكــي رقــم (م‪ )85/‬وتاريــخ ‪1428/10/26‬ه ـ‬\n\n\n‫‪101‬‬\n\f‫علمـ ًا بــأن احلــق اخلــاص انتهــى بالتنــازل فيمــا يتعلــق بالــدم والديــة باقيــة‬\n‫علــى حالهــا مبوجــب إقــرار التنــازل املصــدق شــرع ًا املدون علــى الصفحة‬\n                                  ‫رقــم «‪ »2‬مــن دفتــر التحقيــق املرفــق لفــة «‪. »97‬‬\n‫وبــاهلل التوفيــق‪ ،،،‬وبنــاء عليــه فقــد حضــر‪ ..........‬ســعودي مبوجــب‬\n‫السجل املدني رقم ‪..........‬بالوكالة عن ‪..........‬و‪ ..........‬مبوجب الوكالة‬\n‫الصــادرة مــن كتابــة عــدل ‪..........‬برقــم ‪..........‬يف ‪1432/6/26‬ه ـ وله يف‬\n‫وكالتــه حــق التنــازل عــن قاتــل مورثهمــا ‪..........‬وبالوكالــة عــن ‪..........‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل ‪..........‬الثانيــة برقــم ‪..........‬‬\n‫يف ‪1432/6/20‬ه ـ ولــه حــق التنــازل عــن املتســبب يف وفــاة زوجهــا وحــال‬\n‫واليتــه علــى أبيــه القاصــر عقليــا ‪..........‬مبوجــب صك الواليــة الصادر من‬\n‫هذه احملكمة برقم ‪..........‬يف ‪1432/7/10‬هـ واملنحصر ارث ‪.......... /‬‬\n‫يف موكلــي املنهــي ومــن هــو حتــت واليتــه وذلــك مبوجــب صــك حصــر‬\n‫الورثــة الصــادر مــن محكمــة الدلــم برقــم ‪..........‬يف ‪1432/7/12‬ه ـ‬\n‫وقــرر املدعــي يف احلــق اخلــاص تنــازل موكليــه عــن املدعــى عليــه األول‬\n‫حــزام وبســؤال املدعــى عليــه األول ‪..........‬أجــاب بقولــه صحيــح أنــي‬\n‫كنــت صبــاح يــوم اجلمعــة ‪1432/5/25‬ه ـ قــادم مــن الريــاض بإجتــاه‬\n‫‪..........‬فإتصلــت بزميلــي املدعــى عليــه الثانــي هــذا احلاضــر ‪..........‬وأعلــم‬\n‫أن معــه املجنــي عليــه ‪..........‬واتفقــت علــى مــكان نتقابــل فيــه وكنــت‬\n‫قــد أحضــرت مســكرا مــن نــوع عــرق ‪ .‬ومعــي مســدس حكومــي ربــع‬\n‫أبــو محالــة وتقابلــت معهمــا عنــد محطــة ‪..........‬يف ‪..........‬وركبــت معهما‬\n‫ومعــي املســدس احلكومــي ومعــي قــارورة املســكر وركبــت يف املقعــد‬\n‫اخللفــي يف الســيارة واملدعــى عليــه هــذا احلاضــر يقــود الســيارة واملجنــي‬\n‫عليــه يركــب يف مقعــد الراكــب األمامــي مــن اليمــن وأنــا يف منتصــف‬\n\n\n                                                                                          ‫‪102‬‬\n\f      ‫املقعــد اخللفــي وقــد أخــذت املســدس احلكومــي معــي حيــث انــي أخشــى‬\n      ‫عليــه مــن الســرقة وبعــد أن ســرنا شــربنا نحــن الثالثــة املســكر مــن‬\n      ‫نــوع عــرق ومتشــينا أكثــر مــن ســاعة أخرجــت املســدس وأطلقــت طلقــة‬\n      ‫واحــدة يف الهــواء ثــم أخــذت أمــازح املدعــى عليــه الثانــي ‪ ..........‬وأمــازح‬\n      ‫املجنــي عليــه ‪..........‬ثــم انطلقــت مــن املســدس طلقــة اصابــت املجني عليه‬\n      ‫‪..........‬يف كتفــه األيســر وال أعلــم كيــف انطلقــت الرصاصــة وكنــت‬\n      ‫أظــن أن املســدس خــال مــن الطلقــات ‪ .‬وأنــا لــم أتعمــد قتــل ‪..........‬وإمنــا‬\n      ‫انطلقــت الرصاصــة مــن غيــر قصــد ومــن غيــر علــم منــي أن يف املســدس‬\n      ‫رصاصــة وأنــا متنيــت أن الرصاصــة انطلقــت يف جســدي ألن املجنــي عليــه‬\n      ‫عزيــز علــي ‪ .‬ثــم جــرى مناقشــة املدعــى عليــه عــن خدمتــه العســكرية‬\n      ‫فقــال إنهــا ســبعة عشــر عامــا وجــرى ســؤاله عــن تاريــخ تســليمه الســاح‬\n      ‫فقــال أنــه قبــل ســنة مــن احلادثــة وجــرى ســؤاله عــن املســدس أبــو محالــة‬\n      ‫هــل يوجــد فيــه تأمــن فقــال ال يوجــد فيــه تأمــن وجــرى ســؤاله هــل يتــم‬\n      ‫مشــاهدة الرصــاص احلــي يف املســدس فقــال أنهــا ال تــرى إال بعــد إخــراج‬\n      ‫املكــرة ( احملالــة) وأنــا تائــب هلل ولــن أعــود لشــئ مــن املعاصــي هكــذا‬\n      ‫أجــاب املدعــى عليــه األول ‪ ...........‬وأجــاب املدعــى عليــه بالوكالــة‬\n      ‫بقولــه أن موكلــي املدعــى عليــه هــذا احلاضــر ‪..........‬لــم يتعمــد الفعــل (‬\n      ‫إطــاق النــار ) ولــم يتعمــد النتيجــة التــي هــي وفــاة املجنــي عليــه ‪..........‬‬\n      ‫كمــا أن العالقــة بــن موكلــي املدعــى عليــه و املجنــي عليــه ‪..........‬‬\n      ‫عالقــة حميمــة كمــا أن عالقــة ذوي املتــويف مبوكلــي املدعــى عليــه‬\n      ‫‪..........‬عالقــة حميمــة وهــم مــن فخــذ واحــد بدليــل أنــه حصــل التنــازل‬\n      ‫مــن أوليــاء الــدم فــورا ويف وقــت قريــب مــن احلادثــة كمــا أن موكلــي‬\n      ‫يتمنــى أن الرصاصــة اصابتــه ولــم تصــب املجنــي عليــه ‪ ...........‬وبســؤال‬\n\n\n‫‪103‬‬\n\f‫املدعــى عليــه الثانــي ‪ ..........‬قــال صحيــح أننــي شــربت املســكر مــن نــوع‬\n‫عــرق وقمــت بقيــادة ســيارتي مــن نــوع صنــي ‪2011‬م قبــل تأثيــر املســكر‬\n‫علــي ‪ .‬وأنــا تائــب هلل جــل وعــا ولــن أعــود لشــئ مــن املعاصــي هكــذا‬\n‫أجــاب املدعــى عليــه الثانــي ‪ . .‬ثــم جــرى ســؤال املدعــى عليــه األول‬\n‫أصالــة واملدعــى عليــه وكالــة هــل ألحدهمــا إضافــة فقــرر أنهمــا يطلبان‬\n‫صــرف النظــر عــن دعــوى املدعــي العــام بإثبــات صفــة القتــل مــن نــوع‬\n‫العمــد ‪ .‬احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة‬\n‫العامــة مبحافظــة اخلــرج افتتحــت اجللســة وفيهــا حضــر املدعــي العــام‬\n‫وحضــر حلضــوره ‪..........‬ســعودي مبوجــب الســجل املدنــي رقــم ‪..........‬و‬\n‫‪ ..........‬ســعودي مبوجــب الســجل املدنــي رقــم ‪..........‬كمــا حضــر ‪..........‬‬\n‫ســعودي مبوجــب الســجل املدنــي رقــم ‪..........‬بالوكالــة عــن ‪..........‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بشــرق الريــاض‬\n‫برقــم ‪..........‬يف ‪1433/4/18‬ه ـ وجــرى االطــاع علــى أوراق املعاملة ومن‬\n‫بينهــا ملــف التحقيــق املرفــق لفــة رقــم ‪ 1‬وجــاء فيــه اســتجواب املدعــى‬\n‫عليــه واجابتــه مطابقــة الجابتــه لدينــا ‪ .‬كمــا جــرى االطــاع علــى‬\n‫التقريــر الفنــي اجلنائــي رقــم ‪/1/32/163‬ط وجــاء فيــه الــراي ‪ :‬اســتنادا‬\n‫الــى مــا تقــدم وبعــد فحــص املالبــس العائــدة للمدعــو ‪..........‬تبــن مــا يلــي‬\n‫‪ - 1 :‬وجــود ثقــب فتحــة خــروج مقــذوف نــاري يف اجلهــة الداخليــة للكــم‬\n‫األيســر بالثــوب العائــد للمذكــور وكمــا تبينــا وجــود ثقــب فتحــة دخــول‬\n‫باجلهــة الداخليــة للكــم االيســر يجــاور الثقــب املوصــوف ســابقا وتبينــا‬\n‫وجــود ثقــب فتحــة دخــول باجلهــة اخلارجيــة للكــم األيســر وثقــب فتحــة‬\n‫خــروج باجلهــة الداخليــة للفانيلــة العائــدة لــه ‪ ،‬أخــذا يف االعتبــار أننــا لــم‬\n‫منيــز ثقــب الدخــول وأضاعــت معاملــة ‪ -2 .‬لــم يتــم عمــل بحــث عالمــات‬\n\n\n                                                                                          ‫‪104‬‬\n\f      ‫قــرب االطــاق لعــدم تبيننــا وجــود ثقــب فتحــة دخــول بالثــوب العائــد‬\n      ‫للمذكــور حيــث يتــم عمــل االختبــار علــى أول ســطح المســة املقــذوف‬\n      ‫عنــد الدخــول ‪ - 3 .‬أعيــدت جميــع املالبــس املوصوفــة أعــاه محــرزه‬\n      ‫رفــق هــذا التقريــر واهلل املوفــق ‪ .‬أ ‪ -‬ه ـ فبنــاء علــى مــا تقــدم مــن دعــوى‬\n      ‫املدعــي العــام واجابــة املدعــى عليــه وإلقــرار املدعــى عليهمــا أنهمــا شــربا‬\n      ‫املســكر وإلقــرار املدعــى عليــه االول ‪..........‬بأنــه أشــهر ســاحه علــى‬\n      ‫املدعــى عليــه الثانــي ‪..........‬وأشــهر ســاحة كذلــك علــى املجنــي عليــه‬\n      ‫‪..........‬وأطلــق عليــه طلقــة واحــدة أدت لوفاتــه وألن املدعــى عليــه رجــل‬\n      ‫أمــن وقــد ســلم الســاح وملــزم باحملافظــة علــى الســاح ومــن احملافظــة‬\n      ‫عليــه عــدم العبــث بــه أو املــزح وألن املدعــى عليــه ‪..........‬قــد تــدرب علــى‬\n      ‫الســاح الــذي حصــل بــه القتــل مســدس أبــو محالــة وأنــه ال أمــان لــه‬\n      ‫ومافيــه مــن طلقــات حيــة تكــون ظاهــرة حلاملــة ونظــرا النتهــاء احلــق‬\n      ‫اخلــاص بتنــازل ورثــة املجنــي عليــه كمــا هــو مبــن بعاليــة لذلــك كلــه‬\n      ‫فقــد حكمــت باآلتــي ‪ )1 :‬أن يجلــد كل واحــد مــن املدعــى عليهمــا‬\n      ‫حــد املســكر ثمانــن جلــدة دفعــة واحــدة علنــا ‪ - 2 .‬ثبــت لــدي ادانــة‬\n      ‫املدعــى عليــه الثانــي بقيــادة الســيارة حتــت تأثيــر املســكر وأن عقابــة‬\n      ‫يف ذلــك للجهــة املختصــة ‪ - 3 .‬ثبــت لــدي ادانــة املدعى عليــه األول ‪..........‬‬\n      ‫بقتــل املجنــي عليــه ‪..........‬وأن قتلــه لــه مــن القتــل العمــد حيــث تعمــد‬\n      ‫االطــاق وإن لــم يقصــد النتيجــة وبنــاء عليــه يســجن املدعــى عليــه خمــس‬\n      ‫ســنني مــن تاريــخ توقيفــه وبــه حكمــت حتريــرا يف ‪1433/5/26‬ه ـ‬\n      ‫وبعرضــه علــى املدعــى عليهــم قنــع املدعــى عليــه الثانــي ‪..........‬ولــم يقنــع‬\n      ‫املدعــى عليــه االول اصالــة ‪..........‬ووكالــة ‪..........‬وطلبــا رفعــه حملكمــة‬\n      ‫االســتئناف وقــرر املدعــى عليــه اصالــة أنــه يكتفــي باعتــراض وكيلــه‬\n\n\n‫‪105‬‬\n\f‫‪..........‬فجــرى افهــام املدعــى عليــه وكالــة مبراجعــة احملكمــة يــوم‬\n‫االحــد املوافــق ‪1433/6/1‬ه ـ الســتالم نســخة مــن احلكــم وتقــدمي الئحة‬\n‫إعتــراض عليهــا يف مــدة أقصاهــا ثالثــون يومــا من التاريــخ املذكور وأنه‬\n‫إن لــم يتقــدم بإعتراضــه خــال تلــك املــدة فسيســقط حقــه يف االعتــراض‬\n‫ويرفــع حملكمــة االســتئناف بــدون الئحــة وصلــى اهلل علــى نبينــا محمــد‬\n‫‪ .‬ويف يــوم األحــد املوافــق ‪1433/6/1‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي العــام وقــرر عــدم رفعــه حملكمــة االســتئناف وصلــى اهلل علــى‬\n‫نبينــا محمــد ‪ .‬احلمــد هلل وحــده ففــي يــوم الســبت املوافــق‪1433/11/20‬‬\n‫ه ـ افتتحــت اجللســة وفيهــا عــادت املعاملــة مــن محكمــة اإلســتئناف‬\n‫وبرفقهــا القــرار رقــم ‪ 33425910‬يف ‪1433/10/15‬ه ـ واملتضمــن أنــه‬\n‫لوحــظ أن احلكــم بســجن املدعــى عليــه خمــس ســنوات غيــر مــاق‬\n‫للدعــوى إذ أن املدعــي العــام طالــب بتطبيــق اإلرادة امللكيــة واملتعيــن‬\n‫تطبيــق اإلرادة امللكيــة وفقــا للتعليمــات وبــاهلل التوفيــق وجواب ـ َا عليــه‬\n‫ولوجاهــة مــا ذكــره أصحــاب الفضيلــة فقــد ثبــت لــدي قتــل املدعــى‬\n‫عليــه للمجنــي عليــه وأن قتلــة مــن بــاب العمــد ويطبــق بحقــه األرادة‬\n‫امللكيــة وتطبيقهــا عائــد للجهــة املختصــة بنــاء علــى التعميــم الــوزاري‬\n‫رقــم ‪/13‬ت‪ 4477/‬يف ‪ 1433/2/12‬ه ـ وبذلــك متــت األجابــة ‪ ،‬ولــم‬\n‫يظهــر لــي خــاف ذلــك وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/20‬ه ـ احلمــد هلل وحــده ففــي‬\n‫يــوم الســبت املوافــق‪ 1433/11/20‬ه ـ افتتحــت اجللســة وفيهــا عــادت‬\n‫املعاملــة مــن محكمــة اإلســتئناف وبرفقهــا القــرار رقــم ‪ 33425910‬يف‬\n‫‪1433/10/15‬ه ـ واملتضمــن أنــه لوحــظ أن احلكــم بســجن املدعــى عليه‬\n‫خمــس ســنوات غيــر مــاق للدعــوى إذ أن املدعــي العــام طالــب بتطبيــق‬\n\n\n                                                                                    ‫‪106‬‬\n\f      ‫اإلرادة امللكيــة واملتعيــن تطبيــق اإلرادة امللكيــة وفقــا للتعليمــات‬\n      ‫وبــاهلل التوفيــق وجواب ـ َا عليــه ولوجاهــة مــا ذكــره أصحــاب الفضيلــة‬\n      ‫فقــد ثبــت لــدي قتــل املدعــى عليــه للمجنــي عليــه وأن قتلــة مــن بــاب‬\n      ‫العمــد ويطبــق بحقــه األرادة امللكيــة وتطبيقهــا عائــد للجهــة املختصــة‬\n      ‫بنــاء علــى التعميــم الــوزاري رقــم ‪/13‬ت‪ 4477/‬يف ‪ 1433/2/12‬ه ـ‬\n      ‫وبذلــك متــت األجابــة ‪ ،‬ولــم يظهــر لــي خــاف ذلــك وصلــى اهلل علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/20‬ه ـ احلمــد هلل‬\n      ‫وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى لتمييــز‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة باخلــرج املكلــف الشــيخ‪........../‬‬\n      ‫برقــم ‪ 34264487‬وتاريــخ ‪1434 /2 /3‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلـ ــته املســجل برقــم ‪ 33273852‬وتاريــخ ‪1433/6/1‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد كل مــن‪ ..........2 .......... -1/‬يف قضيــة قتــل‬\n      ‫علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل بــه وحيــث ســبق دراســة القــرار وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلــة‬\n      ‫القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنا رقــم ‪349404‬‬\n      ‫وتاريــخ ‪1434/1/12‬ه ـ قررنــا بأنــه لــم يظهــر مــا يوجــب املالحظــة اخير ًا‬\n                                                                      ‫وبــاهلل التوفيــق ‪.‬‬\n\n\n\n\n‫‪107‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":93,"source_page_end":107,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"32849560a77cdc207e6518e91cdb3887190260f89325cd3a29ae3242d358d5ed","normalized_text_hash":"30e5e985fe797195a9106c2c07fef79f1bf176c4dc00968369e786c0c6728f27","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p93-33460348"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"f31890e1-c074-5831-98b0-d2b8e38089f8","document_type":"judgment","category":"judicial","subcategory":"general","title":"قتل -قتل خطأ -حيازة ساح بدون ترخيص -استخدام ساح ناري -إقرار املدعى عليه -تنازل عن حق خاص -األخذ بالقرائن لتحديد القصد اجلنائي -إدانة بالقتل اخلطأ -عدم تقيد المحكمة بالوصف الوارد يف الئحة الدعوى -تعزير بالسجن وأخذ التعهد وإفهام بكفارة القتل اخلطأ ما أشار له القاضي يف تسبيب احلكم.","document_number":"34296822","case_number":"3246628","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/14","year":"1434","subject":"قتل -قتل خطأ -حيازة ساح بدون ترخيص -استخدام ساح ناري -إقرار املدعى عليه -تنازل عن حق خاص -األخذ بالقرائن لتحديد القصد اجلنائي -إدانة بالقتل اخلطأ -عدم تقيد المحكمة بالوصف الوارد يف الئحة الدعوى -تعزير بالسجن وأخذ التعهد وإفهام بكفارة القتل اخلطأ ما أشار له القاضي يف تسبيب احلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34296822 :‬تاريخه‪1434/8/14 :‬هـ‬\n                     ‫رقم الدعوى‪3246628:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34309760‬تاريخه‪1434/9/1 :‬هـ‬\n\n\n‫قتــل ‪ -‬قتــل خطــأ ‪ -‬حيــازة ســاح بــدون ترخيــص ‪ -‬اســتخدام ســاح‬\n‫نــاري ‪ -‬إقــرار املدعــى عليــه ‪ -‬تنــازل عــن حــق خــاص ‪ -‬األخــذ بالقرائــن‬\n‫لتحديــد القصــد اجلنائــي ‪ -‬إدانــة بالقتــل اخلطــأ ‪ -‬عــدم تقيد احملكمة‬\n‫بالوصــف الــوارد يف الئحــة الدعــوى ‪ -‬تعزيــر بالســجن وأخــذ التعهــد‬\n                                            ‫وإفهــام بكفــارة القتــل اخلطــأ‬\n\n\n\n\n                                      ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n‫توجيــه االتهــام مــن االدعــاء العــام نحــو املدعــى عليــه بقتــل املجنــي عليــه‬\n‫عمــدا عدوانــا وطلــب إثبــات صفــة القتــل ‪ ،‬تلقــت الدوريــات األمنيــة‬\n‫بالغــا عــن وجــود حالــة طــوارئ باملستشــفى فتوجهــت نحــوه فظهــر بــأن‬\n‫املجنــي عليــه تــويف إثــر تعرضــه إلطــاق نــار ‪ ،‬بضبــط إفــادة صاحــب‬\n‫املنــزل والــد املدعــى عليــه أفــاد بأنــه كان جالســا يف بيتــه فســمع صــوت‬\n‫إطــاق نــار مــن أحــد الغــرف فتوجــه نحــوه فوجــد ابنــه املدعــى عليــه‬\n‫ممســكا بســاح رشــاش ويصــرخ ويبكــي والدمــاء تســيل علــى صــدر‬\n‫املجنــي عليــه‪ ،‬بالتحقيــق مــع املدعــى عليــه أجــاب بأنــه قــام بإطــاق‬\n‫طلقــة يف الهــواء فلــم تخــرج رصاصــة فعشــق الســاح مــرة أخــرى وصوبــه‬\n\n                                                                                        ‫‪34‬‬\n\f     ‫نحــو املجنــي عليــه مازحــا يقصــد إخافتــه فانطلقــت رصاصــة نحــو‬\n     ‫صــدره‪ ،‬تنــازل ورثــة املجنــي عليــه عــن املدعــى عليــه‪ ،‬بعــرض الدعــوى‬\n     ‫عليــه أجــاب بــأن مــا جــاء يف دعــوى املدعــي العــام صحيــح حيــث قمــت‬\n     ‫بإطــاق طلقــة يف الهــواء فلــم تخــرج رصاصــة فعشــق الســاح مــرة أخــرى‬\n     ‫وصوبــه نحــو املجنــي عليــه مازحــا يقصــد إخافتــه فانطلقــت رصاصــة‬\n     ‫نحــو صــدره وكان ذلــك باخلطــأ ولــم أقصــد قتلــه‪ ،‬جــرى االطــاع علــى‬\n     ‫التقريــر الطبــي املتضمــن حــدوث الوفــاة نتيجــة الطلقــة الناريــة النافــذة‬\n     ‫بالصــدر‪ ،‬وإلقــرار املدعــى عليــه ودفعــه بحدوثــه خطــأ ‪ ،‬عليــه ولصغــر‬\n     ‫ســن املدعــى عليــه وإقــرار الورثــة بالتنــازل ولعــدم وجــود عــداوة ‪ ،‬وهــذه‬\n     ‫قرائــن تؤيــد دفــع املدعــى عليــه‪ ،‬لــذا فقــد قــررت احملكمــة ثبــوت‬\n     ‫قيــام املدعــى عليــه بإطــاق النــار مــن ســاح رشــاش نحــو املجنــي عليــه‬\n     ‫باخلطــأ أدى لوفاتــه وقــررت تعزيــره ألجلــه بســجنه شــهرا يحســب منهــا‬\n     ‫مــدة إيقافــه بســبب القضيــة مــع أخــذ التعهــد عليــه بعــدم العــودة ملثــل‬\n     ‫كمــت‪ ،‬أفهــم بــأن عليــه كفــارة قتــل اخلطــأ ‪،‬‬    ‫مــا بــدر منــه وبذلــك َح َ‬\n     ‫قــرر املدعــى عليــه القناعــة بينمــا اعتــرض املدعــي العــام بــدون الئحــة ‪،‬‬\n                                        ‫صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ..........‬القاضــي باحملكمــة اجلزائيــة‬\n     ‫بتبــوك بنــاء علــى املعاملــة الــواردة إلــى احملكمــة مــن هيئــة التحقيــق‬\n     ‫واإلدعــاء العــام بتبــوك بكتابهــم رقــم ‪ 9208‬وتاريــخ ‪1431/7/3‬ه ـ‬\n     ‫واحملالــة إلــي مــن فضيلــة الرئيــس برقــم ‪ 3246628‬وتاريــخ‬\n     ‫‪1432/2/18‬ه ـ والتــي ســبق أن أحيلــت لفضيــة القاضــي باحملكمــة‬\n\n‫‪35‬‬\n\f‫الشــيخ ‪..........‬برقــم ‪ 1576‬يف ‪1434/7/4‬ه ـ فصــدر فيهــا احلكــم مــن‬\n‫فضيلتــه برقــم ‪4/7/104‬ج وتاريــخ ‪1434/7/14‬ه ـ املنقــوض مــن‬\n‫محكمــة االســتئناف مبكــة املكرمــة مــن الدائــرة اجلزائيــة اخلامســة‬\n‫برقــم ‪/5/5‬ن‪/‬ج يف ‪1432/1/21‬ه ـ عليــه حضــر املدعــي العــام ‪..........‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪..........‬املكلــف لــدى‬\n‫احملكمــة مبوجــب كتــاب التعميد رقــم ‪..........‬يف ‪1433/9/5‬هـ وادعى‬\n‫علــى احلاضــر معــه ‪..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫ا يف حتريــر دعــواه بتاريــخ ‪1430/12/29‬ه ـ تلقــت‬                  ‫(‪ )..........‬قائ ـ ً‬\n‫الدوريــات األمنيــة بالغـ ًا عــن وجــود حالــة داخــل طــوارئ مستشــفى امللــك‬\n‫خالــد وعنــد حضــور الدوريــات وجــد ‪..........‬متوفــى داخــل املستشــفى‬\n‫لتعرضــه إلطــاق نــار وبضبــط إفــادة صاحــب املنــزل والــد احلــدث املدعى‬\n‫ـاء وحينمــا كان جالس ـ ًا يف‬   ‫عليــه أفــاد بأنــه يف الســاعة العاشــرة مسـ ً‬\n‫املجلــس وعندهــا ســمع طلقــة صــادرة مــن غرفــة النــوم التــي تخصــه‬\n‫وعندهــا حضــر فوجــد ابنــه ‪..........‬ممســك ًا بســاح رشــاش‬\n‫الكالشــنكوف وكان يصــرخ ويبكــي وممســك ًا بولــد شــقيقه‬\n‫‪..........‬ويقــول أبويــه ‪..........‬مــات مــات والدمــاء تســيل مــن صــدر ‪..........‬‬\n‫مــن اجلهــة اليمنــى لصــدره وأخــذ ‪..........‬وذهــب بــه إلــى املستشــفى كمــا‬\n‫أفــاد بــأن الســاح كان موجــود ًا بالغرفــة وباالنتقــال ملعاينــة موقــع‬\n‫اجلرميــة اتضــح أن املنــزل يقــع بحــي ‪..........‬خلــف قصــر أفــراح ‪..........‬وهــو‬\n‫عبــارة عــن عمــارة مســلحة مكونــة مــن دوريــن ومــكان اجلرميــة يقــع‬\n‫بالــدور األول ويتكــون مــن مدخــل ثــم ممــر ثــم بعــد املمــر مجلــس يف‬\n‫اجلهــة اليســرى طولــه خمســة يف أربعــة وغرفــة أربعــة يف أربعــة ثــم صالــة‬\n‫داخليــة مســاحتها أربعــة يف ســتة وغرفــة أخــرى صغيــرة والتــي وقــع فيهــا‬\n\n\n                                                                                           ‫‪36‬‬\n\f     ‫إطــاق النــار حســب إفــادة أهــل املنــزل ومســاحتها أربعــة يف أربعــة وجــد‬\n     ‫بداخلهــا طاولــة خشــبية وعليهــا مالبــس تبعــد عــن البــاب حوالــي متــر ًا‬\n     ‫تقريبـ ًا متحركــة مــن مكانهــا املالصــق للجــدار األيســر بحوالــي نصف‬\n     ‫متــر ويف اجلهــة اليمنــى مــن الغرفــة وجــدت مالبــس متنوعــة رجاليــة‬\n     ‫ونســائية كثيــرة موضوعــة علــى األرض بعضهــا فــوق بعــض بشــكل‬\n     ‫عشــوائي ووجــد الســاح نــوع رشــاش كالشــنكوف فــوق املالبــس‬\n     ‫مغطــى وال يظهــر منــه ســوى العقــب اخلشــبي اخللفــي و بالبحــث يف الغرفة‬\n     ‫وجــود العربــود رأس املقــذوف يف أعلــى املالبــس التــي علــى الطاولــة‬\n     ‫اخلشــبية ووجــد الظــرف الفــارغ يف الزاويــة اليمنــى املقابلــة للبــاب‬\n     ‫واحتمــال أن يكــون تغيــر مــن موقعــة أثنــاء البحــث ومــن خــال معاينــة‬\n     ‫املنــزل بشــكل كامــل والبحــث وجــد عرض ـ ًا ســاح آخــر عبــارة عــن‬\n     ‫مســدس ربــع صغيــر بداخــل جــراب الســاح ومخــزن أســود مــع تســع‬\n     ‫طلقــات حيــة ملفــوف الســاح يف قمــاش ملــون ويبــدوا أنــه لــم يســتخدم‬\n     ‫منــذ فتــره وكذلــك أثنــاء متشــيط املوقــع وجــدت بقــع دمويــة علــى فــراش‬\n     ‫األرض لونــه أزرق فــاحت وكذلــك بقــع دمويــة متفرقة يف الصالة الداخلية‬\n     ‫وثــاث نقــط دمويــة أمــام البــاب اخلارجــي وخــاف ذلــك لــم يظهــر أي‬\n     ‫أدلــة تفيــد التحقيــق وجــرى تصويــر املوقــع ورفــع جميــع اآلثــار وقــد صــدر‬\n     ‫التقريــر الطبــي رقــم بــدون وتاريــخ ‪1430/12/29‬ه ـ بحــق ‪..........‬‬\n     ‫واملتضمــن إصابتــه بطلــق نــاري ولديــه جــرح باحللمــة اليســرى بطــول‬\n     ‫(‪1.5‬ســم) وخــروج الطلقــة مــن ناحيــة اإلبــط األميــن بطــول حوالي (‪5‬ســم)‬\n     ‫مــع كســر ضلعــن يف الناحيــة اليمنــى مت اســتقبال املريــض املتوفــى‬\n     ‫بــدون عالمــات حيويــة كمــا ورد التقريــر رقــم ‪..........‬بشــأن فحــص‬\n     ‫عينــات رفعــت مــن يــد اجلانــي املدعــى عليــه حيــث أعطيت جميــع العينات‬\n\n\n‫‪37‬‬\n\f‫إيجابيــة ملخلفــات اإلطــاق علــى األيــدي كمــا ورد التقريــر الفنــي رقــم‬\n‫‪..........‬والعائــد للمتوفــى ‪..........‬واملتضمــن وجــود بقــع كثيفــة بلــون أحمر‬\n‫يشــتبه أن تكــون دم مــع وجــود متزقــات مــن ناحيــة مقدمــة القميــص‬\n‫بطــول (‪ )0.5‬ومتــزق مــن ناحيــة اإلبــط األميــن للقميــص بطــول (‪1.5‬ســم)‬\n‫كمــا ورد التقريــر الفنــي رقم‪..........‬واملتضمــن إيجابية العينات املوجودة‬\n‫مبالبــس املتوفــى ‪..........‬ألدمــي) كمــا ورد خطــاب مديــر مركز شــرطة‬\n‫احلمــراء ‪..........‬وتاريــخ ‪1431/2/9‬ه ـ واملتضمــن تقريــر مصــور ملوقــع‬\n‫اجلرميــة وجلثمــان املتوفــى واملتضمــن وجــود مدخــل للطلــق النــاري مــن‬\n‫الناحيــة اليســرى ومخــرج لــه مــن ناحيــة اإلبــط األميــن مــن اخللــف كمــا‬\n‫ورد خطــاب مديــر شــعبة التحريــات والبحــث اجلنائــي رقــم ‪ ..........‬وتاريــخ‬\n‫‪1431/1/2‬ه ـ واملتضمــن كــون العالقــة بــن اجلانــي وذوي املتوفــى‬\n‫(عالقــة عائليــة) كــون والــد ‪..........‬واملدعــو ‪..........‬هــو شــقيق املدعــو‬\n‫‪ ..........‬والــد املدعــى عليــه وبالبحــث والتحــري لــم يتضــح وجــود أي‬\n‫مشــاكل بينهــم كمــا صــدر التقريــر الطبــي الشــرعي النهائــي بالقضية‬\n‫رقــم ‪ ..........‬واملتضمــن أن الوفــاة تعــود لتوقــف القلــب والتنفــس نــاجت عــن‬\n‫علــة كامنــة تعــذر معرفتهــا نظــر ًا لعــدم تشــريح اجلثمــان ولكونــه بنــاء‬\n‫علــى الكشــف الظاهــري واألشــعة املجــراة وفحــص املالبــس ومعاينــة‬\n‫مــكان الوفــاة وســلبية عينــات الــدم والبــول فــا مانــع لدينــا مــن حــدوث‬\n‫الوفــاة نتيجــة الطلــق النــاري النافــذ بالصــدر ومــا يحدثــه عــادة مــن‬\n‫إصابــات بأحشــاء جــوف الصــدر وبالنســبة لزمــن الوفــاة نتيجــة الطلــق‬\n‫النــاري النافــذ بالصــدر ومــا يحدثــه عــادة مــن حوالــي ســاعة واحــدة مــن‬\n‫توقيــت املعاينــة األوليــة قــد تزيــد أو تنقــص تبع ـ ًا للتغيــرات احمليطــة‬\n‫باجلثمــان كمــا فــرزت أوراق مســتقلة حليــازة الســاح بــدون ترخيــص‬\n\n\n                                                                                       ‫‪38‬‬\n\f     ‫العائــد لوالــد اجلانــي واملســتخدم يف القضيــة والســاح اآلخــر املضبــوط‬\n     ‫وباســتجواب املدعــى عليــه احلــدث ‪..........‬أقــر بأنــه يف يــوم األربعــاء‬\n     ‫‪1431/12/29‬ه ـ أطلــق النــار مــن ســاح مــن نــوع رشــاش يعــود لوالــده‬\n     ‫علــى ‪..........‬طلقــة واحــدة باجتــاه الصــدر حيــث إنــه أطلــق طلقــة يف الهواء‬\n     ‫فلــم تخــرج مــن الســاح أي ذخيــرة فتوقــع أن الســاح ال يجــد بــه ذخيــرة‬\n     ‫وقــام بعــد ذلــك بتعشــيق الســاح مــرة أخــرى وتصويبــه باجتــاه ‪..........‬‬\n     ‫قاصــد ًا إخافتــه بذلــك وأنــه كان ميازحــه فأطلــق طلقــة واحــدة فأصابــت‬\n     ‫‪..........‬ممــا نتــج عنــه وفاتــه ومت تصديــق إقــراره شــرع ًا وملــا أشــير إليــه‬\n     ‫أقــرر توجيــه االتهــام للحــدث املذكــور بإطــاق النــار عمــد ًا مــن ســاح‬\n     ‫ا‬\n     ‫نــوع رشــاش طلقــة واحــدة أصابــت ‪ ..........‬بصــدره فــأرداه قتي ـ ً‬\n     ‫واســتخدامه للســاح العائــد لوالــده وذلــك لألدلــة والقرائــن التاليــة ‪.1‬‬\n     ‫إقــرار املدعــى عليــه املصــدق شــرع ًا واملنــوه عنــه يف الصفحــة رقــم (‪)4‬‬\n     ‫لفــة رقــم (‪.2 )29‬مــا جــاء مبحضــر متثيــل اجلرميــة املرفــق ‪.3‬مــا جــاء‬\n     ‫مبحضــر االنتقــال واملعاينــة املــدون علــى الصفحــة رقــم (‪ )4‬لفــة رقــم (‪)1‬‬\n     ‫‪.4‬مــا جــاء يف التقريــر املصــور ملســرح اجلرميــة وجثمــان املتوفــى لفــة رقــم‬\n     ‫(‪.5 )67‬مــا جــاء بالتقريــر الطبــي لفــة رقــم (‪. )41‬مــا جــاء يف التقريــر‬\n     ‫الفنــي رقــم (‪/60‬كيميــاء جنائيــة ‪1431/‬ه) لفــة رقــم (‪.7 )39‬التقريــر‬\n     ‫الطبــي الشــرعي النهائــي رقــم (‪1430/114‬ه) وحيــث إن مــا أقــدم عليــه‬\n     ‫املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إحالتــه‬\n     ‫لفضيلــة قاضــي األحــداث إلثبــات إدانتــه مبــا أســند إليــه وحتديــد صفــة‬\n     ‫القتــل والنظــر يف إنهــاء احلــق العــام يف ضــوء املــادة (‪ )174‬واملــادة رقــم‬\n     ‫(‪ )126‬و املــادة رقــم (‪ )152‬مــن نظــام اإلجــراءات اجلزائيــة (علم ـ ًا بــأن‬\n     ‫احلــق اخلــاص قــد انتهــى بالتنــازل وصــدق التنــازل شــرعاً) هــذه دعــواي‬\n\n\n‫‪39‬‬\n\f‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه وســؤاله عنهــا أجــاب‬\n‫بقولــه مــا ذكــره املدعــي العــام يف دعــواه صحيــح حيــث أننــي وجــدت‬\n‫ســاح لوالــدي يف الغرفــة وقــد قمــت بتعشــقيه وإطــاق النــار يف الهــواء‬\n‫مرتــن فلــم يخــرج مــن الســاح أي طلــق نــاري ثــم قمــت بتعشــيقه مــرة‬\n‫أخــرى وصوبتــه جتــاه ابــن عمــي ‪..........‬مــن بــاب املمازحــة وإخافتــه‬\n‫فخرجــت طلقــة فأصابــت ‪..........‬يف صــدره ممــا تســبب لــه بالوفــاة علمـ ًا‬\n‫أن مــا مت منــي كان عــن طريــق اخلطــأ فلــم أكــن أقصــد فعــل ذلــك‬\n‫هكــذا أجــاب وبالرجــوع إلــى أوراق املعاملــة وجــد باللفــة رقــم (‪)115‬‬\n‫صــك صــادر مــن احملكمــة العامــة بتبــوك برقــم ‪5/2‬يف ‪1430/2/24‬ه ـ‬\n‫املتضمــن تنــازل ورثــة القتيــل ‪..........‬وهمــا والــداه ‪ ..........‬و‪ ..........‬مبوجــب‬\n‫صــك حصــر ورثــة الصــادر مــن احملكمــة العامــة برقــم ‪..........‬يف‬\n‫‪1430/1/2‬ه ـ وذلــك أن قتــل املدعــى عليــه ألبنهمــا مــن ســاح رشــاش‬\n‫عــن طريــق اخلطــأ ركمــا جــرى الرجــوع إلــى التقريــر الطبــي الشــرعي‬\n‫النهائــي لفــة رقــم (‪ 86‬إلــى ‪ )92‬املتضمــن أن الوفــاة تعــود لتوقــف القلــب‬\n‫والتنفــس نــاجت عــن علــة كامنــة تعــذر معرفتهــا نظــر ًا لعــدم تشــريح‬\n‫اجلثمــان ولكــن بنــاء علــى الكشــف الظاهري واألشــعة املجــراة وفحص‬\n‫املالبــس ومعاينــة مــكان الوفــاة وســلبية العينــات الــدم والبــول فــا مانــع‬\n‫لدينــا مــن حــدوث الوفــاة نتيجــة الطلــق النــاري النافــذ بالصــدر ومــا‬\n‫يحدثــه عــادة مــن إصابــات بأحشــاء جــوف الصــدر والنســبة لزمــن الوفــاة‬\n‫فبنــاء علــى العالمــات الرميــة املشــاهدة علــى اجلثمــان حوالــي ســاعة‬\n‫واحــدة املعاينــة األوليــة قــد تزيــد أو تنقــص تبع ـ ًا للتغيــرات احمليطــة‬\n‫باجلثمــان كمــا جــرى الرجــوع إلــى لفــة رقــم (‪ )29‬صفحــة (‪ )4‬املتضمــن‬\n‫إقــرار املدعــى عليــه وفــق إجابتــه فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n\n\n                                                                                             ‫‪40‬‬\n\f     ‫واإلجابــة وملّــا أقــر املدعــى عليــه بإطالقــه للنــار علــى املجنــي عليــه‬\n     ‫والتســبب يف قتلــه وأن ذلــك عــن طريــق اخلطــأ وحيــث عــن اإلقــرار حجــة‬\n     ‫علــى صاحبــه مؤاخــذ بــه ونظــر ًا لكــون جميــع األدلــة والقرائــن احملتفــه‬\n     ‫باملعاملــة تؤيــد ذلــك مــن صغــر ســن املدعــى عليــه وإقــرار ورثــة املتوفــى‬\n     ‫ـدي إطــاق‬  ‫بذلــك وعــدم وجــود عــداوة لــذا وجلميــع مــا تقــدم فقــد ثبــت لـ َّ‬\n     ‫املدعــى عليــه النــار مــن ســاح نــوع رشــاش أصابــت املجنــي عليــه ‪..........‬‬\n     ‫فتســببت يف وفاتــه وأن القتــل املوصــوف مــن قبيــل اخلطــأ وقــررت تعزيــر‬\n     ‫املدعــى عليــه لقــاء مــا بــدر منــه بســجنه ملــدة شــهر يحتســب مــن ذلــك مــدة‬\n     ‫إيقافــه بســبب هــذه القضيــة مــع أخــذ التعهــد عليــه بعــدم العــودة ملثــل مــا‬\n     ‫بــدر منــه وبذلــك حكمــت كمــا أفهمتــه بــأن عليــه كفــارة القتــل اخلطــأ‬\n     ‫وهــي عتــق رقبــة فــإن لــم يجــد فصيــام شــهرين متتابعــن وبعــرض احلكــم‬\n     ‫علــى الطرفــن قــرر املدعــى عليــه قناعتــه بــه وأمــا املدعــي العــام فقــد‬\n     ‫قــرر اعتراضــه مكتفي ـ ًا مبــا جــاء يف أوراق املعاملــة عــن تقــدمي الئحــة‬\n     ‫اعتراضيــة وللبيــان حــرر ‪1434/8/14‬ه ـ وصلــى اهلل علــى نبينــا محمــد‬\n     ‫وعلــى آلــه وصحبــه أجمعــن‪ .‬احلمــد هلل وحــده وبعــد‪ :‬فقــد اطلعن ــا نحــن‬\n     ‫قـض ــاة الدائ ــرة اجلزائيــة الثانيــة يف محكمــة االســتئناف مبنطقــة تبــوك‬\n     ‫علــى املعاملــة الــواردة مــن احملكمــة اجلزائيــة بتبــوك برقــم وتاريــخ‬\n     ‫‪1434/8/21‬هـ‪،‬املرفــق بهــا القــرار الصــادر مــن فضيلــة ‪..........‬برقــم‬\n     ‫وتاريــخ ‪1434/8/14‬ه ـ ‪،‬واخلــاص بدعــوى املدعــي العــام ضــد ‪..........‬يف‬\n     ‫قضيــة إثبــات صفــة القتــل ‪ ،‬علــى النحــو املوضــح بالقــرار واملتضمــن‬\n     ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة‬\n     ‫ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق‬\n                                    ‫‪،‬وصلى اهلل على نبينا محمد آله وصحبه وسلم‪.‬‬\n\n\n‫‪41‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":34,"source_page_end":41,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d10d8cf188569f007c4333e9c4a524806506dbea8a5ca428fae139165e54c70c","normalized_text_hash":"2e46b15b860f03f7144a3b886c9a4ec4c400b8e1885f2a58bd4c6bc819879f53","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p34-34296822"},{"id":"73bc1b8d-70c3-5f7c-ab67-4457eb8ab744","document_type":"judgment","category":"judicial","subcategory":"general","title":"قيام أخته -املدعى عليها -بضرب أخيه مما تسبب بجرح يف رأسه من جهة الصدغ وبعد مضي ما يقارب الثاث ساعات فارق احلياة وبناء على التقرير الطبي بأن سبب الوفاة يعود لتوقف مفاجئ يف الدورة الدموية قاموا بدفنه دون إباغ اجلهات األمنية ،تنازل ورثة املجني عليه عن املدعى عليها عدا املبلغ ،بعرض الدعوى على «وكيل املدعى عليها» أجاب مبذكرة جوابية خالصتها إنكاره","document_number":"34223913","case_number":"3422571","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/27","year":"1434","subject":"قيام أخته -املدعى عليها -بضرب أخيه مما تسبب بجرح يف رأسه من جهة الصدغ وبعد مضي ما يقارب الثاث ساعات فارق احلياة وبناء على التقرير الطبي بأن سبب الوفاة يعود لتوقف مفاجئ يف الدورة الدموية قاموا بدفنه دون إباغ اجلهات األمنية ،تنازل ورثة املجني عليه عن املدعى عليها عدا املبلغ ،بعرض الدعوى على «وكيل املدعى عليها» أجاب مبذكرة جوابية خالصتها إنكاره","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34223913 :‬تاريخه‪1434/5/27 :‬هـ‬\n                     ‫رقم الدعوى‪3422571:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34270456‬تاريخه‪1434/7/17 :‬هـ‬\n\n\n‫قتــل ‪ ،‬قتــل خطــأ ‪ ،‬ضــرب باســتخدام ســطل حديــدي «أداة حديديــة» ‪،‬‬\n‫ضــرب أفضــى إلــى املــوت ‪ ،‬دعــوى عامــة وخاصــة ‪ ،‬تقريــر طبــي شــرعي ‪،‬‬\n                                                 ‫رد دعــوى املدعــى العــام‪.‬‬\n\n\n\n\n                                      ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن قبــل االدعــاء العــام علــى املدعــى عليهــا بقيامهــا‬\n‫بقتــل أخيهــا بضربهــا علــى رأســه بســطل حديــدي إثــر اعتــداء بالضــرب‬\n‫حصــل بينهمــا حصلــت بينهمــا ويطلــب إثبــات صفــة قتلهــا لــه «شــبه‬\n‫عمــد» لتطبيــق مقتضــى اإلرادة امللكيــة يف حقهــا بســجنها ســنتني‬\n‫ونصــف حيــث تقــدم أحــد املواطنــن ألحــد مراكــز الشــرطة ببــاغ عــن‬\n‫قيــام أختــه ‪ -‬املدعــى عليهــا ‪ -‬بضــرب أخيــه ممــا تســبب بجــرح يف رأســه‬\n‫مــن جهــة الصــدغ وبعــد مضــي مــا يقــارب الثــاث ســاعات فــارق احليــاة‬\n‫وبنــاء علــى التقريــر الطبــي بــأن ســبب الوفــاة يعــود لتوقــف مفاجــئ يف‬\n‫الــدورة الدمويــة قامــوا بدفنــه دون إبــاغ اجلهــات األمنيــة ‪ ،‬تنــازل ورثــة‬\n‫املجنــي عليــه عــن املدعــى عليهــا عــدا املبلــغ ‪ ،‬بعــرض الدعــوى علــى‬\n‫«وكيــل املدعــى عليهــا» أجــاب مبذكــرة جوابيــة خالصتهــا إنــكاره‬\n\n                                                                                        ‫‪42‬‬\n\f     ‫بــأن الضربــة التــي أصابتــه مــن موكلتــه أدت لوفاتــه‪ ،‬وإمنــا تــويف إثــر‬\n     ‫نوبــة ربــو حــادة أدت لتوقــف مفاجــئ يف الــدورة الدمويــة والتنفــس‪،‬‬\n     ‫وأن دعــوى املدعــي اخلــاص «املبلــغ» كيديــة إثــر خــاف مالــي بينهمــا ‪،‬‬\n     ‫جــرى االطــاع علــى التقريــر الطبــي املتضمــن بــأن ســبب الوفــاة توقــف‬\n     ‫مفاجــئ يف الــدورة الدمويــة والتنفســية ‪ ،‬جــرى االطــاع علــى اعتــراف‬\n     ‫املدعــى عليهــا املتضمــن إقرارهــا بالشــجار الــذي دار بينهــا وبــن املتوفــى‬\n     ‫تطــور لالشــتباك باأليــدي فقامــت علــى إثــر ضربــه وشــد شــعر رأســه‬\n     ‫بتنــاول ســطل حديــدي بجوارهــا ضربــت بــه رأســه ففرقــت بينهمــا‬\n     ‫أختــه‪ ،‬فشــاهدت قطــرات مــن دم تســيل مــن رأســه يف محــل االصابــة‬\n     ‫فاتصــل علــى الدوريــات األمنيــة فحلــوا اإلشــكال بينهمــا وقــررا التنــازل‬\n     ‫عــن بعضهمــا يف املوقــع فمكــث قليــا وغــادر املوقــع ومعــه أختــه وبعــد‬\n     ‫منتصــف الليــل اتصلــت أختهــا عليــه فأخبرتهــا بنقلــه للمستشــفى فاقــدا‬\n     ‫الوعــي ثــم أخبــرت بوفاتــه ‪ ،‬بعــرض اإلقــرار علــى وكيلها صــادق عليه‪،‬‬\n     ‫جــرى االطــاع علــى محضــر اســتجواب أخــت املتوفــى واملدعــى عليهــا‬\n     ‫واملتضمــن أن املتوفــى يعانــي مــن مــرض بصــدره وبعــد ضربــه مــن قبــل‬\n     ‫املدعــى عليهــا اتصــل املتوفــى بالشــرطة ولــم يــرض نقلــه للمستشــفى وأن‬\n     ‫الــدم الــذي خــرج منــه كان قليــا وقــد خــرج وهــو يقــود ســيارته ‪ ،‬جــرى‬\n     ‫االطــاع علــى إفــادة أخــوي املدعــى عليهــا أن املتوفــى كان يعانــي مــن‬\n     ‫ألــم يف صــدره ‪ ،‬جــرى االطــاع علــى إفــادة أحــد أقاربــه بــأن املتوفــى‬\n     ‫كان يعانــي مــن ألــم يف صــدره ويســتفرغ دمــا وكان يعانــي مــن األلــم يف‬\n     ‫صــدره مــن خمــس ســنوات تقريبـ ًا ‪ ،‬وعليــه وملــا تضمنــه التقريــر الطبــي‪،‬‬\n     ‫ومــا ورد يف محاضــر اســتجواب أشــقاء املدعــى عليهــا وأقــارب املتوفــى‬\n     ‫مــن أنــه كان يعانــي مــن مــرض يف صــدره وأن الــدم الــذي نــزف منــه‬\n\n\n‫‪43‬‬\n\f‫كان قليــا ‪ ،‬لــذا قــررت احملكمــة عــدم ثبــوت إدانــة املدعــى عليهــا‬\n‫بقتــل أخيهــا وصرفــت النظــر عــن طلــب املدعــي العــام ‪ ،‬بعرضــه علــى‬\n‫املدعــي العــام قــرر االعتــراض بالئحــة ‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                               ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬مســاعد رئيــس احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫وتاريــخ‬           ‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم‬\n‫‪1434/01/13‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ ‪1434/01/13‬ه ـ‬\n‫ففــي يــوم اإلثنــن املوافق‪1434/03/23‬ه ـ افتتحــت اجللســة الســاعة ‪45‬‬\n‫‪ 09 :‬وفيهــا حضر‪..........‬املكلــف بالترافــع لدينــا يف قضايــا احلــق العــام‬\n‫مبوجــب خطــاب رئيــس دائــرة اإلدعــاء العــام مبكــة املكرمــة رقــم‬\n‫‪..........‬يف ‪1434/1/24‬ه ـ وأدعــى علــى ‪ 38(..........‬عام ـاً) ســعودية‬\n‫ا يف دعــواه عليهــا أنــه بتاريخ‬‫اجلنســية بالســجل املدنــي رقــم (‪ )..........‬قائـ ً‬\n‫‪1433/4/5‬ه ـ تقــدم املواطــن‪.......... /‬ملركــز شــرطة ‪..........‬ببــاغ عــن‬\n‫قيــام أختــه املدعــى عليهــا بضــرب أخيــه ‪..........‬البالــغ مــن العمر‪42‬عــام‬\n‫ممــا تســبب يف إصابتــه بجــرح يف رأســه مــن جهــة الصــدغ األميــن وبعــد‬\n‫مضــي مــا يقــارب الثــاث ســاعات فــارق احليــاة وبنقلــه ملستشــفى امللــك‬\n‫فيصــل ومعاينتــه مــن قبــل الطبيــب املقيــم صــدر بحقــه التقريــر الطبــي‬\n‫‪..........‬بتاريــخ ‪1433/3/26‬ه ـ صــادر مــن مستشــفى امللــك فيصــل‬\n‫متضمن ـ ًا ان ســبب الوفــاه توقــف مفاجــئ بالقلــب والــدوره الدمويــه‬\n‫والتنفســيه‪ .‬وان إخوتــه قامــوا بدفنــه دون إبــاغ اجلهــات االمنيــه عــن‬\n\n                                                                                         ‫‪44‬‬\n\f     ‫االصابــه التــي بــه وقــد مت دفنــه ولــم يبلــغ هــو اال بعــد مضــي أكثــر مــن‬\n     ‫أســبوع علــى الواقعــة وبضبــط أقــوال اخــوة املجنــي عليــه ذكــرت‬\n     ‫املدعوة‪........../‬شــقيقة طــريف القضيــة بــان املجنــي عليــه حضــر للمنــزل‬\n     ‫العائــد لوالدتهمــا والــذي تقطنــه رفقــة أختهــا املدعــى عليهــا وأثنــاء‬\n     ‫وجــوده بداخــل غرفتهــا حضــرت املدعــى عليهــا وحــدث بينهــا وبــن‬\n     ‫أخيهــا نقــاش بســبب عــدم رغبتهــا يف حضــوره للمنــزل وتطــور النقــاش‬\n     ‫الشــتباك ومضاربــه وقامــت املدعــى عليهــا بالتقــاط ســطل حديــدي‬\n     ‫وضربــت بــه رأس أخيهــا ممــا تســبب لــه بجــرح نــزف علــى أثــره قليــا مــن‬\n     ‫الــدم وقــام هــو باالتصــال علــى الدوريــات االمنيــه التــي حضــرت للموقــع‬\n     ‫وتنــازل الطرفــان عــن بعضهمــا البعــض وبعدهــا جلــس لديهــا باملنــزل‬\n     ‫لفتــرة وغــادرت معــه ملنزلــه وكان يقــود الســيارة وبعــد وصولهــم أطعــم‬\n     ‫القطــط العائــدة لــه ومتــدد علــى فراشــه وأحــس ببعــض اآلالم وطلبــت منــه‬\n     ‫الذهــاب للمستشــفى فرفــض ذلــك وبعــد فتــره أحســت انــه غــاب عــن‬\n     ‫الوعــي وأبلغــت ذويهــا وابنهــا الذيــن نقلــوه للمستشــفى وقــد أفــادت بــأن‬\n     ‫املجنــي عليــه لــه تاريــخ مرضــي قــدمي وكان يســعل حتــى يخــرج الــدم مــن‬\n     ‫فمــه وبضبــط أقــوال بقيــة أخــوة املجنــي عليــه توافقــت أقوالهــم مــع‬\n     ‫أقــوال أخيهــم املدعــي حيــال تعــرض املجنــي عليــه ألصابــه تــويف بعدهــا‬\n     ‫بثــاث ســاعات كمــا أخبرتهــم أختهــم ‪..........‬بذلــك ممــا يؤكــد أن‬\n     ‫املتوفــى بــه إصابــه أدت لنزيــف مــن رأســه وقــد توافقــت أقوالهــم بــأن‬\n     ‫املجنــي عليــه لــه تاريــخ مرضــي قــدمي وكان يســعل حتــى يخــرج الــدم مــن‬\n     ‫فمــه ولديــه ربــو مزمــن وأنهــم قامــوا بدفنــه بنــاء لتقريــر الطبيــب املختص‬\n     ‫الــذي لــم يذكــران ســبب الوفــاة االصابــه وأنهــم ابلغــوا أخاهــم األكبــر‬\n     ‫وهــو املدعــي باملشــكلة التــي حدثــت وطالبهــم بعــدم دفــن اجلثمــان‬\n\n\n‫‪45‬‬\n\f‫لرغبتــه يف احلضــور واالســتفادة مــن كليــة أخيــه املتــويف إلصابتــه هــو‬\n‫بفشــل كلــوي وحاجتــه ملتبــرع بضبــط أقــوال املدعو‪20........../‬عامــا‬\n‫ســعودي اجلنســيه وهــو ابــن املــرأه ‪ - ..........‬شــقيقة املجنــي عليــه‪ -‬وهــو‬\n‫مــن قــام بإســعافه حيــث حضــر لــه يف تلــك الليلــه مبنزلــه وهــو يكــح‬\n‫بشــده ويســتفرغ الــدم وطلــب منــه أن يقــوم بشــراء عشــاء وعنــد ذهابــه‬\n‫اتصلــت عليــه والدتــه وطلبــت منــه احلضــور الن املجنــي عليــه خالــه اليــرد‬\n‫عليهــم وحضــر ونقلــه ملســتوصف ‪..........‬ب‪ ..........‬فابلغــوه بانــه فــارق‬\n‫احليــاه ومت نقلــه بواســطة الهــال االحمــر ملستشــفى امللــك فيصــل مبكــه‬\n‫وعاينــه الطبيــب واصــدر أذنــه بدفنــه بســماع شــهادة الشــاهد ‪..........‬ابــن‬\n‫اخــت املجنــي عليــه افــاد بانــه اثنــاء غســل املجنــي عليــه شــاهد الــدم ينــزل‬\n‫مــن راســه كمــا شــاهد اثــر نــزف الــدم اثنــاء تكفينــه بضبــط شــهادة‬\n‫املدعو‪........../‬شــقيق املجنــي عليــه أفــاد مبشــاهدته نــزف الــدم مــن أخيه‬\n‫اثنــاء غســله لــه قبــل دفنــه وبضبــط شــهادة الشــاهد ‪ ..........‬افــاد بانــه‬\n‫حضــر ب‪ ..........‬وقــت وصــول االســعاف وكانــت متوقفــة بجــوار‬\n‫ســيارة‪..........‬وقاموا بانــزال املجنــي عليــه واركابــه باالســعاف ولــم‬\n‫يشــاهد أثــار دم وبعــد ان اخــذوا اجلثمــان للمستشــفى شــاهد اثــار نــزف‬\n‫بســيط مــن راس املجنــي عليــه وباملغســله اتصــل املدعــي ‪..........‬علــى أخيه‬\n‫‪..........‬وطلــب عــدم دفــن اجلثمــان لالســتفاده مــن الكلــي العائــده‬\n‫للمتوفــى حيــث انــه يعانــي مــن فشــل كلــوي وبســواله هــل يعانــي املجنــي‬\n‫عليــه مــن امــراض افــاد بانــه يعانــي مــن كتمــه بالصــدر وقــد حضــر‬\n‫جميــع أوليــاء الــدم وهــم إخــوة املجنــي عليــه وقــرروا تنازلهــم شــرعا عــن‬\n‫أختهــم وعــدم رغبتهــم يف نبــش قبــر أخيهــم وصــدق التنازل شــرع ًا ماعدا‬\n‫املدعــي الــذي يطالــب بالتحقيــق وإظهــار النتائــج وبإحالــة املدعــى عليهــا‬\n\n\n                                                                                         ‫‪46‬‬\n\f     ‫للجنــة الطبيــة الشــرعية صــدر بحقهــا التقريــر الطبــي النفســي رقــم‬\n     ‫‪..........‬وتاريــخ ‪1433/12/20‬ه ـ املتضمــن أن املدعــى عليهــا مســؤولة‬\n     ‫جنائي ـ ًا عــن تصرفاتهــا وباســتجواب املدعــى عليهــا ‪ ........../‬اقــرت‬\n     ‫بضــرب أخيهــا ليلــة الواقعــة بســطل حديــدي إثــر قيامــه بضربهــا وأنهــا‬\n     ‫شــاهدت نزيف ـ ًا دموي ـ ًا طفيــف مــن موقــع االصابــه حيــث ضربتــه يف‬\n     ‫رأســه بســطل حديــدي لقــاء تهجمــه عليهــا بســبب مشــاكل ســابقه‬\n     ‫ـاء لبــاغ املجنــي عليــه ومت‬‫بينهمــا وقــد حضــرت الدوريــات االمنيــه بنـ ً‬\n     ‫الصلــح مبوقــع احلادثــة وقــرر الطرفــان التنــازل عــن بعضهمــا البعــض‬\n     ‫وبعــد مغــادرة املجنــي عليــه ملنــزل أختــه اجتــه لبيتــه وبعــد مــرور مــا يقارب‬\n     ‫الثــاث ســاعات عانــى مــن الــم مفاجــي وتــويف قبــل إســعافه وصدقــت‬\n     ‫اقرارهــا شــرع ًا بذلــك وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى‬\n     ‫عليهــا بالقتــل شــبه العمــد بضــرب اخيهــا ‪........../‬بســطل حديــدي أثــر‬\n     ‫قيامــه بالتضــارب معهــا ممــا تســبب يف إصابتــه ووفاتــه متاثــر ًا بجراحــه‬\n     ‫وذلــك لألدلــة والقرائــن التاليــة‪ -1:‬إقرارهــا املصــدق شــرع ًا مبــا اســند‬\n     ‫اليهــا املــدون بالصفحــة رقــم( ‪) 5‬مــن دفتــر التحقيــق املرفــق لفــه رقــم(‪65‬‬\n     ‫)‪ -2‬اقوال الشهود املدونه مبلف االستدالل ا ملرفق لفه(‪-3)28/14/2/1‬‬\n     ‫محضــر االنتقــال واملعاينــه املــدون مبلــف االســتدالل املرفــق لفــه(‪-4)19‬‬\n     ‫التقريــر الطبــي املرفــق لفــه(‪ -5)10‬تقريــر رقم‪/21-270‬فحــوص‬\n     ‫وراثيه‪1433/‬ه ـ املرفــق بــاوراق القضيــه‪ -6‬دعــوى املدعــي وتطابقهــا مــع‬\n     ‫أقــوال اطــراف القضيــه واملدونــه مبلــف االســتدالل لفــه(‪ )1‬وبالبحــث‬\n     ‫عــن ســوابقها لــم يعثــر لهــا علــى ســوابق وحيــث ان مــا قامــت بــه املدعــى‬\n     ‫عليهــا فعــل محــرم ومعاقــب عليــه شــرعا لــذا أطلــب اثبــات صفــة القتــل‬\n     ‫شــبه العمــد ضدهــا إســتنادا إلــى املــواد(‪ )174-129-126‬واحلكــم‬\n\n\n‫‪47‬‬\n\f‫عليها بتطبيق االراده امللكيه رقم ‪ 2104/4/8‬بتاريخ‪1363/10/26‬هـ‬\n‫ورقم‪2624‬بتاريخ‪1372/4/9‬ه ـ وفقــا ملــا ورد يف قــرار املجلــس االعلــى‬\n‫رقــم ‪ 3/106‬بتاريــخ ‪1408/4/23‬ه ـ املؤيــد باالمــر الســامي‬\n‫رقم‪1197/4‬بتاريخ‪1409/6/12‬ه ـ علمــا ان احلــق اخلــاص انتهى بالتنازل‬\n‫ماعــدا احــد اوليــاء الــدم مــازال مطالبــا بحقــه وبســؤال املدعــى عليــه‬\n‫وكالــة ‪ ..........‬بالســجل املدنــي رقــم (‪ )..........‬مبوجب الوكالة الصادرة‬\n‫مــن كتابــة العــدل الثانيــة مبكــة املكرمــة رقــم (‪ )..........‬يف‬\n‫‪1434/2/4‬ه ـ قــال أطلــب إمهالــي للــرد علــى الئحــة املدعي العــام فجرى‬\n‫رفــع اجللســة ويف يــوم الثالثــاء املوافق‪1434/04/23‬ه ـ افتتحــت اجللســة‬\n‫الســاعة (‪ )10‬وفيهــا حضــر الطرفــان وقــدم املدعــى عليــه وكالــة ‪..........‬‬\n‫علــى دعــوى املدعــي العــام وهــذا نصــه (إشــارة إلــى الدعــوى املقيــدة لــدى‬\n‫فضيلتكــم برقــم (‪ )34108241‬وتاريــخ ‪1434/1/13‬ه ـ املقامــة مــن‬\n‫اإلدعــاء العــام واملطالــب فيهــا بإثبــات صفــة القتــل شــبه العمــد بحــق‬\n‫موكلتي‪..........‬التهامهــا بقتــل أخيهــا ‪..........‬واســتنادا للمــادة‬\n‫(‪174‬إجــراءات جزائيــة) أوجــز ردي يف النقــاط اآلتيــه‪ :‬أوال‪ :‬إن الغــرض‬\n‫مــن دعــوى املدعــي باحلــق اخلــاص هــو النكايــة مبوكلتــي وإحلــاق األذى‬\n‫بهــا ومحاولــة احلصــول علــى كســب مالــي واالنتقــام منهــا لوجــود‬\n‫خالفــات ســابقة بينهمــا حيــث كان املدعــي باحلــق اخلــاص وكيــا‬\n‫ملوكلتــي يف تصفيــة حقوقهــا يف تركــة والدهــا وحلصــول ضــرر علــى‬\n‫موكلتــي مــن املدعــي قامــت بإلغــاء وكالتــه وكذلــك بقيــة أخواتهــا‬\n‫اقتــداء بهــا ممــا جعــل املدعــي يحمــل الضغينــة لهــا مرفــق صــور‬\n‫الــوكاالت والفســخ‪ -‬ب‪ -‬مــا ذكــره املدعــي باحلــق اخلــاص يف شــكواه‬\n‫مــن أنــه لــم يعــرف بإصابــة املتوفــى برأســه قبــل دفنــه يخالــف الواقــع‬\n\n\n                                                                                     ‫‪48‬‬\n\f     ‫حيــث أن أخــوة املتوفــى أبلغــوا املدعــي مبــا حــدث بــن موكلتــي واملتوفى‬\n     ‫قبــل دفنــه وطالبهــم بعــدم دفــن اجلثمــان لرغبتــه يف احلضــور واالســتفادة‬\n     ‫مــن كليــة أخيــه املتوفــى إلصابــة املدعــي بالفشــل الكلــوي وحاجتــه‬\n     ‫ملتبــرع ؛ ورفــض الورثــة ذلــك وهــذا هــو الســبب احلقيقــي لرفعــه الدعــوى‬\n     ‫بعــد الوفــاة بعشــرة أيــام انتقامــا مــن موكلتــي املعارضــة لــه علــى وجــه‬\n     ‫اخلصــوص ومــن بقيــة أخوتــه لعــدم تلبيــة طلبــه وابتــدأ مبوكلتــي التــي‬\n     ‫اتهمهــا بالقتــل وقــام كذلــك برفــع دعــاوى متعــددة علــى بقيــة أخوتــه‬\n     ‫يطالبهــم مبطالبــات ماليــة ممــا يــدل علــى كيديــة دعــواه وعــدم صحــة‬\n     ‫زعمــه ثاني ـ ًا ‪ :‬عــدم وجــود أدلــة لتوجيــه التهمــة ضــد موكلتــي وجــه‬\n     ‫املدعــي العــام إلــى موكلتــي تهمــة القتــل شــبه العمــد بضــرب أخيهــا‬\n     ‫بســطل حديــدي أثــر قيامهمــا بالتضــارب مع ـ ًا ممــا تســبب يف إصابتــه‬\n     ‫ا وال أســاس‬  ‫ووفاتــه متأثــر ًا بجراحــه وهــذا غيــر صحيــح جملــة وتفصيـ ً‬\n     ‫لــه مــن الصحــة واملدعــي العــام ليــس لديــه البينــة علــى مــا قــال و قــد نفــى‬\n     ‫التقريــر الطبــي وأقــوال الشــهود الــذي ذكــر أن ســبب هــو إصابــة الرأس‬\n     ‫؛ فالوفــاة لــم حتــدث نتيجــة تأثــره بإصابــة الــرأس كمــا زعــم املدعــي‬\n     ‫العــام ألن اإلصابــة كانــت ســطحية ولــم تســبب غيــر نــزف طفيــف و‬\n     ‫هــذا مــا أكــده الشــهود ‪ ،‬أمــا األلــم الــذي حلــق املتوفــى قبــل وفاتــه كان‬\n     ‫مــن مضاعفــات مرضــه املزمــن بالربــو والكتمــة الصدريــة و الســعال‬\n     ‫حتــى خــروج الــدم وهــذا مــا أكــده التقريــر الطبــي و أقــوال الشــهود‬\n     ‫علــى النحــو التالــي‪ :‬أ‪ -‬ليــس يف الدعــوى املقامــة ضــد موكلتــي بينــة‬\n     ‫تثبــت صحــة التهمــة الباطلــة وكل مــا ورد يف الئحــة االدعــاء العــام مــن‬\n     ‫بينــات وقرائــن جميعهــا تثبــت بــراءة موكلتــي مــن التهمــة املوجهــة لهــا ؛‬\n     ‫فموكلتــي لــم تقصــد ضــرب أخيهــا إمنــا قصــدت دفــع أذاه عنهــا عنــد‬\n\n\n‫‪49‬‬\n\f‫ضربــه لهــا وشــد شــعرها بشــدة وأثنــاء ذلــك المســت يدهــا الســطل‬\n‫املوجــود بالغرفــة فضربتــه بهــا لوقــف ضربــه املبــرح ؛ فلــم يوجــد قصــد‬\n‫وال آلــة قاتلــة ولــم يثبــت شــرعا تســبب الضربــة يف وفاتــه ؛ فالتقريــر‬\n‫الطبــي رقــم ‪..........‬تاريــخ ‪1433/3/26‬ه ـ هــو الفيصــل يف القضيــة حيث‬\n‫نــص علــى أن ســبب الوفــاة [ توقــف مفاجــئ بالــدورة الدمويــة واجلهــاز‬\n‫التنفســي والقلــب ] ممــا يثبــت قطعــا أن الوفــاة كانــت طبيعيــة ويدحــض‬\n‫زعــم املدعــي العــام بــأن الوفــاة كانــت نتيجــة تأثــره بجــراح إصابــة‬\n‫الــرأس ‪ ،‬كمــا أن هــذه اإلصابــة تركــت جرحــا ســطحيا وقــد ذكــر‬\n‫ذلــك جميــع الشــهود فلــم يحــدث نزيــف أو مضاعفــات أدت إلــى الوفــاة ؛‬\n‫فلــو كانــت هــذه اإلصابــة ســببا يف الوفــاة لظهــر ذلــك يف التقريــر الطبي‬\n‫الــذي ذكــر أن ســبب الوفــاة توقــف مفاجــئ بالــدورة الدمويــة وليــس‬\n‫نزيــف حســب زعــم املدعــى العــام كمــا أن النزيــف املزعــوم لــن يخفــى‬\n‫علــى الطيــب الــذي أعــد التقريــر وإدارة املستشــفى كانــت ســتحول‬\n‫ـاء علــى‬\n        ‫امللــف للشــرطة للتحقيــق يف ذلــك ب‪ -‬ذكــر املدعــى العــام بنـ ً‬\n‫شــهادة جميــع أخــوة املتوفــى مبــا فيهــم املدعــي أن املتوفــى لــه تاريــخ‬\n‫مرضــي قــدمي وكان يســعل حتــى يخــرج الــدم مــن فمــه ولديــه ربــو مزمــن‬\n‫وقــد ذكــرت الشــاهدة ‪..........‬أن املتوفــى بعــد مشــاجرته مــع موكلتــي‬\n‫واتصالــه بالشــرطة وانتهــاء الشــكوى بالصلــح ؛ جلــس معهــا باملنــزل‬\n‫وكان طبيعيــا ال يشــتكي مــن أيــة اآلالم ثــم غــادرت معــه ملنزلــه وكان‬\n‫يقــود ســيارته وبعــد وصولهــم أطعــم القطــط ‪ ،‬ثــم بعــد ذلــك متــدد علــى‬\n‫الفــراش عندهــا أحــس ببعــض اآلالم ورفــض الذهــاب للمستشــفى إلــى‬\n‫أن فقــد الوعــي ‪ ،‬كمــا ذكــر الشــاهد ‪..........‬الــذي قــام بإســعاف‬\n‫املتوفــى بــأن املتوفــى كان يكــح بشــدة ويســتفرغ الــدم عنــد حضــوره‬\n\n\n                                                                                  ‫‪50‬‬\n\f     ‫إليــه ممــا يــدل يقينــا أن األلــم الــذي شــعر بــه املتوفــى وفقــد بعــده الوعــي‬\n     ‫كان بســبب مرضــه املزمــن ومــن الواضــح تعــرض املتوفــى لنوبــة ربــو‬\n     ‫حــادة أدت إلــى انســداد الشــعب الهوائيــة ممــا تــاه توقف الــدورة الدموية‬\n     ‫واجلهــاز التنفســي والقلــب وحدثــت الوفــاة ‪ ،‬ومــن املعلــوم طبيـ ًا أن مريض‬\n     ‫الربــو معــرض لنوبــات الربــو احلــادة والشــديدة التــي ميكــن أن تــؤدي إلــى‬\n     ‫الوفــاة إذا لــم تتــدارك وتعالــج يف الوقــت املناســب‪ ،‬خاصــة عنــد أولئــك‬\n     ‫الذيــن ال يشــعرون بشــدة األعــراض أو الذيــن ال يقــدرون خطورتهــا وقــد‬\n     ‫ذكــرت الشــاهدة ‪..........‬عنــد ســؤال احملقــق لهــا ( بعــد أن قامت املدعوة‬\n     ‫‪..........‬بضــرب املدعــو ‪..........‬ملــاذا لــم ينقــل إلــى املستشــفى ؟ ) فأجابــت‬\n     ‫بقولهــا (لــم يــرض ولــم يفكــر يف الضربــة وإمنــا كان يعانــي مــن صــدره‬\n     ‫‪ ،‬ممــا يعنــي أن أقــوال الشــهود تطابقــت مــع التقريــر الطبــي يف أن وفاتــه‬\n     ‫كان بســبب مرضــه املزمــن وليــس بســبب إصابــة الــرأس كمــا ذكــر‬\n     ‫املدعــي العــام الــذي اســتند علــى أقــوال املدعــي باحلــق اخلــاص ؛ فبالتالــي‬\n     ‫تنتفــي العالقــة الســببية بــن ضربــة الســطل ووفــاة ‪..........‬ممــا يعنــي‬\n     ‫انتفــاء مســؤولية موكلتــي عــن وفــاة أخيهــا ثالث ـ ًا ‪ :‬قــرار االتهــام جانبــه‬\n     ‫الصــواب و يحتــاج إلــى إعــادة نظــر أ‪ -‬وجــه االدعــاء العــام التهمــة‬\n     ‫ـاء علــى أقــوال مرســلة عاريــة مــن الصحــة وتخالــف الواقــع‬     ‫ملوكلتــي بنـ ً‬\n     ‫والتقاريــر الطبيــة ‪ ،‬حيــث اســتند علــى أقــوال املدعــي باحلــق اخلــاص دون‬\n     ‫بينــة تثبــت صحــة دعــواه يقــول الرســول صلــى اهلل عليــه وســلم (لــو يعطــى‬\n     ‫النــاس بدعواهــم‪ ،‬الدعــى رجــال أمــوال قــوم ودماءهــم‪ ،‬ولكــن البينــة‬\n     ‫علــى املدعــي واليمــن علــى مــن أنكــر) واســتناده يف اتهــام موكلتــي‬\n     ‫إلــى مجــرد أقــوال املدعــي ُيعــد إخــال بالقواعــد الشــرعية التــي تقضــي‬\n     ‫بــأن األصــل يف اإلنســان البــراءة والبــراءة يقــن ال يــزول بالشــك وال يعــدل‬\n\n\n‫‪51‬‬\n\f‫عــن ذلــك إال بدليــل قاطــع وال يجــوز املطالبــة بإثبــات تهمــة القتــل شــبه‬\n‫العمــد ملجــرد الشــك دون التثبــت مــن التهمــة اســتناد ًا إلــى قــول الرســول‬\n‫‪ -‬صلــى اهلل عليــه وســلم ‪ ( -‬ادرؤا احلــدود بالشــبهات فــإن كان لــه‬\n‫مخــرج فخلــوا ســبيله فــإن اإلمــام ليخطــئ يف العفــو خيــر مــن أن يخطــئ‬\n‫يف العقوبــة ) ويقــول بــن تيميــة‪« :‬إمنــا العقوبــة علــى ذنــب ثابــت» [فتــاوى‬\n‫ابــن تيميــة (‪ ]107/28‬بــل إن جميــع األدلــة املذكــورة يف الئحــة اإلدعــاء‬\n‫العــام تثبــت بــراءة موكلتــي مــن التهمــة الباطلــة املنســوبة لهــا ب‪ -‬طالــب‬\n‫االدعــاء العــام بإثبــات صفــة القتــل شــبه العمــد بحــق موكلتــي وهــذا‬\n‫االتهــام يفتقــد ألركان اجلــرم املطالــب بإثباتــه حيــث أن القتــل شــبه‬\n‫العمــد هــو أن يقصــد الفعــل دون نيــة القتــل وحيــث أن ضربــة موكلتــي‬\n‫علــى رأس املتوفــى لــم تتســبب يف قتلــه وإمنــا كانــت وفاتــه طبيعيــة كمــا‬\n‫هــو مبــن يف التقريــر الطبــي فبالتالــي ال ينطبــق هــذا الوصــف عليهــا‬\n‫لعــدم ارتكابهــا اجلــرم املنســوب إليهــا وعــدم وجــود جرميــة يف األصــل‬\n‫لطبيعيــة الوفــاة ت‪ -‬ذكــر املدعــي العــام يف مذكرتــه ‪ -‬ص‪ 2‬ســطر‪، 6‬‬\n‫أنــه [ بضبــط أقــوال بقيــة أخــوة املجنــى عليــه توافقــت أقوالهــم مــع أقــوال‬\n‫أخيهــم املدعــي حيــال تعــرض املجنــى عليــه إلصابــة توفــى بعدهــا بثــاث‬\n‫ســاعات كمــا أخبرتهــم أختهــم ‪ ]..........‬و لعــدم وجــود بينــات علــى دعوى‬\n‫املدعــى العــام حــاول االســتناد علــى هــذا القــول حملاولــة إدانــة موكلتــي‬\n‫حيــث ذكــر [ ممــا يؤكــد أن املتوفــى بــه إصابــة أدت لنزيــف مــن رأســه‬\n‫] وهــذا اســتناد خاطــئ حيــث أن مــا ذكرتــه الشــاهدة ‪..........‬أنــه بعــد‬\n‫ا مــن الــدم وهــذا يــدل‬  ‫ضربــة الســطل حــدث جــرح نــزف علــى أثــره قليـ ً‬\n‫علــى أن اجلــرح ســطحي وليــس باجلــرح الــذي حــدث علــى أثــره نزيــف‬\n‫غزيــر أو نزيــف داخلــي باملــخ أدى إلــى املــوت ‪ ،‬والصحيــح أن املتوفــى‬\n\n\n                                                                                       ‫‪52‬‬\n\f     ‫حانــت منيتــه يف هــذه الســاعة وكانــت وفاتــه طبيعيــة وال ميكــن ربــط‬\n     ‫وفاتــه باألحــداث التــي حدثــت قبــل الوفــاة بســاعات ألن هــذه األحــداث‬\n     ‫لــم يثبــت أنهــا أحدثــت الوفــاة ث‪ -‬طالــب االدعــاء العــام بإثبــات صفــة‬\n     ‫القتــل شــبه العمــد بحــق موكلتــي وذلــك عــن التهمــة املنســوبة إليهــا‬\n     ‫وحيــث نــص القــرار الــوزاري رقــم ‪ 1900‬بتاريــخ ‪1428/7/9‬ه ـ علــى‬\n     ‫اجلرائــم املوجبــة لإليقــاف حلــن االنتهــاء منهــا شــرع ًا ومنهــا جرائــم القتــل‬\n     ‫العمــد وشــبه العمــد و إن إطــاق ســراح موكلتــي يــدل علــى أن االدعــاء‬\n     ‫العــام غيــر متأكــد مــن التهمــة التــي وجههــا ملوكلتــي وأن ليــس هنــاك‬\n     ‫مبــرر إليقافهــا ج‪ -‬ذكــر املدعــي العــام بيانــات خاطئــة يف مذكرتــه‬\n     ‫بغــرض محاولــة إدانــة موكلتــي منهــا ذكــره يف ‪-‬ص‪ -1‬أن موكلتــي‬\n     ‫موقوفــة علــى ذمــة القضيــة وهــذا غيــر صحيــح حيــث أن موكلتــي أفــرج‬\n     ‫عنهــا قبــل حتويــل الدعــوى للمحكمــة د‪ -‬قــال املدعــي العــام أن التقريــر‬\n     ‫الطبــي النفســي رقــم ‪..........‬تاريــخ ‪1433/12/20‬هـ ذكر أنها‪ .‬مســؤولة‬\n     ‫جنائيــة عــن تصرفاتهــا يف محاولــة منــه لالســتناد علــى هــذا التقريــر يف‬\n     ‫إدانــة موكلتــي ‪ ،‬وهــذا التقريــر ال يعطــي املدعــي العــام دليــل علــى أنهــا‬\n     ‫مســؤولة جنائيــا عــن وفــاة أخيهــا لعــدم وجــود إدانــة يف التقريــر الطبــي‬\n     ‫املذكــور حيــث ذكــر التقريــر أنهــا تعتبــر مســؤولة جنائيــا يف حــال‬\n     ‫إدانتهــا يف القضيــة ولــم يثبــت شــرعا ذلــك رابع ـ ًا ‪ :‬أجيــب علــى األدلــة‬\n     ‫والوقائــع التــي اســتند إليهــا املدعــي العــام بإيجــاز يف التالــي باإلضافــة‬\n     ‫إلــى مــا ذكــر أعــاه‪ -1 :‬إقرارهــا املصــدق شــرع ًا مبــا أســند إليهــا‬\n     ‫بالصفحــة رقــم ‪ 5‬مــن دفتــر التحقيــق املرفــق لفــه ‪ 65‬لــم تقــر موكلتــي‬\n     ‫بقتــل شــقيقتها كمــا ذكــر املدعــي العــام وإمنــا ذكــر أنهــا حاولــت صــد‬\n     ‫هجومــه بضربــة علــى رأســه وبالتالــي حــاول املدعــي العــام جتزئــة إقــرار‬\n\n\n‫‪53‬‬\n\f‫موكلتي حملاولة إدانتها بطريقة خاطئة مخالفا بذلك ‪،‬م‪106‬مرافعات‬\n‫شــرعية‪ -‬التــي تنــص علــى أنــه ال يتجــزأ اإلقــرار علــى صاحِ ِبــه‪ ،‬فــا‬\n‫ويتــرك الصا ِلــح ل ـ ُه‪ ،‬بــل يؤخــذ جملــة واحِ ــدة ‪،‬‬  ‫يؤخــذ مِ نــه الضــار ِبــه ُ‬\n‫فموكلتــي أقــرت بضربــه علــى رأســه ولــم تقــر بالقتــل وقــد ثبــت شــرعا‬\n‫مبوجــب التقريــر الطبــي و شــهادة الشــهود أن الوفــاة كانــت بســبب‬\n‫توقــف الــدورة الدمويــة واجلهــاز التنفســي والقلــب وليــس بســبب إصابــة‬\n‫الــرأس كمــا زعــم املدعــي العــام ‪ -2‬أقــوال الشــهود املدونــة مبلــف‬\n‫االســتدالل املرفــق لفــه (‪ )28/14/2/1‬لــم يذكــر الشــهود أن إصابــة‬\n‫الــرأس أدت إلــى الوفــاة إمنــا ذكــروا أنهــم شــاهدوا دم قليــا برأســه بــل‬\n‫إن الذيــن شــهدوا احلــادث ذكــروا أن املتوفــى كان يعانــي قبــل وفاتــه‬\n‫مــن صــدره و ليــس مــن إصابــة الــرأس كمــا هــو موضــح أعــاه ‪-3‬‬\n‫محضــر االنتقــال واملعاينــة املــدون مبلــف االســتدالل املرفــق لفــة (‪)19‬‬\n‫جميــع مــا ذكــر بهــذا احملضــر ال يوجــد فيــه مــا يــدل علــى تهمــة القتــل‬\n‫‪ -4‬التقريــر الطبــي املرفــق لفــة ‪ 10‬وهــذا التقريــر جــزم بــكل وضــوح أن‬\n‫الوفــاة كانــت بســبب توقــف مفاجــئ بالقلــب والــدورة الدمويــة واجلهــاز‬\n‫التنفســي ممــا يثبــت بــراءة موكلتــي مــن التهمــة الباطلــة املنســوبة إليهــا‬\n‫‪ -5‬تقريــر رقــم‪ ..........‬املرفــق بــأوراق القضيــة هــذا التقريــر ال يوجــد بــه‬\n‫مــا يــدل علــى إثبــات التهمــة ‪ -6‬دعــوى املدعــي وتطابقهــا مــع أقــوال‬\n‫أطــراف القضيــة واملدونــة مبلــف االســتدالل لفــة ‪ 1‬ال يصــح االســتناد‬\n‫علــى أقــوال املدعــي دون بينــات تثبــت صحــة دعــواه يقــول الرســول عليــه‬\n‫الصــاة والســام ‪ -‬البينــة علــى املدعــي ‪ ،‬فلــم يقــدم املدعــي أيــة بينــة‬\n‫ـاء علــى مــا ســبق تقدميــه أعــاه ألتمــس‬   ‫تثبــت صحــة دعــواه خامس ـاً‪ :‬بنـ ً‬\n‫مــن فضيلتكــم احلكــم بــرد دعــوى املدعــي العــام املبنيــة علــى دعــوى‬\n\n\n                                                                                            ‫‪54‬‬\n\f     ‫املدعــي باحلــق اخلــاص طبقــا للمــادة ‪ 4 -‬مرافعــات شــرعية ‪ -‬وألتمــس‬\n     ‫احلكــم ببــراءة موكلتــي مــن التهمــة الباطلــة املنســوبة إليهــا لعــدم ثبــوت‬\n     ‫دعــوى املدعــي العــام واخلــاص) وبعــرض ذلــك علــى املدعــي العــام قــال‬\n     ‫الصحيــح مــا ذكرتــه وقــد ضمنــت الئحــة دعــواي مــا لــدي مــن بينــات‬\n     ‫وقرائــن تثبــت صحــة مــا أدعيــت بــه وليــس لــدي ســواه فجــرى رفع اجللســة‬\n     ‫لدراســة املعاملــة ويف يــوم الســبت املوافــق‪ 1434/05/25‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة (‪ )8:15‬وفيهــا حضــر الطرفــان وقــد جــرى اإلطــاع علــى‬\n     ‫التقريــر الطبــي املرفــق باملعاملــة لفــة (‪ )10‬وتضمــن أن نتيجــة الكشــف‬\n     ‫الطبــي تــرى أن ســبب الوفــاة توقــف مفاجــئ بالقلــب والــدورة الدمويــة‬\n     ‫والتنفســية وصــدر التقريــر بتاريــخ ‪1433/3/26‬ه ـ كمــا جــرى اإلطالع‬\n     ‫علــى إقــرار املدعــى عليهــا املــدون علــى ملــف التحقيــق لفــة (‪ )66‬صحيفــة‬\n     ‫(‪ )5‬وهــذا نصــه (أقــر وأعتــرف أنا‪........../‬ســعودية اجلنســية مبوجــب‬\n     ‫ســجل مدنــي رقــم (‪ )..........‬وأنــا بكامــل قــواي العقليــة واجلســدية‬\n     ‫املعتبــرة شــرع ًا مــن غيــر ضغــط أو إكــراه بأنــه بتاريــخ ‪1433/3/26‬ه ـ‬\n     ‫بعــد صــاة العشــاء حضــرت لغرفــة أختــي ‪..........‬التــي تقطــن معــي يف‬\n     ‫نفــس املنــزل ووجــدت أخــي ‪..........‬لديهــا بالغرفــة وحيــث أن املذكــور‬\n     ‫بينــي وبينــه مشــاكل ســابقة حيــث أنــه يتلفــظ علـ َـي وال يقــوم علــى‬\n     ‫خدمتــي وحصــل بيننــا نقــاش حــاد تطــور الشــتباك باأليدي وقــام بضربي‬\n     ‫وشــدي مــن شــعري ويف حلظــة وقعــت يــدي علــى ســطل حديــدي قمــت‬\n     ‫بجذبــه وضربــت ‪..........‬بــه علــى رأســه وفرقــت بيننــا أختــي ‪..........‬‬\n     ‫وشــاهدت قطــرات مــن الــدم تخــرج مــن مــكان اإلصابــة التــي فأتصــل‬\n     ‫هــو علــى الدوريــات األمنيــة وحضــروا إلــى املوقــع وحــل االشــكال بيننــا‬\n     ‫ا ‪..........‬‬\n                ‫وقررنــا التنــازل عــن بعضنــا البعــض بنفــس املوقــع ومكــث قليـ ً‬\n\n\n‫‪55‬‬\n\f‫مــن ثــم غــادر املنــزل يقــود ســيارته وبرفقتــه أختــي ‪..........‬وبعــد منتصــف‬\n‫الليــل اتصلــت علـ َـي أختــي صبــاح وســألني عــن املشــكلة وقالــت أن‬\n‫‪..........‬مت نقلــه للمستشــفى فاقــد ًا للوعــي ولــم أقتنــع مبــا ذكــرت فقمــت‬\n‫بــدوري باالتصــال علــى أختــي ‪..........‬التــي قامــت بالدعاء علـ َـي وأخبرتني‬\n‫أن ‪..........‬أنتقــل إلــى رحمــة اهلل وقمــت بالذهــاب إلى املستشــفى للتأكد‬\n‫مــن الواقــع ولــم أمتكــن مــن شــاهدته وأبلغــت بأنــه يف ثالجــة املوتــى هــذا‬\n‫مــا لــدي وأذنــت ملــن يشــهد واهلل خيــر الشــاهدين) وبعرضــه علــى املدعــى‬\n‫عليــه وكالــة قــال نعــم صــدر هــذا اإلقــرار مــن موكلتــي كمــا جــرى‬\n‫االطــاع علــى اســتجواب شــقيقة املتــويف وهــي ‪..........‬املــدون علــى‬\n‫الصحيفــة (‪ )13‬مــن ملــف التحقيــق لفــة (‪ )1‬وتضمــن أن املتــويف كان‬\n‫يعانــي مــن صــدره وبعــد ضربــه مــن قبــل املدعــى عليهــا أتصــل علــى‬\n‫الشــرطة ولــم يرضــى أن ينقــل إلــى املستشــفى والــدم الــذي خــرج منــه‬\n‫كان قليــل جــد ًا وخــرج يقــود ســيارته كمــا جــرى االطــاع علــى‬\n‫اســتجواب ‪ ..........‬علــى الصحيفــة (‪ )13‬مــن ملــف التحقيــق لفــة (‪)14‬‬\n‫و‪..........‬علــى الصحيفــة (‪ )9‬مــن ذات امللــف وتضمــن أن املتــويف كان‬\n‫يعانــي مــن ألــم يف صــدره كمــا أفــاد ‪ ..........‬يف الصحيفــة (‪ )15‬أن‬\n‫املتــويف كان يعانــي مــن ألــم يف صــدره ويســتفرغ دم وكان يعانــي مــن‬\n‫األلــم يف صــدره مــن خمــس ســنوات تقريبـ ًا وكان يتحــدث معــه وأعطــاه‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n                                            ‫مبلغـ ًا مــن املــال لشــراء عشــاء وبنـ ً‬\n‫ومــا تضمنــه التقريــر الطبــي املذكــور أعــاه ومــا جــاء يف اســتجوابات‬\n‫أشــقاء وأقــارب املتــويف مــن أنــه كان يعانــي مــن مــرض يف صــدره وأن‬\n‫ا فلــم يثبــت لــدي قتــل املدعــى‬ ‫الــدم الــذي نــزف معــه املتــويف كان قليـ ً‬\n‫عليهــا ألخيهــا ‪..........‬وحكمــت بصــرف النظــر عــن طلــب املدعــي العــام‬\n\n\n                                                                                          ‫‪56‬‬\n\f     ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه وكالــة قناعتــه‬\n     ‫باحلكــم كمــا قــرر املدعــي العــام اإلعتــراض بالئحــة وبــاهلل التوفيــق ‪،‬‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n     ‫‪ 1434/05/25‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى مــا ال نبــي‬\n                                                   ‫بعده ‪ ،‬وبعد ‪:‬ـ فقد جرى منا نحن‬\n     ‫قضــاة الدائــرة اجلزائيــة الثانيــة يف محكمــة االســتئناف مبنطقــة مكــة‬\n                                                                    ‫املكرمــة اإلطــاع‬\n     ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة‬\n     ‫املكرمــة املســاعد الشــيخ ‪........../‬برقــم ‪ 34108241‬وتاريــخ‬\n                                                                       ‫‪1434 /7 /9‬ه ـ‬\n     ‫املرفــق بهــا القــرار الشــرعي رقــم ‪ 34223913‬وتاريــخ ‪1434/5/27‬ه ـ‬\n     ‫الصــادر مــن فضيلتــه املتضمــن دعــوى املدعــي العــام ضــد املــرأة‪........../‬‬\n     ‫املتهمــة يف قضيــة قتــل احملكــوم فيــه مبــادون باطنــه ‪ .‬وبدراســة‬\n     ‫القراروصـ ـ ــورة ضبطــه والئحتــه االعتراضيــة تقررباالكثريــة املوافقــة‬\n     ‫علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                      ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪57‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":42,"source_page_end":57,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"330249f822c347f0fb83dc421f4bb00850c17eac4e8f242158e752b24bc6872f","normalized_text_hash":"32dd5d515ff532024c86e00c0323a67974c824ec3e2f9b0094090ad92dfb02a3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p42-34223913"},{"id":"7e64f08d-ebe6-503d-ad6b-aa315c821fcc","document_type":"judgment","category":"judicial","subcategory":"general","title":"-1األمر السامي رقم 10711يف 1393/5/2ه وقرار مجلس القضاء األعلى بهيئته الدائمة برقم 3/51يف 1409/3/6ه املؤيد باألمر السامي رقم /1197/4م يف 1409/6/2ه املبلغ بالتعميم /8ت 95/يف 1409/7/25ه بشأن تطبيق اإلرادة امللكية على قاتل العمد وشبه العمد إذا تنازل أولياء الدم عن القصاص (التصنيف املوضوعي","document_number":"3460109","case_number":"3466575","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة صك بإثبات تنازل أولياء الدم عن القصاص","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/11","year":"1434","subject":"-1األمر السامي رقم 10711يف 1393/5/2ه وقرار مجلس القضاء األعلى بهيئته الدائمة برقم 3/51يف 1409/3/6ه املؤيد باألمر السامي رقم /1197/4م يف 1409/6/2ه املبلغ بالتعميم /8ت 95/يف 1409/7/25ه بشأن تطبيق اإلرادة امللكية على قاتل العمد وشبه العمد إذا تنازل أولياء الدم عن القصاص (التصنيف املوضوعي","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3460109 :‬تاريخه‪1434/3/11 :‬هـ‬\n                    ‫رقم الدعوى‪3466575:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34197846‬تاريخه‪1434/4/24 :‬هـ‬\n\n\n‫قتــل ‪ ،‬قتــل عمــد ‪ ،‬اســتخدام ســاح نــاري ‪ ،‬إقــرار املدعــى عليــه ‪ ،‬تنــازل‬\n‫عــن حــق خــاص ‪ ،‬تقريــر طبــي نفســي‪ ،‬تقريــر طبــي شــرعي ‪ ،‬تقريــر أدلــة‬\n                     ‫جنائيــة‪ ،‬ثبــوت إدانــة‪ ،‬عقوبــة عائــدة للجهــة املختصــة‪.‬‬\n\n\n\n\n‫‪ -1‬األمــر الســامي رقــم ‪ 10711‬يف ‪1393/5/2‬ه ـ وقــرار مجلــس القضــاء‬\n‫األعلــى بهيئتــه الدائمــة برقــم‪ 3/51‬يف ‪1409/3/6‬ه ـ املؤيــد باألمــر‬\n‫الســامي رقــم ‪/1197/4‬م يف ‪1409/6/2‬ه ـ املبلــغ بالتعميــم ‪/8‬ت‪ 95/‬يف‬\n‫‪1409/7/25‬ه ـ بشــأن تطبيــق اإلرادة امللكيــة علــى قاتــل العمــد وشــبه‬\n‫العمــد إذا تنــازل أوليــاء الــدم عــن القصــاص (التصنيــف املوضوعــي‬\n                                           ‫لتعاميــم وزارة العــدل ‪.)782/1‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن قبــل واالدعــاء العــام للمدعــى عليــه لقيامه بقتل‬\n‫شــقيقته عمــدا وعدوانــا وطلــب إثبات ما أســند إليــه وإفهامه بأن عقوبته‬\n‫لــدى اجلهــة املختصــة وفــق اإلرادة امللكيــة ‪ -‬حيــث تلقــت الشــرطة بالغــا‬\n‫مــن الهــال األحمــر بتعــرض إمرأة لطلقات ناريــة أدت لوفاتها ‪ -‬ضبطت‬\n‫إفــادة املجنــي عليهــا قبــل وفاتهــا وحاصلــه قيــام شــقيقها‪ -‬املدعــى عليــه‪-‬‬\n‫بإطــاق النــار عليهــا وهــي يف غرفتهــا بشــكل مفاجــئ وال تعلــم الدافــع‬\n\n                                                                                     ‫‪58‬‬\n\f     ‫غيــر أنــه يعانــي مــن مــرض نفســي وشــكوك وضــاالت ‪ ،‬أقــر املدعــى‬\n     ‫عليــه حتقيقــا بقتلــه شــقيقته ألنــه ســمع مــن أحــد أقاربــه بــأن لشــقيقته‬\n     ‫عالقــة مــع أحــد الرجــال ‪ ،‬أنكــر القريــب مــا نســبه إليــه املدعــى عليــه‬\n     ‫ومبواجهتــه باملدعــى عليــه تراجــع وقــرر بأنهــا كانــت مجــرد شــكوك‬\n     ‫لديــه ولــم يســمع منــه ذلــك ‪ ،‬صــدر مــن احملكمــة العامــة صــك بإثبــات‬\n     ‫تنــازل أوليــاء الــدم عــن القصــاص‪ ،‬صــدر تقريــر طبــي مــن مستشــفى‬\n     ‫الصحــة النفســية بأنــه جــرى تشــخيص حالتــه نوبــات صــرع كبــرى وأنــه‬\n     ‫يعانــي مــن اضطــراب يف التفكيــر وشــكوك وضــاالت غيــر مبــررة‬\n     ‫يف ســلوك شــقيقته كمــا صــدر تقريــر آخــر بأنــه ونظــرا ملــا يعانيــه‬\n     ‫مــن صــرع مصحــوب بأعــراض ذهنيــة مصحوبــة مبعتقــدات خاطئــة‬\n     ‫وســوء احلكــم علــى األمــور فــإن ذلــك يخفــف عنــه املســؤولية اجلنائيــة‬\n     ‫‪ ،‬بعــرض الدعــوى علــى املدعــى عليــه أقــر بقيامــه بقتــل شــقيقته ودفــع‬\n     ‫بأنــه مريــض نفســي ويعانــي مــن صــرع وقــد انتابــه حالــة نفســية شــديدة‬\n     ‫قــام علــى إثرهــا بالدخــول علــى أختــه يف غرفتهــا وإطــاق النــار عليهــا‬\n     ‫مــن مســدس وتوفيــت بعــد ذلــك ‪ ،‬جــرى االطــاع علــى شــهادة الوفــاة‬\n     ‫املتضمنــة ثبــوت وفــاة شــقيقته ‪ ،‬عليــه فقــد قــررت احملكمــة ثبــوت قيــام‬\n     ‫املدعــى عليــه بقتــل شــقيقته عمــدا وعدوانــا وإفهامــه بــأن عقوبتــه عائــدة‬\n     ‫للجهــة املختصــة ‪ ،‬قــرر املدعــى عليــه القناعــة بينمــا قــرر املدعــي العــام‬\n         ‫االعتــراض بــدون الئحــة ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪59‬‬\n\f‫اجلزائيــة‬\n   ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة‬\n‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة االحســاء برقــم وتاريــخ ‪ 1434/02/10‬ه ـ املقيدة‬\n‫باحملكمــة برقــم وتاريــخ ‪ 1434/02/10‬ه ـ ففــي يــوم األربعــاء‬\n‫املوافــق‪ 1434/03/04‬ه ـ افتتحــت اجللســة الســاعة ‪ 12 : 00‬وفيهــا‬\n‫حضــر املدعــي ‪..........‬وادعــى ضــد احلاضــر معــه ‪..........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪..........‬قائــا يف دعــواه إنــه بتاريــخ‬\n‫‪1433/2/15‬ه ـ تلقــت غرفــة عمليــات شــرطة محافظــة األحســاء بالغـ ًا‬\n‫مــن الهــال األحمــر الســعودي عــن قيامهــم بنقــل املــرأة تدعــى‪.......... /‬‬\n‫إلــى مستشــفى امللــك فهــد بالهفــوف علــى إثــر تعرضهــا لإلصابــة بعــدة‬\n‫طلقــات ناريــة أثنــاء وجودهــا مبنزلهــا وباالنتقــال واملعاينــة جلســم املجنــي‬\n‫عليهــا اتضــح وجــود عــدد تســع فتحــات بعضهــا دخــول وبعضهــا اآلخــر‬\n‫خــروج فيمــا أظهــرت األشــعة التــي اتخــذت علــى جســمها وجــود طلقتــن‬\n‫مســتقرتني بها أحدهما يف الظهر واألخرى بالركبة اليســرى ومبعاينة‬\n‫املنــزل محــل ارتــكاب اجلرميــة اتضــح انــه منــزل حديــث البنــاء يقــع يف‬\n‫حــي ‪..........‬ومبعاينــة مســرح احلــادث اتضــح أنهــا غرفــة مبســاحة (‪4,4‬م)‬\n‫حتتــوي علــى ســرير نــوم مفــرد ودوالب صغيــر وطاولــة كمبيوتــر وطاولة‬\n‫أخــرى عليهــا جهــاز تلفزيــون وقــد تبــن أن اجلــدار للجهــة الشــرقية‬\n‫صناعــي (جبــس بــورد) فيمــا شــوهد علــى ارتفــاع (‪120‬ســم) مــن اجلــدار‬\n‫عــدد أربــع فتحــات دخــول متقاربــة ملقاذيــف ناريــة جميعهــا نافــذة للجهــة‬\n‫األخــرى مــن اجلــدار والتــي مت تتبعهــا واتضــح اســتقرارها يف دوالب‬\n\n                                                                                      ‫‪60‬‬\n\f     ‫مالبــس مــن الغرفــة املجــاورة يف الوقــت الــذي شــوهد مقذوفــن ناريــن‬\n     ‫علــى أرضيــة الغرفــة محــل اإلصابــة وأيض ـ ًا بقعتــي دمــاء صغيــرة علــى‬\n     ‫الســجادة حيــث قــام ذوي املجنــي عليهــا بتســليم جهــة التحقيــق ســاح‬\n     ‫نــاري مــن نــوع مســدس ‪ ....‬ماركــة ‪ ....‬عيــار (‪ )22‬يحمــل الرقــم (‪)..........‬‬\n     ‫يتســع إلــى عــدد تســع طلقــات ناريــة وبفحصــه مبدئي ـ ًا اتضــح بــأن‬\n     ‫اســطوانة الســاح حتتــوي علــى عــدد تســعة ظــروف ناريــة فارغــة وتبــن‬\n     ‫أن الفاعــل املدعــى عليــه وهــو شــقيق املجنــي عليهــا وبتفتيــش غرفــة‬\n     ‫املدعــى عليــه عثــر علــى ســاح نــاري آخــر نــوع ‪ ....‬عيــار (‪ ).....‬يحمــل رقــم‬\n     ‫(‪ )..........‬مــع خزنــن بــدون طلقــات ناريــة (فــرزت لــه أوراق مســتقلة‬\n     ‫للســاح) وبضبــط إفــادة املجنــي عليهــا قبــل وفاتهــا أفــادت أنــه بعــد‬\n     ‫منتصــف ليــل يــوم الواقعــة كانــت جالســة مبفردهــا يف غرفتهــا مبنــزل‬\n     ‫والدهــا يف حــي ‪..........‬وقــد حضــر مــن خــارج املنــزل شــقيقها املدعــى‬\n     ‫عليــه الــذي دخــل عليهــا يف غرفتهــا وقــام دون ســابق نقــاش معهــا بإشــهار‬\n     ‫ســاح نــاري اجتاههــا ومــن ثــم مباشــرتها بإطــاق عــدة طلقــات ناريــة‬\n     ‫اجتاههــا ممــا أدى إلــى إصابتهــا يف العمــود الفقــرة والركبــة اليســرى‬\n     ‫والصــدر وقــد مت مناقشــتها عــن أســباب إقــدام شــقيقها بإطــاق النــار‬\n     ‫عليهــا وذكــرت بأنــه ال يوجــد أيــة ســوى أن شــقيقها يعانــي مــن مــرض‬\n     ‫نفســي واضطرابــات يف التفكيــر وشــكوك وضــاالت غيــر مبــررة‬\n     ‫ويتلقــى العــاج منــذ فتــرة طويلــة يف مستشــفى الصحــة النفســية‬\n     ‫باألحســاء والــذي توفيــت فيمــا بعــد نتيجــة اإلصابــة التــي حلقــت بهــا‬\n     ‫وباســتجواب املدعــى عليــه أقــر أنــه يف مســاء يــوم الواقعــة اجتــه برفــق‬\n     ‫خالــه‪.......... /‬واملدعــو‪.......... /‬إلــى محافظــة ‪ ...‬حلضــور عــزاء أحــد‬\n     ‫أقاربــه ويف طريــق عودتــه إلــى محافظــة األحســاء اســتمع إلــى نقــاش‬\n\n\n‫‪61‬‬\n\f‫كان يــدور بــن خالــه املذكــور ‪..........‬حيــث صــرح خالــه دخــول شــخص‬\n‫يدعــى ‪..........‬علــى شــقيقته ‪..........‬يف املنــزل وبعــد وصولهــم إلى محافظة‬\n‫األحســاء دخــل إلــى منزلــه ثــم وقــف علــى بــاب غرفــة شــقيقاته وقــام‬\n‫ينظــر اليهــن وقــد كــن نائمــات جميعهــن يف الوقــت الــذي اجتــه إلــى‬\n‫غرفتــه بالــدور العلــوي مــن املنــزل وأخــذ ســاحه النــاري مــن نوع مســدس‬\n‫‪ ....‬ماركــة ‪ .....‬عيــار (‪ )22‬يحمــل الرقــم (‪ )..........‬ومــن ثــم نــزل مباشــرة‬\n‫إلــى الغرفــة اخلاصــة بشــقيقته‪.......... /‬وقــام بالدخــول عليهــا ومباغتتهــا‬\n‫وذلــك بإطــاق عــدة أعيــرة ناريــة اجتاههــا ممــا أدى إلــى إصابتهــا بعــدة‬\n‫طلقــات نتــج عنــه ســقوطها علــى األرض وذلــك علــى خلفيــة مــا صــرح بــه‬\n‫خالــه يف الســيارة حيــث دخــول شــخص عليهــا وبضبــط إفــادة ‪ ....‬املدعــى‬\n‫عليــه‪.......... /‬مــا أورده املدعــى عليــه مــن حيــث تصريحــه لــه مبعلومــات‬\n‫مفادهــا دخــول شــخص يدعــى‪.......... /‬علــى املجنــي عليهــا والــذي نفــى‬\n‫تلــك املعلومــة وذكــر أنــه يف الليلــة التــي حدثــت فيهــا الواقعــة كان‬\n‫واملدعــى عليــه وقريبــه ‪..........‬قادمــن مــن محافظــة ‪ ...‬بعــد حضورهــم‬\n‫وفــاة أحــد أبنــاء جماعتهــم ويف طريــق عودتهــم لإلحســاء جــاءت ســيرة‬\n‫املتوفــى‪.......... /‬مــن بــاب الذكــرى فقــط ثــم فوجــئ عقــب وصولهــم‬\n‫لإلحســاء بإقــدام املدعــى عليــه علــى جرميتــه جتــاه املجني عليهــا وبضبط‬\n‫إفــادة املرافــق ‪.......... /‬لهــم يف الســيارة حــول مــا ورد مــن حديــث يف‬\n‫الســيارة أثنــاء ركوبــه معهــم املدعــى عليــه وحيــث نفــى ذلــك وكان يف‬\n‫الليلــة التــي حدثــت فيهــا الواقعــة هــو واجلانــي وخاله قادمــن من محافظة‬\n‫اخلــرج بعــد حضورهــم عــزاء أحــد أبنــاء جماعتهــم ويف طريقهم لإلحســاء‬\n‫جــاءت ســيرة املتوفى‪..........‬مــن بــاب الذكــرى فقــط ثــم فوجــئ عقــب‬\n‫وصولهــم لإلحســاء بإقــدام املدعــى عليــه علــى جرميتــه جتــاه املجنــي‬\n\n\n                                                                                       ‫‪62‬‬\n\f     ‫عليهــا فيمــا ذكــر أن املدعــى عليــه يعانــي مــن مــرض نفســي واضطــراب‬\n     ‫يف التفكيــر وشــكوك جتــاه شــقيقته وبضبــط والــدة املجنــي عليهــا‬\n     ‫وشــقيقاتها‪........../‬والذي أفــادوا جميعـ ًا بأنــه يف حوالــي الســاعة الثانيــة‬\n     ‫عشــر صباحـ ًا يف اليــوم االثنــن املوافــق ‪1433/2/15‬ه ـ حضــر املدعــو‪/‬‬\n     ‫‪..........‬الــذي كان يف زيــارة إلــى محافظــة ‪ ....‬برفــق خالهــم ألداء واجــب‬\n     ‫العــزاء وبعــد دخولــه املنــزل قــام بالســام عليهــم ثــم صعــد إلــى غرفــة‬\n     ‫نومــه وبعــد حلظــات نــزل وبيــده منشــفه ودخــل دورة امليــاه ثــم خــرج وصعــد‬\n     ‫مــرة أخــرى إلــى غرفتــه وعــاد متوجه ـ ًا إلــى غرفــة شــقيقته‪.......... /‬ثــم‬\n     ‫ســمعن صــوت إطــاق النــار وخــرج مباشــرة مــن الغرفــة وهــو يكبــر (اهلل‬\n     ‫أكبــر اهلل أكبــر) وبيــده مســدس وقــام بالنظــر إليهــم ورمــى الســاح‬\n     ‫يف مــوزع املنــزل ويف حلــال اجتهــن إلــى غرفــة املجنــي عليهــا وشــاهدا‬\n     ‫الدمــاء يف األرض وعلــى مالبســها يف الوقــت الــذي أكــدن عــدم وجــود‬\n     ‫أي خــاف بــن اجلانــي واملجنــي عليهــا وأن اجلانــي يعانــي مــن مــرض‬\n     ‫نفســي واضطرابــات يف التفكيــر والشــكوك يف اآلخريــن وبضبــط‬\n     ‫إفــادة زوج شــقيقته‪ )40(.......... /‬عام ـ ًا ســعودي اجلنســية ســجل مدنــي‬\n     ‫رقــم (‪ )..........‬متعلــم موظــف حكومــي يســكن محافظــة اإلحســاء‬\n     ‫والــذي ذكــر املدعــى عليــه أنــه قــام بإهدائــه الســاح املســتخدم يف‬\n     ‫اجلرميــة ومبناقشــته عــن مصــدر الســاح املســتخدم يف القضيــة أقــر بأنــه‬\n     ‫قــام بإعطائــه لشــقيق زوجتــه املدعــو‪.......... /‬منذ عشــر ســنوات كهدية‬\n     ‫وقــد وعــده بــأن يقــوم بتصريــح الســاح باســمه إال أنــه لــم يفعــل وبعــرض‬\n     ‫الســاح تعــرف عليــه ومبواجهــة املدعــى عليــه ‪..........‬وخالــه املدعــو‬\n     ‫‪ ..........‬وابــن عمــه ‪..........‬ملعرفــة صحــة مــا ادعــى بــه املدعــى عليــه مــن‬\n     ‫ســماعه قولهــم أن شــقيقته املجنــي عليهــا تربطهــا عالقــة مــع املدعــو‬\n\n‫‪63‬‬\n\f‫‪..........‬وقــد أكــدا عــدم صحــة مــاورد علــى لســانة ومبواجهتــه بهــم‬\n‫تراجــع عــن اقوالــه وأثــار أنــه لــم يســمع بذلــك منهــم وإمنــا بنــاء علــى‬\n‫شــكوك لديــه وفيمــا بعــد ورد خطــاب رئيــس احملكمــة العامــة‬\n‫باألحســاء رقــم (‪)33/1423663‬بتاريــخ ‪1433/09/19‬ه ـ واملتضمــن‬\n‫إثبــات تنــازل أوليــاء الــدم عــن القصــاص وصــدر بحــق املدعــى عليــه‬\n‫التقريــر الطبــي مــن مستشــفى الصحــة النفســية مبحافظــة األحســاء‬\n‫برقــم ‪ ..........‬وتاريــخ ‪1433/02/22‬ه ـ املتضمــن مراجعــة املدعــى عليــه‬\n‫للمستشــفى بتاريــخ ‪1429/09/15‬ه ـ ومت تشــخيص حالتــه نوبــات صــرع‬\n‫كبــرى ومت حتويلــة للمتابعــة بعيــادة األمــراض العصبيــة فيمــا أشــير‬\n‫بأنــه منــوم حالي ـ ًا طرفهــم منــذ تاريــخ ‪1433/03/15‬ه ـ وأتضــح بعــد‬\n‫الكشــف أنــه يعانــي مــن اضطــراب التفكيــر وشــكوك وضــاالت‬\n‫غيــر مبــرره يف ســلوك شــقيقته (املجنــي عليهــا) وانــه البــد مــن عرضــه‬\n‫علــى اللجنــة الطبيــة الشــرعية وصــدر التقريــر الطبــي رقــم ‪..........‬بتاريــخ‬\n‫‪1433/07/14‬ه ـ مــن مستشــفى الصحــة النفســية بالطائــف والــذي‬\n‫يتضمــن أن اللجنــة تــرى نظــر ًا ملــا يعانيــة املذكــور مــن مــرض الصــراع‬\n‫واملصحــوب بأعــراض ذهنيــة والتــي تشــمل املعتقــدات املرضيــة اخلاطئــة‬\n‫وســوء احلكــم علــى األمــور فــإن ذلــك يخفــف مــن مســؤليته اجلانبيــه عمــا‬\n‫قــام بــه كــم اثبــت التقريــر رقــم (‪/12‬طــب شــرعي‪1433/‬هـ) املتضمــن‬\n‫أنــه بفحــص مالبــس املجنــي عليهــا تبــن وجــود عــدة ثمانيــة ثقــوب يف‬\n‫القميــص دائريــة الشــكل علــى الكتــف األميــن مــن اجلهــة األماميــة‬\n‫واخللفيــة مــع وجــود ثقــب أســفل البــدن اخللفــي األيســر أيضـ ًا ثقــب دائــري‬\n‫الشــكل يف الشــلحة يقــع اســفل يســار البــدن اخللفــي وكمــا ورد خطــاب‬\n‫مستشــفى امللــك فهــد ب الهفــوف رقــم (‪ ..........‬يف ‪1433/02/21‬ه ـ‬\n\n\n                                                                                      ‫‪64‬‬\n\f     ‫املتضمــن بــأن املصابــة ‪..........‬واملنومــة لديهــم انتقلــت الــى رحمــة اهلل‬\n     ‫نتيجــة اإلصابــات التــي حلقــت بهــا وصــدر بحقهــا شــهادة الوفــاة (‪)..........‬‬\n     ‫مــن األحــوال املدنيــة ورد التقريــر الطبــي الصــادر مــن مستشــفى امللــك‬\n     ‫فهــد بالهفــوف رقــم(‪ )..........‬يف ‪1433/03/23‬ه ـ املتضمــن اآلتــي او ًال‬\n     ‫وجــد باجلثــة عــدد ثمــان طلقــات ناريــة غيــر نافــذة بالظهــر والركبــة‬\n     ‫اليســرى والســتة الباقيــة فتحــات دخــول وخــروج ملرامــي ناريــة مفــردة‬\n     ‫تعــذر حتديــد ماهيــة الفتحــات مــن حيــث الدخــول واخلــروج نتيجــة تغيــر‬\n     ‫معالــم الفتحــات بإجــراءات اإلســعاف واملعاجلــة ومــرور الوقــت وقــد‬\n     ‫احدثــت هــذه اإلصابــات أذيــات موضعيــة بالنســبة لألطــراف مــع كســر‬\n     ‫بالعمــود الفقــري الفقــرة الظهريــة الثامنــة وإصابــة بالرئــة اليمنــى‬\n     ‫بالنســبة لطلقــة الظهــر حيــث اســتقر جــزء منهــا بالرئــة اليمنــى وجــدار‬\n     ‫الصــدر األميــن وهــذه األصابــات مبجملهــا ناجمــة عــن األصابــة بطلــق‬\n     ‫نــاري مفــرد ويرجــع لتحديــد فتحــات الدخــول واخلــروج بدقــة الــى تقريــر‬\n     ‫األدلــة اجلنائيــة املتعلــق بفحــص املالبــس مــع وجــود خثــرات بالوريــد‬\n     ‫الفخــذي األيســر وأوردة الســاق اليســرى ثاني ـ ًا جــاءت نتيجــة فحــص‬\n     ‫مختبــر األنســجة مبستشــفى امللــك فهــد بالهفــوف تفيــد ( بعــدم وجــود‬\n     ‫ال مــن الغــدة النخاميــة واملــخ واملخيــخ وجــذع املــخ‬      ‫تغيــرات يف ك ً‬\n     ‫والكليتــن واملبيضــن والرحــم والشــرايني األكليلــة وامللتــف األميــن‬\n     ‫واأليســر مــع وجــود تضيــق بنســبة (‪ )%50‬بالنــازل األمامــي مــع وجــود‬\n     ‫تنخــر جلــدي مــع رد فعــل حيــوي يتوافــق مــع اصابــة حيويــة وعــدم وجــود‬\n     ‫عالمــة البــودرة يف الفتحــة رقــم (‪ )4-1-2-8-6-5-9‬مــع وجــود عالمــة‬\n     ‫البــودرة يف الفتحــة رقــم (‪ )3‬فقــط مــع وجــود خثــرات متعضيــة يف كل‬\n     ‫مــن الوريــد احلرقفــي األيســر األصلــي والوريــد الشــظوي العميــق والوريــد‬\n\n\n‫‪65‬‬\n\f‫الفخــذي األيســر ثالثـ ًا الوفــاة ســببها اإلصابــات الناريــة ومــا أحدثتــه مــن‬\n‫أذيــات ومضاعفــات ومــا رافــق احلالــة مــن هبــوط بالــدورة الدمويــة‬\n‫والتنفســية‪ 0‬التقاريــر املخبريــة ‪ -1‬وصدر التقريــر الرقم ‪..........‬املتضمن‬\n‫بالكشــف عــن التلوثــات الدمويــة ألحــد املقاذيــف النارية جــاءت نتيجتها‬\n‫(إيجابــي) مــع فصيلــة دم املجنــي عليهــا ‪ -2‬وصــدر التقريــر الرقــم ‪..........‬‬\n‫املتضمــن بالكشــف عــن التلوثــات الدمويــة للعينــات املرفوعــة مــن‬\n‫مســرح احلــادث جــاءت نتيجتهــا إيجابيــة للدمــاء اآلدميــة مــع فصيلــة دم‬\n‫املجنــي عليهــا ‪ -3‬وصــدر التقريــر الرقــم ‪..........‬املتضمــن بالكشــف عــن‬\n‫التلوثــات الدمويــة ملالبــس املجنــي عليهــا جــاءت نتيجــة بعضهــا إيجابيــة‬\n‫للدمــاء األدميــة مــع فصيلــة دم املجنــي عليهــا ‪ 0‬وقــد اســفر التحقيــق معــه‬\n‫عــن توجيــه األتهــام لــه باإلقــدام علــى قتــل شــقيقته عمــد ًا وعدوانـ ًا وذلــك‬\n‫بإطــاق اعيــرة ناريــة عليهــا مباشــرة مــن ســاح مســدس ‪ .....‬ماركة(‪)....‬‬\n‫عيار(‪).....‬ممــا أدى إلــى إصابتهــا بخمســة منهــا أدى الــى إصابتهــا ومــن‬\n‫ثــم نتــج عــن ذلــك وفاتهــا وذلــك لألدلــة والقرائــن التاليــة‪ -1‬إقــراره مبــا‬\n‫نــوه عنــه املــدون علــى الصفحــة رقــم (‪ )15-14‬مــن ملــف التحقيــق املرفــق‬\n‫لفــة(‪ -2 )22‬ماأثبتــه محضــر املعاينــة املتضمــن إصابــة املذكــوره بعــدد‬\n‫خمــس طلقــات ناريــة خلــف تســع فتحــات بعضهــا فتحــات دخــول وبعضها‬\n‫فتحــات خــروج مبواضــع مختلفــة مــن جســدها وفــق ماجــاء بالتقريــر‬\n‫األمنــي املرفــق لفــة(‪ -3 )8-6‬مــا أثبتــه محضــر معاينــة الغرفــة محــل‬\n‫اطــاق النــار املتضمــن مشــاهدة عــدد أربعــة فتحــات دخــول متقاربــة‬\n‫ملقاذيــف ناريــة يف اجلــدار الشــرقي املكــون مــن لوائــح جبســية جميعهــا‬\n‫نافــذه والتــي تتبعهــا واتضــح اســتقرارها يف دوالب بالغرفــة املجــاورة‬\n‫وكــذا العثــور علــى مقذوفــن ناريــن يف ارضيــة الغرفــة وأيضـ ًا بقعتــن‬\n\n\n                                                                                         ‫‪66‬‬\n\f     ‫دمــاء صغيــرة علــى الســجادة ممــا يؤكــد تعــرض املجنــي عليهــا لإلصابة‬\n     ‫أثنــاء تواجدهــا يف غرفتهــا ‪ -4‬مــاورد بأقــوال املجنــي عليهــا املتضمنــه‬\n     ‫قيــام شــقيقها ‪..........‬بإطــاق عــدة طلقــات ناريــة جتاههــا أثنــاء تواجدهــا‬\n     ‫يف غرفتهــا مبنزلهــم ‪ -5‬مبــا جــاء بأقــوال شــقيق والــدة املدعــى عليــه‬\n     ‫‪..........‬املتضمــن بأنــه وقريبــه ‪ ..........‬كانــا يتحدثــان عــن املدعــو ‪..........‬‬\n     ‫املتوفــى قبــل نحــو عشــر ســنوات مــن بــاب الذكــرى فقــط وأن املدعــى‬\n     ‫عليــه املذكــور أقــدم علــى جرميتــه جتــاه شــقيقته نتيجــة معاناتــه مــع‬\n     ‫مــرض نفســي املــدون علــى صفحــات ملــف التحقيــق املرفــق لفــة(‪)10-9‬‬\n     ‫‪ -6‬مــا أثبتــه محضــر ضبــط الســاح النــاري املســتخدم يف القتــل وهــو‬\n     ‫مــن نــوع مســدس ‪ .....‬ماركــة ‪ ....‬عيــار(‪ ).....‬يحمــل الرقــم (‪ )..........‬يف‬\n     ‫منــزل املدعــى عليــه الــذي اتضــح بالفحص املبدئي أن اســطوانة الســاح‬\n     ‫حتتــوي علــى عــدد تســعة ظــروف ناريــه فارغــة ‪ -7‬مــا أثبتــه التقاريــر‬\n     ‫احليويــة والفنيــة املرفــق علــى الصفحــة رقــم (‪ )200-195‬لفــة رقم (‪-130‬‬\n     ‫‪ )132‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق‬\n     ‫جنائيــة مســجلة وحيــث أن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليته‬\n     ‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند‬\n     ‫إليــه وإثبــات بصفــة القتــل وإفهامــه بــأن عقابــه وفق ـ ًا لــإرادة امللكيــة‬\n     ‫عائــد ًا للجهــة املختصــة علمـ ًا أنــه صــدر القــرار الشــرعي مــن احملكمــة‬\n     ‫العامــة مبحافظــة األحســاء رقــم (‪ )33/407434‬وتاريــخ ‪1433/9/11‬هـ‬\n     ‫املتضمــن تنــازل اوليــاء الــدم عــن حقهــم يف القصــاص هــذه دعــواي‬\n     ‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي‬\n     ‫العــام يف دعــواه مــن قيامــي بإطــاق النــار علــى شــقيقتي ‪..........‬وقتلهــا‬\n     ‫صحيــح وقــد حصــل يف هــذا األمــر لكونــي مريــض نفســي وأعانــي مــن‬\n\n\n‫‪67‬‬\n\f‫الصــرع وقــد جاءتنــي حالــة نفســيه شــديدة فقمــت بالدخــول علــى أختــي‬\n‫املذكــورة يف غرفتهــا وأطلقــت عليهــا النــار مــن املســدس ثــم حملــت إلــى‬\n‫املستشــفى وتوفيــت بعــد ذلــك هــذه إجابتــي بعــد ذلــك جــرى الرجــوع إلــى‬\n‫شــهادة الوفــاة لشــقيقة املدعــى عليــه علــى لفــة ‪ 46‬مــن املعاملــة وفيهــا‬\n‫أثبــات وفــاة شــقيقة ‪..........‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وإقــرار املدعــى عليــه بقيامــه بإطــاق النــار علــى شــقيقته ‪..........‬ووفاتهــا‬\n‫بعــد ذلــك وبنــاء علــى شــهادة الوفــاة املذكــورة أعــاه بنــاء علــى ذلــك‬\n‫كلــه فقــد ثبــت لــدي بــان املدعــى عليــه قــد قتــل شــقيقته املذكــورة‬\n‫عمــد ًا عدوان ـ ًا وأفهمتــه بــأن عقابــه علــى ذلــك وفــق اإلرادة امللكيــة‬\n‫عائــده للجهــة املختصــة وبعــرض ذلــك عليــه وعلــى املدعــي العــام قــرر‬\n‫املدعــى عليــه قناعتــه وقــرر املدعــي العام عــدم قناعته وطلب االســتئناف‬\n‫وقــرر بأنــه لــن يقــدم الئحــة اعتراضيــه وإمنــا يكتفــي بــأوراق املعاملــة‬\n‫والئحــة الدعــوى عــن االعتــراض واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                  ‫محمد وعلى آله وصحبه وسلم‪ .‬حرر يف ‪1434/03/04‬هـ‬\n‫فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة األولــى مبحكمــة‬\n‫االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف برقــم ‪3478500‬‬\n‫وتاريــخ ‪1434/6/10‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪34/1495982‬‬\n‫وتاريــخ ‪1434/6/20‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ ‪..........‬املســجل برقــم ‪ 3460109‬وتاريــخ‬\n‫‪1434/3/11‬ه ـ اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد‪........../‬يف قضيــة‬\n‫اثبــات صفــة القتــل وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬عليــه قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حرريف‪1434/6/24‬ه ـ‬\n                                                                                       ‫‪68‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":58,"source_page_end":68,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2f06c4ae0efbe8f88194a4ee2d3068c344d0d7de59f5014d2e348b08d846f668","normalized_text_hash":"7878d37d790efc165d61cfa9d3563855fa62192a051a652a09e41a872c46f870","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p58-3460109"},{"id":"ac2787d2-6ca2-5a5b-81a5-ad1b29ef73a2","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -قتل -طعن بسكني -طلب إثبات صفة القتل وتطبيق اإلرادة امللكية -تعاطي احلبوب احملظورة «الكبتاجون» -حيازة حشيش -إقرار املدعى عليه -ثبوت إدانة -ثبوت صفة القتل العمد والعقوبة عائدة للجهة املختصة -تقرير قصاص األثر - تعزير مبصادرة السيارة املستخدمة يف اجلرمية .","document_number":"34204971","case_number":"3494926","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/4","year":"1434","subject":"اعتداء -قتل -طعن بسكني -طلب إثبات صفة القتل وتطبيق اإلرادة امللكية -تعاطي احلبوب احملظورة «الكبتاجون» -حيازة حشيش -إقرار املدعى عليه -ثبوت إدانة -ثبوت صفة القتل العمد والعقوبة عائدة للجهة املختصة -تقرير قصاص األثر - تعزير مبصادرة السيارة املستخدمة يف اجلرمية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34204971 :‬تاريخه‪1434/5/4 :‬هـ‬\n                         ‫رقم الدعوى‪3494926:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34247869‬تاريخه‪1434/6/21 :‬هـ‬\n\n\n     ‫اعتــداء ‪ -‬قتــل ‪ -‬طعــن بســكني ‪ -‬طلــب إثبــات صفــة القتــل وتطبيــق‬\n     ‫اإلرادة امللكيــة ‪ -‬تعاطــي احلبــوب احملظــورة «الكبتاجــون» ‪ -‬حيــازة‬\n     ‫حشــيش ‪ -‬إقــرار املدعــى عليــه ‪ -‬ثبــوت إدانــة ‪ -‬ثبــوت صفــة القتــل‬\n     ‫العمــد والعقوبــة عائــدة للجهــة املختصــة ‪ -‬تقريــر قصــاص األثــر ‪-‬‬\n                     ‫تعزيــر مبصــادرة الســيارة املســتخدمة يف اجلرميــة ‪.‬‬\n\n\n\n\n     ‫‪ -1‬األمــر الســامي رقــم ‪ 10711‬يف ‪1393/5/2‬ه ـ وقــرار مجلــس القضــاء‬\n     ‫األعلــى بهيئتــه الدائمــة برقــم‪ 3/51‬يف ‪1409/3/6‬ه ـ املؤيــد باألمــر‬\n     ‫الســامي رقــم ‪/1197/4‬م يف ‪1409/6/2‬ه ـ املبلــغ بالتعميــم ‪/8‬ت‪ 95/‬يف‬\n     ‫‪1409/7/25‬ه ـ بشــأن تطبيــق اإلرادة امللكيــة علــى قاتــل العمــد وشــبه‬\n     ‫العمــد إذا تنــازل أوليــاء الــدم عــن القصــاص (التصنيــف املوضوعــي‬\n                                                ‫لتعاميــم وزارة العــدل ‪.)782/1‬‬\n\n\n\n\n     ‫جــرى توجيــه االتهــام مــن االدعــاء العــام علــى املدعــى عليــه بقيامــه بقتــل‬\n     ‫املجنــي عليــه عمــدا وعدوانــا وطلــب إثباتــه واحلكــم عليــه بتطبيــق‬\n     ‫اإلرادة امللكيــة ومصــادرة الســيارة حيــث قــام املدعــى عليــه بتســليم‬\n     ‫نفســه للجهــات األمنيــة معترفــا بأنــه قــام بقتــل املجنــي عليــه بطعنــه‬\n\n‫‪69‬‬\n\f‫بالســكني ‪ -‬أقــر املدعــى عليــه محاكمــة بــأن املجنــي عليــه صديقــه‬\n‫وأنــه اختلــف معــه فطعنــه بالســكني فرمــاه املجنــي عليــه بحجــر فقــام‬\n‫بعدهــا بطعنــه عــدة مــرات ولــم يكــن يتوقــع بأنهــا ســتقتله فلمــا رأى‬\n‫ينــزف دمــا ســاعده فأركبــه ســيارته وتوجــه بــه ألقــرب مركــز صحــي‬\n‫ثــم ســلم نفســه للشــرطة ‪ ،‬عليــه وإلقــرار املدعــى عليــه بقصــد اجلنايــة‬\n‫مبحــدد يف مقتــل علــى نحــو متكــرر يقتــل غالبــا ‪ ،‬لــذا فقــد ثبــت لــدى‬\n‫احملكمــة أن صفــة قتــل املدعــى عليــه للمجنــي عليــه عمــد وأف َه َمــت‬\n‫املدعــى عليــه بــأن عقوبتــه لقــاء احلــق العــام عائــد للجهــة املختصــة حســب‬\n‫اإلرادة امللكيــة‪ ،‬ومصــادرة الســيارة املســتعملة يف اجلرميــة والتصــرف‬\n‫حك َمــت ‪ ،‬قــرر املدعــى عليــه عــدم‬   ‫بهــا حســب التعليمــات وبذلــك َ‬\n‫القناعــة وطلــب االســتئناف بــدون الئحــة ‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                     ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 3494926‬وتاريــخ‬\n‫‪ 1434/02/26‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1434/02/26‬ه ـ‬\n‫ففــي يــوم الســبت املوافــق‪ 1434/05/04‬ه ـ افتتحت اجللســة الســاعة ‪45‬‬\n‫‪ 10 :‬وفيهــا حضــر ‪ /‬املدعــي العــام ‪..........‬مبوجــب خطــاب التكليــف‬\n‫مــن مرجعــه رقــم‪..........‬يف ‪1434/1/24‬ه ـ وادعــى علــى احلاضــر ‪/‬‬\n‫‪ ،..........‬البالــغ مــن العمــر (‪ )24‬عام ـ ًا ‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب‬\n‫الســجل املدنــي رقــم (‪ ، )..........‬موقــوف بســجون مكــة املكرمــة‬\n\n                                                                                      ‫‪70‬‬\n\f     ‫بتاريــخ ‪29‬ـ ــ‪1432/4/30‬هـ ـ ـ قــام املدعــى عليــه املذكــور بتســليم نفســه‬\n     ‫إلــى مركــز شــرطة ‪..........‬مخبــر ًا عــن قيامــه بالتضــارب مــع املجنــي‬\n     ‫عليه‪........../‬أثنــاء جلوســهما لوحدهمــا يف منطقــة ‪..........‬خلــف مركــز‬\n     ‫‪..........‬وقيامــه بضــرب املجنــي عليــه ثــم نقلــه إلــى املســتوصف‬\n     ‫‪..........‬ب‪..........‬وحضــر إلــى املركــز لتســليم نفســه ومبعاينــة الســيارة‬\n     ‫التــي يســتقلها املدعــى عليــه نــوع ‪ ........‬رقــم اللوحــة (‪ )..........‬اللــون ‪......‬‬\n     ‫‪ ،‬اتضــح وجــود آثــار دمــاء علــى البابــن اخللفيــن األميــن واأليســر وآثــار‬\n     ‫دمــاء علــى املقعــد اخللفــي وبتفتيــش الســيارة نــوع ‪ .........‬رقــم اللوحــة‬\n     ‫(‪ )..........‬اللــون ‪ ......‬عثــر علــى قطعــة بنيــة اللــون يشــتبه أن تكــون مــن‬\n     ‫احلشــيش املخــدر علــى املرتبــة اخللفيــة مــن اجلهــة اليمنــى مت تــزن(‪ 3‬جــم)‬\n     ‫ثالثــة جرامــات (مت احلكــم يف قضيــة املخــدرات مبوجــب القــرار‬\n     ‫الشــرعي رقــم (‪ )6/207‬وتاريــخ ‪1433/4/14‬هـ ـ املرفــق ومبعاينــة موقــع‬\n     ‫احلادثــة ‪ :‬اتضــح بأنــه يقــع يف منطقــة ‪..........‬بعــد أن قــام املدعــى عليــه‬\n     ‫باإلرشــاد إلــى موقــع احلادثــة باالجتــاه إلــى الطريــق املــؤدي إلــى مســجد‬\n     ‫‪..........‬وقبــل املســجد مت األلتفــاف إلــى اليســار والدخــول إلــى طريــق‬\n     ‫إســفلتي والوصــول إلــى مخطــط حديــث اإلنشــاء ويف اجلهــة اليمنــى‬\n     ‫الشــمالية الغربيــة مســجد ‪..........‬وقــام املدعــى عليــه باإلرشــاد إلــى‬\n     ‫منطقــة جبليــة ممهــدة خلــف االســتراحات وعثــر باملوقــع على أربــع مواقع‬\n     ‫بهــا بقــع دمويــة كبيــرة يف إنحــاء متفرقــة متسلســلة مــن أعلــى املنطقــة‬\n     ‫اجلبليــة إلــى األســفل بطــول ‪ 800‬متــر تقريبــا ومنهــا بقعــة دمويــة يف أعلــى‬\n     ‫املنطقــة اجلبليــة وعثــر علــى جــوال وشــماغ وطاقيتــن بيضــاء اللــون‬\n     ‫وشــريحة ومقبــض ســكني مكســور ونصــل ســكني مكســور يبعــد‬\n     ‫عــن املقبــض مبســافة حوالــي متريــن عليهــا آثــار دمــاء وفردتــي حــذاء‬\n\n\n‫‪71‬‬\n\f‫وآثــار إطــارات ســيارة كمــا وجــد آثــار إطــارات ســيارة واضحــة أثنــاء‬\n‫طلوعهــا ونزولهــا مــن أعلــى املنطقــة اجلبلية وقام قصــاص األثر مبقارنتها‬\n‫مــع الســيارة التــي حضــر بهــا املدعــى عليــه نــوع ‪ ........‬رقــم اللوحــة‪..........‬‬\n‫اللــون رصاصــي واتضــح بأنهــا نفــس اإلطــارات التــي شــاهد آثارهــا يف‬\n‫املوقــع ورد تقريــر األدلــة اجلنائيــة تقريــر فنــي رقــم (‪ )19‬مســرح حــادث‬\n‫لعــام ‪1432‬ه ـ ـ متضمن ـ ًا تعــرض املجنــي عليــه للطعــن باســتخدام أداة‬\n‫حــادة وإصابتــه بجــروح طعنيــة غائــرة أدت إلــى وفاتــه كمــا ورد تقريــر‬\n‫األدلــة اجلنائيــة فنــي انطبــاق رقــم (‪ )..........‬لعــام ‪1432‬ه ـ ـ انطبــاق أثــر‬\n‫جلــزء مــن بصمــة راحــة اليــد اليمنــى (مــا حتــت األصابــع) متــام االنطبــاق‬\n‫للجــزء املقابــل لــه مــن طبعــة بصمــة راحــة اليــد للمدعــى عليــه ومت رفــع‬\n‫األثــر مــن زجــاج البــاب مــن اخلــارج خلــف الســائق ‪ .‬وانطبــاق أثــر جلــزء مــن‬\n‫بصمــة راحــة اليــد اليمنــى (كلــوة خنصــر) متــام االنطبــاق للجــزء املقابــل‬\n‫لهــا مــن طبعــة راحــة اليــد اليســرى للمدعــى عليــه ومت رفــع األثــر مــن‬\n‫زجــاج البــاب مــن اخلــارج خلــف الســائق ‪ .‬وانطبــاق أثــر جلــزء مــن بصمــة‬\n‫راحــة اليــد اليســرى (كلــوة خنصــر) متــام االنطبــاق للجــزء املقابــل لهــا‬\n‫مــن طبعــة راحــة اليــد اليســرى للمدعــى عليــه ومت رفــع األثــر مــن البــاب‬\n‫خلــف الســائق ‪ .‬وانطبــاق أثــر جلــزء مــن بصمــة راحــة اليــد اليمنــى (كلــوة‬\n‫خنصــر) متــام االنطبــاق للجــزء املقابــل لهــا مــن طبعــة راحــة اليــد اليســرى‬\n‫للمدعــى عليــه ومت رفــع األثــر مــن علــى البــاب اخللفــي األيســر ‪ ،‬وباقــي‬\n‫اآلثــار ال تــزال مجهولــة كمــا ورد تقريــر األدلــة اجلنائيــة فنــي انطبــاق‬\n‫رقــم (‪ )..........‬لعــام ‪1432‬هـ ـ ـ انطبــاق أثــر جلــزء مــن بصمــة راحــة اليــد‬\n‫اليســرى متــام االنطبــاق للجــزء املقابــل لــه مــن طبعــة راحــة اليــد اليســرى‬\n‫للمجنــي عليــه‪........../‬ومت رفــع األثــر مــن علــى البــاب اخللفــي األيســر مــن‬\n\n\n                                                                                            ‫‪72‬‬\n\f     ‫الزجــاج مــن الداخــل ‪ .‬وانطبــاق أثــر جلــزء مــن بصمــة راحــة اليــد اليســرى‬\n     ‫(كلــوة خنصــر) متــام االنطبــاق للجــزء املقابــل لهــا مــن طبعــة راحــة اليــد‬\n     ‫اليســرى للمجنــي عليــه‪ /‬ومت رفــع األثــر مــن علــى البــاب اخللفــي األيســر‬\n     ‫مــن الزجــاج مــن الداخــل ‪ .‬انطبــاق أثــر جلــزء مــن بصمــة يــد اليمنــى للجــزء‬\n     ‫املقابــل لهــا مــن طبعــة بصمــة أصبــع إبهــام اليــد اليمنــى للمجنــي عليــه‪/‬‬\n     ‫‪..........‬ومت رفــع األثــر مــن الزجــاج خلــف املعــاون وباقــي اآلثــار ال تــزال‬\n     ‫مجهولــة تقريــر األدلــة اجلنائيــة فنــي رقم (‪..........‬متضمــن اآلتي ‪-1‬تطابق‬\n     ‫األمنــاط الوراثيــة للعينــة رقــم (‪01‬ـ ـ ـ ‪ 07‬ـ ــ‪ 09‬ـ ــ‪ 11‬ـ ــ‪ 19‬ـ ــ‪ 21‬ـ ــ‪23‬ـ ــ‪25‬ـ ـ ــ‪)28‬‬\n     ‫الــوارد تفصيلهــا باجلــدول وأنهــا أمنــاط وراثيــة ذكريــة واحــدة مجهولــة‬\n     ‫املصــدر ‪ ،‬كمــا أتضــح اختــاف األمنــاط الوراثيــة لعينــة الــدم القياســية‬\n     ‫(‪ )29‬للمدعــى عليــه عــن األمنــاط الوراثيــة املذكــورة أعــاه ‪-2‬األمنــاط‬\n     ‫الوراثيــة لعينــة الــدم القياســية (‪ )29‬للمدعــى عليــه تقــع ضمــن األمنــاط‬\n     ‫الوراثيــة املختلفــة رقــم (‪20‬ـ ـ ــ‪ )24‬ممــا يــدل علــى أنــه مصــدر هــذا‬\n     ‫االختــاط يف تلــك العينتــن كمــا ورد تقريــر الطــب شــرعي رقــم‬\n     ‫(‪ )..........‬املتضمــن تطابــق جميــع القطــوع التــي علــى مالبــس املجنــي‬\n     ‫عليــه مــع اإلصابــات التــي باجلثــة ‪ ،‬واإلصابــة املوجــودة بيســار العنــق‬\n     ‫واإلبــط األيســر إصابــة طعنيــة نافــذة واإلصابــة التــي يســار مقــدم الصدر‬\n     ‫ومقــدم الكتــف األيســر إصابــة طعنيــة غيــر نافــذة وجميــع هــذه‬\n     ‫اإلصابــات حدثــت مــن اإلصابــة بجســم صلــب حــاد وســن مدبــب مثــل‬\n     ‫الســكني ‪ ،‬والســحجات الهاللية الشــكل على مقدم الســاعد األيســر‬\n     ‫والعضــد األميــن وخلفيــة الكتــف األميــن وأعلــى ميــن مقــدم الصــدر‬\n     ‫حدثــت مــن جســم صلــب مدبــب مثــل رأس الســكني واجلــرح القطعــي‬\n     ‫الــذي يف مقــدم الســاعد األيســر نــاجت عــن أداة حــادة كالســكني أيضـ ًا‬\n\n\n‫‪73‬‬\n\f‫‪ ،‬واجلــرح القطعــي علــى اجلانــب األنســي لليــد اليمنــى الــذي دفاعــي نــاجت‬\n‫عــن جســم صلــب حــاد كالســكني ‪ ،‬وجميــع اإلصابــات املذكــورة‬\n‫أعــاه حيويــة ‪ ،‬ولــم يشــاهد بعمــوم اجلثــة أي إصابــات أخــرى ‪ ،‬كمــا لــم‬\n‫يظهــر مــن خــال الفحــص باألشــعة العاديــة واحلــس اليــدوي وجــود‬\n‫كســور كمــا أظهــرت أشــعة الصــدر وجــود جتمــع هوائــي يف اجلهــة‬\n‫اليســرى بالتجويــف الصــدري ‪ ،‬وبينــت الصفــة التشــريحية إصابــة‬\n‫األوعيــة الدمويــة يســار العنــق بجــوار اجلانــب األنســي لزاويــة الفــك‬\n‫الســفلي األيســر واألنســجة الرخويــة املجــاورة حتــى يســار قاعــدة اللســان‬\n‫مقابــل الطعنــة التــي يســار العنــق وكذلــك اســترواح صــدري يف اجلهــة‬\n‫اليســرى مــن جتويــف الصــدر نــاجت عــن اجلــرح الطعنــي النافــذ الــذي يف‬\n‫منطقــة اإلبــط األيســر حيــث نفــذ إلــى التجويــف الصــدري بــن الضلــع‬\n‫اخلامــس والســادس يف الناحيــة الوحشــية اخللفيــة وهــذه اجلــروح اجتاههــا‬\n‫مــن اجلهــة العليــا اليســرى جلســد املجنــي عليــه إلــى اجلهــة الســفلية اليمنــى‬\n‫‪ ،‬كمــا ثبــت ســلبية العينــات املأخــوذة مــن اجلثــة للمواد املخدرة والســامة‬\n‫واملســكرة وســبب الوفــاة النزيــف احلــاد النــاجت عــن إصابــة أوعيــة دمويــة‬\n‫أعلــى يســار الرقبــة نتيجــة إصابــة طعنيــة غائــرة بآلــة حــادة كالســكني‬\n‫واالســترواح الصــدري يف اجلهــة اليســرى مــن الصــدر نــاجت عــن طعنــة‬\n‫غائــرة يف منطقــة اإلبــط األيســر ســاهم يف ســرعة تدهــور حالــة املجنــي‬\n‫عليــه وحصلــت الوفــاة يف حوالــي الســاعة الثانيــة عشــر والنصــف بعــد‬\n‫منتصــف ليلــة االثنــن املوافــق ‪1432/4/30‬هـ ـ ـ ورد‪ /‬خطــاب مديــر‬\n‫شــعبة التحريــات والبحــث اجلنائــي رقــم (‪ )..........‬وتاريــخ ‪1432/5/9‬هـ ـ ـ‬\n‫متضمــن أنــه مــن خــال البحــث والتحــري اتضــح بــأن املدعــى عليــه‬\n‫واملجنــي عليــه أصدقــاء ويتــرددون علــى بعضهمــا البعــض وهمــا مــن‬\n\n\n                                                                                         ‫‪74‬‬\n\f     ‫مســتعملي املســكرات واملخــدرات حســب مــا يشــاع عنهمــا يف احلــي‬\n     ‫الــذي يســكنون فيــه مبنطقــة ‪..........‬وأن ســبب قيــام املدعــى عليــه بطعن‬\n     ‫املجنــي عليــه الختالفهمــا علــى حســاب املخــدرات حيــث اختلفــوا علــى‬\n     ‫مبالــغ ماليــة وكان املدعــى عليــه يطالــب املجنــي عليــه بهــا ونشــب‬\n     ‫خــاف بينهمــا ونتــج عنــه طعــن املدعــى عليــه للمجنــي عليــه ممــا أدى‬\n     ‫إلــى وفاتــه بوضــع التقاريــر وورد تقريــر األدلــة اجلنائيــة رقــم ‪)..........‬‬\n     ‫متضمــن تطابــق األمنــاط لعينــة األظافــر القياســية رقــم (‪ )..........‬للمجنــي‬\n     ‫عليــه‪ /‬مــع األمنــاط الوراثيــة للعينــة رقــم (‪ )..........‬مــع األمنــاط الوراثيــة‬\n     ‫للعينــات مــن رقــم (‪ )..........‬إلــى رقــم (‪ )..........‬ورقــم (‪ )..........‬ومــن رقــم‬\n     ‫(‪ )..........‬إلــى رقــم (‪ )..........‬ورقــم (‪ )..........‬ورقــم (‪ )..........‬ومــن رقــم‬\n     ‫(‪ )..........‬إلــى رقــم (‪ )..........‬الصــادر بحقهــا التقريــر رقم‪..........‬ممــا يثبت‬\n     ‫بــأن املجنــي عليــه ‪.......... /‬هــو مصــدر تلــك العينــات ‪ ،‬وأن األمنــاط‬\n     ‫الوراثيــة لعينــة األظافــر القياســية للمجنــي عليه‪........../‬رقــم (‪)..........‬‬\n     ‫تقــع ضمــن األمنــاط الوراثيــة املختلطــة للعينة رقــم (‪ )..........‬ورقم (‪)..........‬‬\n     ‫الصــادر بحقهــا التقريــر رقم‪..........‬بســماع أقــوال‪.......... /‬ذكــر بأنــه يف‬\n     ‫ا وأثنــاء مــروره بجــوار‬   ‫يــوم احلادثــة ويف الســاعة الثانيــة عشــر والربــع ليـ ً‬\n     ‫مســتوصف ‪..........‬شــاهد ســيارة نــوع جمــس اللــون رصاصــي واملدعــى‬\n     ‫عليــه ينــزل منهــا وثيابــه مليئــة بالــدم وذهــب وأحضــر عربيــة ومســعفني‬\n     ‫ولــم يشــاهده بعدهــا ويف املقعــد اخللفــي املجنــي عليــه ‪.......... /‬وهــو‬\n     ‫مصــاب يف رقبتــه مــن اجلهــة اليســرى ويف إبطــه األيســر وقام هو بإســعاف‬\n     ‫املجنــي عليــه وقــال لــه املجنــي عليــه (يــا ‪..........‬أســعفنى أنــا مبــوت) وأثناء‬\n     ‫محاولــة إســعافه باملســتوصف نطــق بالشــهادة وتــويف بســماع أقــوال‪/‬‬\n     ‫‪..........‬ذكــر بأنــه يف يــوم احلادثــة حضــر املدعــى عليــه مــا بــن الســاعة‬\n\n\n‫‪75‬‬\n\f‫ا إلــى منزلهــم وبقيادتــه‬    ‫احلاديــة عشــر والنصــف إلــى الثانيــة عشــر لي ـ ً‬\n‫ســيارة نــوع ‪ ....‬وتقابــل معــه وشــقيقه املجنــي عليــه فقــال املدعــى عليــه‬\n‫للمجنــي عليــه هيــا معــي ســوف نذهــب مشــوار وطلــب هــو مــن املدعــى‬\n‫عليــه الذهــاب معهمــا فــرد عليــه املدعــى عليــه بقولــه بنروح مشــوار قريب‬\n‫ونعــود ثــم دخــل هــو إلــى املنــزل ثم علم بعد ذلك بوفاة شــقيقة باســتجواب‬\n‫املدعــى عليــه أقــر بقتــل املجنــي عليــه‪.......... /‬وذلــك بضربــة بالســكني‬\n‫وذكــر بأنــه يف يــوم احلادثــة وبعــد صــاة العشــاء اتصــل علــى املجنــي‬\n‫عليــه وطلــب منــه إيجــاد شــخص لشــراء احلبــوب احملظــورة وتواعــد معــه‬\n‫ا توجــه إلــى منــزل‬  ‫عنــد منزلــه يف ‪..........‬ويف حوالــي الســاعة العاشــرة ليـ ً‬\n‫املجنــي عليــه وتقابــل مــع شــقيقه‪........../‬وحضر املجنــي عليــه بعــد ذلــك‬\n‫ا ثــم انطلــق هــو مــع املجنــي عليــه وبقيادتــه ســيارة نــوع ‪.....‬‬\n                                                                      ‫وحتدثــوا قليـ ً‬\n‫اللــون‪ ......‬وذهبــا إلــى أحــد معــارف املجنــي عليــه يف ‪..........‬الــذي قــام‬\n‫بإرشــادهم إلــى مــكان شــخص آخــر لشــراء املخــدرات وأعطــى املجنــي‬\n‫عليــه مبلــغ (‪ )90‬تســعني ريــال وأضــاف عليهــا املجنــي عليــه مبلــغ (‪)100‬‬\n‫مائــة ريــال وقــام بإعطائهــا للشــخص الــذي يعرفــه والــذي قــام بــدورة‬\n‫بشــراء حبــوب مــن الكبتاجــون وقطعــة مــن احلشــيش املخــدر وإعطائهــا‬\n‫للمجنــي عليــه وأنــزل الشــخص الــذي معهــم يف ‪..........‬واجتــه هــو واملجني‬\n‫عليــه إلــى بقالــه وقامــا بشــراء العصيــر واجتــه بعــد ذلــك إلــى مخطــط‬\n‫جبلــي علــى طريــق ‪..........‬وصعــد بالســيارة إلــى أعلــى املخطــط ثــم نــزل‬\n‫مــن الســيارة وأخــرج الســكني مــن جيبــه وتضــارب مــع املجنــي عليــه‬\n‫وقــام بضربــه بالســكني ثــم نــزل املجنــي عليــه إلــى أســفل املخطــط وحلــق‬\n‫بــه وتضــارب معــه مــرة أخــرى وعندمــا شــاهد الــدم علــى مالبــس املجنــي‬\n‫عليــه صعــد إلــى الســيارة واســتمر املجنــي عليــه يف النــزول وحلــق باملجنــي‬\n\n\n                                                                                         ‫‪76‬‬\n\f     ‫عليــه بالســيارة وفتــح قفــل األبــواب وركــب املجنــي عليــه يف املرتبــة‬\n     ‫اخللفيــة ثــم تنــاول هــو ثــاث حبــات مــن احلبــوب احملظــورة والتــي قــام‬\n     ‫بشــرائها وكانــت علــى درج الســيارة األوســط وتوجــه بعــد ذلــك إلــى‬\n     ‫املســتوصف ‪..........‬ب‪..........‬وتوقــف عنــد املســتوصف وقــام بإدخــال‬\n     ‫املجنــي عليــه إلســعافه وتوجــه بعــد ذلــك إلــى مركــز شــرطة ‪..........‬‬\n     ‫وقــام بتســليم نفســه وأضــاف بأنــه قــام بشــراء الســكني املســتخدمة مــن‬\n     ‫نــوع (‪ )........‬مــن محطــة ‪..........‬قبــل احلادثــة مــن أجــل التضــارب بهــا مــع‬\n     ‫املجنــي عليــه ‪ ،‬وصــدق إقــراره بذلــك شــرع ًا وقــد انتهــى التحقيــق إلــى‬\n     ‫توجيــه االتهــام للمدعــى عليــه بقتــل‪.......... /‬بطعنــه بســكني عمــد ًا‬\n     ‫وعدوان ـ ًا ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة ‪-1‬إقــراره املصــدق شــرع ًا‬\n     ‫املنــوه عنــه املــدون علــى صفحــة رقــم (‪ )2/1‬مبلــف التحقيــق رقــم (‪)3‬‬\n     ‫املرفــق لفــه رقــم (‪-2 )22‬مــا جــاء يف التقريــر الطبــي الشــرعي النهائــي‬\n     ‫املنــوه عنــه واملرفــق لفــه رقــم (‪ )92‬إلــى (‪-3)102‬تقاريــر األدلــة اجلنائيــة‬\n     ‫رقم ‪ )..........‬ورقم (‪ )..........‬ورقم (‪ )..........‬ورقم (‪ )..........‬ورقم (‪)..........‬‬\n     ‫واملرفقــة لفــة رقــم (‪33‬ـ ــ‪37‬ـ ــ‪ 41‬ـ ـ ـ ومــن ‪ 67‬إلــى ‪-4)77‬محضــر قصــاص‬\n     ‫األثــر املنــوه عنــه واملــدون علــى صفحــة رقــم (‪ )11‬مبلــف إجــراءات‬\n     ‫االســتدالل املرفــق لفــه رقــم (‪-5 )2‬محضــر االنتقــال واملعاينــة والتفتيــش‬\n     ‫املنــوه عنهــا واملــدون مبلــف إجــراءات االســتدالل املرفــق لفــه رقــم‬\n     ‫(‪ 1‬ـ ـ‪ 2‬ـ ــ‪ )30‬وحيــث إن مــا قــام بــه املدعــى عليــه فعــل محــرم ومعاقــب‬\n     ‫عليــه شــرع ًا لــذا أطلــب إثبــات صفــه القتــل وتطبيــق اإلرادة امللكيــة‬\n     ‫واحلكــم مبصــادرة الســيارة املســتخدمة يف اجلرميــة نــوع ‪ .....‬رقــم اللوحــة‬\n     ‫(‪( )..........‬احلــق اخلــاص مــا زال قائم ـاً) هــذه دعــواي وبســؤال املدعــى‬\n     ‫عليــه اجــاب بقولــه مــا ذكــره املدعــي العــام صحيــح حيــث اختلفــت مــع‬\n\n\n‫‪77‬‬\n\f‫املجنــي عليــه وكان صديقــا لــي ثــم طلبــت منــه مرافقتــي إلــى املخطــط‬\n‫اجلبلــي املذكــور واختلفنــا وتخاصمنــا وطعنتــه بالســكني ثــم ضربنــي‬\n‫بحجــر ثــم طعنتــه عــدة مــرات وإحداهــا يف جانــب رقبتــه وكنــت أقصــد‬\n‫إصابتــه لكننــي لــم أتوقــع أن اإلصابــات ســتقتله وعندمــا رأيــت أنــه‬\n‫ينــزف ســاعدته حتــى ركــب الســيارة وتوجهــت بــه ألقــرب مركــز‬\n‫صحــي ثــم ســلمت نفســي للشــرطة هــذه إجابتــي فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وإلــى إقــرار املدعــى عليــه بدعــوى املدعــي العــام‬\n‫وحيــث إنــه أصــاب املجنــي عليــه مبحــدد يقتــل غالبــا وأصابــه يف مقتــل‬\n‫وكــرر الطعــن وهــو قاصــد اإلصابــة لــذا فقــد ثبــت لــدي أن صفــة قتــل‬\n‫املدعــى عليــه للمجنــي عليــه هــي القتــل العمــد وأفهمــت املدعــى عليــه‬\n‫بــأن جــزاءه لقــاء احلــق العــام عائــد للجهــة املختصــة حســب اإلرادة‬\n‫امللكيــة مبثــل هــذا الشــأن وحكمــت مبصــادرة الســيارة املســتخدمة يف‬\n‫اجلرميــة والتصــرف بهــا حســب األنظمــة والتعليمــات اخلاصــة بهــذا الشــأن‬\n‫وبعــرض احلكــم علــى املدعــى عليــه لــم يقنــع وطلــب االســتئناف بــدون‬\n‫الئحــة فأجيــب لطلبــه ولــم يعــارض املدعــي العــام حيــث حكــم لــه بــكل‬\n‫طلباتــه وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وآله وصحبه‬\n‫‪ .‬حــرر يف ‪1434/5/4‬هــ‪ .‬ثــم عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫وبرفقهــا القــرار رقــم ‪ 34247869‬وتاريــخ ‪1434/06/21‬ه ـ املتضمــن‬\n‫املوافقــة والتصديــق علــى احلكــم قاضــي اســتئناف ‪..........‬قاضــي‬\n‫اســتئناف‪..........‬قاضي اســتئناف ‪..........‬لــذا جــرى إحلاقــه وإثباتــه وبــاهلل‬\n                                                ‫التوفيق حرر يف ‪1434/07/10‬هـ‬\n\n\n\n\n                                                                                      ‫‪78‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":69,"source_page_end":78,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b2791ce7cff4a1828c2e544b63a0f12409f6b502c643dde469eb3847e40a855e","normalized_text_hash":"87f1295d4c3d07ef3ca1107c6fcf0c8751c76cdd30b537e82ee07059959c4c51","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p69-34204971"},{"id":"233af501-96c6-5312-b50e-058bd6b059f5","document_type":"judgment","category":"judicial","subcategory":"general","title":"قتل -القتل العمد وشبه العمد اخلطأ -قتل خطأ -حدث -إقرار املدعى عليه -تنازل عن احلق اخلاص -مشروعية االستئناس بالقرائن يف حتديد القصد اجلنائي -رد دعوى اإلدانة بالقتل اخلطأ -عدم صحة تنازل الولي عن حقوق القاصرين حتت واليته ما أشار له القاضي يف تسبيب احلكم.","document_number":"3312366","case_number":"32507275","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة كما هو موضح يف أوراق املعاملة","circuit":"الدائرة اجلزائية الثانية رقم 33150802وتاريخ 1433/3/23ه","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/1/8","year":"1434","subject":"قتل -القتل العمد وشبه العمد اخلطأ -قتل خطأ -حدث -إقرار املدعى عليه -تنازل عن احلق اخلاص -مشروعية االستئناس بالقرائن يف حتديد القصد اجلنائي -رد دعوى اإلدانة بالقتل اخلطأ -عدم صحة تنازل الولي عن حقوق القاصرين حتت واليته ما أشار له القاضي يف تسبيب احلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 3312366 :‬تاريخه‪1433/1/8 :‬هـ رقم‬\n                               ‫الدعوى‪32507275:‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 3433818‬تاريخه‪1434/2/10 :‬هـ‬\n\n\n       ‫قتــل ‪ -‬القتــل العمــد وشــبه العمــد اخلطــأ ‪ -‬قتــل خطــأ ‪ -‬حــدث ‪ -‬إقــرار‬\n       ‫املدعــى عليــه ‪ -‬تنــازل عــن احلــق اخلــاص ‪ -‬مشــروعية االســتئناس‬\n       ‫بالقرائــن يف حتديــد القصــد اجلنائــي ‪ -‬رد دعــوى اإلدانــة بالقتــل‬\n       ‫اخلطــأ ‪ -‬عــدم صحــة تنــازل الولــي عــن حقــوق القاصريــن حتــت واليتــه‬\n\n\n\n\n                                              ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n       ‫جــرى توجيــه مــن قبــل االدعــاء العــام علــى املدعــى عليــه احلــدث بقيامــه‬\n       ‫بقتــل شــقيقه عمــدا وعدوانــا وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n       ‫بعقوبــة تعزيريــة حيــث تلقــت الشــرطة بالغــا عــن وجــود شــخص مطعــون‬\n       ‫وباالنتقــال للموقــع واســتجواب أســرته ظهــر بــأن املدعــى عليــه هــو مــن‬\n       ‫تســبب بقتلــه علــى إثــر شــجار أســري ‪ ،‬انتهــى احلــق اخلــاص بالتنــازل ‪،‬‬\n       ‫أقــر املدعــى عليــه بتســببه يف قتــل أخيــه ودفــع بأنــه لــم يكــن عمــدا بــل‬\n       ‫خطــأ حيــث ال توجــد عــداوة بينــه وبــن املجنــي عليــه حيــث تدخــل لفــك‬\n       ‫الشــجار بــن املجنــي عليــه وشــقيقه اآلخــر فلمــا تفرقــا عــاد املجنــي عليــه‬\n       ‫وبيــده ســكينا والمــه علــى فــض واقعــة الضــرب بينهما وطعنــه يف ذراعه‬\n       ‫األيســر ثــم رفــع يــده مــرة أخــرى ليطعنــه بهــا فمســك يــده ودفعــه للخلــف‬\n\n‫‪79‬‬\n\f‫فارتــدت الســكني عليــه نحــو قلبــه ثــم ســار قليــا وســقط علــى األرض‬\n‫‪ ،‬وألن الظاهــر انتفــاء قصــد اجلنايــة وقصــده الدفــاع عــن نفســه ‪ ،‬يؤيــده‬\n‫تصديــق ورثــة املجنــي عليــه ‪ ،‬لــذا وألن القصــد خفــي وإمنــا يســتدل لــه‬\n‫بالقرائــن ‪ ،‬وألن القرائــن املصاحبــة للجنايــة تؤيــد صحــة دفعــه لعــدم‬\n‫ثبــوت حملــه الســكني ابتــداء وعــدم وجــود عــداوة ســابقة عليــه ولتنــازل‬\n‫الورثــة عــن الديــة ‪ ،‬وملجمــوع مــا تقــدم فقــد قــررت احملكمــة صــرف‬\n‫النظــر عــن طلــب املدعــي العــام إثبــات صفــة قتــل املدعــى عليــه للمجنــي‬\n‫كمــت ‪،‬‬  ‫ـاء وبذلــك َح َ‬‫عليــه عمــدا وثبــوت إدانــة املدعــى عليــه بقتلــه خطـ ً‬\n‫أفهــم املدعــى عليــه بــأن عليــه كفــارة قتــل اخلطــأ ‪ ،‬قــرر املدعــى عليــه‬\n‫القناعــة واملدعــى العــام عدمهــا بــدون تقــدمي الئحــة ‪ ،‬عــادت القضيــة‬\n‫مــن محكمــة االســتئناف مبلحوظتــن األولــى بأنــه جــرى ضبــط تنــازل‬\n‫والــدة املقتــول أصالــة وواليــة وســكت عــن إثباتــه مــن عدمــه واملتعــن‬\n‫إثباتــه بحــق البالــغ دون القاصــر‪ ،‬واألخــرى بطلــب إعــادة النظــر يف‬\n‫حتديــد صفــة القتــل بالنظــر إلــى اآللــة (الســكني) مــع مــا صاحــب‬\n‫ذلــك مــن شــجار واعتــراف املدعــى عليــه بأنــه مســك بيــد املجنــي عليــه‬\n‫وبيــده الســكني فدفعــه فطعــن نفســه وأن أقــل األحــوال أن يكــون شــبه‬\n‫عمــد‪ ،‬أجابــت احملكمــة عــن امللحوظتــن بأنهــا لــم تقــم بضبــط التنــازل‬\n‫بصفــة مســتقلة يف ضبــط التنــازالت وإمنــا ذكــرت ذلــك ملــا تنازلــت يف‬\n‫احملكمــة العامــة كمــا هــو موضــح يف أوراق املعاملــة ‪ ،‬وعــن امللحوظــة‬\n‫الثانيــة بــأن املدعــى عليــه لــم يقصــد اجلنايــة وأن العمــد و شــبه العمــد‬\n‫يتفقــان يف القصــد ويختلفــان يف اآللــة ‪ ،‬والقتــل اخلطــأ ليــس فيــه قصــد‬\n‫اجلنايــة واملدعــى عليــه لــم يقصــد اجلنايــة حيــث ال عــداوة مســبقة وال هــو‬\n‫مــن جــاء بالســكني وطعــن لــذا لــم يظهــر لهــا مــا يوجــب الرجــوع عــن‬\n                       ‫احلكــم ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n                                                                                       ‫‪80‬‬\n\f     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪..........‬القاضــي باحملكمــة اجلزئيــة‬\n     ‫ـاء علــى املعاملــة احملالــة إلــي مــن فضيلــة الرئيــس‬\n                                                            ‫مبنطقــة تبــوك وبنـ ً‬\n     ‫املساعد برقم ‪ 321233181‬وتاريخ ‪ 1432 / 10 / 2‬ه ـ ويف متام الساعة‬\n     ‫العاشــرة مــن هــذا األربعــاء املوافــق ‪ 1433 / 1 /5‬هـ ـ افتتحــت اجللســة‬\n     ‫وفيهــا حضــر املدعــي العــام ‪.......... /‬ســعودي مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪..........‬واملعمــد مــن احملكمــة برقــم ‪..........‬يف ‪ 1431 / 7 / 15‬هـ ـ‬\n     ‫وحضــر حلضــوره املدعــى عليــه‪.......... /‬ســعودي اجلنســية مبوجب الســجل‬\n     ‫املدنــي رقــم ‪..........‬فأدعــى قائــا يف حتريــر دعــواه أنــه يف يــوم األحــد‬\n     ‫املوافــق ‪1432/6/26‬ه ـ ويف متــام الســاعة الرابعــة عصــر ًا ورد بــاغ مــن‬\n     ‫مستشــفى امللــك فهــد بتبــوك ملركــز شــرطة ‪..........‬عــن وجــود شــخص‬\n     ‫مطعــون وهــو بحالــة حرجــة وباالنتقــال واملعاينــة تبــن أنــه املجنــي عليــه‬\n     ‫‪..........‬وبســماع أقــوال شــقيق املجنــي عليــه‪ .......... /‬أفــاد أنــه وجــد أخــوه‬\n     ‫املجنــي عليــه مطعــون وممــدد خــارج املنــزل بالقــرب مــن زاويــة املنــزل ‪.‬‬\n     ‫وباالنتقــال واملعاينــة ملوقــع اجلرميــة تبــن أنــه ال يوجــد آثــار أو عالمــات‬\n     ‫ـاء علــى عــدم وجــود أي‬ ‫تــدل علــى أن الواقعــة حصلــت خــارج املنــزل وبنـ ً‬\n     ‫معلومــات فقــد مت معاينــة املنــزل مــن الداخــل وقــد تبــن وجــود آثــار دمــاء‬\n     ‫علــى بعــض اجلــدران واملوكيــت ومت رفعهــا ومبناقشــة أشــقاء املتوفــى‪/‬‬\n     ‫‪10(..........‬ســنوات ) أفــادوا بــأن هنــاك مشــكلة حدثــت بــن شــقيقهم‪/‬‬\n     ‫‪..........‬املجنــي عليــه و‪..........‬اجلانــي وأن بهــا آلــة حــادة ـ ســكني ـ وأن‬\n     ‫شــقيقهم‪.......... /‬اجلانــي تعــرض للطعــن بكتفــه األيســر وشــقيقهم‬\n     ‫‪..........‬املجنــي عليــه تعــرض لطعنــه بصــدره‪ ،‬وباالنتقــال إلــى مستشــفى‬\n\n‫‪81‬‬\n\f‫‪ ...........‬ملعاينــة جثمــان املتوفــى اتضــح أنــه بالعقــد الثالــث مــن العمــر‬\n‫بطــول حوالــي ‪170‬ســم حنطــي البشــرة لــون الشــعر أســود وطويــل يرتــدي‬\n‫ســروال أبيــض طويــل لــم يتــم العثــور علــى متزقــات وعليــه بقــع بلــون أحمــر‬\n‫يشــتبه أنهــا دم وكذلــك يرتــدي ســروال قصيــر بلــون أبيــض عليــه بقــع‬\n‫بلــون أحمــر يشــتبه أنهــا دم و فانيلــة نــص كــم مقصــوص أثناء اإلســعاف‬\n‫بــه متــزق بطــول ‪3‬ســم بأعلــى الصــدر مــن الناحيــة اليســرى وعليــه بقــع‬\n‫بلــون أحمــر يشــتبه أن تكــون دم واتضــح وجــود جــرح طعنــي أعلــى يســار‬\n‫الصــدر بطــول حوالــي ‪2.5‬ســم وكذلــك جــرح أيســر الصــدر مــكان‬\n‫تركيــب أنبــوب لتصريــف الســوائل ‪ ،‬ويف يــوم األحــد املوافــق‬\n‫‪1432/7/17‬ه ـ مت االنتقــال للموقــع الــذي حدثــت فيــه اجلرميــة مبنزلهــم‬\n‫الكائــن بحــي ‪..........‬وقــام املدعــى عليــه بتمثيــل اجلرميــة وكان متثيــل‬\n‫اجلرميــة مطابــق ملــا ذكــرة املدعــى عليــه ‪ ،‬وقــد مت عــرض احلــدث علــى‬\n‫فضيلــة قاضــي األحــداث وأمــر بإيقافــه حتــى محاكمتــه كمــا هــو‬\n‫مرفــق لفــه (‪ )59‬صفحــة (‪، )15‬وباســتجواب املدعــى عليــه‪.......... /‬أقــر‬\n‫بأنــه يف يــوم األحــد املوافــق ‪1432/6/26‬ه ـ ويف حوالــي الســاعة الثالثــة‬\n‫عصــر ًا حدثــت مشــاجرة بــن األخويــن ‪..........‬و‪..........‬وقــام بالتفريــق‬\n‫بينهمــا وذهــب ‪..........‬إلــى مجلــس الرجــال مــع أمــه وأخواتــه وذهــب‬\n‫املجنــي عليــه‪.......... /‬إلــى غرفتــه اخلاصــة ومكــث املدعــى عليــه ‪..........‬‬\n‫بصالــة املنــزل وال يوجــد عنــده أحــد وفجــأة خــرج املجنــي عليــه‪.......... /‬‬\n‫مــن غرفتــه اخلاصــة وبيــده اليمنــى ســكني ( نصــاب خضــرة ) لونهــا‬\n‫أبيــض وهــو يقــول لــه ( ملــاذا فككــت بينــي وبــن ‪ )..........‬فقــال لــه‬\n‫املدعــى عليــه ( ال نريــد مشــاكل ) فقــام املجنــي عليــه‪.......... /‬وطعــن‬\n‫املدعــى عليــه يف عضــده األيســر فأمســك املدعــى عليــه بيــد املجنــي‬\n\n\n                                                                                       ‫‪82‬‬\n\f     ‫عليــه‪.......... /‬ودفعــه علــى صــدره فدخلــت الســكني يف صــدر املجنــي‬\n     ‫عليــه‪.......... /‬فهــرب املدعــى عليــه نحــو مجلــس الرجــال وكان يلحــق بــه‬\n     ‫املجنــي عليــه ويقــول لــه ( فــدا كــذا الذيــب ) وســقط بعدها أمــام املطبخ‬\n     ‫باملمــر وقــام املدعــى عليــه بإخبــار أخيــه‪.......... /‬فقامــا بحمــل املجنــي‬\n     ‫عليــه ‪.......... /‬وإركابــه يف الســيارة مــن نــوع ‪ ..........‬لونهــا أســود مــع‬\n     ‫ذهبــي وذهــب بــه ‪ .......‬إلــى املستشــفى إلســعافه وعــاد املدعــى عليــه إلــى‬\n     ‫املنــزل وأخبــر والدتــه وشــقيقته‪.......... /‬مبــا حصــل واتصــل املدعــى عليــه‬\n     ‫علــى أخويــه‪.......... /‬و‪ ..........‬وأخبرهــم مبــا حصــل وأفــاد املدعــى عليــه‬\n     ‫بــأن الســكني املســتخدمة يف اجلرميــة قــام أخــوه الصغيــر املدعــو‪.......... /‬‬\n     ‫برميهــا يف حاويــة النفايــات اخلاصــة باملنــزل وصــادق علــى إقــراره شــرع ًا‬\n     ‫‪ ،‬وبضبــط إفــادة شــقيق املدعــى عليــه واملجنــي عليــه‪.......... /‬أفــاد أنــه يف‬\n     ‫يــوم االحــد املوافــق ‪1432/6/26‬ه ـ حوالــي الســاعة الثانيــة ظهــر ًا‬\n     ‫اســتيقظ شــقيقه ‪..........‬مــن نومــه ويطالــب بالفطــور وقــام بتنــاول وجبــة‬\n     ‫اإلفطــار وبعــد انتهائــه مــن اإلفطــار ذهــب إلــى غرفتــه وذهــب هــو إلــى‬\n     ‫املطعــم إلحضــار وجبــة الغــداء وعندمــا أحضــر الغــداء إلــى املنــزل طلبــوا‬\n     ‫مــن ‪..........‬أن يشــاركهم يف الغــداء هــو وأمــه وأختــه ‪..........‬و‪..........‬‬\n     ‫و‪ ..........‬و‪ ..........‬لكنــه رفــض وال يريــد الغــداء وبعــد انتهائهــم مــن‬\n     ‫الغــداء حضــر إلــى أمه‪..........‬وطلــب منهــا أن تعمــل لــه قهــوة تركيــة‬\n     ‫فقالــت لــه أمــه أنــا ال أشــتغل عنــدك خدامــة وأخــذ يتلفــظ علــى أمــه‬\n     ‫بألفــاظ غيــر الئقــة ويقــوم بلعنهــا فقــام إليــه فأمــره بــأن يذهــب إلــى‬\n     ‫غرفتــه لكونــه دائمـ ًا يعمــل مشــاكل يف البيــت فرفــض أن يذهــب إلــى‬\n     ‫غرفتــه وقــام ‪..........‬بضربــه علــى صــدره بيــده وقــام هــو بدفعه وتشــابكا‬\n     ‫فقــام أخيــه ‪..........‬بالتفريــق بينهمــا وفكهــم عــن بعــض فذهــب أخيــه‬\n\n\n‫‪83‬‬\n\f‫‪..........‬إلــى غرفتــه وذهــب هــو إلــى مجلــس الرجــال مــع والدتــه وأختــه‬\n‫‪..........‬وأخيــه ‪..........‬وأخيــه ‪..........‬وأخيــه ‪..........‬فبعدهــا قــال ألخيــه‬\n‫‪..........‬اذهــب وأكــوي ثوبــه يف الصالــة فبعدمــا ذهــب ‪..........‬وســمع‬\n‫صــوت شــجار بــن أخيــه ‪..........‬وأخيــه ‪..........‬فشــاهد عــن طريــق املنظرة‬\n‫أخيــه ‪..........‬ميــد يــده علــى ‪ ..........‬فبعدهــا هــرب ‪..........‬إلــى املجلــس‬\n‫فلحــق بــه أخيــه ‪..........‬فأمســك ب‪ ..........‬وشــاهد الــدم علــى صــدره فقال‬\n‫هيــا نذهــب إلســعافك باملستشــفى فســقط ‪..........‬علــى األرض عنــد بــاب‬\n‫املطبــخ وقــام بعدهــا هــو وأخيــه ‪..........‬بحملــه ونقلــه بالســيارة مــن نــوع‬\n‫‪ ........‬أســود وذهبــي بــه لوحــده إلــى مستشــفى ‪ ......‬ولــم يذهــب معــه أخيــه‬\n‫‪..........‬وحينمــا دخــل إلــى املستشــفى اخبرهــم بأنــه مطعــون فجلــس‬\n‫ينتظــر ويــرى مــاذا يحصــل فحضــر إليــه أخيــه ‪..........‬باملستشــفى بقســم‬\n‫الطــوارئ وبعدهــا تلقــى خبــر وفاتــه حينمــا عــاد إلــى البيــت ‪.‬وقــد مت‬\n‫حفــظ االتهــام بحــق املدعــو‪.......... /‬يف قضيــة املضاربــة بينــه وبــن املجني‬\n‫عليــه لعــدم كفايــة األدلــة وذلــك اســتناد ًا للمــادة رقــم (‪ )124‬مــن نظــام‬\n‫اإلجــراءات اجلزائيــة ‪ ،‬وبضبــط إفــادة املــرأة‪ .......... /‬والــدة اجلانــي‬\n‫واملجني عليه أفادت أنه يف يوم األحد املوافق ‪1432/6/26‬هـ اســتيقظ‬\n‫ابنهــا‪.......... /‬املجنــي عليــه الســاعة الثانيــة ظهــر ًا وكعادتــه يقــوم‬\n‫بالصيــاح عليهــم والصــراخ لكونــه مريــض حركي ـ ًا ولديــه اختــال يف‬\n‫املــخ يحصــل لــه أحيان ـ ًا بعــد حــادث مــروري حصــل لــه وطلــب طعــام‬\n‫اإلفطــار وبعــد انتهائــه مــن الفطــور رجــع إلــى غرفتــه وقرابــة الســاعة‬\n‫الثالثــة والنصــف قامــوا مبناداتــه مــن أجــل أن يتغــدى معهــم فرفــض أن‬\n‫يشــاركهم يف الغــداء وبعــد أن انهــوا الغــداء جــاء ابنهــا‪.......... /‬وهــم يف‬\n‫صالــة املنــزل وطلــب منهــا وهــو يســب ويشــتم أن تعمــل لــه فنجــان قهــوة‬\n\n\n                                                                                         ‫‪84‬‬\n\f     ‫تركــي فقالــت لــه أنــا مانــي خدامــة عنــدك فأخــذ يســبها ويلعنهــا‬\n     ‫ويشــتهما فقــام ابنهــا‪.......... /‬يدافــع عنهــا ويقــول ألخيــه‪.......... /‬ليــش‬\n     ‫تســب أمــي وتلعنهــا وحصلــت بينهــم مشــابكة باأليــدي فقــام ابنهــا‪/‬‬\n     ‫‪..........‬بالتفريــق بــن إخوانــه وإبعادهــم عــن بعــض فقامــت بعدهــا بأخــذ‬\n     ‫ابنهــا‪.......... /‬و‪ ..........‬و‪ ..........‬و‪ ..........‬و‪ ..........‬وذهبــت بهــم إلــى مجلــس‬\n     ‫الرجــال الكتفــاء شــر ابنهــا‪.......... /‬حيــث أنــه دائمـ ًا يســبب املشــاكل‬\n     ‫بــن إخوانــه وذكــرت بأنهــم أثنــاء جلوســهم باملجلــس أمــر ابنهــا ‪..........‬‬\n     ‫أخــوه ‪..........‬بــأن يكــوي لــه ثــوب املوجــود يف الصالــة فقــام ‪..........‬وذهــب‬\n     ‫إلــى الصالــة وفجــأة ســمعت صــوت ابنهــا ‪..........‬مرتفعـ ًا عاليـ ًا كعادتــه‬\n     ‫يســب ويشــتم إخوانــه ولــم تذهــب لهــم ألننهــم متعوديــن علــى ســبه‬\n     ‫وصياحــه وأفــادت بــأن أبنهــا ‪..........‬أخبرهــا بــأن أخويــه ‪..........‬و‪..........‬‬\n     ‫متطاعنــن بالســكني ويريــد أن يذهــب ب‪ ..........‬إلى املستشــفى فقامت‬\n     ‫لتنظــر مــاذا حصــل فشــاهدت ابنهــا ‪..........‬واقــف وفنيلتــه عليهــا دم‬\n     ‫بســيط ومتقطعــة ثــم أســعفوه إلــى املستشــفى وبعدهــا علمــت بوفاتــه‬\n     ‫باملستشــفى ‪.‬وقــد مت حفــظ االتهــام بحــق املجنــي عليــه يف قضيــة ســبه‬\n     ‫لوالدتــه النقضــاء الدعــوى اجلزائيــة بوفــاة املجنــي عليــه وذلــك اســتناد ًا‬\n     ‫للمــادة رقــم (‪ )22‬مــن نظــام اإلجــراءات اجلزائيــة‪ ،‬وبضبــط إفــادة الفتاة‪/‬‬\n     ‫‪..........‬أفــادت أنــه يف يــوم األحــد املوافــق ‪1432/6/26‬ه ـ عــادت مــن‬\n     ‫املدرســة إلــى البيــت قرابــة الســاعة الواحــدة والنصــف وكان يف املنــزل‬\n     ‫والدتهــا وإخوانهــا ‪..........‬و‪ ..........‬و‪ ..........‬و‪ ..........‬و‪ ..........‬فاســتيقظ‬\n     ‫أخيهــا ‪..........‬وخــرج مــن غرفتــه وهــو يطلــب طعــام اإلفطــار وأعــدت لــه‬\n     ‫اإلفطــار فــول وأفطــر يف الصالــة فذهبــت إلــى غرفتهــا لتســتريح مــن‬\n     ‫عنــاء الدراســة وفجــأة ســمعت صــوت أخيهــا ‪..........‬عالي ـ ًا يســب ويلعــن‬\n\n\n‫‪85‬‬\n\f‫فخرجــت مــن غرفتهــا يف يــوم األحــد املوافــق ‪1432/6/26‬ه ـ ويف متــام‬\n‫الســاعة الثالثــة عصــر ًا كنــا جالســن بالصالــة فخــرج أخيــه ‪..........‬مــن‬\n‫غرفتــه وطلــب مــن أمــه إصــاح قهــوة تركيــة فرفضــت أمــه فجلــس‬\n‫يســب عليهــا ويلعــن فقــام عليــه أخــي ‪..........‬يخاصمــه وحصلــت بينهــم‬\n‫مشــاجرة فقــام أخيــه ‪..........‬يفــك بينهــم فقامــت أمــه بأخذهــم إلــى‬\n‫مجلــس الرجــال إال أنــه جلــس يف الصالــة فرجــع إلــى أخيــه ‪..........‬وهــو‬\n‫يف الصالــة يريــد أن يكــوي ثوب ـ ًا فخــرج أخيــه ‪..........‬مــن غرفتــه ومعــه‬\n‫ســكني وقــال ل‪..........‬ملــاذا دزيتنــي ) فقــام ‪..........‬بطعــن ‪..........‬يف ذراعه‬\n‫فتشــاجرا فقــام ‪..........‬وكان يريــد أخــذ الســكني مــن يــد ‪..........‬فقــام‬\n‫‪..........‬بــرد الســكني إلــى صــدره فهــرب ‪..........‬إلــى املجلــس وحلــق بــه‬\n‫‪..........‬ويف الطريــق ســقط ‪..........‬باملمــر مقابــل املطبــخ وكان يشــاهد‬\n‫الــدم علــى صــدر ‪..........‬وهــذا مــا حصــل ‪ .‬وقــد صــدر بحــق املجنــي عليــه‬\n‫‪........../‬التقريــر الطبــي الشــرعي النهائــي رقم‪..........‬وتاريــخ‬\n‫‪1432/7/1‬ه ـ املتضمــن أن الوفــاة ناجتــة عــن اجلــرح الطعنــي باجلهــة‬\n‫اليســرى مــن الصــدر والــذي أدى إلــى متــزق بالرئــة اليســرى والشــريان‬\n‫الرئــوي ومــا نتــج عنــه مــن نــزف وصدمــه نزفيــه‪ .‬كمــا صــدر بحــق‬\n‫املدعــى عليــه ‪........../‬التقريــر الطبــي رقــم (‪ )..........‬وتاريــخ‬\n‫‪1432/6/28‬ه ـ املتضمــن وجــود جــرح قطعــي بالكتــف األيســر حوالــي‬\n‫‪1‬ســم ومــدة الشــفاء أســبوع واحــد وقــد أســفر التحقيــق عــن توجيــه‬\n‫االتهــام للحــدث‪.......... /‬بقتــل شــقيقه‪.......... /‬عمــد ًا وعدوان ـ ًا وذلــك‬\n‫بطعنــه بســكني يف صــدره أدت لوفاتــه وذلــك لألدلــة والقرائــن اآلتيــة ‪:‬‬\n                                                                                     ‫‪-‬‬\n          ‫‪ -1‬ما جاء باعترافه املصادق عليه شرع ًا املرفق لفه رقم (‪. )68‬‬\n\n\n                                                                                         ‫‪86‬‬\n\f     ‫‪ -2‬مــا جــاء مبحضــر االنتقــال واملعاينــة املــدون علــى الصفحــة رقــم‬\n                                                          ‫(‪ )10‬املرفــق برقــم (‪. )99‬‬\n     ‫‪ -3‬مــا جــاء بأقــوال والــدة املدعــى عليــه وأشــقائه ( ‪-.......... ..........‬‬\n     ‫‪ ).......... ،..........‬املدونــة علــى دفاتــر التحقيــق املرفقــة لفــة رقــم (‪)59‬‬\n                                                                              ‫ورقــم (‪)42‬‬\n             ‫‪ -4‬ما جاء بتقرير الطب الشرعي املرفق لفه رقم ( ‪) 78 , 70‬‬\n     ‫‪ -5‬مــا جــاء مبحضــر متثيــل اجلرميــة وأنــه مطابــق ملــا جــاء يف أقــوال‬\n                                            ‫املدعــى عليــه املرفــق لفــه رقــم (‪. )84‬‬\n                       ‫‪ -6‬ما جاء بتقرير األدلة اجلنائية املرفق لفه رقم (‪. )87‬‬\n                     ‫‪ -7‬ما جاء مبحضر معاينة اجلثة لفه رقم (‪ )43‬ص (‪)10‬‬\n          ‫‪ -8‬التقرير الطبي املرفق اخلاص باملدعى عليه املرفق لفه (‪. )15‬‬\n     ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه احلــدث املذكــور من قتــل النفس‬\n     ‫عمــد ًا بغيــر حــق فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب ‪ -1:‬إثبات‬\n     ‫مــا أســند إليــه ‪ -2،‬احلكــم عليــه بعقوبــة تأديبيــة لقــاء احلــق العــام يف‬\n     ‫ضــوء املــادة (‪ )174‬مــن نظــام اإلجــراءات اجلزائيــة‪ ( ،‬علم ـ ًا بــأن احلــق‬\n     ‫اخلــاص انتهــى بالتنــازل ) هــذه دعــواي وبعــرض دعــوي املدعــي العــام‬\n     ‫علــى املدعــي عليــه أجــاب بقولــه أن مــا ذكــره املدعــي العــام يف دعــواه‬\n     ‫مــن تســببي يف قتــل أخــي ‪..........‬صحيــح ولكــن لــم يكــن ذلــك عمــد ًا‬\n     ‫حيــث انــه ال توجــد بينــي وبــن املجنــي عليــه أي عــداوة وهــو شــقيقي وإمنــا‬\n     ‫كان ذلــك عــن طريــق اخلطــأ بســبب أن املجنــي عليــه توجــد بينــه وبــن‬\n     ‫أخــي ســوء تفاهــم وتدخلــت لفــك هــذا الشــجار بينهمــا وبعدهــا ذهــب‬\n     ‫أخــي املجنــي عليــه إلــى غرفتــه وذهــب أخــي ‪..........‬مــع أخوتــي ووالدتــي‬\n     ‫إلــى املجلــس فشــاهدت أخويهــا ‪..........‬و‪ ..........‬يتشــاجران وكان أخيهــا‬\n\n\n‫‪87‬‬\n\f‫‪..........‬يفــك بينهــا وبعــد انتهــاء املشــكلة قامــت أمهــا وأخذتهــم جميع ـ ًا‬\n‫إلــى مجلــس الرجــال وعــاد أخيهــا ‪..........‬إلــى غرفتــه وهــم يف املجلــس‬\n‫أمــر أخيهــا ‪..........‬أخيهــا ‪..........‬بــأن يكــوي لــه ثوب ـ ًا يف صالــة املنــزل‬\n‫فخــرج ‪..........‬مــن املجلــس وبعــد حلظــات جــاء أخيهــا ‪..........‬وذكــر أن‬\n‫أخويــه ‪..........‬و‪..........‬تطاعنــا بالســكني وشــاهدت ‪..........‬وكان يلبــس‬\n‫مالبــس داخليــة بيضــاء عليهــا دم وقــام ‪..........‬و‪ ..........‬بحمــل ‪..........‬‬\n‫بالســيارة وذهــب بــه ‪..........‬للمستشــفى وبضبــط إفــادة‪.......... /‬أفــاد بانــه‬\n‫شــاهد أخيــه ‪..........‬وأخيــه ‪..........‬يتشــاجران ففــك بينهــم أخيــه ‪..........‬‬\n‫وأخذتهــم أمهــم إلــى املجلــس وكان أخيــه ‪..........‬يســب ويشــتم وعــض‬\n‫أخيــه ‪..........‬أخيــه ‪..........‬يف أذنــه وهــذا مــا حصــل وبضبــط إفــادة‪/‬‬\n‫‪..........‬أفــاد بأنــه فطلــب منــي أخــي ‪..........‬أن أقــوم بكــوي ثوبــه فذهبــت‬\n‫إلــى الصالــة وبعدهــا ذهــب املجنــي عليــه ولــم انتبــه لــه وكانــت يف يــده‬\n‫ســكني فأجتــه إلـ ٌـي وقــال لــي ملــاذا فككــت املضاربــة بينــي وبــن أخــي‬\n‫‪..........‬فقلــت لــه يــا ‪..........‬مــا نبغــي مشــاكل بهــذه العبــارة فقــام بطعنــي‬\n‫يف ذراعــي األيســر ممــا أدى إلــى جرحــي ثــم رفــع يــده لكــي يطعنــي مــرة‬\n‫أخــرى فقمــت مبســك يــده ثــم دفعتــه إلــى اخللــف بقــوه فعــادت الســكني‬\n‫إلــى جهــة قلبــه وبعدهــا اخــذ ميشــي متجهــا للمجلــس وبعدهــا ســقط‬\n‫علــى األرض فقمــت بإخبــار أخــي ورأى املوقــف وبعدهــا قمــت بحملــه‬\n‫أنــا وأخــي ‪..........‬إلــى الســيارة والزال علــى قيــد احليــاة ثــم ذهــب بــه‬\n‫أخــي ‪..........‬إلــى املستشــفى هكــذا أجــاب كمــا جــرى ســؤاله املدعــى‬\n‫عليــه عــن بلوغــه وقــت اجلرميــة فأجــاب بقولــه كنــت بالغ ـ ًا وقــت اجلرميــة‬\n‫يف واحتالمــي هكــذا أجــاب وبســؤال‬            ‫وذلــك بظهــور عالمــات البلــوغ ٌ‬\n‫املدعــي العــام هــل لديــك بينــة علــى أن القتــل حصــل عمــدا فأجــاب ليــس‬\n\n\n                                                                                           ‫‪88‬‬\n\f     ‫لــدي بينــه ســوى مــا جــاء يف أوراق املعاملــة هكــذا أجــاب ويف أثنــاء‬\n     ‫اجللســة حضــرت والــدة املدعــى عليــه واملجنــي عليــه ‪.......... /‬ســعودية‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪..........‬وأخــوت املجنــي عليــه ‪/‬‬\n     ‫‪..........‬ســعودي مبوجــب الســجل املدنــي رقــم ‪..........‬و‪..........‬ســعودي‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪..........‬و‪ ..........‬ســعودي مبوجــب الســجل‬\n     ‫املدنــي رقــم ‪..........‬و‪ ..........‬ســعودية مبوجــب الســجل املدنــي رقــم ‪..........‬و‬\n     ‫‪..........‬ســعودية مبوجــب الســجل املدنــي رقــم ‪ ،..........‬وعليــه قــررت والدة‬\n     ‫املجنــي عليــه بــأن املجنــي عليــه لديــه أعاقــه يف يــده اليســرى وال يســتطيع‬\n     ‫إنزالهــا وكذلــك رجلــه اليســرى لديــه أصابــه بهــا وذلــك بســبب حــادث‬\n     ‫مــروري ممــا تســبب يف حصــول عــرج يف رجلــه وكمــا قــررت والــدة‬\n     ‫املجنــي عليــه وبحســب واليتهــا علــى القاصريــن ‪..........‬و‪ ..........‬وعــن‬\n     ‫نفســها بأنهــا متنازلــة يف احلــق اخلــاص كمــا قــرر بقولهــا إننــي أصــادق‬\n     ‫علــى صفــة القتــل وكيفيــه وقوعــه وأنــه كان خطــأ مــن املدعــى عليــه‬\n     ‫كمــا قــرروا إخــوة املدعــى عليــه واملجنــي عليــه بقولهــم أننــا متنازلــون‬\n     ‫عــن احلــق اخلــاص كمــا قــرروا املصادقــة علــى مــا ذكــره املدعــي عليــه‬\n     ‫مــن صفــة القتــل التــي ذكــر هكــذا أجابــوا ‪ ،‬فبنــاء علــى مــا تقــدم مــن‬\n     ‫الدعــوى واإلجابــة ولعــدم وجــود بينــه للمدعــي العــام علــى القتــل العمــد‬\n     ‫وملصادقــة ورثــة املجنــي عليــه يف صفــة القتــل وانــه كان على صفة اخلطأ‬\n     ‫ولكــون املدعــى عليــه ذكــر بأنــه قــام بدفــع املجنــي عليــه بعــد مــا طعنــه‬\n     ‫يف ذراعــه وكمــا ان املجنــي عليــه توجــد لديــه أعاقــه يف يــده اليســرى‬\n     ‫كمــا ذكــرت والدتــه ممــا يصعــب دفــع الســكني التــي ارتكــزت‬\n     ‫يف صــدره ومبــا انــه ال توجــد عــدواه بــن املدعــى عليــه واملجنــي عليــه‬\n     ‫ولكــون مــا قــرره الفقهــاء رحمهــم اهلل تعالــى مــن ان قتــل العمــد وشــبه‬\n\n\n‫‪89‬‬\n\f‫العمــد يتفقــان يف القصــد يف اجلنايــة إال إنهمــا يختلفــان يف اآللــة فالعمــد‬\n‫يف آلــة تقتــل غالبــا وشــبه العمــد مــاال تقتــل غالبــا واخلطــأ يســتثنى فيــه‬\n‫قصــد اجلنايــة فاملدعــى عليــه يظهــر منــه انــه لــم يقصــد اجلنايــة وإمنــا قصد‬\n‫دفــع املجنــي عليــه مــن إصابتــه مــرة أخــرى وممــا يؤكــد ذلــك مصادقــة‬\n‫ورثــة املجنــي عليــه ومبــا أن القصــد خفــي ال يظهــر وال يتجلــى إال بوجــود‬\n‫قرائــن تــدل عليــه فهنــا عــدم حملــه اآللــة ابتــداء وعــدم العــداوة املســبقة‬\n‫ومبــا أن ورثــة املجنــي عليــه قــد قــرروا تنازلهــم عــن حقهــم اخلــاص مــن‬\n‫الديــة وبنــاء علــى ذلــك كلــه فقــد صرفــت النظــر عــن إثبــات صفــة قتــل‬\n‫العمــد لعــدم الثبــوت كمــا ثبــت لــدي إدانــة املدعــى عليــه يف تســببه يف‬\n‫قتــل أخيــه وذلــك عــن طريــق اخلطــأ وبذلــك حكمــت وبعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــى عليــه القناعــة بــه وأمــا املدعــي العــام فقــرر‬\n‫اعتراضــه بــدون تقــدمي الئحــة اعتراضيــة ‪ ،‬كمــا انــه ســوف يتــم إفهامــه‬\n‫بالكفــارة بعــد اكتســاب احلكــم الصفــة القطعيــة وللبيــان حــرر يف‬\n‫‪1433 / 1/ 5‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه ‪،‬‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن املوافــق ‪1433/11/1‬ه ـ‬\n‫الســاعة العاشــرة جــرى فتــح ضبــط هــذه القضيــة وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف بخطابهــم رقــم وتاريــخ ‪1433/4/27‬ه ـ‬\n‫واملقيــدة باحملكمــة برقــم وتاريــخ ‪1433/5/3‬ه ـ ومشــفوعها قــرار‬\n‫الدائــرة اجلزائيــة الثانيــة رقــم ‪ 33150802‬وتاريــخ ‪1433/3/23‬ه ـ‬\n‫املتضمــن ( وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ‬\n‫باألكثريــة مــا يلــي‪ :‬أوال‪ :‬ضبــط فضيلتــه تنــازل والــدة املقتــول بصفتهــا‬\n‫وليــة علــى القاصريــن مــن الورثــة وســكت فضيلتــه عــن إثبــات ذلــك‬\n‫مــن عدمــه والواجــب أن يــرد هــذا التنــازل فيمــا يخــص القصــر ويفهــم‬\n\n\n                                                                                        ‫‪90‬‬\n\f     ‫الوليــة بأنــه ال يحــق لهــا التنــازل عــن حقــوق القاصريــن ‪ .‬ثانيــا ‪ :‬حكــم‬\n     ‫فضيلتــه بإدانــة املدعــى عليــه يف تســببه يف قتــل أخيــه عــن طريــق اخلطــأ‬\n     ‫وصــرف النظــر عــن طلــب املدعــي العــام إثبــات صفــة القتــل العمــد‬\n     ‫وهــذا يف غيــر محــل نظــر فالقتــل حصــل مــن املدعــى عليــه وال خــاف‬\n     ‫عليــه أمــا القصــد فتــدل عليــه آلــة القتــل وهــي الســكني التــي تقتــل‬\n     ‫غالبــا يضــاف إليهــا حصــول املشــاجرة بــن القاتــل واملقتــول و اعتــراف‬\n     ‫القاتــل أثنــاء احملاكمــة بــأن املقتــول بيــده الســكني وهــوى بهــا ليطعــن‬\n     ‫القاتــل فقــام مبســك يــد املقتــول وبهــا الســكني فدفعهــا بقــوة فانغــرزت‬\n     ‫الســكني يف صــدر أخيــه وقتلتــه فــإن لــم يكــن ذلــك قتــل عمــد فــا‬\n     ‫أقــل مــن أن يكــون شــبه عمــد فعلــى فضيلتــه إعــادة النظــر والتأمــل يف‬\n     ‫حكمــه ‪ .‬ثالثــا‪ :‬صــورة الضبــط لــم توقــع مــن قبــل املختــص والبــد مــن‬\n     ‫ذلــك فعلــى فضيلتــه إكمــال الــازم وإحلــاق مــا يجــد للضبــط وصــورة‬\n     ‫والقــرار وســجله وإعــادة املعاملــة كاملتبــع واهلل املوفــق وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬قاضــي اســتئناف ‪ ..........‬ختــم‬\n     ‫وتوقيــع‪ ،‬قاضــي اســتئناف د‪...........‬ختــم وتوقيــع ‪ ،‬رئيــس الدائــرة ‪..........‬‬\n     ‫ختــم وتوقيــع ‪ .‬فأقــول جوابــا علــى مالحظــة أصحــاب الفضيلــة أوال‪ :‬لــم‬\n     ‫أقــم بضبــط التنــازل بصفــة مســتقلة يف ضبــط التنــازالت وإمنــا ذكــرت‬\n     ‫ذلــك ملــا تنازلــت يف احملكمــة العامــة كمــا هــو موضــح يف أوراق املعاملة‬\n     ‫‪ ،‬أمــا امللحوظــة الثانيــة فلــم يظهــر لــي خــاف مــا توصلــت إليــه لكــون‬\n     ‫املدعــى عليــه لــم يقصــد اجلنايــة و كمــا ال يخفــى على أصحــاب الفضيلة‬\n     ‫أن العمــد و شــبه العمــد ينفعــان يف القصــد ويختلفــان يف اآللــة والقتــل‬\n     ‫اخلطــأ ليــس فيــه قصــد اجلنايــة وهنــا املدعــى عليــه لــم يقصــد اجلنايــة‬\n     ‫حيــث ال عــداوة مســبقة وال هــو مــن جــاء بالســكني وطعــن ‪ ،‬وأمــا‬\n\n\n‫‪91‬‬\n\f‫امللحوظــة الثالثــة فقــد جــرى إكمــال الــازم وعليــه فــا أزال مســتمرا‬\n‫علــى مــا حكمــت بــه وللبيــان حــرر يف متــام الســاعة العاشــرة و الربــع‬\n‫مــن يــوم االثنــن املوافــق ‪1433/11/1‬ه ـ وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم ‪ .‬احلمــد هلل وحــده وبعــد ‪ ....‬فقــد اطلعنــا نحــن‬\n‫قضــاة الدائــرة الثانيــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف‬\n‫مبنطقــة اجلــوف علــى املعاملــة الــواردة مــن احملكمــة اجلزائيــة بتبــوك‬\n‫برقــم وتاريــخ ‪1433/11/14‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة الشيخ‪........../‬املســجل برقــم يف‪1433/1/8‬ه ـ اخلــاص بدعــوى‬\n‫املدعــي العــام ضــد‪ .......... /‬يف قضيــة إثبــات صفــة القتــل وقــد تضمــن‬\n‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلــة‬\n‫القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا الســابق رقــم‬\n‫‪ 33150802‬وتاريــخ ‪1433/3/23‬ه ـ تقــرر باألكثريــة املصادقــة علــى‬\n‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                         ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪92‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":79,"source_page_end":92,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7c429200b291ed220ce9d10f553239c9391ddbfe65063d818af6e094d8626f41","normalized_text_hash":"f4ae4df3ad22317eba3821e122aee55b1028e6475fc3c83a67fc816de5da9346","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p79-3312366"},{"id":"80a10ed6-1951-5562-9e2c-a969cae89ff4","document_type":"judgment","category":"judicial","subcategory":"general","title":"قتل عمد -إثبات صفة القتل العمد ،حد املسكر ،قيادة حتت تأثير املسكر ،إقرار ،تنازل عن حق خاص ،تقرير أدلة جنائية ، إدانة بالقتل العمد وانطباق موجب تطبيق اإلرادة امللكية على قاتل العمد مبعرفة اجلهة املختصة.","document_number":"33460348","case_number":"33167151","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/21","year":"1434","subject":"قتل عمد -إثبات صفة القتل العمد ،حد املسكر ،قيادة حتت تأثير املسكر ،إقرار ،تنازل عن حق خاص ،تقرير أدلة جنائية ، إدانة بالقتل العمد وانطباق موجب تطبيق اإلرادة امللكية على قاتل العمد مبعرفة اجلهة املختصة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 33460348 :‬تاريخه‪1433/11/21 :‬هـ‬\n                           ‫رقم الدعوى‪33167151:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 33273852‬تاريخه‪1433/6/1 :‬هـ‬\n\n\n       ‫قتــل عمــد ‪ -‬إثبــات صفــة القتــل العمــد ‪ ،‬حــد املســكر ‪ ،‬قيــادة حتــت‬\n       ‫تأثيــر املســكر ‪ ،‬إقــرار ‪ ،‬تنــازل عــن حــق خــاص ‪ ،‬تقريــر أدلــة جنائيــة ‪،‬‬\n       ‫إدانــة بالقتــل العمــد وانطبــاق موجــب تطبيــق اإلرادة امللكيــة علــى قاتــل‬\n                                                 ‫العمــد مبعرفــة اجلهــة املختصــة‪.‬‬\n\n\n\n\n       ‫‪ -1‬األمــر الســامي رقــم ‪ 10711‬يف ‪1393/5/2‬ه ـ وقــرار مجلــس القضــاء‬\n       ‫األعلــى بهيئتــه الدائمــة برقــم‪ 3/51‬يف ‪1409/3/6‬ه ـ املؤيــد باألمــر‬\n       ‫الســامي رقــم ‪/1197/4‬م يف ‪1409/6/2‬ه ـ املبلــغ بالتعميــم ‪/8‬ت‪ 95/‬يف‬\n       ‫‪1409/7/25‬ه ـ بشــأن تطبيــق اإلرادة امللكيــة علــى قاتــل العمــد وشــبه‬\n       ‫العمــد إذا تنــازل أوليــاء الــدم عــن القصــاص (التصنيــف املوضوعــي‬\n                                                  ‫لتعاميــم وزارة العــدل ‪.)782/1‬‬\n\n\n\n       ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه األول بقتــل املجني‬\n       ‫عليــه عمــد ًا بإطــاق النــار عليــه مــن مسدســه احلكومــي‪ ،‬وشــرب األول‬\n       ‫والثانــي للمســكر الــذي أحضــره األول وحيازتهمــا لــه وقيــادة الثانــي‬\n       ‫للســيارة حتــت تأثيــر املســكر ‪ ،‬وطلــب إثبــات إدانتهمــا مبــا أســند‬\n       ‫إليهمــا وإثبــات صفــة القتــل العمــد وتطبيــق اإلرادة امللكيــة بحــق القاتــل‬\n\n‫‪93‬‬\n\f‫املدعــى عليــه األول واحلكــم عليهمــا بحد شــرب املســكر وقيــادة الثاني‬\n‫للســيارة حتــت تأثيــر املســكر وإفهامــه بــأن عقوبته يف ذلــك عائد للجهة‬\n‫املختصــة حيــث ورد بــاغ عــن وجــود شــخص متوفــى يف املستشــفى بطلق‬\n‫نــاري ‪ -‬بتفتيــش الســيارة الواقفــة أمــام بــاب الطــوارئ عثــر علــى ســاح‬\n‫نــاري وثالثــة أظــرف فارغــة وأربــع طلقــات حيــة داخــل جــراب املســدس‬\n‫وقــارورة مــاء بهــا مــادة (العــرق) املســكر ‪ -‬باستشــمام املدعــى عليهمــا‬\n‫ظهــر انبعــاث رائحــة املســكر مــن أفواههمــا ‪-‬صــدر تقريــر مــن األدلــة‬\n‫اجلنائيــة بــأن الطلقــات املســتخرجة مــن جســم املجنــي عليــه تعــود‬\n‫للمســدس املضبــوط بالســيارة ‪ -‬حضــر وكيــل ورثــة املقتــول وقــرر‬\n‫تنــازل موكليــه عــن املدعــى عليــه األول ‪ -‬أقــر املدعــى عليــه األول بأنــه‬\n‫ركــب مــع املدعــى عليــه الثانــي واملجنــي عليــه بســيارة وتعاطــوا جميعــا‬\n‫املســكر الــذي أحضــره لهــم وجتولــوا بالســيارة وكان معــه مسدســا‬\n‫حكوميــا فأطلــق طلقــة يف الهــواء مازحــا وكان يظــن املســدس خاليــا‬\n‫مــن الطلقــات فانطلقــت رصاصــة مــن مسدســه نحــو املجنــي عليــه ودفــع‬\n‫بأنــه لــم يتعمــد قتلــه ومتنــى لــو أن الطلقــة أصابتــه ولــم تصــب املجنــي عليه‬\n‫لكونــه عزيــزا عليــه وأنــه تائــب ‪ -‬جــرى ســؤال املدعــى عليــه عــن خدمته‬\n‫العســكرية فأجــاب بأنهــا ســبعة عشــر عامــا‪ ،‬كمــا جــرى ســؤاله هــل‬\n‫يوجــد يف املســدس تأمــن فأجــاب بأنــه ال يوجــد بــه تأمــن ‪ -‬أقــر املدعــى‬\n‫عليــه الثانــي بشــربه املســكر وقيامــه بقيــادة الســيارة حتــت تأثيــره وأنــه‬\n‫تائــب ‪ -‬جــرى االطــاع علــى التقريــر الفنــي اجلنائــي املتضمــن اإلشــارة‬\n‫ألثــر الطلقــات التــي كانــت موجــودة علــى جســم املدعــى عليــه ‪ -‬عليــه‬\n‫وإلقــرار املدعــى عليهمــا أنهمــا شــربا املســكر وإلقــرار املدعــى عليــه‬\n‫األول بأنــه أشــهر ســاحه علــى املدعــى عليــه الثانــي واملجنــي عليــه‬\n\n\n                                                                                         ‫‪94‬‬\n\f     ‫وأطلــق عليــه طلقــة واحــدة أدت لوفاتــه‪ ،‬وألن املدعــى عليــه األول رجــل‬\n     ‫أمــن وقــد ســلم لــه الســاح ويلزمــه احملافظــة عليــه وعــدم العبــث بــه أو‬\n     ‫املــزح‪ ،‬وألن املدعــى عليــه األول قــد تــدرب علــى الســاح الــذي حصــل‬\n     ‫بــه القتــل ويعلــم بأنــه ال أمــان فيــه كمــا يعلــم بــأن مــا فيــه مــن طلقــات‬\n     ‫حيــة تكــون ظاهــرة حلاملــة‪ ،‬عليــه والنتهــاء احلــق اخلــاص بتنــازل ورثــة‬\n     ‫كمــت باآلتــي ‪ :‬أوال‪ /‬جلــد كل‬          ‫املجنــي عليــه لذلــك كلــه فقــد َح َ‬\n     ‫واحــد مــن املدعــى عليهمــا حــد املســكر ثمانــن جلــدة دفعــة واحــدة‬\n     ‫علنــا ‪ .‬ثانيــا‪ /‬ثبــوت إدانــة املدعــى عليــه الثانــي بقيــادة الســيارة حتــت‬\n     ‫تأثيــر املســكر وأن عقابــه يف ذلــك للجهــة املختصــة ‪ .‬ثالثــا‪ /‬ثبــوت إدانــة‬\n     ‫املدعــى عليــه األول بقتــل املجنــي عليــه عمــدا لتعمــده إطــاق النــار وإن‬\n     ‫لــم يقصــد النتيجــة وبنــاء عليــه يســجن خمــس ســنني مــن تاريــخ توقيفــه‬\n     ‫‪ -‬قــرر املدعــى عليــه الثانــي القناعــة واملدعــي العــام عــدم االعتــراض أمــا‬\n     ‫املدعــى عليــه األول فعــدم القناعــة فأفهــم بالتعليمــات ‪ -‬عــادت القضيــة‬\n     ‫مــن محكمــة االســتئناف مبلحوظــة بــأن احلكــم علــى املدعــى عليــه‬\n     ‫األول بســجن خمــس ســنوات غيــر مــاق للدعــوى فاملدعــي العــام يطلــب‬\n     ‫تطبيــق اإلرادة امللكيــة وفقــا للتعليمــات ‪ -‬قــررت احملكمــة رجوعهــا‬\n     ‫عــن احلكــم بســجن املدعــى عليــه األول خمــس ســنوات وانطبــاق اإلرادة‬\n     ‫امللكيــة بحقــه وإنفــاذه عائــد للجهــة املختصــة ‪ -‬صــدق احلكــم مــن‬\n                                                                ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪95‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة باخلرج‪/‬املســاعد برقــم وتاريــخ ‪ 1433/03/07‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم وتاريــخ ‪1433/3/7‬ه ـ ففــي يــوم األحــد‬\n‫املوافــق ‪ 1433/04/25‬ه ـ افتتحــت اجللســة بشــأن دعــوى املدعــي‬\n‫العــام بدائــرة التحقيــق واالدعــاء العــام ضــد كال مــن ‪.......... :‬ســعودي‬\n‫مبوجــب الســجل املدنــي رقــم ‪..........‬و ‪..........‬ســعودي مبوجــب الســجل‬\n‫املدنــي رقــم ‪..........‬كمــا حضــر ‪..........‬ســعودي مبوجــب الســجل املدنــي‬\n‫رقــم ‪..........‬بالوكالــة عــن ‪..........‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة بشــرق الريــاض برقــم ‪..........‬يف ‪1433/4/18‬ه ـ واحملــررة‬\n‫وهــذا نصهــا ( بأنــه يف الســاعة اخلامســة صبــاح يــوم اجلمعــة املوافــق‬\n‫‪1432/5/25‬ه ـ تبلــغ مركــز شــرطة ‪..........‬مــن الشــرطة العســكرية‬\n‫يف املؤسســة العامــة للصناعــات احلربيــة عــن وجــود شــخص متوفــى‬\n‫بطلــق نــاري يف الكتــف األيســر واخترقــت الصــدر يف أســفل البطــن ‪.‬‬\n‫وباالنتقــال رفــق املختصــن إلــى املستشــفى وجــد املجنــي عليــه‪.......... /‬‬\n‫يف العقــد الثالــث مــن العمــر حنطــي البشــرة متوســط الطــول ويرتــدي‬\n‫ثــوب أبيــض بــدون شــماغ ومبعاينــة اجلثمــان وجــد بــه أثــر طلقــة واحــدة‬\n‫يف الكتــف األيســر واخترقــت الصــدر واســتقرت يف أســفل البطــن‪ .‬وقــد‬\n‫مت معاينــة الســيارة مــن نــوع صنــي لوحــة رقــم (‪ )..........‬أبيــض مســتأجرة‬\n‫باســم‪.......... /‬وكانــت واقفــة أمــام بوابــة الطــوارئ وبتفتيشــها عثــر‬\n‫علــى ســاح مســدس أبــو محالــة رقمــه (‪ )..........‬وعــدد ثالثــة أظــرف‬\n\n                                                                                     ‫‪96‬‬\n\f     ‫فارغــة وكذلــك عــدد أربــع طلقــات حيــة داخــل جــراب املســدس(فرزت‬\n     ‫أوراق مســتقلة ملعاجلــة ذلــك) وعثــر علــى قــارورة مــاء صغيــرة بهــا أكثــر‬\n     ‫مــن النصــف مــادة ســائلة (عــرق) كمــا شــوهد يف املقعــد األمامــي‬\n     ‫للراكــب علــى بقــع دم وقــد صــدر التقريــر الطبــي الشــرعي النهائــي‬\n     ‫مــن إدارة الطــب الشــرعي باملديريــة العامــة للشــؤون الصحيــة مبنطقــة‬\n     ‫الريــاض برقــم (‪ )..........‬لســنة ‪1432‬ه ـ املتضمــن أنــه بإجــراء الكشــف‬\n     ‫الطبــي الشــرعي والصفــة التشــريحية والفحــوص املعمليــة علــى جثمــان‬\n     ‫املتوفــى‪ 37 ،.......... /‬ســنة ‪ ،‬ســعودي اجلنســية ‪ ،‬تبــن وجــود جــرح نــاري‬\n     ‫حيــوي وحديــث بأعلــى وحشــية العضــد األيســر وقــد نفــذ إلــى يســار‬\n     ‫التجويــف الصــدري والبطــن ثــم اســتقر مقذوفــه بأعلــى إنســية وخلفيــة‬\n     ‫الفخــذ األميــن وقــد أحــدث يف مســاره تهتــك شــديد يف الرئــة واملعــدة‬\n     ‫واملســاريقا ونزيــف شــديد وكان اجتــاه إطالقــه مــن األعلــى واليســار‬\n     ‫إلــى األســفل واليمــن بزاويــة تقــدر ب ـ ‪ 45‬درجــة يف الوضــع الطبيعــي‬\n     ‫القائــم للجســم مــع العلــم بــأن لــكل مــن الطــرف العلــوي واجلــذع حريــة‬\n     ‫يف احلركــة وقــد مت التحفــظ علــى مقذوفــه املســتخرج بغــرض إرســاله‬\n     ‫للمختصــن باألدلــة اجلنائيــة لبيــان نوعــه ونــوع ســاحه وقــد أثبــت‬\n     ‫الكشــف والفحــوص النســجية وجــود عالمــات لقــرب اإلطــاق والتــي‬\n     ‫تشــير إلــى أن اإلطــاق قريــب إال أنــه يصعــب إحداثهــا مــن الشــخص‬\n     ‫نفســه وهــذه اإلصابــة لوحدهــا وبحــد ذاتهــا مميتــه مبــا ضاعفهــا ‪ .‬كمــا‬\n     ‫لــم يتبــن وجــود آثــار مقاومــة أو متاســك أو أي إصابــات أخــرى ‪ .‬كمــا‬\n     ‫ثبــت إيجابيــة كل مــن عينــات الــدم والبــول وســائل قــاع العــن للكحــول‬\n     ‫املســكر بنســبة متوســطة تشــير إلــى تعاطــي املذكــور للكحــول أثنــاء‬\n     ‫حياتــه ‪ ،‬إال أنــه ليــس لهــا دخــل يف إحــداث الوفــاة ‪ ،‬كمــا ثبــت ســلبية‬\n\n‫‪97‬‬\n\f‫العينــات البيولوجيــة واحلشــوية األخــرى للســموم واملخــدرات املوصوفــة‬\n‫يف صلــب التقريــر ‪ .‬وتعــزى الوفــاة إلــى توقــف القلــب والتنفــس الناجــم‬\n‫عــن الطلــق النــاري ومــا ضاعفــه مــن تهتــك ونزيــف وصدمــة‪ .‬ويعــود‬\n‫تاريــخ الوفــاة إلــى ‪1432/5/25‬هـ‪.‬وصــدر بحقــه شــهادة الوفــاة مــن إدارة‬\n‫األحــوال املدنيــة يف ‪..........‬برقــم ‪ ..........‬وتاريــخ ‪1432/6/8‬هــ‪ .‬وبفحــص‬\n‫الســائل الشــفاف الــذي بقــارورة املــاء املضبوطــة أثبــت التقريــر الصــادر‬\n‫مــن شــعبة املختبــرات اجلنائيــة بــإدارة األدلــة اجلنائيــة بشــرطة منطقــة‬\n‫الريــاض باألمــن العــام برقــم ‪..........‬إيجابيتــه للكحــول اإليثيلــي بنســبة‬\n‫(‪ )%74‬أربعــة وســبعون باملائــة ‪ .‬وباستشــمام املدعــى عليهمــا اتضــح وجود‬\n‫رائحــة تشــبه رائحــة املســكر تنبعــث مــن فيهما‪ .‬كما أنــه وبتحليل عينة‬\n‫مــن دم املدعــى عليــه األول أثبــت التقريــر الكيمائــي الشــرعي الصــادر‬\n‫مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية باملديريــة‬\n‫العامــة للشــؤون الصحيــة مبنطقــة الريــاض برقــم ‪..........‬إيجابيتهــا ملــادة‬\n‫الكحــول اإليثيلــي‪ .‬وبفحــص مالبــس املجنــي عليــه صــدر التقريــر مــن‬\n‫شــعبة الطــب الشــرعي بــإدارة املختبــرات اجلنائيــة بــاإلدارة العامــة لألدلــة‬\n‫اجلنائيــة باألمــن العــام برقــم ‪..........‬املتضمــن وجــود ثقــب فتحــة خــروج‬\n‫مقــذوف نــاري يف اجلهــة الداخليــة للكــم األيســر بالثــوب العائــد للمجنــي‬\n‫عليــه وتبــن وجــود ثقــب فتحــة دخــول باجلهــة اخلارجيــة للكــم األيســر‬\n‫يجــاور الثقــب املوصــوف ســابق ًا كمــا تبــن وجــود ثقــب فتحــة دخــول‬\n‫باجلهــة اخلارجيــة للكــم األيســر وثقــب فتحــة خــروج باجلهــة الداخليــة‬\n‫للفانيلــة العائــدة للمجنــي عليــه‪ .‬وبفحــص املســدس الــذي مــن نــوع (أبــو‬\n‫محالــة) حكومــي أمريكــي الصنــع عيــار ‪ 0.38‬بوصــة رقــم‪ ..........‬مــع‬\n‫اجلــراب وعــدد (‪ )3‬ظــروف فارغــة عيــار ‪ 0.38‬بوصــة وعــدد (‪ )4‬طلقــات‬\n\n\n                                                                                      ‫‪98‬‬\n\f     ‫حيــة عيــار ‪ 0.38‬بوصــة املضبوطــة ومقــذوف نــاري عيــار ‪ 0.38‬بوصــة‪-‬‬\n     ‫املســتخرج مــن جســم املجنــي عليــه‪ -‬أثبــت التقريــر الفنــي الصــادر مــن‬\n     ‫إدارة فحــص األســلحة واآلالت بــاإلدارة العامــة لألدلــة اجلنائيــة باألمــن‬\n     ‫العــام برقــم ‪..........‬املتضمــن أن الـ(‪)3‬ثالثــة الظــروف الفارغــة التــي مــن‬\n     ‫عيــار ‪ 0.38‬بوصــة مطلقــة مــن املســدس املشــار إليــه‪ .‬كمــا أثبــت أن‬\n     ‫املقــذوف النــاري الــذي مــن عيــار (‪ )0.38‬بوصــة‪ -‬املســتخرج مــن جســم‬\n     ‫املجنــي عليــه‪ُ -‬مطلــق مــن املســدس املشــار إليــه ‪ .‬وباســتجواب املدعــى‬\n     ‫عليــه األول أقــر أنــه يف صبــاح يــوم اجلمعــة املوافــق ‪1432/5/25‬ه ـ‬\n     ‫عنــد الســاعة الواحــدة والنصــف صباح ـ ًا كان قادم ـ ًا مــن الريــاض‬\n     ‫وبحوزتــه ســاحه حكومــي مســدس ربــع أبــو محالــة فأجــرى اتصــال‬\n     ‫علــى املدعــى عليــه الثانــي ليتقابــا عنــد محطــة ‪..........‬ب‪..........‬‬\n     ‫واجتــه إلــى املوقــع مباشــرة فوجــد املدعــى عليــه الثانــي واملجنــي عليــه‬\n     ‫علــى ســيارة املدعــى عليــه الثانــي نــوع صنــي أبيــض فركــب معهمــا‬\n     ‫يف املرتبــة اخللفيــة وقــد كان قــد أحضــر معــه مــن الريــاض مســكر‬\n     ‫عبــارة عــن قــارورة مــاء صغيــرة بهــا مــادة املســكر نــوع (عــرق) فشــربوا‬\n     ‫املســكر داخــل الســيارة أثنــاء ســيرهم علــى الطريــق وعنــد كبــري‬\n     ‫‪..........‬باجتــاه الغــرب أخــرج مسدســه احلكومــي وشــحنه بطلقــة ثــم‬\n     ‫قــام بإطــاق طلقــة واحــدة يف الهــواء ثــم قــام ميــازح املدعــى عليــه الثانــي‬\n     ‫واملجنــي عليــه داخــل الســيارة بســاحه املســدس املذكــور وتخويفهــم‬\n     ‫بــه ثــم ضغــط علــى الزنــاد فخرجــت الطلقــة وأصابــت املجنــي عليــه‬\n     ‫يف كتفــه األيســر فحــاول إســعافه بالضغــط علــى مــكان اإلصابــة‬\n     ‫والذهــاب بــه للمستشــفى إال أنــه فــارق احليــاة وصــدق علــى ذلــك شــرعاً‪.‬‬\n     ‫وباســتجواب املدعــى عليــه الثانــي أقــر بأنــه يف صبــاح يــوم اجلمعــة املوافــق‬\n\n\n‫‪99‬‬\n\f‫‪1432/5/25‬ه ـ عنــد الســاعة الواحــدة والنصــف صباح ـ ًا كان هــو‬\n‫وخالــه املجنــي عليــه علــى ســيارته نــوع صنــي بيضــاء وهــو يقودهــا عنــد‬\n‫محطــة ‪..........‬ب‪ ..........‬بانتظــار املدعــى عليــه األول والــذي كان قادمـ ًا‬\n‫مــن الريــاض فتقابلــوا عنــد احملطــة املذكــورة وركــب معهمــا املدعــى‬\n‫عليــه األول يف املرتبــة اخللفيــة وقــد أحضــر معــه حبــة شــراب مســكر‬\n‫نــوع (عــرق) صغيــرة فذهبــوا وتعاطــوا املســكر داخــل الســيارة أثنــاء‬\n‫ســيرهم وعنــد كوبــري ‪..........‬علــى الطريــق املــؤدي باجتــاه الغــرب قــام‬\n‫املدعــى عليــه األول بإخــراج مسدســه احلكومــي الــذي كان يحملــه معه‬\n‫وأطلــق طلقــة واحــدة يف الهــواء ثــم قــام بتخويفهــم باملســدس فانطلقــت‬\n‫طلقــه منــه فأصابــت املجنــي عليــه يف كتفــه األيســر ثــم اجتهــوا بــه‬\n‫للمستشــفى إلســعافه وصــدق علــى ذلــك شــرع ًا ‪ .‬وقــد انتهــى التحقيــق‬\n‫معهمــا إلــى توجيــه االتهــام لــأول بقتــل‪ .......... /‬عمــد ًا وذلــك بإطــاق‬\n‫النــار عليــه مــن مسدســه احلكومــي وشــرب األول والثانــي للمســكر‬\n‫الــذي أحضــره األول وحيازتهمــا لــه وقيــادة الثانــي للســيارة حتــت تأثيــر‬\n‫املســكر‪ .‬وفــق قــرار االتهــام رقم‪..........‬لعــام ‪1432‬ه ـ املؤيــد مــن جلنــة‬\n‫إدارة هيئــة التحقيــق واالدعــاء العــام بقرارهــا ‪..........‬لعــام ‪1432‬ه ـ وذلــك‬\n                                                         ‫لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ .1‬مــا جــاء بإقــرار املدعــى عليــه األول املصــادق عليــه شــرع ًا املنــوه عنــه‬\n‫املــدون علــى الصفحــة رقــم (‪ )3‬مــن ملــف التحقيــق رقــم (‪ )2‬املرفــق لفــه‬\n                                                                               ‫رقــم(‪.)2‬‬\n‫‪ .2‬مــا جــاء بإقــرار املدعــى عليــه الثانــي املصــادق عليــه شــرع ًا املنــوه عنــه‬\n‫املــدون علــى الصفحــة رقــم (‪ )4‬مــن ملــف التحقيــق رقــم (‪ )2‬املرفــق لفــه‬\n                                                                             ‫رقــم (‪.)2‬‬\n\n\n                                                                                           ‫‪100‬‬\n\f      ‫‪ .3‬مــا جــاء مبحضــر املعاينــة للســيارة املنــوه عنــه املــدون علــى الصفحــة‬\n                       ‫رقــم (‪ )8‬مــن ملــف التحقيــق رقــم (‪ )2‬املرفــق لفــه رقــم (‪.)2‬‬\n      ‫‪ .4‬مــا جــاء بالتقريــر الطبــي الشــرعي النهائــي رقــم (‪ 301‬ط ش) املنــوه‬\n                                                         ‫عنــه املرفــق لفــه رقــم (‪.)81-76‬‬\n      ‫‪ .5‬مــا جــاء مبحضــر االستشــمام املنــوه عنــه املــدون علــى الصفحــة رقــم‬\n                             ‫(‪ )6‬مــن ملــف التحقيــق رقــم (‪ )1‬املرفــق لفــه رقــم (‪.)1‬‬\n          ‫‪ .6‬ما جاء بالتقرير رقم ‪..........‬املنوه عنه املرفق لفه رقم (‪.)116-114‬‬\n         ‫‪ .7‬ما جاء بالتقرير الفني رقم ‪..........‬املنوه عنه املرفق لفه رقم (‪.)104‬‬\n      ‫‪ .8‬مــا جــاء بالتقريــر رقــم ‪..........‬املنــوه عنــه املنــوه عنــه املرفــق لفــه رقــم‬\n                                                                                           ‫(‪.)71‬‬\n                             ‫‪ .9‬ما جاء بالصور الفوتوغرافية املرفقة لفة رقم (‪.)64‬‬\n      ‫‪ .10‬مــا جــاء يف التقريــر الكيمائــي الشــرعي رقــم ‪..........‬املنــوه عنــه‬\n                                                                      ‫املرفــق لفــه رقــم (‪.)54‬‬\n                    ‫‪ .11‬ما جاء يف تقرير الشرطة العسكرية املرفق لفة رقم(‪. )4‬‬\n      ‫وبالبحــث عــن مــا إذا كان لهمــا ســوابق لــم يعثــر لهمــا علــى ســوابق‬\n                                                                              ‫مســجلة جنائي ـاً‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا وهمــا بكامــل أهليتهمــا‬\n      ‫املعتبــرة شــرعاً‪-‬فعل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتهمــا‬\n      ‫مبــا ُأ ْس ـن َِد إليهمــا وإثبــات صفــة القتــل العمــد وتطبيــق اإلرادة امللكيــة‬\n      ‫بحــق القاتل‪-‬املدعــى عليــه األول‪ -‬واحلكــم علــى املدعــى عليهمــا بحــد‬\n      ‫املســكر وإلثبات إدانة الثاني بقيادة الســيارة وهو حتت تأثير املســكر‬\n      ‫وإفهامــه أن أمــر معاقبتــه علــى ذلــك عائــد للجهــة املختصــة وفق ـ ًا للبنــد‬\n      ‫(ثانيــا) مــن املرســوم امللكــي رقــم (م‪ )85/‬وتاريــخ ‪1428/10/26‬ه ـ‬\n\n\n‫‪101‬‬\n\f‫علمـ ًا بــأن احلــق اخلــاص انتهــى بالتنــازل فيمــا يتعلــق بالــدم والديــة باقيــة‬\n‫علــى حالهــا مبوجــب إقــرار التنــازل املصــدق شــرع ًا املدون علــى الصفحة‬\n                                  ‫رقــم «‪ »2‬مــن دفتــر التحقيــق املرفــق لفــة «‪. »97‬‬\n‫وبــاهلل التوفيــق‪ ،،،‬وبنــاء عليــه فقــد حضــر‪ ..........‬ســعودي مبوجــب‬\n‫السجل املدني رقم ‪..........‬بالوكالة عن ‪..........‬و‪ ..........‬مبوجب الوكالة‬\n‫الصــادرة مــن كتابــة عــدل ‪..........‬برقــم ‪..........‬يف ‪1432/6/26‬ه ـ وله يف‬\n‫وكالتــه حــق التنــازل عــن قاتــل مورثهمــا ‪..........‬وبالوكالــة عــن ‪..........‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل ‪..........‬الثانيــة برقــم ‪..........‬‬\n‫يف ‪1432/6/20‬ه ـ ولــه حــق التنــازل عــن املتســبب يف وفــاة زوجهــا وحــال‬\n‫واليتــه علــى أبيــه القاصــر عقليــا ‪..........‬مبوجــب صك الواليــة الصادر من‬\n‫هذه احملكمة برقم ‪..........‬يف ‪1432/7/10‬هـ واملنحصر ارث ‪.......... /‬‬\n‫يف موكلــي املنهــي ومــن هــو حتــت واليتــه وذلــك مبوجــب صــك حصــر‬\n‫الورثــة الصــادر مــن محكمــة الدلــم برقــم ‪..........‬يف ‪1432/7/12‬ه ـ‬\n‫وقــرر املدعــي يف احلــق اخلــاص تنــازل موكليــه عــن املدعــى عليــه األول‬\n‫حــزام وبســؤال املدعــى عليــه األول ‪..........‬أجــاب بقولــه صحيــح أنــي‬\n‫كنــت صبــاح يــوم اجلمعــة ‪1432/5/25‬ه ـ قــادم مــن الريــاض بإجتــاه‬\n‫‪..........‬فإتصلــت بزميلــي املدعــى عليــه الثانــي هــذا احلاضــر ‪..........‬وأعلــم‬\n‫أن معــه املجنــي عليــه ‪..........‬واتفقــت علــى مــكان نتقابــل فيــه وكنــت‬\n‫قــد أحضــرت مســكرا مــن نــوع عــرق ‪ .‬ومعــي مســدس حكومــي ربــع‬\n‫أبــو محالــة وتقابلــت معهمــا عنــد محطــة ‪..........‬يف ‪..........‬وركبــت معهما‬\n‫ومعــي املســدس احلكومــي ومعــي قــارورة املســكر وركبــت يف املقعــد‬\n‫اخللفــي يف الســيارة واملدعــى عليــه هــذا احلاضــر يقــود الســيارة واملجنــي‬\n‫عليــه يركــب يف مقعــد الراكــب األمامــي مــن اليمــن وأنــا يف منتصــف‬\n\n\n                                                                                          ‫‪102‬‬\n\f      ‫املقعــد اخللفــي وقــد أخــذت املســدس احلكومــي معــي حيــث انــي أخشــى‬\n      ‫عليــه مــن الســرقة وبعــد أن ســرنا شــربنا نحــن الثالثــة املســكر مــن‬\n      ‫نــوع عــرق ومتشــينا أكثــر مــن ســاعة أخرجــت املســدس وأطلقــت طلقــة‬\n      ‫واحــدة يف الهــواء ثــم أخــذت أمــازح املدعــى عليــه الثانــي ‪ ..........‬وأمــازح‬\n      ‫املجنــي عليــه ‪..........‬ثــم انطلقــت مــن املســدس طلقــة اصابــت املجني عليه‬\n      ‫‪..........‬يف كتفــه األيســر وال أعلــم كيــف انطلقــت الرصاصــة وكنــت‬\n      ‫أظــن أن املســدس خــال مــن الطلقــات ‪ .‬وأنــا لــم أتعمــد قتــل ‪..........‬وإمنــا‬\n      ‫انطلقــت الرصاصــة مــن غيــر قصــد ومــن غيــر علــم منــي أن يف املســدس‬\n      ‫رصاصــة وأنــا متنيــت أن الرصاصــة انطلقــت يف جســدي ألن املجنــي عليــه‬\n      ‫عزيــز علــي ‪ .‬ثــم جــرى مناقشــة املدعــى عليــه عــن خدمتــه العســكرية‬\n      ‫فقــال إنهــا ســبعة عشــر عامــا وجــرى ســؤاله عــن تاريــخ تســليمه الســاح‬\n      ‫فقــال أنــه قبــل ســنة مــن احلادثــة وجــرى ســؤاله عــن املســدس أبــو محالــة‬\n      ‫هــل يوجــد فيــه تأمــن فقــال ال يوجــد فيــه تأمــن وجــرى ســؤاله هــل يتــم‬\n      ‫مشــاهدة الرصــاص احلــي يف املســدس فقــال أنهــا ال تــرى إال بعــد إخــراج‬\n      ‫املكــرة ( احملالــة) وأنــا تائــب هلل ولــن أعــود لشــئ مــن املعاصــي هكــذا‬\n      ‫أجــاب املدعــى عليــه األول ‪ ...........‬وأجــاب املدعــى عليــه بالوكالــة‬\n      ‫بقولــه أن موكلــي املدعــى عليــه هــذا احلاضــر ‪..........‬لــم يتعمــد الفعــل (‬\n      ‫إطــاق النــار ) ولــم يتعمــد النتيجــة التــي هــي وفــاة املجنــي عليــه ‪..........‬‬\n      ‫كمــا أن العالقــة بــن موكلــي املدعــى عليــه و املجنــي عليــه ‪..........‬‬\n      ‫عالقــة حميمــة كمــا أن عالقــة ذوي املتــويف مبوكلــي املدعــى عليــه‬\n      ‫‪..........‬عالقــة حميمــة وهــم مــن فخــذ واحــد بدليــل أنــه حصــل التنــازل‬\n      ‫مــن أوليــاء الــدم فــورا ويف وقــت قريــب مــن احلادثــة كمــا أن موكلــي‬\n      ‫يتمنــى أن الرصاصــة اصابتــه ولــم تصــب املجنــي عليــه ‪ ...........‬وبســؤال‬\n\n\n‫‪103‬‬\n\f‫املدعــى عليــه الثانــي ‪ ..........‬قــال صحيــح أننــي شــربت املســكر مــن نــوع‬\n‫عــرق وقمــت بقيــادة ســيارتي مــن نــوع صنــي ‪2011‬م قبــل تأثيــر املســكر‬\n‫علــي ‪ .‬وأنــا تائــب هلل جــل وعــا ولــن أعــود لشــئ مــن املعاصــي هكــذا‬\n‫أجــاب املدعــى عليــه الثانــي ‪ . .‬ثــم جــرى ســؤال املدعــى عليــه األول‬\n‫أصالــة واملدعــى عليــه وكالــة هــل ألحدهمــا إضافــة فقــرر أنهمــا يطلبان‬\n‫صــرف النظــر عــن دعــوى املدعــي العــام بإثبــات صفــة القتــل مــن نــوع‬\n‫العمــد ‪ .‬احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة‬\n‫العامــة مبحافظــة اخلــرج افتتحــت اجللســة وفيهــا حضــر املدعــي العــام‬\n‫وحضــر حلضــوره ‪..........‬ســعودي مبوجــب الســجل املدنــي رقــم ‪..........‬و‬\n‫‪ ..........‬ســعودي مبوجــب الســجل املدنــي رقــم ‪..........‬كمــا حضــر ‪..........‬‬\n‫ســعودي مبوجــب الســجل املدنــي رقــم ‪..........‬بالوكالــة عــن ‪..........‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بشــرق الريــاض‬\n‫برقــم ‪..........‬يف ‪1433/4/18‬ه ـ وجــرى االطــاع علــى أوراق املعاملة ومن‬\n‫بينهــا ملــف التحقيــق املرفــق لفــة رقــم ‪ 1‬وجــاء فيــه اســتجواب املدعــى‬\n‫عليــه واجابتــه مطابقــة الجابتــه لدينــا ‪ .‬كمــا جــرى االطــاع علــى‬\n‫التقريــر الفنــي اجلنائــي رقــم ‪/1/32/163‬ط وجــاء فيــه الــراي ‪ :‬اســتنادا‬\n‫الــى مــا تقــدم وبعــد فحــص املالبــس العائــدة للمدعــو ‪..........‬تبــن مــا يلــي‬\n‫‪ - 1 :‬وجــود ثقــب فتحــة خــروج مقــذوف نــاري يف اجلهــة الداخليــة للكــم‬\n‫األيســر بالثــوب العائــد للمذكــور وكمــا تبينــا وجــود ثقــب فتحــة دخــول‬\n‫باجلهــة الداخليــة للكــم االيســر يجــاور الثقــب املوصــوف ســابقا وتبينــا‬\n‫وجــود ثقــب فتحــة دخــول باجلهــة اخلارجيــة للكــم األيســر وثقــب فتحــة‬\n‫خــروج باجلهــة الداخليــة للفانيلــة العائــدة لــه ‪ ،‬أخــذا يف االعتبــار أننــا لــم‬\n‫منيــز ثقــب الدخــول وأضاعــت معاملــة ‪ -2 .‬لــم يتــم عمــل بحــث عالمــات‬\n\n\n                                                                                          ‫‪104‬‬\n\f      ‫قــرب االطــاق لعــدم تبيننــا وجــود ثقــب فتحــة دخــول بالثــوب العائــد‬\n      ‫للمذكــور حيــث يتــم عمــل االختبــار علــى أول ســطح المســة املقــذوف‬\n      ‫عنــد الدخــول ‪ - 3 .‬أعيــدت جميــع املالبــس املوصوفــة أعــاه محــرزه‬\n      ‫رفــق هــذا التقريــر واهلل املوفــق ‪ .‬أ ‪ -‬ه ـ فبنــاء علــى مــا تقــدم مــن دعــوى‬\n      ‫املدعــي العــام واجابــة املدعــى عليــه وإلقــرار املدعــى عليهمــا أنهمــا شــربا‬\n      ‫املســكر وإلقــرار املدعــى عليــه االول ‪..........‬بأنــه أشــهر ســاحه علــى‬\n      ‫املدعــى عليــه الثانــي ‪..........‬وأشــهر ســاحة كذلــك علــى املجنــي عليــه‬\n      ‫‪..........‬وأطلــق عليــه طلقــة واحــدة أدت لوفاتــه وألن املدعــى عليــه رجــل‬\n      ‫أمــن وقــد ســلم الســاح وملــزم باحملافظــة علــى الســاح ومــن احملافظــة‬\n      ‫عليــه عــدم العبــث بــه أو املــزح وألن املدعــى عليــه ‪..........‬قــد تــدرب علــى‬\n      ‫الســاح الــذي حصــل بــه القتــل مســدس أبــو محالــة وأنــه ال أمــان لــه‬\n      ‫ومافيــه مــن طلقــات حيــة تكــون ظاهــرة حلاملــة ونظــرا النتهــاء احلــق‬\n      ‫اخلــاص بتنــازل ورثــة املجنــي عليــه كمــا هــو مبــن بعاليــة لذلــك كلــه‬\n      ‫فقــد حكمــت باآلتــي ‪ )1 :‬أن يجلــد كل واحــد مــن املدعــى عليهمــا‬\n      ‫حــد املســكر ثمانــن جلــدة دفعــة واحــدة علنــا ‪ - 2 .‬ثبــت لــدي ادانــة‬\n      ‫املدعــى عليــه الثانــي بقيــادة الســيارة حتــت تأثيــر املســكر وأن عقابــة‬\n      ‫يف ذلــك للجهــة املختصــة ‪ - 3 .‬ثبــت لــدي ادانــة املدعى عليــه األول ‪..........‬‬\n      ‫بقتــل املجنــي عليــه ‪..........‬وأن قتلــه لــه مــن القتــل العمــد حيــث تعمــد‬\n      ‫االطــاق وإن لــم يقصــد النتيجــة وبنــاء عليــه يســجن املدعــى عليــه خمــس‬\n      ‫ســنني مــن تاريــخ توقيفــه وبــه حكمــت حتريــرا يف ‪1433/5/26‬ه ـ‬\n      ‫وبعرضــه علــى املدعــى عليهــم قنــع املدعــى عليــه الثانــي ‪..........‬ولــم يقنــع‬\n      ‫املدعــى عليــه االول اصالــة ‪..........‬ووكالــة ‪..........‬وطلبــا رفعــه حملكمــة‬\n      ‫االســتئناف وقــرر املدعــى عليــه اصالــة أنــه يكتفــي باعتــراض وكيلــه‬\n\n\n‫‪105‬‬\n\f‫‪..........‬فجــرى افهــام املدعــى عليــه وكالــة مبراجعــة احملكمــة يــوم‬\n‫االحــد املوافــق ‪1433/6/1‬ه ـ الســتالم نســخة مــن احلكــم وتقــدمي الئحة‬\n‫إعتــراض عليهــا يف مــدة أقصاهــا ثالثــون يومــا من التاريــخ املذكور وأنه‬\n‫إن لــم يتقــدم بإعتراضــه خــال تلــك املــدة فسيســقط حقــه يف االعتــراض‬\n‫ويرفــع حملكمــة االســتئناف بــدون الئحــة وصلــى اهلل علــى نبينــا محمــد‬\n‫‪ .‬ويف يــوم األحــد املوافــق ‪1433/6/1‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي العــام وقــرر عــدم رفعــه حملكمــة االســتئناف وصلــى اهلل علــى‬\n‫نبينــا محمــد ‪ .‬احلمــد هلل وحــده ففــي يــوم الســبت املوافــق‪1433/11/20‬‬\n‫ه ـ افتتحــت اجللســة وفيهــا عــادت املعاملــة مــن محكمــة اإلســتئناف‬\n‫وبرفقهــا القــرار رقــم ‪ 33425910‬يف ‪1433/10/15‬ه ـ واملتضمــن أنــه‬\n‫لوحــظ أن احلكــم بســجن املدعــى عليــه خمــس ســنوات غيــر مــاق‬\n‫للدعــوى إذ أن املدعــي العــام طالــب بتطبيــق اإلرادة امللكيــة واملتعيــن‬\n‫تطبيــق اإلرادة امللكيــة وفقــا للتعليمــات وبــاهلل التوفيــق وجواب ـ َا عليــه‬\n‫ولوجاهــة مــا ذكــره أصحــاب الفضيلــة فقــد ثبــت لــدي قتــل املدعــى‬\n‫عليــه للمجنــي عليــه وأن قتلــة مــن بــاب العمــد ويطبــق بحقــه األرادة‬\n‫امللكيــة وتطبيقهــا عائــد للجهــة املختصــة بنــاء علــى التعميــم الــوزاري‬\n‫رقــم ‪/13‬ت‪ 4477/‬يف ‪ 1433/2/12‬ه ـ وبذلــك متــت األجابــة ‪ ،‬ولــم‬\n‫يظهــر لــي خــاف ذلــك وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/20‬ه ـ احلمــد هلل وحــده ففــي‬\n‫يــوم الســبت املوافــق‪ 1433/11/20‬ه ـ افتتحــت اجللســة وفيهــا عــادت‬\n‫املعاملــة مــن محكمــة اإلســتئناف وبرفقهــا القــرار رقــم ‪ 33425910‬يف‬\n‫‪1433/10/15‬ه ـ واملتضمــن أنــه لوحــظ أن احلكــم بســجن املدعــى عليه‬\n‫خمــس ســنوات غيــر مــاق للدعــوى إذ أن املدعــي العــام طالــب بتطبيــق‬\n\n\n                                                                                    ‫‪106‬‬\n\f      ‫اإلرادة امللكيــة واملتعيــن تطبيــق اإلرادة امللكيــة وفقــا للتعليمــات‬\n      ‫وبــاهلل التوفيــق وجواب ـ َا عليــه ولوجاهــة مــا ذكــره أصحــاب الفضيلــة‬\n      ‫فقــد ثبــت لــدي قتــل املدعــى عليــه للمجنــي عليــه وأن قتلــة مــن بــاب‬\n      ‫العمــد ويطبــق بحقــه األرادة امللكيــة وتطبيقهــا عائــد للجهــة املختصــة‬\n      ‫بنــاء علــى التعميــم الــوزاري رقــم ‪/13‬ت‪ 4477/‬يف ‪ 1433/2/12‬ه ـ‬\n      ‫وبذلــك متــت األجابــة ‪ ،‬ولــم يظهــر لــي خــاف ذلــك وصلــى اهلل علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/20‬ه ـ احلمــد هلل‬\n      ‫وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى لتمييــز‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة باخلــرج املكلــف الشــيخ‪........../‬‬\n      ‫برقــم ‪ 34264487‬وتاريــخ ‪1434 /2 /3‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلـ ــته املســجل برقــم ‪ 33273852‬وتاريــخ ‪1433/6/1‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد كل مــن‪ ..........2 .......... -1/‬يف قضيــة قتــل‬\n      ‫علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل بــه وحيــث ســبق دراســة القــرار وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلــة‬\n      ‫القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنا رقــم ‪349404‬‬\n      ‫وتاريــخ ‪1434/1/12‬ه ـ قررنــا بأنــه لــم يظهــر مــا يوجــب املالحظــة اخير ًا‬\n                                                                      ‫وبــاهلل التوفيــق ‪.‬‬\n\n\n\n\n‫‪107‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":93,"source_page_end":107,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"32849560a77cdc207e6518e91cdb3887190260f89325cd3a29ae3242d358d5ed","normalized_text_hash":"30e5e985fe797195a9106c2c07fef79f1bf176c4dc00968369e786c0c6728f27","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p93-33460348"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
